-- Name: word; Type: TABLE; Schema: quranhub_schema; Owner: -
--

CREATE TABLE "quranhub_schema"."word" (
    "id" integer NOT NULL,
    "surat_id" integer,
    "numberinsurat" integer,
    "position" integer,
    "line_number" integer,
    "text" "text",
    "location" "text" GENERATED ALWAYS AS (((((("surat_id")::"text" || ':'::"text") || ("numberinsurat")::"text") || ':'::"text") || ("position")::"text")) STORED,
    "tajweed" "jsonb",
    "v4_img_url" "text",
    "rq_img_url" "text",
    "qa_img_url" "text"
);


--
-- Name: word_id_seq; Type: SEQUENCE; Schema: quranhub_schema; Owner: -
--

CREATE SEQUENCE "quranhub_schema"."word_id_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: word_id_seq; Type: SEQUENCE OWNED BY; Schema: quranhub_schema; Owner: -
--

ALTER SEQUENCE "quranhub_schema"."word_id_seq" OWNED BY "quranhub_schema"."word"."id";


--
-- Name: word_morphology; Type: TABLE; Schema: quranhub_schema; Owner: -
--

CREATE TABLE "quranhub_schema"."word_morphology" (
    "id" integer NOT NULL,
    "word_id" integer NOT NULL,
    "tag_code" "text" NOT NULL,
    "tag_order" smallint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: word_morphology_id_seq; Type: SEQUENCE; Schema: quranhub_schema; Owner: -
--

CREATE SEQUENCE "quranhub_schema"."word_morphology_id_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: word_morphology_id_seq; Type: SEQUENCE OWNED BY; Schema: quranhub_schema; Owner: -
--

ALTER SEQUENCE "quranhub_schema"."word_morphology_id_seq" OWNED BY "quranhub_schema"."word_morphology"."id";


--
-- Name: word_morphology_index; Type: MATERIALIZED VIEW; Schema: quranhub_schema; Owner: -
--

CREATE MATERIALIZED VIEW "quranhub_schema"."word_morphology_index" AS
 SELECT "wm"."tag_code",
    "mt"."category",
    "mt"."meaning",
    "count"(DISTINCT "wm"."word_id") AS "word_count",
    "count"(DISTINCT "w"."surat_id") AS "surah_count"
   FROM (("quranhub_schema"."word_morphology" "wm"
     JOIN "quranhub_schema"."morphological_tag" "mt" ON (("wm"."tag_code" = "mt"."code")))
     JOIN "quranhub_schema"."word" "w" ON (("wm"."word_id" = "w"."id")))
  GROUP BY "wm"."tag_code", "mt"."category", "mt"."meaning"
  WITH NO DATA;


