INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (1, 1, 1, 1, 1, 'سورة الفاتحة سميت هذه السورة بالفاتحة؛ لأنه يفتتح بها القرآن العظيم، وتسمى المثاني؛ لأنها تقرأ في كل ركعة، ولها أسماء أخر.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (2, 1, 1, 1, 2, '(الحَمْدُ للهِ رَبِّ العَالَمِينَ) الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، وفي ضمنه أَمْرٌ لعباده أن يحمدوه، فهو المستحق له وحده، وهو سبحانه المنشئ للخلق، القائم بأمورهم، المربي لجميع خلقه بنعمه، ولأوليائه بالإيمان والعمل الصالح.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (3, 1, 1, 1, 3, '(الرَّحْمَنِ) الذي وسعت رحمته جميع الخلق، (الرَّحِيمِ)، بالمؤمنين، وهما اسمان من أسماء الله تعالى.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (4, 1, 1, 1, 4, 'وهو سبحانه وحده مالك يوم القيامة، وهو يوم الجزاء على الأعمال.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (5, 1, 1, 1, 5, 'إنا نخصك وحدك بالعبادة، ونستعين بك وحدك في جميع أمورنا، فالأمر كله بيدك، لا يملك منه أحد مثقال ذرة.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (6, 1, 1, 1, 6, 'دُلَّنا، وأرشدنا، ووفقنا إلى الطريق المستقيم، وثبتنا عليه حتى نلقاك، وهو الإسلام، الذي هو الطريق الواضح الموصل إلى رضوان الله وإلى جنته، الذي دلّ عليه خاتم رسله وأنبيائه محمد صلى الله عليه وسلم، فلا سبيل إلى سعادة العبد إلا بالاستقامة عليه.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (7, 1, 1, 1, 7, 'طريق الذين أنعمت عليهم من النبيين والصدِّيقين والشهداء والصالحين، فهم أهل الهداية والاستقامة، ولا تجعلنا ممن سلك طريق المغضوب عليهم، الذين عرفوا الحق ولم يعملوا به، وهم اليهود، ومن كان على شاكلتهم، والضالين، وهم الذين لم يهتدوا، فضلوا الطريق، وهم النصارى، ومن اتبع سنتهم.
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (8, 2, 1, 1, 8, 'هذه الحروف وغيرها من الحروف المقطَّعة في أوائل السور فيها إشارة إلى إعجاز القرآن؛ فقد وقع به تحدي المشركين، فعجزوا عن معارضته، وهو مركَّب من هذه الحروف التي تتكون منها لغة العرب. فدَلَّ عجز العرب عن الإتيان بمثله -مع أنهم أفصح الناس- على أن القرآن وحي من الله.', 1, 1, 2, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (9, 2, 1, 1, 9, 'ذلك القرآن هو الكتاب العظيم الذي لا شَكَّ أنه من عند الله، فلا يصح أن يرتاب فيه أحد لوضوحه، ينتفع به المتقون بالعلم النافع والعمل الصالح وهم الذين يخافون الله، ويتبعون أحكامه.', 2, 1, 2, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (10, 2, 1, 1, 10, 'وهم الذين يُصَدِّقون بالغيب الذي لا تدركه حواسُّهم ولا عقولهم وحدها؛ لأنه لا يُعْرف إلا بوحي الله إلى رسله، مثل الإيمان بالملائكة، والجنة، والنار، وغير ذلك مما أخبر الله به أو أخبر به رسوله، (والإيمان: كلمة جامعة للإقرار بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، وتصديق الإقرار بالقول والعمل بالقلب واللسان والجوارح) وهم مع تصديقهم بالغيب يحافظون على أداء الصلاة في مواقيتها أداءً صحيحًا وَفْق ما شرع الله لنبيه محمد صلى الله عليه وسلم، ومما أعطيناهم من المال يخرجون صدقة أموالهم الواجبة والمستحبة.', 3, 1, 2, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (11, 2, 1, 1, 11, 'والذين يُصَدِّقون بما أُنزل إليك أيها الرسول من القرآن، وبما أنزل إليك من الحكمة، وهي السنة، وبكل ما أُنزل مِن قبلك على الرسل من كتب، كالتوراة والإنجيل وغيرهما، ويُصَدِّقون بدار الحياة بعد الموت وما فيها من الحساب والجزاء، تصديقا بقلوبهم يظهر على ألسنتهم وجوارحهم وخص يوم الآخرة؛ لأن الإيمان به من أعظم البواعث على فعل الطاعات، واجتناب المحرمات، ومحاسبة النفس.', 4, 1, 2, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (12, 2, 1, 1, 12, 'أصحاب هذه الصفات يسيرون على نور من ربهم وبتوفيق مِن خالقهم وهاديهم، وهم الفائزون الذين أدركوا ما طلبوا، ونَجَوا من شرِّ ما منه هربوا.', 5, 1, 2, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (13, 2, 1, 1, 13, 'إن الذين جحدوا ما أُنزل إليك من ربك استكبارًا وطغيانًا، لن يقع منهم الإيمان، سواء أخوَّفتهم وحذرتهم من عذاب الله، أم تركت ذلك؛ لإصرارهم على باطلهم.', 6, 1, 3, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (14, 2, 1, 1, 14, 'طبع الله على قلوب هؤلاء وعلى سمعهم، وجعل على أبصارهم غطاء؛ بسبب كفرهم وعنادهم مِن بعد ما تبيَّن لهم الحق، فلم يوفقهم للهدى، ولهم عذاب شديد في نار جهنم.', 7, 1, 3, 2, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (15, 2, 1, 1, 15, 'ومن الناس فريق يتردد متحيِّرًا بين المؤمنين والكافرين، وهم المنافقون الذين يقولون بألسنتهم: صدَّقْنَا بالله وباليوم الآخر، وهم في باطنهم كاذبون لم يؤمنوا.', 8, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (16, 2, 1, 1, 16, 'يعتقدون بجهلهم أنهم يخادعون الله والذين آمنوا بإظهارهم الإيمان وإضمارهم الكفر، وما يخدعون إلا أنفسهم؛ لأن عاقبة خداعهم تعود عليهم. ومِن فرط جهلهم لا يُحِسُّون بذلك؛ لفساد قلوبهم.', 9, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (17, 2, 1, 1, 17, 'في قلوبهم شكٌّ وفساد فابْتُلوا بالمعاصي الموجبة لعقوبتهم، فزادهم الله شكًا، ولهم عقوبة موجعة بسبب كذبهم ونفاقهم.', 10, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (18, 2, 1, 1, 18, 'وإذا نُصحوا ليكفُّوا عن الإفساد في الأرض بالكفر والمعاصي، وإفشاء أسرار المؤمنين، وموالاة الكافرين، قالوا كذبًا وجدالا إنما نحن أهل الإصلاح.', 11, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (19, 2, 1, 1, 19, 'إنَّ هذا الذي يفعلونه ويزعمون أنه إصلاح هو عين الفساد، لكنهم بسبب جهلهم وعنادهم لا يُحِسُّون.', 12, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (20, 2, 1, 1, 20, 'وإذا قيل للمنافقين: آمِنُوا -مثل إيمان الصحابة، وهو الإيمان بالقلب واللسان والجوارح-، جادَلوا وقالوا: أَنُصَدِّق مثل تصديق ضعاف العقل والرأي، فنكون نحن وهم في السَّفَهِ سواء؟ فردَّ الله عليهم بأن السَّفَهَ مقصور عليهم، وهم لا يعلمون أن ما هم فيه هو الضلال والخسران.', 13, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (21, 2, 1, 1, 21, 'هؤلاء المنافقون إذا قابلوا المؤمنين قالوا: صدَّقنا بالإسلام مثلكم، وإذا انصرفوا وذهبوا إلى زعمائهم الكفرة المتمردين على الله أكَّدوا لهم أنهم على ملة الكفر لم يتركوها، وإنما كانوا يَسْتَخِفُّون بالمؤمنين، ويسخرون منهم.', 14, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (22, 2, 1, 1, 22, 'الله يستهزئ بهم ويُمهلهم؛ ليزدادوا ضلالا وحَيْرة وترددًا، ويجازيهم على استهزائهم بالمؤمنين.', 15, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (23, 2, 1, 1, 23, 'أولئك المنافقون باعوا أنفسهم في صفقة خاسرة، فأخذوا الكفر، وتركوا الإيمان، فما كسبوا شيئًا، بل خَسِروا الهداية. وهذا هو الخسران المبين.', 16, 1, 3, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (24, 2, 1, 1, 24, 'حال المنافقين الذين آمنوا -ظاهرًا لا باطنًا- برسالة محمد صلى الله عليه وسلم، ثم كفروا، فصاروا يتخبطون في ظلماتِ ضلالهم وهم لا يشعرون، ولا أمل لهم في الخروج منها، تُشْبه حالَ جماعة في ليلة مظلمة، وأوقد أحدهم نارًا عظيمة للدفء والإضاءة، فلما سطعت النار وأنارت ما حوله، انطفأت وأعتمت، فصار أصحابها في ظلمات لا يرون شيئًا، ولا يهتدون إلى طريق ولا مخرج.', 17, 1, 4, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (25, 2, 1, 1, 25, 'هم صُمٌّ عن سماع الحق سماع تدبر، بُكْم عن النطق به، عُمْي عن إبصار نور الهداية؛ لذلك لا يستطيعون الرجوع إلى الإيمان الذي تركوه، واستعاضوا عنه بالضلال.', 18, 1, 4, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (26, 2, 1, 1, 26, 'أو تُشْبه حالُ فريق آخر من المنافقين يظهر لهم الحق تارة، ويشكون فيه تارة أخرى، حالَ جماعة يمشون في العراء، فينصب عليهم مطر شديد، تصاحبه ظلمات بعضها فوق بعض، مع قصف الرعد، ولمعان البرق، والصواعق المحرقة، التي تجعلهم من شدة الهول يضعون أصابعهم في آذانهم؛ خوفًا من الهلاك. والله تعالى محيط بالكافرين لا يفوتونه ولا يعجزونه.', 19, 1, 4, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (27, 2, 1, 1, 27, 'يقارب البرق -من شدة لمعانه- أن يسلب أبصارهم، ومع ذلك فكلَّما أضاء لهم مشَوْا في ضوئه، وإذا ذهب أظلم الطريق عليهم فيقفون في أماكنهم. ولولا إمهال الله لهم لسلب سمعهم وأبصارهم، وهو قادر على ذلك في كل وقتٍ، إنه على كل شيء قدير.', 20, 1, 4, 3, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (28, 2, 1, 1, 28, 'نداء من الله للبشر جميعًا: أن اعبدوا الله الذي ربَّاكم بنعمه، وخافوه ولا تخالفوا دينه؛ فقد أوجدكم من العدم، وأوجد الذين من قبلكم؛ لتكونوا من المتقين الذين رضي الله عنهم ورضوا عنه.', 21, 1, 4, 4, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (29, 2, 1, 1, 29, 'ربكم الذي جعل لكم الأرض بساطًا؛ لتسهل حياتكم عليها، والسماء محكمة البناء، وأنزل المطر من السحاب فأخرج لكم به من ألوان الثمرات وأنواع النبات رزقًا لكم، فلا تجعلوا لله نظراء في العبادة، وأنتم تعلمون تفرُّده بالخلق والرزق، واستحقاقِه العبودية.', 22, 1, 4, 4, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (30, 2, 1, 1, 30, 'وإن كنتم -أيها الكافرون المعاندون- في شَكٍّ من القرآن الذي نَزَّلناه على عبدنا محمد صلى الله عليه وسلم، وتزعمون أنه ليس من عند الله، فهاتوا سورة تماثل سورة من القرآن، واستعينوا بمن تقدرون عليه مِن أعوانكم، إن كنتم صادقين في دعواكم.', 23, 1, 4, 4, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (31, 2, 1, 1, 31, 'فإن عجَزتم الآن -وستعجزون مستقبلا لا محالة- فاتقوا النار بالإيمان بالنبي صلى الله عليه وسلم وطاعة الله تعالى. هذه النار التي حَطَبُها الناس والحجارة، أُعِدَّتْ للكافرين بالله ورسله.', 24, 1, 4, 4, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (32, 2, 1, 1, 32, 'وأخبر -أيها الرسول- أهل الإيمان والعمل الصالح خبرًا يملؤهم سرورًا، بأن لهم في الآخرة حدائق عجيبة، تجري الأنهار تحت قصورها العالية وأشجارها الظليلة. كلَّما رزقهم الله فيها نوعًا من الفاكهة اللذيذة قالوا: قد رَزَقَنا الله هذا النوع من قبل، فإذا ذاقوه وجدوه شيئًا جديدًا في طعمه ولذته، وإن تشابه مع سابقه في اللون والمنظر والاسم. ولهم في الجنَّات زوجات مطهَّرات من كل ألوان الدنس الحسيِّ كالبول والحيض، والمعنوي كالكذب وسوء الخُلُق. وهم في الجنة ونعيمها دائمون، لا يموتون فيها ولا يخرجون منها.', 25, 1, 5, 4, NULL, 1, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (33, 2, 1, 1, 33, 'إن الله تعالى لا يستحيي من الحق أن يذكر شيئًا ما، قلَّ أو كثر، ولو كان تمثيلا بأصغر شيء، كالبعوضة والذباب ونحو ذلك، مما ضربه الله مثلا لِعَجْز كل ما يُعْبَد من دون الله. فأما المؤمنون فيعلمون حكمة الله في التمثيل بالصغير والكبير من خلقه، وأما الكفار فَيَسْخرون ويقولون: ما مراد الله مِن ضَرْب المثل بهذه الحشرات الحقيرة؟ ويجيبهم الله بأن المراد هو الاختبار، وتمييز المؤمن من الكافر؛ لذلك يصرف الله بهذا المثل ناسًا كثيرين عن الحق لسخريتهم منه، ويوفق به غيرهم إلى مزيد من الإيمان والهداية. والله تعالى لا يظلم أحدًا؛ لأنه لا يَصْرِف عن الحق إلا الخارجين عن طاعته.', 26, 1, 5, 4, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (34, 2, 1, 1, 34, 'الذين ينكثون عهد الله الذي أخذه عليهم بالتوحيد والطاعة، وقد أكَّده بإرسال الرسل، وإنزال الكتب، ويخالفون دين الله كقطع الأرحام ونشر الفساد في الأرض، أولئك هم الخاسرون في الدنيا والآخرة.', 27, 1, 5, 4, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (35, 2, 1, 1, 35, 'كيف تنكرون -أيُّها المشركون- وحدانية الله تعالى، وتشركون به غيره في العبادة مع البرهان القاطع عليها في أنفسكم؟ فلقد كنتم أمواتًا فأوجدكم ونفخ فيكم الحياة، ثم يميتكم بعد انقضاء آجالكم التي حددها لكم، ثم يعيدكم أحياء يوم البعث، ثم إليه ترجعون للحساب والجزاء.', 28, 1, 5, 4, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (36, 2, 1, 1, 36, 'اللهُ وحده الذي خَلَق لأجلكم كل ما في الأرض من النِّعم التي تنتفعون بها، ثم قصد إلى خلق السموات، فسوَّاهنَّ سبع سموات، وهو بكل شيء عليم. فعِلْمُه -سبحانه- محيط بجميع ما خلق.', 29, 1, 5, 4, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (37, 2, 1, 1, 37, 'واذكر -أيها الرسول- للناس حين قال ربك للملائكة: إني جاعل في الأرض قومًا يخلف بعضهم بعضًا لعمارتها. قالت: يا ربَّنا علِّمْنا وأَرْشِدْنا ما الحكمة في خلق هؤلاء، مع أنَّ من شأنهم الإفساد في الأرض واراقة الدماء ظلما وعدوانًا ونحن طوع أمرك، ننزِّهك التنزيه اللائق بحمدك وجلالك، ونمجِّدك بكل صفات الكمال والجلال؟ قال الله لهم: إني أعلم ما لا تعلمون من الحكمة البالغة في خلقهم.', 30, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (38, 2, 1, 1, 38, 'وبيانًا لفضل آدم عليه السلام علَّمه الله أسماء الأشياء كلها، ثم عرض مسمياتها على الملائكة قائلا لهم: أخبروني بأسماء هؤلاء الموجودات، إن كنتم صادقين في أنكم أَوْلى بالاستخلاف في الأرض منهم.', 31, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (39, 2, 1, 1, 39, 'قالت الملائكة: ننزِّهك يا ربَّنا، ليس لنا علم إلا ما علَّمتنا إياه. إنك أنت وحدك العليم بشئون خلقك، الحكيم في تدبيرك.', 32, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (40, 2, 1, 1, 40, 'قال الله: يا آدم أخبرهم بأسماء هذه الأشياء التي عجَزوا عن معرفتها. فلما أخبرهم آدم بها، قال الله للملائكة: لقد أخبرتكم أني أعلم ما خفي عنكم في السموات والأرض، وأعلم ما تظهرونه وما تخفونه.', 33, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (41, 2, 1, 1, 41, 'واذكر -أيها الرسول- للناس تكريم الله لآدم حين قال سبحانه للملائكة: اسجدوا لآدم إكرامًا له وإظهارًا لفضله، فأطاعوا جميعًا إلا إبليس امتنع عن السجود تكبرًا وحسدًا، فصار من الجاحدين بالله، العاصين لأمره.', 34, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (42, 2, 1, 1, 42, 'وقال الله: يا آدم اسكن أنت وزوجك حواء الجنة، وتمتعا بثمارها تمتعًا هنيئًا واسعًا في أي مكان تشاءان فيها، ولا تقربا هذه الشجرة حتى لا تقعا في المعصية، فتصيرا من المتجاوزين أمر الله.', 35, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (43, 2, 1, 1, 43, 'فأوقعهما الشيطان في الخطيئة: بأنْ وسوس لهما حتى أكلا من الشجرة، فتسبب في إخراجهما من الجنة ونعيمها. وقال الله لهم: اهبطوا إلى الأرض، يعادي بعضكم بعضًا -أي آدم وحواء والشيطان- ولكم في الأرض استقرار وإقامة، وانتفاع بما فيها إلى وقت انتهاء آجالكم.', 36, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (44, 2, 1, 1, 44, 'فتلقى آدمُ بالقبول كلماتٍ، ألهمه الله إياها توبة واستغفارًا، وهي قوله تعالى: {رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ (7:23)} فتاب الله عليه، وغفر له ذنبه إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم.', 37, 1, 6, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (45, 2, 1, 1, 45, 'قال الله لهم: اهبطوا من الجنة جميعًا، وسيأتيكم أنتم وذرياتكم المتعاقبة ما فيه هدايتكم إلى الحق. فمن عمل بها فلا خوف عليهم فيما يستقبلونه من أمر الآخرة ولا هم يحزنون على ما فاتهم من أمور الدنيا.', 38, 1, 7, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (46, 2, 1, 1, 46, 'والذين جحدوا وكذبوا بآياتنا المتلوة ودلائل توحيدنا، أولئك الذين يلازمون النار، هم فيها خالدون، لا يخرجون منها.', 39, 1, 7, 5, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (47, 2, 1, 1, 47, 'يا ذرية يعقوب اذكروا نعمي الكثيرة عليكم، واشكروا لي، وأتموا وصيتي لكم: بأن تؤمنوا بكتبي ورسلي جميعًا، وتعملوا بشرائعي. فإن فعلتم ذلك أُتمم لكم ما وعدتكم به من الرحمة في الدنيا، والنجاة في الآخرة. وإيَّايَ -وحدي- فخافوني، واحذروا نقمتي إن نقضتم العهد، وكفرتم بي.', 40, 1, 7, 6, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (48, 2, 1, 1, 48, 'وآمنوا- يا بني إسرائيل- بالقرآن الذي أنزَلْتُه على محمد نبي الله ورسوله، موافقًا لما تعلمونه من صحيح التوراة، ولا تكونوا أول فريق من أهل الكتاب يكفر به، ولا تستبدلوا بآياتي ثمنًا قليلا من حطام الدنيا الزائل، وإياي وحدي فاعملوا بطاعتي واتركوا معصيتي.', 41, 1, 7, 6, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (49, 2, 1, 1, 49, 'ولا تخلِطوا الحق الذي بيَّنته لكم بالباطل الذي افتريتموه، واحذروا كتمان الحق الصريح من صفة نبي الله ورسوله محمد صلى الله عليه وسلم التي في كتبكم، وأنتم تجدونها مكتوبة عندكم، فيما تعلمون من الكتب التي بأيديكم.', 42, 1, 7, 6, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (50, 2, 1, 1, 50, 'وادخلوا في دين الإسلام: بأن تقيموا الصلاة على الوجه الصحيح، كما جاء بها نبي الله ورسوله محمد صلى الله عليه وسلم، وتؤدوا الزكاة المفروضة على الوجه المشروع، وتكونوا مع الراكعين من أمته صلى الله عليه وسلم.', 43, 1, 7, 6, NULL, 2, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (51, 2, 1, 1, 51, 'ما أقبح حالَكم وحالَ علمائكم حين تأمرون الناس بعمل الخيرات، وتتركون أنفسكم، فلا تأمرونها بالخير العظيم، وهو الإسلام، وأنتم تقرءون التوراة، التي فيها صفات محمد صلى الله عليه وسلم، ووجوب الإيمان به!! أفلا تستعملون عقولكم استعمالا صحيحًا؟', 44, 1, 7, 6, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (52, 2, 1, 1, 52, 'واستعينوا في كل أموركم بالصبر بجميع أنواعه، وكذلك الصلاة. وإنها لشاقة إلا على الخاشعين.', 45, 1, 7, 6, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (53, 2, 1, 1, 53, 'الذين يخشون الله ويرجون ما عنده، ويوقنون أنهم ملاقو ربِّهم جلَّ وعلا بعد الموت، وأنهم إليه راجعون يوم القيامة للحساب والجزاء.', 46, 1, 7, 6, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (54, 2, 1, 1, 54, 'يا ذرية يعقوب تذكَّروا نعمي الكثيرة عليكم، واشكروا لي عليها، وتذكروا أني فَضَّلْتكم على عالَمي زمانكم بكثرة الأنبياء، والكتب المنزَّلة كالتوراة والإنجيل.', 47, 1, 7, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (55, 2, 1, 1, 55, 'وخافوا يوم القيامة، يوم لا يغني أحد عن أحد شيئًا، ولا يقبل الله شفاعة في الكافرين، ولا يقبل منهم فدية، ولو كانت أموال الأرض جميعًا، ولا يملك أحد في هذا اليوم أن يتقدم لنصرتهم وإنقاذهم من العذاب.', 48, 1, 7, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (56, 2, 1, 1, 56, 'واذكروا نعمتنا عليكم حين أنقذناكم من بطش فرعون وأتباعه، وهم يُذيقونكم أشدَّ العذاب، فيُكثِرون مِن ذَبْح أبنائكم، وترك بناتكم للخدمة والامتهان. وفي ذلك اختبار لكم من ربكم، وفي إنجائكم منه نعمة عظيمة، تستوجب شكر الله تعالى في كل عصوركم وأجيالكم.', 49, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (57, 2, 1, 1, 57, 'واذكروا نعمتنا عليكم، حين فَصَلْنا بسببكم البحر، وجعلنا فيه طرقًا يابسةً، فعبرتم، وأنقذناكم من فرعون وجنوده، ومن الهلاك في الماء. فلما دخل فرعون وجنوده طرقكم أهلكناهم في الماء أمام أعينكم.', 50, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (58, 2, 1, 1, 58, 'واذكروا نعمتنا عليكم: حين واعدنا موسى أربعين ليلة لإنزال التوراة هدايةً ونورًا لكم، فإذا بكم تنتهزون فرصة غيابه هذه المدة القليلة، وتجعلون العجل الذي صنعتموه بأيديكم معبودًا لكم من دون الله - وهذا أشنع الكفر بالله- وأنتم ظالمون باتخاذكم العجل إلهًا.', 51, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (59, 2, 1, 1, 59, 'ثمَّ تجاوزنا عن هذه الفعلة المنكرة، وقَبِلْنَا توبتكم بعد عودة موسى؛ رجاءَ أن تشكروا الله على نعمه وأفضاله، ولا تتمادوا في الكفر والطغيان.', 52, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (60, 2, 1, 1, 60, 'واذكروا نعمتنا عليكم حين أعطينا موسى الكتاب الفارق بين الحق والباطل -وهو التوراة-؛ لكي تهتدوا من الضلالة.', 53, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (61, 2, 1, 1, 61, 'واذكروا نعمتنا عليكم حين قال موسى لقومه: إنكم ظلمتم أنفسكم باتخاذكم العجل إلهًا، فتوبوا إلى خالقكم: بأن يَقْتل بعضكم بعضًا، وهذا خير لكم عند خالقكم من الخلود الأبدي في النار، فامتثلتم ذلك، فمنَّ الله عليكم بقَبول توبتكم. إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم.', 54, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (62, 2, 1, 1, 62, 'واذكروا إذ قلتم: يا موسى لن نصدقك في أن الكلام الذي نسمعه منك هو كلام الله، حتى نرى الله عِيَانًا، فنزلت نار من السماء رأيتموها بأعينكم، فقَتَلَتْكم بسبب ذنوبكم، وجُرْأتكم على الله تعالى.', 55, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (63, 2, 1, 1, 63, 'ثم أحييناكم مِن بعد موتكم بالصاعقة؛ لتشكروا نعمة الله عليكم، فهذا الموت عقوبة لهم، ثم بعثهم الله لاستيفاء آجالهم.', 56, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (64, 2, 1, 1, 64, 'واذكروا نعمتنا عليكم حين كنتم تتيهون في الأرض؛ إذ جعلنا السحاب مظللا عليكم من حَرِّ الشمس، وأنزلنا عليكم المنَّ، وهو شيء يشبه الصَّمغ طعمه كالعسل، وأنزلنا عليكم السَّلوى وهو طير يشبه السُّمانَى، وقلنا لكم: كلوا من طيِّبات ما رزقناكم، ولا تخالفوا دينكم، فلم تمتثلوا. وما ظلمونا بكفران النعم، ولكن كانوا أنفسهم يظلمون؛ لأن عاقبة الظلم عائدة عليهم.', 57, 1, 8, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (65, 2, 1, 1, 65, 'واذكروا نعمتنا عليكم حين قلنا: ادخلوا مدينة "بيت المقدس" فكلوا من طيباتها في أي مكان منها أكلا هنيئًا، وكونوا في دخولكم خاضعين لله، ذليلين له، وقولوا: ربَّنا ضَعْ عنَّا ذنوبنا، نستجب لكم ونعف ونسترها عليكم، وسنزيد المحسنين بأعمالهم خيرًا وثوابًا.', 58, 1, 9, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (66, 2, 1, 1, 66, 'فبدَّل الجائرون الضالون من بني إسرائيل قول الله، وحرَّفوا القول والفعل جميعًا، إذ دخلوا يزحفون على أستاههم وقالوا: حبة في شعرة، واستهزءوا بدين الله. فأنزل الله عليهم عذابًا من السماء؛ بسبب تمردهم وخروجهم عن طاعة الله.', 59, 1, 9, 7, NULL, 3, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (67, 2, 1, 1, 67, 'واذكروا نعمتنا عليكم -وأنتم عطاش في التِّيْه- حين دعانا موسى -بضراعة- أن نسقي قومه، فقلنا: اضرب بعصاك الحجر، فضرب، فانفجرت منه اثنتا عشرة عينًا، بعدد القبائل، مع إعلام كل قبيلة بالعين الخاصة بها حتى لا يتنازعوا. وقلنا لهم: كلوا واشربوا من رزق الله، ولا تسعوا في الأرض مفسدين.', 60, 1, 9, 8, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (68, 2, 1, 1, 68, 'واذكروا حين أنزلنا عليكم الطعام الحلو، والطير الشهي، فبطِرتم النعمة كعادتكم، وأصابكم الضيق والملل، فقلتم: يا موسى لن نصبر على طعام ثابت لا يتغير مع الأيام، فادع لنا ربك يخرج لنا من نبات الأرض طعامًا من البقول والخُضَر، والقثاء والحبوب التي تؤكل، والعدس، والبصل. قال موسى -مستنكرًا عليهم-: أتطلبون هذه الأطعمة التي هي أقل قدرًا، وتتركون هذا الرزق النافع الذي اختاره الله لكم؟ اهبطوا من هذه البادية إلى أي مدينة، تجدوا ما اشتهيتم كثيرًا في الحقول والأسواق. ولما هبطوا تبيَّن لهم أنهم يُقَدِّمون اختيارهم -في كل موطن- على اختيار الله، ويُؤْثِرون شهواتهم على ما اختاره الله لهم؛ لذلك لزمتهم صِفَةُ الذل وفقر النفوس، وانصرفوا ورجعوا بغضب من الله؛ لإعراضهم عن دين الله، ولأنهم كانوا يكفرون بآيات الله ويقتلون النبيين ظلمًا وعدوانًا؛ وذلك بسبب عصيانهم وتجاوزهم حدود ربهم.', 61, 1, 9, 8, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (69, 2, 1, 1, 69, 'إن المؤمنين من هذه الأمة، الذين صدَّقوا بالله ورسله، وعملوا بشرعه، والذين كانوا قبل بعثة محمد صلى الله عليه وسلم من الأمم السالفة من اليهود، والنصارى، والصابئين- وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه- هؤلاء جميعًا إذا صدَّقوا بالله تصديقًا صحيحًا خالصًا، وبيوم البعث والجزاء، وعملوا عملا مرضيًا عند الله، فثوابهم ثابت لهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من أمور الدنيا. وأما بعد بعثة محمد صلى الله عليه وسلم خاتمًا للنبيين والمرسلين إلى الناس كافة، فلا يقبل الله من أحد دينًا غير ما جاء به، وهو الإسلام.', 62, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (70, 2, 1, 1, 70, 'واذكروا -يا بني إسرائيل- حين أَخَذْنا العهد المؤكَّد منكم بالإيمان بالله وإفراده بالعبادة، ورفعنا جبل الطور فوقكم، وقلنا لكم: خذوا الكتاب الذي أعطيناكم بجدٍ واجتهاد واحفظوه، وإلا أطبقنا عليكم الجبل، ولا تنسوا التوراة قولا وعملا كي تتقوني وتخافوا عقابي.', 63, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (71, 2, 1, 1, 71, 'ثم خالفتم وعصيتم مرة أخرى، بعد أَخْذِ الميثاق ورَفْع الجبل كشأنكم دائمًا. فلولا فَضْلُ الله عليكم ورحمته بالتوبة، والتجاوز عن خطاياكم، لصرتم من الخاسرين في الدنيا والآخرة.', 64, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (72, 2, 1, 1, 72, 'ولقد علمتم -يا معشر اليهود- ما حلَّ من البأس بأسلافكم من أهل القرية التي عصت الله، فيما أخذه عليهم من تعظيم السبت، فاحتالوا لاصطياد السمك في يوم السبت، بوضع الشِّباك وحفر البِرَك، ثم اصطادوا السمك يوم الأحد حيلة إلى المحرم، فلما فعلوا ذلك، مسخهم الله قردة منبوذين.', 65, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (73, 2, 1, 1, 73, 'فجعلنا هذه القرية عبرة لمن بحضرتها من القرى، يبلغهم خبرها وما حلَّ بها، وعبرة لمن يعمل بعدها مثل تلك الذُّنوب، وجعلناها تذكرة للصالحين؛ ليعلموا أنهم على الحق، فيثبتوا عليه.', 66, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (74, 2, 1, 1, 74, 'واذكروا يا بني إسرائيل جناية أسلافكم، وكثرة تعنتهم وجدالهم لموسى عليه الصلاة والسلام، حين قال لهم: إن الله يأمركم أن تذبحوا بقرة، فقالوا -مستكبرين-: أتجعلنا موضعًا للسخرية والاستخفاف؟ فردَّ عليهم موسى بقوله: أستجير بالله أن أكون من المستهزئين.', 67, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (75, 2, 1, 1, 75, 'قالوا: ادع لنا ربَّك يوضح لنا صفة هذه البقرة، فأجابهم: إن الله يقول لكم: صفتها ألا تكون مسنَّة هَرِمة، ولا صغيرة فَتِيَّة، وإنما هي متوسطة بينهما، فسارِعوا إلى امتثال أمر ربكم.', 68, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (76, 2, 1, 1, 76, 'فعادوا إلى جدالهم قائلين: ادع لنا ربك يوضح لنا لونها. قال: إنه يقول: إنها بقرة صفراء شديدة الصُّفْرة، تَسُرُّ مَن ينظر إليها.', 69, 1, 10, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (77, 2, 1, 1, 77, 'قال بنو إسرائيل لموسى: ادع لنا ربك يوضح لنا صفات أخرى غير ما سبق؛ لأن البقر -بهذه الصفات- كثير فاشْتَبَهَ علينا ماذا نختار؟ وإننا -إن شاء الله- لمهتدون إلى البقرة المأمور بذبحها.', 70, 1, 11, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (78, 2, 1, 1, 78, 'قال لهم موسى: إن الله يقول: إنها بقرة غير مذللة للعمل في حراثة الأرض للزراعة، وغير معدة للسقي من الساقية، وخالية من العيوب جميعها، وليس فيها علامة من لون غير لون جلدها. قالوا: الآن جئت بحقيقة وصف البقرة، فاضطروا إلى ذبحها بعد طول المراوغة، وقد قاربوا ألا يفعلوا ذلك لعنادهم. وهكذا شددوا فشدَّد الله عليهم.', 71, 1, 11, 9, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (79, 2, 1, 1, 79, 'واذكروا إذ قتلتم نفسًا فتنازعتم بشأنها، كلٌّ يدفع عن نفسه تهمة القتل، والله مخرج ما كنتم تخفون مِن قَتْل القتيل.', 72, 1, 11, 10, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (80, 2, 1, 1, 80, 'فقلنا: اضربوا القتيل بجزء من هذه البقرة المذبوحة، فإن الله سيبعثه حيًا، ويخبركم عن قاتله. فضربوه ببعضها فأحياه الله وأخبر بقاتله. كذلك يُحيي الله الموتى يوم القيامة، ويريكم- يا بني إسرائيل- معجزاته الدالة على كمال قدرته تعالى؛ لكي تتفكروا بعقولكم، فتمتنعوا عن معاصيه.', 73, 1, 11, 10, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (81, 2, 1, 1, 81, 'ولكنكم لم تنتفعوا بذلك؛ إذ بعد كل هذه المعجزات الخارقة اشتدت قلوبكم وغلظت، فلم يَنْفُذ إليها خير، ولم تَلِنْ أمام الآيات الباهرة التي أريتكموها، حتى صارت قلوبكم مثل الحجارة الصمَّاء، بل هي أشد منها غلظة؛ لأن من الحجارة ما يتسع وينفرج حتى تنصبَّ منه المياه صبًا، فتصير أنهارًا جاريةً، ومن الحجارة ما يتصدع فينشق، فتخرج منه العيون والينابيع، ومن الحجارة ما يسقط من أعالي الجبال مِن خشية الله تعالى وتعظيمه. وما الله بغافل عما تعملون.', 74, 1, 11, 10, NULL, 4, 1);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (82, 2, 1, 1, 82, 'أيها المسلمون أنسيتم أفعال بني إسرائيل، فطمعت نفوسكم أن يصدِّق اليهودُ بدينكم؟ وقد كان علماؤهم يسمعون كلام الله من التوراة، ثم يحرفونه بِصَرْفِه إلى غير معناه الصحيح بعد ما عقلوا حقيقته، أو بتحريف ألفاظه، وهم يعلمون أنهم يحرفون كلام رب العالمين عمدًا وكذبًا.', 75, 1, 11, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (83, 2, 1, 1, 83, 'هؤلاء اليهود إذا لقوا الذين آمنوا قالوا بلسانهم: آمنَّا بدينكم ورسولكم المبشَّر به في التوراة، وإذا خلا بعض هؤلاء المنافقين من اليهود إلى بعض قالوا في إنكار: أتحدِّثون المؤمنين بما بيَّن الله لكم في التوراة من أمر محمد؛ لتكون لهم الحجة عليكم عند ربكم يوم القيامة؟ أفلا تفقهون فتحذروا؟', 76, 1, 11, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (84, 2, 1, 1, 84, 'أيفعلون كلَّ هذه الجرائم، ولا يعلمون أن الله يعلم جميع ما يخفونه وما يظهرونه؟', 77, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (85, 2, 1, 1, 85, 'ومن اليهود جماعة يجهلون القراءة والكتابة، ولا يعلمون التوراة وما فيها من صفات نبي الله ورسوله محمد صلى الله عليه وسلم، وما عندهم من ذلك إلا أكاذيبُ وظنون فاسدة.', 78, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (86, 2, 1, 1, 86, 'فهلاك ووعيد شديد لأحبار السوء من اليهود الذين يكتبون الكتاب بأيديهم، ثم يقولون: هذا من عند الله وهو مخالف لما أنزل الله على نبيِّه موسى عليه الصلاة والسلام؛ ليأخذوا في مقابل هذا عرض الدنيا. فلهم عقوبة مهلكة بسبب كتابتهم هذا الباطل بأيديهم، ولهم عقوبة مهلكة بسبب ما يأخذونه في المقابل من المال الحرام، كالرشوة وغيرها.', 79, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (87, 2, 1, 1, 87, 'وقال بنو إسرائيل: لن تصيبنا النار في الآخرة إلا أيامًا قليلة العدد. قل لهم -أيها الرسول مبطلا دعواهم-: أعندكم عهد من الله بهذا، فإن الله لا يخلف عهده؟ بل إنكم تقولون على الله ما لا تعلمون بافترائكم الكذب.', 80, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (88, 2, 1, 1, 88, 'فحُكْمُ الله ثابت: أن من ارتكب الآثام حتى جَرَّته إلى الكفر، واستولت عليه ذنوبه مِن جميع جوانبه وهذا لا يكون إلا فيمن أشرك بالله، فالمشركون والكفار هم الذين يلازمون نار جهنم ملازمة دائمةً لا تنقطع.', 81, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (89, 2, 1, 1, 89, 'وحكم الله الثابتُ في مقابل هذا: أنَّ الذين صدَّقوا بالله ورسله تصديقًا خالصًا، وعملوا الأعمال المتفقة مع شريعة الله التي أوحاها إلى رسله، هؤلاء يلازمون الجنة في الآخرة ملازمةً دائمةً لا تنقطع.', 82, 1, 12, 10, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (90, 2, 1, 1, 90, 'واذكروا يا بني إسرائيل حين أخَذْنا عليكم عهدًا مؤكدًا: بأن تعبدوا الله وحده لا شريك له، وأن تحسنوا للوالدين، وللأقربين، وللأولاد الذين مات آباؤهم وهم دون بلوغ الحلم، وللمساكين، وأن تقولوا للناس أطيب الكلام، مع أداء الصلاة وإيتاء الزكاة، ثم أَعْرَضْتم ونقضتم العهد -إلا قليلا منكم ثبت عليه- وأنتم مستمرون في إعراضكم.', 83, 1, 12, 11, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (91, 2, 1, 1, 91, 'واذكروا -يا بني إسرائيل- حين أَخَذْنا عليكم عهدًا مؤكدًا في التوراة: يحرم سفك بعضكم دم بعض، وإخراج بعضكم بعضًا من دياركم، ثم اعترفتم بذلك، وأنتم تشهدون على صحته.', 84, 1, 13, 11, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (92, 2, 1, 1, 92, 'ثم أنتم يا هؤلاء يقتل بعضكم بعضًا، ويُخرج بعضكم بعضًا من ديارهم، ويَتَقَوَّى كل فريق منكم على إخوانه بالأعداء بغيًا وعدوانًا. وأن يأتوكم أسارى في يد الأعداء سعيتم في تحريرهم من الأسر، بدفع الفدية، مع أنه محرم عليكم إخراجهم من ديارهم. ما أقبح ما تفعلون حين تؤمنون ببعض أحكام التوراة وتكفرون ببعضها! فليس جزاء مَن يفعل ذلك منكم إلا ذُلا وفضيحة في الدنيا. ويوم القيامة يردُّهم الله إلى أفظع العذاب في النار. وما الله بغافل عما تعملون.', 85, 1, 13, 11, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (93, 2, 1, 1, 93, 'أولئك هم الذين آثروا الحياة الدنيا على الآخرة، فلا يخفف عنهم العذاب، وليس لهم ناصر ينصرهم مِن عذاب الله.', 86, 1, 13, 11, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (94, 2, 1, 1, 94, 'ولقد أعطينا موسى التوراة، وأتبعناه برسل من بني إسرائيل، وأعطينا عيسى ابن مريم المعجزات الواضحات، وقوَّيناه بجبريل عليه السلام. أفكلما جاءكم رسول بوحي من عند الله لا يوافق أهواءكم، استعليتم عليه، فكذَّبتم فريقًا وتقتلون فريقًا؟', 87, 1, 13, 12, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (95, 2, 1, 1, 95, 'وقال بنو إسرائيل لنبي الله ورسوله محمد صلى الله عليه وسلم: قلوبنا مغطاة، لا يَنْفُذ إليها قولك. وليس الأمر كما ادَّعَوْا، بل قلوبهم ملعونة، مطبوع عليها، وهم مطرودون من رحمة الله بسبب جحودهم، فلا يؤمنون إلا إيمانًا قليلا لا ينفعهم.', 88, 1, 13, 12, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (96, 2, 1, 1, 96, 'وحين جاءهم القرأن من عند الله مصدقا لما معهم من التوراة جحدوه، وأنكروا نبوة محمد صلى الله عليه وسلم، وكانوا قبل بعثته يستنصرون به على مشركي العرب، ويقولون: قَرُبَ مبعث نبيِّ آخرِ الزمان، وسنتبعه ونقاتلكم معه. فلمَّا جاءهم الرسول الذي عرفوا صفاتِه وصِدْقَه كفروا به وكذبوه. فلعنةُ الله على كل مَن كفر بنبي الله ورسوله محمد صلى الله عليه وسلم، وكتابه الذي أوحاه الله إليه.', 89, 1, 14, 12, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (97, 2, 1, 1, 97, 'قَبُحَ ما اختاره بنو إسرائيل لأنفسهم؛ إذ استبدلوا الكفر بالإيمان ظلمًا وحسدًا لإنزال الله من فضله القرآن على نبي الله ورسوله محمد صلى الله عليه وسلم، فرجعوا بغضب من الله عليهم بسبب جحودهم بالنبي محمد صلى الله عليه وسلم، بعد غضبه عليهم بسبب تحريفهم التوراة. وللجاحدين نبوَّة محمد صلى الله عليه وسلم عذابٌ يذلُّهم ويخزيهم.', 90, 1, 14, 12, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (98, 2, 1, 1, 98, 'وإذا قال بعض المسلمين لليهود: صدِّقوا بما أنزل الله من القرآن، قالوا: نحن نصدِّق بما أنزل الله على أنبيائنا، ويجحدون ما أنزل الله بعد ذلك، وهو الحق مصدقًا لما معهم. فلو كانوا يؤمنون بكتبهم حقًا لآمنوا بالقرآن الذي صدَّقها. قل لهم -يا محمد-: إن كنتم مؤمنين بما أنزل الله عليكم، فلماذا قتلتم أنبياء الله مِن قبل؟', 91, 1, 14, 12, NULL, 5, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (99, 2, 1, 1, 99, 'ولقد جاءكم نبي الله موسى بالمعجزات الواضحات الدالة على صدقه، كالطوفان والجراد والقُمَّل والضفادع، وغير ذلك مما ذكره الله في القرآن العظيم، ومع ذلك اتخذتم العجل معبودًا، بعد ذهاب موسى إلى ميقات ربه، وأنتم متجاوزون حدود الله.', 92, 1, 14, 12, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (100, 2, 1, 1, 100, 'واذكروا حين أَخَذْنا عليكم عهدًا مؤكدًا بقَبول ما جاءكم به موسى من التوراة، فنقضتم العهد، فرفعنا جبل الطور فوق رؤوسكم، وقلنا لكم: خذوا ما آتيناكم بجدٍّ، واسمعوا وأطيعوا، وإلا أسقطنا الجبل عليكم، فقلتم: سمعنا قولك وعصينا أمرك؛ لأن عبادة العجل قد امتزجت بقلوبكم بسبب تماديكم في الكفر. قل لهم -أيها الرسول-: قَبُحَ ما يأمركم به إيمانكم من الكفر والضلال، إن كنتم مصدِّقين بما أنزل الله عليكم.', 93, 1, 14, 12, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (101, 2, 1, 1, 101, 'قل -أيها الرسول- لليهود الذين يدَّعون أن الجنة خاصة بهم؛ لزعمهم أنهم أولياء الله من دون الناس، وأنهم أبناؤه وأحباؤه: إن كان الأمر كذلك فادْعُوا على الكاذبين منكم أو من غيركم بالموت، إن كنتم صادقين في دعواكم هذه.', 94, 1, 15, 12, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (102, 2, 1, 1, 102, 'ولن يفعلوا ذلك أبدًا؛ لما يعرفونه من صدق النبي محمد صلى الله عليه وسلم ومن كذبهم وافترائهم، وبسبب ما ارتكبوه من الكفر والعصيان، المؤَدِّيَيْن إلى حرمانهم من الجنة ودخول النار. والله تعالى عليم بالظالمين من عباده، وسيجازيهم على ذلك.', 95, 1, 15, 12, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (103, 2, 1, 1, 103, 'ولتعلمَنَّ -أيها الرسول- أن اليهود أشد الناس رغبة في طول الحياة أيًّا كانت هذه الحياة من الذلَّة والمهانة، بل تزيد رغبتهم في طول الحياة على رغبات المشركين. يتمنى اليهودي أن يعيش ألف سنة، ولا يُبْعده هذا العمر الطويل إن حصل من عذاب الله. والله تعالى لا يخفى عليه شيء من أعمالهم وسيجازيهم عليها بما يستحقون من العذاب.', 96, 1, 15, 12, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (104, 2, 1, 1, 104, 'قل-أيها الرسول- لليهود حين قالوا: إن جبريل هو عدونا من الملائكة: من كان عدوًا لجبريل فإنه نزَّل القرآن على قلبك بإذن الله تعالى مصدِّقًا لما سبقه من كتب الله، وهاديًا إلى الحق، ومبشرًا للمصدِّقين به بكل خير في الدنيا والآخرة.', 97, 1, 15, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (105, 2, 1, 1, 105, 'من عادى الله وملائكته، ورسله من الملائكة أو البشر، وبخاصة المَلَكان جبريلُ وميكالُ؛ لأن اليهود زعموا أن جبريل عدوهم، وميكال وليُّهم، فأعلمهم الله أنه من عادى واحدًا منهما فقد عادى الآخر، وعادى الله أيضًا، فإن الله عدو للجاحدين ما أنزل على رسوله محمد صلى الله عليه وسلم.', 98, 1, 15, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (106, 2, 1, 1, 106, 'ولقد أنزلنا إليك-أيها الرسول- آيات بينات واضحات تدل على أنّك رسول من الله صدقا وحقا، وما ينكر تلك الآيات إلا الخارجون عن دين الله.', 99, 1, 15, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (107, 2, 1, 1, 107, 'ما أقبح حال بني إسرائيل في نقضهم للعهود!! فكلما عاهدوا عهدًا طرح ذلك العهد فريق منهم، ونقضوه، فتراهم يُبْرِمون العهد اليوم وينقضونه غدًا، بل أكثرهم لا يصدِّقون بما جاء به نبي الله ورسوله محمد صلى الله عليه وسلم.', 100, 1, 15, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (108, 2, 1, 1, 108, 'ولما جاءهم محمد رسول الله صلى الله عليه وسلم بالقرآن الموافق لما معهم من التوراة طرح فريق منهم كتاب الله، وجعلوه وراء ظهورهم، شأنهم شأن الجهال الذين لا يعلمون حقيقته.', 101, 1, 15, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (109, 2, 1, 1, 109, 'واتبع اليهود ما تُحَدِّث الشياطينُ به السحرةَ على عهد ملك سليمان بن داود. وما كفر سليمان وما تَعَلَّم السِّحر، ولكنَّ الشياطين هم الذين كفروا بالله حين علَّموا الناس السحر؛ إفسادًا لدينهم. وكذلك اتبع اليهود السِّحر الذي أُنزل على الملَكَين هاروت وماروت، بأرض "بابل" في "العراق"؛ امتحانًا وابتلاء من الله لعباده، وما يعلِّم الملكان من أحد حتى ينصحاه ويحذِّراه من تعلم السحر، ويقولا له: لا تكفر بتعلم السِّحر وطاعة الشياطين. فيتعلم الناس من الملكين ما يُحْدِثون به الكراهية بين الزوجين حتى يتفرقا. ولا يستطيع السحرة أن يضروا به أحدًا إلا بإذن الله وقضائه. وما يتعلم السحرة إلا شرًا يضرهم ولا ينفعهم، وقد نقلته الشياطين إلى اليهود، فشاع فيهم حتى فضَّلوه على كتاب الله. ولقد علم اليهود أن من اختار السِّحر وترك الحق ما له في الآخرة من نصيب في الخير. ولبئس ما باعوا به أنفسهم من السحر والكفر عوضًا عن الإيمان ومتابعة الرسول، لو كان لهم عِلْمٌ يثمر العمل بما وُعِظوا به.', 102, 1, 16, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (110, 2, 1, 1, 110, 'ولو أن اليهود آمنوا وخافوا الله لأيقنوا أن ثواب الله خير لهم من السِّحر ومما اكتسبوه به، لو كانوا يعلمون ما يحصل بالإيمان والتقوى من الثواب والجزاء علما حقيقيا لآمنوا.', 103, 1, 16, 13, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (111, 2, 1, 1, 111, 'يا أيها الذين آمنوا لا تقولوا للرسول محمد صلى الله عليه وسلم: راعنا، أي: راعنا سمعك، فافهم عنا وأفهمنا؛ لأن اليهود كانوا يقولونها للنبي صلى الله عليه وسلم يلوون ألسنتهم بها، يقصدون سبَّه ونسبته إلى الرعونة، وقولوا- أيها المؤمنون- بدلا منها: انظرنا، أي انظر إلينا وتعهَّدْنا، وهي تؤدي المعنى المطلوب نفسه واسمعوا ما يتلى عليكم من كتاب ربكم وافهموه. وللجاحدين عذاب موجع.', 104, 1, 16, 14, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (112, 2, 1, 1, 112, 'ما يحب الكفار من أهل الكتاب والمشركين أن يُنزَّل عليكم أدنى خير من ربكم قرآنًا أو علمًا، أو نصرًا أو بشارة. والله يختص برحمته مَن يشاء مِن عباده بالنبوة والرسالة. والله ذو العطاء الكثير الواسع.', 105, 1, 16, 14, NULL, 6, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (113, 2, 1, 1, 113, 'ما نبدِّل من آية أو نُزِلها من القلوب والأذهان نأت بأنفع لكم منها، أو نأت بمثلها في التكليف والثواب، ولكلٍ حكمة. ألم تعلم -أيها النبي- أنت وأمتك أن الله قادر لا يعجزه شيء؟', 106, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (114, 2, 1, 1, 114, 'أما علمتَ -أيها النبي- أنت وأمتك أن الله تعالى هو المالك المتصرف في السموات والأرض؟ يفعل ما يشاء، ويحكم ما يريد، ويأمر عباده وينهاهم كيفما شاء، وعليهم الطاعة والقَبول. وليعلم من عصى أن ليس لأحد من دون الله من وليٍّ يتولاهم، ولا نصير يمنعهم من عذاب الله.', 107, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (115, 2, 1, 1, 115, 'بل أتريدون- أيها الناس- أن تطلبوا من رسولكم محمد صلى الله عليه وسلم أشياء بقصد العناد والمكابرة، كما طُلِبَ مثل ذلك من موسى. علموا أن من يختر الكفر ويترك الإيمان فقد خرج عن صراط الله المستقيم إلى الجهل والضَّلال.', 108, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (116, 2, 1, 1, 116, 'تمنى كثير من أهل الكتاب أن يرجعوكم بعد إيمانكم كفارًا كما كنتم من قبلُ تعبدون الأصنام؛ بسبب الحقد الذي امتلأت به نفوسهم من بعد ما تبيَّن لهم صدق نبي الله ورسوله محمد صلى الله عليه وسلم فيما جاء به، فتجاوزوا عمَّا كان منهم من إساءة وخطأ، واصفحوا عن جهلهم، حتى يأتي الله بحكمه فيهم بقتالهم (وقد جاء ووقع)، وسيعاقبهم لسوء أفعالهم. إن الله على كل شيء قدير لا يعجزه شيء.', 109, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (117, 2, 1, 1, 117, 'واشتغلوا -أيها المؤمنون- بأداء الصلاة على وجهها الصحيح، وإعطاء الزكاة المفروضة. واعلموا أنَّ كل خير تقدمونه لأنفسكم تجدون ثوابه عند الله في الآخرة. إنه تعالى بصير بكل أعمالكم، وسيجازيكم عليها.', 110, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (118, 2, 1, 1, 118, 'ادَّعى كلٌّ من اليهود والنصارى أن الجنة خاصة بطائفته لا يدخلها غيرهم، تلك أوهامهم الفاسدة. قل لهم -أيها الرسول-: أحضروا دليلكم على صحة ما تدَّعون إن كنتم صادقين في دعواكم.', 111, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (119, 2, 1, 1, 119, 'ليس الأمر كما زعموا أنَّ الجنة تختص بطائفة دون غيرها، وإنما يدخل الجنَّة مَن أخلص لله وحده لا شريك له، وهو متبع للرسول محمد صلى الله عليه وسلم في كل أقواله وأعماله. فمن فعل ذلك فله ثواب عمله عند ربه في الآخرة، وهو دخول الجنة، وهم لا يخافون فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.', 112, 1, 17, 14, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (120, 2, 1, 1, 120, 'وقالت اليهود: ليست النصارى على شيء من الدين الصحيح، وكذلك قالت النصارى في اليهود وهم يقرؤون التوراة والإنجيل، وفيهما وجوب الإيمان بالأنبياء جميعًا. كذلك قال الذين لا يعلمون من مشركي العرب وغيرهم مثل قولهم، أي قالوا لكل ذي دين: لست على شيء، فالله يفصل بينهم يوم القيامة فيما اختلفوا فيه مِن أمر الدين، ويجازي كلا بعمله.', 113, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (121, 2, 1, 1, 121, 'لا أحد أظلم من الذين منعوا ذِكْرَ الله في المساجد من إقام الصلاة، وتلاوة القرآن، ونحو ذلك، وجدُّوا في تخريبها بالهدم أو الإغلاق، أو بمنع المؤمنين منها. أولئك الظالمون ما كان ينبغي لهم أن يدخلوا المساجد إلا على خوف ووجل من العقوبة، لهم بذلك صَغار وفضيحة في الدنيا، ولهم في الآخرة عذاب شديد.', 114, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (122, 2, 1, 1, 122, 'ولله جهتا شروق الشمس وغروبها وما بينهما، فهو مالك الأرض كلها. فأي جهة توجهتم إليها في الصلاة بأمر الله لكم فإنكم مبتغون وجهه، لم تخرجوا عن ملكه وطاعته. إن الله واسع الرحمة بعباده، عليم بأفعالهم، لا يغيب عنه منها شيء.', 115, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (123, 2, 1, 1, 123, 'وقالت اليهود والنصارى والمشركون: اتخذ الله لنفسه ولدًا، تنزَّه الله -سبحانه- عن هذا القول الباطل، بل كل مَن في السموات والأرض ملكه وعبيده، وهم جميعًا خاضعون له، مسخَّرون تحت تدبيره.', 116, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (124, 2, 1, 1, 124, 'والله تعالى هو خالق السموات والأرض على غير مثال سبق. وإذا قدَّر أمرًا وأراد كونه فإنما يقول له: "كن" فيكون.', 117, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (125, 2, 1, 1, 125, 'وقال الجهلة من أهل الكتاب وغيرهم لنبي الله ورسوله محمد صلى الله عليه وسلم على سبيل العناد: هلا يكلمنا الله مباشرة ليخبرنا أنك رسوله، أو تأتينا معجزة من الله تدل على صدقك. ومثل هذا القول قالته الأمم من قبلُ لرسلها عنادًا ومكابرة؛ بسبب تشابه قلوب السابقين واللاحقين في الكفر والضَّلال، قد أوضحنا الآيات للذين يصدِّقون تصديقًا جازمًا؛ لكونهم مؤمنين بالله تعالى، متَّبعين ما شرعه لهم.', 118, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (126, 2, 1, 1, 126, 'إنا أرسلناك -أيها الرسول- بالدين الحق المؤيد بالحجج والمعجزات، فبلِّغه للناس مع تبشير المؤمنين بخيري الدنيا والآخرة، وتخويف المعاندين بما ينتظرهم من عذاب الله، ولست -بعد البلاغ- مسئولا عن كفر مَن كفر بك؛ فإنهم يدخلون النار يوم القيامة، ولا يخرجون منها.', 119, 1, 18, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (127, 2, 1, 1, 127, 'ولن ترضى عنك -أيها الرسول- اليهود ولا النصارى إلا إذا تركت دينك واتبعتَ دينهم. قل لهم: إن دين الإسلام هو الدين الصحيح. ولئن اتبعت أهواء هؤلاء بعد الذي جاءك من الوحي ما لك عند الله مِن وليٍّ ينفعك، ولا نصير ينصرك. هذا موجه إلى الأمّة عامة وإن كان خطابًا للنبي صلى الله عليه وسلم.', 120, 1, 19, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (128, 2, 1, 1, 128, 'الذين أعطيناهم الكتاب من اليهود والنصارى، يقرؤونه القراءة الصحيحة، ويتبعونه حق الاتباع، ويؤمنون بما جاء فيه من الإيمان برسل الله، ومنهم خاتمهم نبينا ورسولنا محمد صلى الله عليه وسلم، ولا يحرفون ولا يبدِّلون ما جاء فيه. هؤلاء هم الذين يؤمنون بالنبي محمد صلى الله عليه وسلم وبما أنزل عليه، وأما الذين بدَّلوا بعض الكتاب وكتموا بعضه، فهؤلاء كفار بنبي الله محمد صلى الله عليه وسلم وبما أنزل عليه، ومن يكفر به فأولئك هم أشد الناس خسرانًا عند الله.', 121, 1, 19, 15, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (129, 2, 1, 1, 129, 'يا ذرية يعقوب اذكروا نعمي الكثيرة عليكم، وأني فَضَّلتكم على عالَمي زمانكم بكثرة أنبيائكم، وما أُنزل عليهم من الكتب.', 122, 1, 19, 16, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (130, 2, 1, 1, 130, 'وخافوا أهوال يوم الحساب إذ لا تغني نفس عن نفس شيئًا، ولا يقبل الله منها فدية تنجيها من العذاب، ولا تنفعها وساطة، ولا أحد ينصرها.', 123, 1, 19, 16, NULL, 7, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (131, 2, 1, 1, 131, 'واذكر-أيها النبي- حين اختبر الله إبراهيم بما شرع له من تكاليف، فأدَّاها وقام بها خير قيام. قال الله له: إني جاعلك قدوة للناس. قال إبراهيم: ربِّ اجعل بعض نسلي أئمة فضلا منك، فأجابه الله سبحانه أنه لا تحصل للظالمين الإمامةُ في الدين.', 124, 1, 19, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (132, 2, 1, 1, 132, 'واذكر -أيها النبي- حين جعلنا الكعبة مرجعًا للناس، يأتونه، ثم يرجعون إلى أهليهم، ثم يعودون إليه، ومجمعًا لهم في الحج والعمرة والطواف والصلاة، وأمنًا لهم، لا يُغِير عليهم عدو فيه. وقلنا: اتخِذوا من مقام إبراهيم مكانًا للصلاة فيه، وهو الحجر الذي وقف عليه إبراهيم عند بنائه الكعبة. وأوحينا إلى إبراهيم وابنه إسماعيل: أن طهِّرا بيتي من كل رجس ودنس؛ للمتعبدين فيه بالطواف حول الكعبة، أو الاعتكاف في المسجد، والصلاة فيه.', 125, 1, 19, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (133, 2, 1, 1, 133, 'واذكر -أيها النبي- حين قال إبراهيم داعيًا: ربِّ اجعل "مكة" بلدًا آمنًا من الخوف، وارزق أهله من أنواع الثمرات، وخُصَّ بهذا الرزق مَن آمن منهم بالله واليوم الآخر. قال الله: ومن كفر منهم فأرزقه في الدنيا وأُمتعه متاعًا قليلا ثم أُلجئُه مرغمًا إلى عذاب النار. وبئس المرجع والمقام هذا المصير.', 126, 1, 19, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (134, 2, 1, 1, 134, 'واذكر -أيها النبي- حين رفع إبراهيم وإسماعيل أسس الكعبة، وهما يدعوان الله في خشوع: ربنا تقبل منَّا صالح أعمالنا ودعاءنا، إنك أنت السميع لأقوال عبادك، العليم بأحوالهم.', 127, 1, 20, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (135, 2, 1, 1, 135, 'ربنا واجعلنا ثابتَيْن على الإسلام، منقادَيْن لأحكامك، واجعل من ذريتنا أمة منقادة لك، بالإيمان، وبصِّرْنا بمعالم عبادتنا لك، وتجاوز عن ذنوبنا. إنك أنت كثير التوبة والرحمة لعبادك.', 128, 1, 20, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (136, 2, 1, 1, 136, 'ربنا وابعث في هذه الأمة رسولا من ذرية إسماعيل يتلو عليهم آياتك ويعلمهم القرآن والسنة، ويطهرهم من الشرك وسوء الأخلاق. إنك أنت العزيز الذي لا يمتنع عليه شيء، الحكيم الذي يضع الأشياء في مواضعها.', 129, 1, 20, 16, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (137, 2, 1, 1, 137, 'ولا أحد يُعرض عن دين إبراهيم -وهو الإسلام- إلا سفيه جاهل، ولقد اخترنا إبراهيم في الدنيا نبيًّا ورسولا وإنه في الآخرة لمن الصالحين الذين لهم أعلى الدرجات.', 130, 1, 20, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (138, 2, 1, 1, 138, 'وسبب هذا الاختيار مسارعته للإسلام دون تردد، حين قال له ربه: أخلص نفسك لله منقادًا له. فاستجاب إبراهيم وقال: أسلمت لرب العالمين إخلاصًا وتوحيدًا ومحبة وإنابة.', 131, 1, 20, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (139, 2, 1, 1, 139, 'وحثَّ إبراهيمُ ويعقوبُ أبناءهما على الثبات على الإسلام قائلَيْن: يا أبناءنا إن الله اختار لكم هذا الدين- وهو دين الإسلام الذي جاء به محمد صلى الله عليه وسلم- فلا تفارقوه أيام حياتكم، ولا يأتكم الموت إلا وأنتم عليه.', 132, 1, 20, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (140, 2, 1, 1, 140, 'أكنتم أيها اليهود حاضرين حين جاء الموتُ يعقوبَ، إذ جمع أبناءه وسألهم ما تعبدون من بعد موتي؟ قالوا: نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلهًا واحدًا، ونحن له منقادون خاضعون.', 133, 1, 20, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (141, 2, 1, 1, 141, 'تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم، ولكم أعمَالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم، وكلٌّ سيجازى بما فعله، لا يؤاخذ أحد بذنب أحد، ولا ينفعُ أحدًا إلا إيمانُه وتقواه.', 134, 1, 20, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (142, 2, 1, 1, 142, 'وقالت اليهود لأمَّة محمد صلى الله عليه وسلم: ادخلوا في دين اليهودية تجدوا الهداية، وقالت النصارى لهم مثل ذلك. قل لهم -أيها الرسول-: بل الهداية أن نتبع- جميعًا- ملة إبراهيم، الذي مال عن كل دين باطل إلى دين الحق، وما كان من المشركين بالله تعالى.', 135, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (143, 2, 1, 1, 143, 'قولوا -أيها المؤمنون- لهؤلاء اليهود والنَّصارى: صدَّقنا بالله الواحد المعبود بحق، وبما أنزل إلينا من القرآن الذي أوحاه الله إلى نبيه ورسوله محمد صلى الله عليه وسلم، وما أنزل من الصحف إلى إبراهيم وابنيه إسماعيل وإسحاق، وإلى يعقوب والأسباط -وهم الأنبياء مِن ولد يعقوب الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة- وما أُعطي موسى من التوراة، وعيسى من الإنجيل، وما أُعطي الأنبياء جميعًا من وحي ربهم، لا نفرق بين أحد منهم في الإيمان، ونحن خاضعون لله بالطاعة والعبادة.', 136, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (144, 2, 1, 1, 144, 'فإنْ آمن الكفار من اليهود والنصارى وغيرهم بمثل الذي آمنتم به، مما جاء به الرسول، فقد اهتدوا إلى الحق، وإن أعرضوا فإنما هم في خلاف شديد، فسيكفيك الله -أيها الرسول- شرَّهم وينصرك عليهم، وهو السميع لأقوالكم، العليم بأحوالكم.', 137, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (145, 2, 1, 1, 145, 'الزموا دين الله الذي فطركم عليه، فليس هناك أحسنُ مِن فطرة الله التي فطر الناس عليها، فالزموها وقولوا نحن خاضعون مطيعون لربنا في اتباعنا ملَّة إبراهيم.', 138, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (146, 2, 1, 1, 146, 'قل -أيها الرسول لأهل الكتاب-: أتجادلوننا في توحيد الله والإخلاص له، وهو رب العالمين جميعًا، لا يختص بقوم دون قوم، ولنا أعمالنا ولكم أعمالكم، ونحن لله مخلصو العبادة والطَّاعة لا نشرك به شيئًا، ولا نعبد أحدًا غيره.', 139, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (147, 2, 1, 1, 147, 'بل أتقولون مجادلين في الله: إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط- وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة من ولد يعقوب- كانوا على دين اليهود أو النصارى؟ وهذا كذب؛ فقد بُعِثوا وماتوا قبل نزول التوراة والإنجيل. قل لهم -أيها الرسول-: أأنتم أعلم بدينهم أم الله تعالى؟ وقد أخبر في القرآن بأنهم كانوا حنفاء مسلمين، ولا أحد أظلم منكم حين تخفون شهادة ثابتة عندكم من الله تعالى، وتدَّعون خلافها افتراء على الله. وما الله بغافل عن شيء من أعمالكم، بل هو مُحْصٍ لها ومجازيكم عليها.', 140, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (148, 2, 1, 1, 148, 'تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم ولكم أعمالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم. وفي الآية قطع للتعلق بالمخلوقين، وعدم الاغترار بالانتساب إليهم، وأن العبرة بالإيمان بالله وعبادته وحده، واتباع رسله، وأن من كفر برسول منهم فقد كفر بسائر الرسل.', 141, 1, 21, 17, NULL, 8, 2);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (149, 2, 1, 2, 149, 'سيقول الجهال وضعاف العقول من اليهود وأمثالهم، في سخرية واعتراض: ما الذي صرف هؤلاء المسلمين عن قبلتهم التي كانوا يُصَلُّون إلى جهتها أول الإسلام؛ (وهي "بيت المقدس") قل لهم -أيها الرسول-: المشرق والمغرب وما بينهما ملك لله، فليست جهة من الجهات خارجة عن ملكه، يهدي مَن يشاء من عباده إلى طريق الهداية القويم. وفي هذا إشعار بأن الشأن كله لله في امتثال أوامره، فحيثما وَجَّهَنا تَوَجَّهْنا.', 142, 1, 22, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (150, 2, 1, 2, 150, 'وكما هديناكم -أيها المسلمون- إلى الطريق الصحيح في الدين، جعلناكم أمة خيارًا عدولا لتشهدوا على الأمم في الآخرة أن رسلهم بلَّغتهم رسالات ربهم، ويكون الرسول في الآخرة كذلك شهيدًا عليكم أنَّه بلَّغكم رسالة ربه. وما جعلنا -أيها الرسول- قبلة "بيت المقدس" التي كنت عليها، ثم صرفناك عنها إلى الكعبة بـ "مكة"، إلا ليظهر ما علمناه في الأزل؛ علما يتعلق به الثواب والعقاب لنميز مَن يتبعك ويطيعك ويستقبل معك حيث توجهت، ومَن هو ضعيف الإيمان فينقلب مرتدًا عن دينه لشكه ونفاقه. وإن هذه الحال التي هي تحول المسلم في صلاته من استقبال بيت المقدس إلى استقبال الكعبة لثقيلة شاقة إلا على الذين هداهم ومنّ عليهم بالإيمان والتقوى وما كان الله ليضيع إيمانكم به واتباعكم لرسوله، ويبطل صلاتكم إلى القبلة السابقة. إنه سبحانه وتعالى بالناس لرءوف رحيم.', 143, 1, 22, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (151, 2, 1, 2, 151, 'قد نرى تحوُّل وجهك -أيها الرسول- في جهة السماء، مرة بعد مرة؛ انتظارًا لنزول الوحي إليك في شأن القبلة، فلنصرفنك عن "بيت المقدس" إلى قبلة تحبها وترضاها، وهي وجهة المسجد الحرام بـ "مكة"، فولِّ وجهك إليها. وفي أي مكان كنتم -أيها المسلمون- وأردتم الصلاة فتوجهوا نحو المسجد الحرام. وإن الذين أعطاهم الله علم الكتاب من اليهود والنصارى لَيعلمون أن تحويلك إلى الكعبة هو الحق الثابت في كتبهم. وما الله بغافل عما يعمل هؤلاء المعترضون المشككون، وسيجازيهم على ذلك.', 144, 1, 22, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (152, 2, 1, 2, 152, 'ولئن جئت -أيها الرسول- الذين أُعطوا التوراة والإنجيل بكل حجة وبرهان على أن توجُّهك إلى الكعبة في الصلاة هو الحق من عند الله، ما تبعوا قبلتك عنادًا واستكبارًا، وما أنت بتابع قبلتهم مرة أخرى، وما بعضهم بتابع قبلة بعض. ولئن اتبعت أهواءهم في شأن القبلة وغيرها بعد ما جاءك من العلم بأنك على الحق وهم على الباطل، إنك حينئذ لمن الظالمين لأنفسهم. وهذا خطاب لجميع الأمة وهو تهديد ووعيد لمن يتبع أهواء المخالفين لشريعة الإسلام.', 145, 1, 22, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (153, 2, 1, 2, 153, 'الذين أعطيناهم التوراة والإنجيل من أحبار اليهود وعلماء النصارى يعرفون أنَّ محمدًا صلى الله عليه وسلم رسول الله بأوصافه المذكورة في كتبهم، مثل معرفتهم بأبنائهم. وإن فريقًا منهم ليكتمون الحق وهم يعلمون صِدْقه، وثبوت أوصافه.', 146, 1, 23, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (154, 2, 1, 2, 154, 'الذي أنزل إليك -أيها النبي- هو الحق من ربك، فلا تكونن من الشاكين فيه. وهذا وإن كان خطابا للرسول صلى الله عليه وسلم فهو موجه للأمة.', 147, 1, 23, 18, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (155, 2, 1, 2, 155, 'ولكل أمة من الأمم قبلة يتوجَّه إليها كل واحد منها في صلاته، فبادروا - أيها المؤمنون- متسابقين إلى فِعْل الأعمال الصالحة التي شرعها الله لكم في دين الإسلام. وسيجمعكم الله جميعا يوم القيامة من أي موضع كنتم فيه. إن الله على كل شيء قدير.', 148, 1, 23, 19, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (156, 2, 1, 2, 156, 'ومن أي مكان خَرَجْتَ -أيها النبي- مسافرًا، وأردت الصلاة، فوجِّه وجهك نحو المسجد الحرام. وإنَّ توجُّهك إليه لهو الحق الثابت من ربك. وما الله بغافل عما تعملونه، وسيجازيكم على ذلك.', 149, 1, 23, 19, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (157, 2, 1, 2, 157, 'ومن أى مكان خرجت -أيها النبي- فتوجَّه إلى المسجد الحرام، وحيثما كنتم -أيها المسلمون-، بأي قطر من أقطار الأرض فولُّوا وجوهكم نحو المسجد الحرام؛ لكي لا يكون للناس المخالفين لكم احتجاج عليكم بالمخاصمة والمجادلة، بعد هذا التوجه إليه، إلا أهل الظلم والعناد منهم، فسيظلُّون على جدالهم، فلا تخافوهم وخافوني بامتثال أمري، واجتناب نهيي؛ ولكي أتم نعمتي عليكم باختيار أكمل الشرائع لكم، ولعلكم تهتدون إلى الحق والصواب.', 150, 1, 23, 19, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (158, 2, 1, 2, 158, 'كما أنعمنا عليكم باستقبال الكعبة أرسلنا فيكم رسولا منكم يتلو عليكم الآيات المبينة للحق من الباطل، ويطهركم من دنس الشرك وسوء الأخلاق، ويعلمكم الكتاب والسنة وأحكام الشريعة، ويعلمكم من أخبار الأنبياء، وقصص الأمم السابقة ما كنتم تجهلونه.', 151, 1, 23, 19, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (159, 2, 1, 2, 159, 'أمر تعالى المؤمنين بذكره، ووعد عليه أفضل الجزاء، وهو الثناء في الملأ الأعلى على مَنْ ذكره، وخصوني -أيها المؤمنون- بالشكر قولا وعملا ولا تجحدوا نعمي عليكم.', 152, 1, 23, 19, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (160, 2, 1, 2, 160, 'يا أيها المؤمنون اطلبوا العون من الله في كل أموركم: بالصبر على النوائب والمصائب، وترك المعاصي والذنوب، والصبر على الطاعات والقربات، والصلاة التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. إن الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الآية: إثبات معيَّة الله الخاصة بالمؤمنين، المقتضية لما سلف ذكره؛ أما المعية العامة، المقتضية للعلم والإحاطة فهي لجميع الخلق.', 153, 1, 23, 20, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (161, 2, 1, 2, 161, 'ولا تقولوا -أيها المؤمنون- فيمن يُقتلون مجاهدين في سبيل الله: هم أموات، بل هم أحياء حياة خاصة بهم في قبورهم، لا يعلم كيفيتها إلا الله - تعالى-، ولكنكم لا تُحسُّون بها. وفي هذا دليل على نعيم القبر.', 154, 1, 24, 20, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (162, 2, 1, 2, 162, 'ولنختبرنكم بشيء يسير من الخوف، ومن الجوع، وبنقص من الأموال بتعسر الحصول عليها، أو ذهابها، ومن الأنفس: بالموت أو الشهادة في سبيل الله، وبنقص من ثمرات النخيل والأعناب والحبوب، بقلَّة ناتجها أو فسادها. وبشِّر -أيها النبي- الصابرين على هذا وأمثاله بما يفرحهم ويَسُرُّهم من حسن العاقبة في الدنيا والآخرة.', 155, 1, 24, 20, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (163, 2, 1, 2, 163, 'من صفة هؤلاء الصابرين أنهم إذا أصابهم شيء يكرهونه قالوا: إنَّا عبيد مملوكون لله، مدبَّرون بأمره وتصريفه، يفعل بنا ما يشاء، وإنا إليه راجعون بالموت، ثم بالبعث للحساب والجزاء.', 156, 1, 24, 20, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (164, 2, 1, 2, 164, 'أولئك الصابرون لهم ثناء من ربهم ورحمة عظيمة منه سبحانه، وأولئك هم المهتدون إلى الرشاد.', 157, 1, 24, 20, NULL, 9, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (165, 2, 1, 2, 165, 'إن الصفا والمروة- وهما جبلان صغيران قرب الكعبة من جهة الشرق- من معالم دين الله الظاهرة التي تعبَّد الله عباده بالسعي بينهما. فمَن قصد الكعبة حاجًّا أو معتمرًا، فلا إثم عليه ولا حرج في أن يسعى بينهما، بل يجب عليه ذلك، ومن فعل الطاعات طواعية من نفسه مخلصًا بها لله تعالى، فإن الله تعالى شاكر يثيب على القليل بالكثير، عليم بأعمال عباده فلا يضعها، ولا يبخس أحدًا مثقال ذرة.', 158, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (166, 2, 1, 2, 166, 'إن الذين يُخْفون ما أنزلنا من الآيات الواضحات الدالة على نبوة محمد صلى الله عليه وسلم وما جاء به، وهم أحبار اليهود وعلماء النصارى وغيرهم ممن يكتم ما أنزل الله من بعد ما أظهرناه للناس في التوراة والإنجيل، أولئك يطردهم الله من رحمته، ويدعو عليهم باللعنة جميع الخليقة.', 159, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (167, 2, 1, 2, 167, 'إلا الذين رجعوا مستغفرين الله من خطاياهم، وأصلحوا ما أفسدوه، وبَيَّنوا ما كتموه، فأولئك أقبل توبتهم وأجازيهم بالمغفرة، وأنا التواب على من تاب من عبادي، الرحيم بهم؛ إذ وفقتُهم للتوبة وقبلتها منهم.', 160, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (168, 2, 1, 2, 168, 'إن الذين جحدوا الإيمان وكتموا الحق، واستمروا على ذلك حتى ماتوا، أولئك عليهم لعنة الله والملائكة والناس أجمعين بالطرد من رحمته.', 161, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (169, 2, 1, 2, 169, 'دائمين في اللعنة والنار، لا يخفف عنهم العذاب، ولا هم يمهلون بمعذرة يعتذرون بها.', 162, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (170, 2, 1, 2, 170, 'وإلهكم -أيها الناس- إله واحد متفرد في ذاته وأسمائه وصفاته وأفعاله وعبودية خلقه له، لا معبود بحق إلا هو، الرحمن المتصف بالرحمة في ذاته وأفعاله لجميع الخلق، الرحيم بالمؤمنين.', 163, 1, 24, 20, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (171, 2, 1, 2, 171, 'إن في خلق السماوات بارتفاعها واتساعها، والأرض بجبالها وسهولها وبحارها، وفي اختلاف الليل والنهار من الطول والقصر، والظلمة والنور، وتعاقبهما بأن يخلف كل منهما الآخر، وفي السفن الجارية في البحار، التي تحمل ما ينفع الناس، وما أنزل الله من السماء من ماء المطر، فأحيا به الأرض، فصارت مخضرَّة ذات بهجة بعد أن كانت يابسة لا نبات فيها، وما نشره الله فيها من كل ما دبَّ على وجه الأرض، وما أنعم به عليكم من تقليب الرياح وتوجيهها، والسحاب المسيَّر بين السماء والأرض -إن في كل الدلائل السابقة لآياتٍ على وحدانية الله، وجليل نعمه، لقوم يعقلون مواضع الحجج، ويفهمون أدلته سبحانه على وحدانيته، واستحقاقه وحده للعبادة.', 164, 1, 25, 21, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (172, 2, 1, 2, 172, 'ومع هذه البراهين القاطعة يتخذ فريق من الناس من دون الله أصنامًا وأوثانًا وأولياء يجعلونهم نظراء لله تعالى، ويعطونهم من المحبة والتعظيم والطاعة، ما لا يليق إلا بالله وحده. والمؤمنون أعظم حبا لله من حب هؤلاء الكفار لله ولآلهتهم؛ لأن المؤمنين أخلصوا المحبة كلها لله، وأولئك أشركوا في المحبة. ولو يعلم الذين ظلموا أنفسهم بالشرك في الحياة الدنيا، حين يشاهدون عذاب الآخرة، أن الله هو المتفرد بالقوة جميعًا، وأن الله شديد العذاب، لما اتخذوا من دون الله آلهة يعبدونهم من دونه، ويتقربون بهم إليه.', 165, 1, 25, 21, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (173, 2, 1, 2, 173, 'عند معاينتهم عذاب الآخرة يتبرأ الرؤساء المتبوعون ممن اتبعهم على الشرك، وتنقطع بينهم كل الصلات التي ارتبطوا بها في الدنيا: من القرابة، والاتِّباع، والدين، وغير ذلك.', 166, 1, 25, 21, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (174, 2, 1, 2, 174, 'وقال التابعون: يا ليت لنا عودة إلى الدنيا، فنعلن براءتنا من هؤلاء الرؤساء، كما أعلنوا براءتهم مِنَّا. وكما أراهم الله شدة عذابه يوم القيامة يريهم أعمالهم الباطلة ندامات عليهم، وليسوا بخارجين من النار أبدًا.', 167, 1, 25, 21, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (175, 2, 1, 2, 175, 'يا أيها الناس كلوا من رزق الله الذي أباحه لكم في الأرض، وهو الطاهر غير النجس، النافع غير الضار، ولا تتبعوا طرق الشيطان في التحليل والتحريم، والبدع والمعاصي. إنه عدو لكم ظاهر العداوة.', 168, 1, 25, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (176, 2, 1, 2, 176, 'إنما يأمركم الشيطان بكل ذنب قبيح يسوءُكم، وبكل معصية بالغة القبح، وبأن تفتروا على الله الكذب من تحريم الحلال وغيره بدون علم.', 169, 1, 25, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (177, 2, 1, 2, 177, 'وإذا قال المؤمنون ناصحين أهل الضلال: اتبعوا ما أنزل الله من القرآن والهدى، أصرُّوا على تقليد أسلافهم المشركين قائلين: لا نتبع دينكم، بل نتبع ما وجدنا عليه آباءنا. أيتبعون آباءهم ولو كانوا لا يعقلون عن الله شيئًا، ولا يدركون رشدًا؟', 170, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (178, 2, 1, 2, 178, 'وصفة الذين كفروا وداعيهم إلى الهدى والإيمان كصفة الراعي الذي يصيح بالبهائم ويزجرها، وهي لا تفهم معاني كلامه، وإنما تسمع النداء ودَوِيَّ الصوت فقط. هؤلاء الكفار صُمٌّ سدُّوا أسماعهم عن الحق، بُكْم أخرسوا ألسنتهم عن النطق به، عُمْي لا ترى أعينهم براهينه الباهرة، فهم لا يعملون عقولهم فيما ينفعهم.', 171, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (179, 2, 1, 2, 179, 'يا أيها المؤمنون كلوا من الأطعمة المستلَذَّة الحلال التي رزقناكم، ولا تكونوا كالكفار الذين يحرمون الطيبات، ويستحِلُّون الخبائث، واشكروا لله نعمه العظيمة عليكم بقلوبكم وألسنتكم وجوارحكم، إن كنتم حقًا منقادين لأمره، سامعين مطيعين له، تعبدونه وحده لا شريك له.', 172, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (180, 2, 1, 2, 180, 'إنما حرم الله عليكم ما يضركم كالميتة التي لم تذبح بطريقة شرعية، والدم المسفوح، ولحم الخنزير، والذبائح التي ذبحت لغير الله. ومِنْ فَضْلِ الله عليكم وتيسيره أنه أباح لكم أكل هذه المحرمات عند الضرورة. فمن ألجأته الضرورة إلى أكل شيء منها، غير ظالم في أكله فوق حاجته، ولا متجاوز حدود الله فيما أُبيح له، فلا ذنب عليه في ذلك. إن الله غفور لعباده، رحيم بهم.', 173, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (181, 2, 1, 2, 181, 'إن الذين يُخْفون ما أنزل الله في كتبه من صفة محمد صلى الله عليه وسلم وغير ذلك من الحق، ويحرصون على أخذ عوض قليل من عرض الحياة الدنيا مقابل هذا الإخفاء، هؤلاء ما يأكلون في مقابلة كتمان الحق إلا نار جهنم تتأجج في بطونهم، ولا يكلمهم الله يوم القيامة لغضبه وسخطه عليهم، ولا يطهرهم من دنس ذنوبهم وكفرهم، ولهم عذاب موجع.', 174, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (182, 2, 1, 2, 182, 'أولئك المتصفون بهذه الصفات استبدلوا الضلالة بالهدى وعذاب الله بمغفرته، فما أشد جراءتهم على النار بعملهم أعمال أهل النار!! يعجب الله من إقدامهم على ذلك، فاعجبوا -أيها الناس- من جراءتهم، ومن صبرهم على النار ومكثهم فيها. وهذا على وجه الاستهانة بهم، والاستخفاف بأمرهم.', 175, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (183, 2, 1, 2, 183, 'ذلك العذاب الذي استحقوه بسبب أن الله تعالى نزَّل كتبه على رسله مشتملة على الحق المبين، فكفروا به. وإن الذين اختلفوا في الكتاب فأمنوا ببعضه وكفروا ببعضه، لفي منازعة ومفارقة بعيدة عن الرشد والصواب.', 176, 1, 26, 22, NULL, 10, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (184, 2, 1, 2, 184, 'ليس الخير عند الله- تعالى- في التوجه في الصلاة إلى جهة المشرق والمغرب إن لم يكن عن أمر الله وشرعه، وإنما الخير كل الخير هو إيمان من آمن بالله وصدَّق به معبودًا وحدَه لا شريك له، وآمن بيوم البعث والجزاء، وبالملائكة جميعًا، وبالكتب المنزلة كافة، وبجميع النبيين من غير تفريق، وأعطى المال تطوُّعًا -مع شدة حبه- ذوي القربى، واليتامى المحتاجين الذين مات آباؤهم وهم دون سن البلوغ، والمساكين الذين أرهقهم الفقر، والمسافرين المحتاجين الذين بَعُدوا عن أهلهم ومالهم، والسائلين الذين اضطروا إلى السؤال لشدة حاجتهم، وأنفق في تحرير الرقيق والأسرى، وأقام الصلاة، وأدى الزكاة المفروضة، والذين يوفون بالعهود، ومن صبر في حال فقره ومرضه، وفي شدة القتال. أولئك المتصفون بهذه الصفات هم الذين صدقوا في إيمانهم، وأولئك هم الذين اتقَوا عقاب الله فتجنبوا معاصيه.', 177, 1, 27, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (185, 2, 1, 2, 185, 'يا أيها الذين صدقوا الله ورسوله وعملوا بشرعه فرض الله عليكم أن تقتصوا من القاتل عمدا بقتله، بشرط المساواة والمماثلة: يُقتل الحر بمثله، والعبد بمثله، والأنثى بمثلها. فمن سامحه ولي المقتول بالعفو عن الاقتصاص منه والاكتفاء بأخذ الدية -وهي قدر مالي محدد يدفعه الجاني مقابل العفو عنه- فليلتزم الطرفان بحسن الخلق، فيطالب الولي بالدية من غير عنف، ويدفع القاتل إليه حقه بإحسان، مِن غير تأخير ولا نقص. ذلك العفو مع أخذ الدية تخفيف من ربكم ورحمة بكم؛ لما فيه من التسهيل والانتفاع. فمَن قتل القاتل بعد العفو عنه وأَخْذِ الدية فله عذاب أليم بقتله قصاصًا في الدنيا، أو بالنار في الآخرة.', 178, 1, 27, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (186, 2, 1, 2, 186, 'ولكم في تشريع القصاص وتنفيذه حياة آمنة -يا أصحاب العقول السليمة-؛ رجاء تقوى الله وخشيته بطاعته دائمًا.', 179, 1, 27, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (187, 2, 1, 2, 187, 'فرض الله عليكم إذا حضر أحدكم علامات الموت ومقدماته -إن ترك مالا- الوصية بجزء من ماله للوالدين والأقربين مع مراعاة العدل؛ فلا يدع الفقير ويوصي للغني، ولا يتجاوز الثلث، وذلك حق ثابت يعمل به أهل التقوى الذين يخافون الله. وكان هذا قبل نزول آيات المواريث التي حدَّد الله فيها نصيب كل وارث.', 180, 1, 27, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (188, 2, 1, 2, 188, 'فمَن غَيَّر وصية الميت بعدما سمعها منه قبل موته، فإنما الذنب على مَن غيَّر وبدَّل. إن الله سميع لوصيتكم وأقوالكم، عليم بما تخفيه صدوركم من الميل إلى الحق والعدل أو الجور والحيف، وسيجازيكم على ذلك.', 181, 1, 27, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (189, 2, 1, 2, 189, 'فمَن علم مِن موصٍ ميلا عن الحق في وصيته على سبيل الخطأ أو العمد، فنصح الموصيَ وقت الوصية بما هو الأعدل، فإن لم يحصل له ذلك فأصلح بين الأطراف بتغيير الوصية؛ لتوافق الشريعة، فلا ذنب عليه في هذا الإصلاح. إن الله غفور لعباده، رحيم بهم.', 182, 1, 28, 23, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (190, 2, 1, 2, 190, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، فرض الله عليكم الصيام كما فرضه على الأمم قبلكم؛ لعلكم تتقون ربكم، فتجعلون بينكم وبين المعاصي وقاية بطاعته وعبادته وحده.', 183, 1, 28, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (191, 2, 1, 2, 191, 'فرض الله عليكم صيام أيام معلومة العدد وهي أيام شهر رمضان. فمن كان منكم مريضًا يشق عليه الصوم، أو مسافرًا فله أن يفطر، وعليه صيام عدد من أيام أُخَر بقدر التي أفطر فيها. وعلى الذين يتكلفون الصيام ويشقُّ عليهم مشقة غير محتملة كالشيخ الكبير، والمريض الذي لا يُرْجَى شفاؤه، فدية عن كل يوم يفطره، وهي طعام مسكين، فمن زاد في قدر الفدية تبرعًا منه فهو خير له، وصيامكم خير لكم -مع تحمُّل المشقة- من إعطاء الفدية، إن كنتم تعلمون الفضل العظيم للصوم عند الله تعالى.', 184, 1, 28, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (192, 2, 1, 2, 192, 'شهر رمضان الذي ابتدأ الله فيه إنزال القرآن في ليلة القدر؛ هداية للناس إلى الحق، فيه أوضح الدلائل على هدى الله، وعلى الفارق بين الحق والباطل. فمن حضر منكم الشهر وكان صحيحًا مقيمًا فليصم نهاره. ويُرخَّص للمريض والمسافر في الفطر، ثم يقضيان عدد تلك الأيام. يريد الله تعالى بكم اليسر والسهولة في شرائعه، ولا يريد بكم العسر والمشقة، ولتكملوا عدة الصيام شهرًا، ولتختموا الصيام بتكبير الله في عيد الفطر، ولتعظموه على هدايته لكم، ولكي تشكروا له على ما أنعم به عليكم من الهداية والتوفيق والتيسير.', 185, 1, 28, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (193, 2, 1, 2, 193, 'وإذا سألك -أيها النبي- عبادي عني فقل لهم: إني قريب منهم، أُجيب دعوة الداعي إذا دعاني، فليطيعوني فيما أمرتهم به ونهيتهم عنه، وليؤمنوا بي، لعلهم يهتدون إلى مصالح دينهم ودنياهم. وفي هذه الآية إخبار منه سبحانه عن قربه من عباده، القرب اللائق بجلاله.', 186, 1, 28, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (194, 2, 1, 2, 194, 'أباح الله لكم في ليالي شهر رمضان جماعَ نسائكم، هنَّ ستر وحفظ لكم، وأنتم ستر وحفظ لهن. علم الله أنكم كنتم تخونون أنفسكم؛ بمخالفة ما حرَّمه الله عليكم من مجامعة النساء بعد العشاء في ليالي الصيام -وكان ذلك في أول الإسلام-، فتاب الله عليكم ووسَّع لكم في الأمر، فالآن جامعوهن، واطلبوا ما قدَّره الله لكم من الأولاد، وكلوا واشربوا حتى يتبَيَّن ضياء الصباح من سواد الليل، بظهور الفجر الصادق، ثم أتموا الصيام بالإمساك عن المفطرات إلى دخول الليل بغروب الشمس. ولا تجامعوا نساءكم أو تتعاطوا ما يفضي إلى جماعهن إذا كنتم معتكفين في المساجد؛ لأن هذا يفسد الاعتكاف (وهو الإقامة في المسجد مدة معلومة بنيَّة التقرب إلى الله تعالى). تلك الأحكام التي شرعها الله لكم هي حدوده الفاصلة بين الحلال والحرام، فلا تقربوها حتى لا تقعوا في الحرام. بمثل هذا البيان الواضح يبين الله آياته وأحكامه للناس؛ كي يتقوه ويخشَوْه.', 187, 1, 29, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (195, 2, 1, 2, 195, 'ولا يأكل بعضكم مال بعض بسبب باطل كاليمين الكاذبة، والغصب، والسرقة، والرشوة، والربا ونحو ذلك، ولا تلقوا بالحجج الباطلة إلى الحكام؛ لتأكلوا عن طريق التخاصم أموال طائفة من الناس بالباطل، وأنتم تعلمون تحريم ذلك عليكم.', 188, 1, 29, 24, NULL, 11, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (196, 2, 1, 2, 196, 'يسألك أصحابك -أيها النبي-: عن الأهلة وتغيُّر أحوالها، قل لهم: جعل اللهُ الأهلة علامات يعرف بها الناس أوقات عباداتهم المحددة بوقت مثل الصيام والحج، ومعاملاتهم. وليس الخير ما تعودتم عليه في الجاهلية وأول الإسلام من دخول البيوت من ظهورها حين تُحْرِمون بالحج أو العمرة، ظانين أن ذلك قربة إلى الله، ولكن الخير هو فِعْلُ مَنِ اتقى الله واجتنب المعاصي، وادخلوا البيوت من أبوابها عند إحرامكم بالحج أو العمرة، واخشوا الله تعالى في كل أموركم، لتفوزوا بكل ما تحبون من خيري الدنيا والآخرة.', 189, 1, 29, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (197, 2, 1, 2, 197, 'وقاتلوا -أيها المؤمنون- لنصرة دين الله الذين يقاتلونكم، ولا ترتكبوا المناهي من المُثْلة، والغُلول، وقَتْلِ من لا يحل قتله من النساء والصبيان والشيوخ، ومن في حكمهم. إن الله لا يحب الذين يجاوزون حدوده، فيستحلون ما حرَّم الله ورسوله.', 190, 1, 29, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (198, 2, 1, 2, 198, 'واقتلوا الذين يقاتلونكم من المشركين حيث وجدتموهم، وأخرجوهم من المكان الذي أخرجوكم منه وهو "مكة". والفتنة -وهي الكفر والشرك والصد عن الإسلام- أشد من قتلكم إياهم. ولا تبدؤوهم بالقتال عند المسجد الحرام تعظيمًا لحرماته حتى يبدؤوكم بالقتال فيه، فإن قاتلوكم في المسجد الحرام فاقتلوهم فيه. مثل ذلك الجزاء الرادع يكون جزاء الكافرين.', 191, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (199, 2, 1, 2, 199, 'فإن تركوا ما هم فيه من الكفر وقتالكم عند المسجد الحرام، ودخلوا في الإيمان، فإن الله غفور لعباده، رحيم بهم.', 192, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (200, 2, 1, 2, 200, 'واستمروا- أيها المؤمنون- في قتال المشركين المعتدين، حتى لا تكون فتنة للمسلمين عن دينهم ولا شرك بالله، ويبقى الدين لله وحده خالصًا لا يُعْبَد معه غيره. فإن كفُّوا عن الكفر والقتال فكُفُّوا عنهم؛ فالعقوبة لا تكون إلا على المستمرين على كفرهم وعدوانهم.', 193, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (201, 2, 1, 2, 201, 'قتالكم -أيها المؤمنون- للمشركين في الشهر الذي حرَّم الله القتال فيه هو جزاء لقتالهم لكم في الشهر الحرام. والذي يعتدي على ما حَرَّم الله من المكان والزمان، يعاقب بمثل فعله، ومن جنس عمله. فمن اعتدى عليكم بالقتال أو غيره فأنزلوا به عقوبة مماثلة لجنايته، ولا حرج عليكم في ذلك؛ لأنهم هم البادئون بالعدوان، وخافوا الله فلا تتجاوزوا المماثلة في العقوبة، واعلموا أن الله مع الذين يتقونه ويطيعونه بأداء فرائضه وتجنب محارمه.', 194, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (202, 2, 1, 2, 202, 'واستمروا- أيها المؤمنون- في إنفاق الأموال لنصرة دين الله تعالى، والجهاد في سبيله، ولا توقعوا أنفسكم في المهالك بترك الجهاد في سبيل الله، وعدم الإنفاق فيه، وأحسنوا في الانفاق والطاعة، واجعلوا عملكم كله خالصًا لوجه الله تعالى. إن الله يحب أهل الإخلاص والإحسان.', 195, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (203, 2, 1, 2, 203, 'وأدُّوا الحج والعمرة تامَّيْنِ، خالصين لوجه الله تعالى. فإن منعكم عن الذهاب لإتمامهما بعد الإحرام بهما مانع كالعدو والمرض، فالواجب عليكم ذَبْحُ ما تيسر لكم من الإبل أو البقر أو الغنم تقربًا إلى الله تعالى؛ لكي تَخْرُجوا من إحرامكم بحلق شعر الرأس أو تقصيره، ولا تحلقوا رؤوسكم إذا كنتم محصرين حتى ينحر المحصر هديه في الموضع الذي حُصر فيه ثم يحل من إحرامه، كما نحر النبي صلى الله عليه وسلم في "الحديبية" ثم حلق رأسه، وغير المحصر لا ينحر الهدي إلا في الحرم، الذي هو محله في يوم العيد، اليوم العاشر وما بعده من أيام التشريق. فمن كان منكم مريضًا، أو به أذى من رأسه يحتاج معه إلى الحلق -وهو مُحْرِم- حَلَق، وعليه فدية: بأن يصوم ثلاثة أيام، أو يتصدق على ستة مساكين لكل مسكين نصف صاع من طعام، أو يذبح شاة لفقراء الحرم. فإذا كنتم في أمن وصحَّة: فمن استمتع بالعمرة إلى الحج وذلك باستباحة ما حُرِّم عليه بسبب الإحرام بعد انتهاء عمرته، فعليه ذبح ما تيسر من الهدي، فمن لم يجد هَدْيًا يذبحه فعليه صيام ثلاثة أيام في أشهر الحج، وسبعة إذا فرغتم من أعمال الحج ورجعتم إلى أهليكم، تلك عشرة كاملة لا بد من صيامها. ذلك الهَدْيُ وما ترتب عليه من الصيام لمن لم يكن أهله من ساكني أرض الحرم، وخافوا الله تعالى وحافظوا على امتثال أوامره واجتناب نواهيه، واعلموا أن الله شديد العقاب لمن خالف أمره، وارتكب ما عنه زجر.', 196, 1, 30, 25, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (204, 2, 1, 2, 204, 'وقت الحج أشهر معلومات، وهي: شوال، وذو القعدة، وعشر من ذي الحجة. فمن أوجب الحج على نفسه فيهن بالإحرام، فيحرم عليه الجماع ومقدماته القولية والفعلية، ويحرم عليه الخروج عن طاعة الله تعالى بفعل المعاصي، والجدال في الحج الذي يؤدي إلى الغضب والكراهية. وما تفعلوا من خير يعلمه الله، فيجازي كلا على عمله. وخذوا لأنفسكم زادًا من الطعام والشراب لسفر الحج، وزادًا من صالح الأعمال للدار الآخرة، فإن خير الزاد تقوى الله، وخافوني يا أصحاب العقول السليمة.', 197, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (205, 2, 1, 2, 205, 'ليس عليكم حرج في أن تطلبوا رزقًا من ربكم بالربح من التجارة في أيام الحج. فإذا دفعتم بعد غروب الشمس راجعين من "عرفات" -وهي المكان الذي يقف فيه الحجاج يوم التاسع من ذي الحجة- فاذكروا الله بالتسبيح والتلبية والدعاء عند المشعر الحرام -"المزدلفة"-، واذكروا الله على الوجه الصحيح الذي هداكم إليه، ولقد كنتم من قبل هذا الهدى في ضلال لا تعرفون معه الحق.', 198, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (206, 2, 1, 2, 206, 'وليكن اندفاعكم من "عرفات" التي أفاض منها إبراهيم عليه السلام مخالفين بذلك من لا يقف بها من أهل الجاهلية، واسألوا الله أن يغفر لكم ذنوبكم. إن الله غفور لعباده المستغفرين التائبين، رحيم بهم.', 199, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (207, 2, 1, 2, 207, 'فإذا أتممتم عبادتكم، وفرغتم من أعمال الحج، فأكثروا من ذكر الله والثناء عليه، مثل ذكركم مفاخر آبائكم وأعظم من ذلك. فمن الناس فريق يجعل همه الدنيا فقط، فيدعو قائلا ربنا آتنا في الدنيا صحة، ومالا وأولادًا، وهؤلاء ليس لهم في الآخرة حظ ولا نصيب؛ لرغبتهم عنها وقَصْرِ هَمِّهم على الدنيا.', 200, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (208, 2, 1, 2, 208, 'ومن الناس فريق مؤمن يقول في دعائه: ربنا آتنا في الدنيا عافية ورزقًا وعلمًا نافعًا، وعملا صالحًا، وغير ذلك من أمور الدين والدنيا، وفي الآخرة الجنة، واصرف عنَّا عذاب النار. وهذا الدعاء من أجمع الأدعية، ولهذا كان أكثر دعاء النبي صلى الله عليه وسلم، كما ثبت في الصحيحين.', 201, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (209, 2, 1, 2, 209, 'أولئك الداعون بهذا الدعاء لهم ثواب عظيم بسبب ما كسبوه من الأعمال الصالحة. والله سريع الحساب، مُحْصٍ أعمال عباده، ومجازيهم بها.', 202, 1, 31, 26, NULL, 12, 3);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (210, 2, 1, 2, 210, 'واذكروا الله تسبيحًا وتكبيرًا في أيام قلائل، وهي أيام التشريق: الحادي عشر والثاني عشر والثالث عشر من شهر ذي الحجة. فمن أراد التعجل وخرج من "مِنى" قبل غروب شمس اليوم الثاني عشر بعد رمي الجمار فلا ذنب عليه، ومن تأخر بأن بات بـ "مِنى" حتى يرمي الجمار في اليوم الثالث عشر فلا ذنب عليه، لمن اتقى الله في حجه. والتأخر أفضل؛ لأنه تزوُّد في العبادة واقتداء بفعل النبي صلى الله عليه وسلم. وخافوا الله- أيها المسلمون- وراقبوه في كل أعمالكم، واعلموا أنكم إليه وحده تُحْشَرون بعد موتكم للحساب والجزاء.', 203, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (211, 2, 1, 2, 211, 'وبعض الناس من المنافقين يعجبك -أيها الرسول- كلامه الفصيح الذي يريد به حظًّا من حظوظ الدنيا لا الآخرة، ويحلف مستشهدًا بالله على ما في قلبه من محبة الإسلام، وفي هذا غاية الجرأة على الله، وهو شديد العداوة والخصومة للإسلام والمسلمين.', 204, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (212, 2, 1, 2, 212, 'وإذا خرج من عندك أيها الرسول، جَدَّ ونَشِط في الأرض ليفسد فيها، ويتلف زروع الناس، ويقتل ماشيتهم. والله لا يحب الفساد.', 205, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (213, 2, 1, 2, 213, 'وإذا نُصِح ذلك المنافق المفسد، وقيل له: اتق الله واحذر عقابه، وكُفَّ عن الفساد في الأرض، لم يقبل النصيحة، بل يحمله الكبر وحميَّة الجاهلية على مزيد من الآثام، فَحَسْبُه جهنم وكافيته عذابًا، ولبئس الفراش هي.', 206, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (214, 2, 1, 2, 214, 'وبعض الناس يبيع نفسه طلبًا لرضا الله عنه، بالجهاد في سبيله، والتزام طاعته. والله رءوف بالعباد، يرحم عباده المؤمنين رحمة واسعة في عاجلهم وآجلهم، فيجازبهم أحسن الجزاء.', 207, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (215, 2, 1, 2, 215, 'يا أيها الذين آمنوا بالله ربًا وبمحمد نبيًا ورسولا وبالإسلام دينًا، ادخلوا في جميع شرائع الإسلام، عاملين بجميع أحكامه، ولا تتركوا منها شيئًا، ولا تتبعوا طرق الشيطان فيما يدعوكم إليه من المعاصي. إنه لكم عدو ظاهر العداوة فاحذروه.', 208, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (216, 2, 1, 2, 216, 'فإن انحرفتم عن طريق الحق، من بعد ما جاءتكم الحجج الواضحة من القرآن والسنة، فاعلموا أن الله عزيز في ملكه لا يفوته شيء، حكيم في أمره ونهيه، يضع كل شيء في موضعه المناسب له.', 209, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (217, 2, 1, 2, 217, 'ما ينتظر هؤلاء المعاندون الكافرون بعد قيام الأدلة البينة إلا أن يأتيهم الله عز وجل على الوجه اللائق به سبحانه في ظُلَل من السحاب يوم القيامة؛ ليفصل بينهم بالقضاء العادل، وأن تأتي الملائكة، وحينئذ يقضي الله تعالى فيهم قضاءه. وإليه وحده ترجع أمور الخلائق جميعها.', 210, 1, 32, 26, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (218, 2, 1, 2, 218, 'سل -أيها الرسول- بني إسرائيل المعاندين لك: كم أعطيناهم من آيات واضحات في كتبهم تهديهم إلى الحق، فكفروا بها كلها، وأعرضوا عنها، وحَرَّفوها عن مواضعها. ومن يبدل نعمة الله -وهي دينه- ويكفر بها من بعد معرفتها، وقيام الحجة عليه بها، فإن الله تعالى شديد العقاب له.', 211, 1, 33, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (219, 2, 1, 2, 219, 'حُسِّن للذين جحدوا وحدانية الله الحياةُ الدنيا وما فيها من الشهوات والملذات، وهم يستهزئون بالمؤمنين. وهؤلاء الذين يخشون ربهم فوق جميع الكفار يوم القيامة؛ حيث يدخلهم الله أعلى درجات الجنة، وينزل الكافرين أسفل دركات النار. والله يرزق مَن يشاء مِن خلقه بغير حساب.', 212, 1, 33, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (220, 2, 1, 2, 220, 'كان الناس جماعة واحدة، متفقين على الإيمان بالله ثم اختلفوا في دينهم، فبعث الله النبيين دعاة لدين الله، مبشرين مَن أطاع الله بالجنة، ومحذرين من كفر به وعصاه النار، وأنزل معهم الكتب السماوية بالحق الذي اشتملت عليه؛ ليحكموا بما فيها بين الناس فيما اختلفوا فيه، وما اخْتَلَف في أمر محمد صلى الله عليه وسلم وكتابه ظلمًا وحسدًا إلا الذين أعطاهم الله التوراة، وعرفوا ما فيها من الحجج والأحكام، فوفَّق الله المؤمنين بفضله إلى تمييز الحق من الباطل، ومعرفة ما اختلفوا فيه. والله يوفِّق من يشاء من عباده إلى طريق مستقيم.', 213, 1, 33, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (221, 2, 1, 2, 221, 'بل أظننتم -أيها المؤمنون- أن تدخلوا الجنة، ولمَّا يصبكم من الابتلاء مثل ما أصاب المؤمنين الذين مضوا من قبلكم: من الفقر والأمراض والخوف والرعب، وزُلزلوا بأنواع المخاوف، حتى قال رسولهم والمؤمنون معه -على سبيل الاستعجال للنصر من الله تعالى-: متى نصر الله؟ ألا إن نصر الله قريب من المؤمنين.', 214, 1, 33, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (222, 2, 1, 2, 222, 'يسألك أصحابك -أيها النبي- أي شيء ينفقون من أصناف أموالهم تقربًا إلى الله تعالى، وعلى مَن ينفقون؟ قل لهم: أنفقوا أيَّ خير يتيسر لكم من أصناف المال الحلال الطيب، واجعلوا نفقتكم للوالدين، والأقربين من أهلكم وذوي أرحامكم، واليتامى، والفقراء، والمسافر المحتاج الذي بَعُدَ عن أهله وماله. وما تفعلوا من خير فإن الله تعالى به عليم.', 215, 1, 33, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (223, 2, 1, 2, 223, 'فرض الله عليكم -أيها المؤمنون- قتال الكفار، والقتال مكروه لكم من جهة الطبع؛ لمشقته وكثرة مخاطره، وقد تكرهون شيئًا وهو في حقيقته خير لكم، وقد تحبون شيئًا لما فيه من الراحة أو اللذة العاجلة، وهو شر لكم. والله تعالى يعلم ما هو خير لكم، وأنتم لا تعلمون ذلك. فبادروا إلى الجهاد في سبيله.', 216, 1, 34, 27, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (224, 2, 1, 2, 224, 'يسألك المشركون -أيها الرسول- عن الشهر الحرام: هل يحل فيه القتال؟ قل لهم: القتال في الشهر الحرام عظيم عند الله استحلاله وسفك الدماء فيه، ومَنْعكم الناس من دخول الإسلام بالتعذيب والتخويف، وجحودكم بالله وبرسوله وبدينه، ومَنْع المسلمين من دخول المسجد الحرام، وإخراج النبي والمهاجرين منه وهم أهله وأولياؤه، ذلك أكبر ذنبًا، وأعظم جرمًا عند الله من القتال في الشهر الحرام. والشرك الذي أنتم فيه أكبر وأشد من القتل في الشهر الحرام. وهؤلاء الكفار لم يرتدعوا عن جرائمهم، بل هم مستمرون عليها، ولا يزالون يقاتلونكم حتى يردوكم عن الإسلام إلى الكفر إن استطاعوا تحقيق ذلك. ومن أطاعهم منكم -أيها المسلمون- وارتدَّ عن دينه فمات على الكفر، فقد ذهب عمله في الدنيا والآخرة، وصار من الملازمين لنار جهنم لا يخرج منها أبدًا.', 217, 1, 34, 28, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (225, 2, 1, 2, 225, 'إن الذين صَدَّقوا بالله ورسوله وعملوا بشرعه والذين تركوا ديارهم، وجاهدوا في سبيل الله، أولئك يطمعون في فضل الله وثوابه. والله غفور لذنوب عباده المؤمنين، رحيم بهم رحمة واسعة.', 218, 1, 34, 28, NULL, 13, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (226, 2, 1, 2, 226, 'يسألك المسلمون -أيها النبي- عن حكم تعاطي الخمر شربًا وبيعًا وشراءً، والخمر كل مسكر خامر العقل وغطاه مشروبًا كان أو مأكولا ويسألونك عن حكم القمار -وهو أَخْذُ المال أو إعطاؤه بالمقامرة وهي المغالبات التي فيها عوض من الطرفين-، قل لهم: في ذلك أضرار ومفاسد كثيرة في الدين والدنيا، والعقول والأموال، وفيهما منافع للناس من جهة كسب الأموال وغيرها، وإثمهما أكبر من نفعهما؛ إذ يصدَّان عن ذكر الله وعن الصلاة، ويوقعان العداوة والبغضاء بين الناس، ويتلفان المال. وكان هذا تمهيدًا لتحريمهما. ويسألونك عن القَدْر الذي ينفقونه من أموالهم تبرعًا وصدقة، قل لهم: أنفقوا القَدْر الذي يزيد على حاجتكم. مثل ذلك البيان الواضح يبيِّن الله لكم الآيات وأحكام الشريعة؛ لكي تتفكروا فيما ينفعكم في الدنيا والآخرة. ويسألونك -أيها النبي- عن اليتامى كيف يتصرفون معهم في معاشهم وأموالهم؟ قل لهم: إصلاحكم لهم خير، فافعلوا الأنفع لهم دائمًا، وإن تخالطوهم في سائر شؤون المعاش فهم إخوانكم في الدين. وعلى الأخ أن يرعى مصلحة أخيه. والله يعلم المضيع لأموال اليتامى من الحريص على إصلاحها. ولو شاء الله لضيَّق وشقَّ عليكم بتحريم المخالطة. إن الله عزيز في ملكه، حكيم في خلقه وتدبيره وتشريعه.', 219, 1, 34, 28, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (227, 2, 1, 2, 227, 'لا يوجد تفسير لهذه الآية', 220, 1, 35, 28, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (228, 2, 1, 2, 228, 'ولا تتزوجوا -أيها المسلمون- المشركات عابدات الأوثان، حتى يدخلن في الإسلام. واعلموا أن امرأة مملوكة لا مال لها ولا حسب، مؤمنةً بالله، خير من امرأة مشركة، وإن أعجبتكم المشركة الحرة. ولا تُزَوِّجوا نساءكم المؤمنات -إماء أو حرائر- للمشركين حتى يؤمنوا بالله ورسوله. واعلموا أن عبدًا مؤمنًا مع فقره، خير من مشرك، وإن أعجبكم المشرك. أولئك المتصفون بالشرك رجالا ونساءً يدعون كل مَن يعاشرهم إلى ما يؤدي به إلى النار، والله سبحانه يدعو عباده إلى دينه الحق المؤدي بهم إلى الجنة ومغفرة ذنوبهم بإذنه، ويبين آياته وأحكامه للناس؛ لكي يتذكروا، فيعتبروا.', 221, 1, 35, 28, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (229, 2, 1, 2, 229, 'ويسألونك عن الحيض- وهو الدم الذي يسيل من أرحام النساء جِبِلَّة في أوقات مخصوصة-، قل لهم -أيها النبي-: هو أذى مستقذر يضر من يَقْرَبُه، فاجتنبوا جماع النساء مدة الحيض حتى ينقطع الدم، فإذا انقطع الدم، واغتسلن، فجامعوهن في الموضع الذي أحلَّه الله لكم، وهو القبل لا الدبر. إن الله يحب عباده المكثرين من الاستغفار والتوبة، ويحب عباده المتطهرين الذين يبتعدون عن الفواحش والأقذار.', 222, 1, 35, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (230, 2, 1, 2, 230, 'نساؤكم موضع زرع لكم، تضعون النطفة في أرحامهن، فَيَخْرج منها الأولاد بمشيئة الله، فجامعوهن في محل الجماع فقط، وهو القبل بأي كيفية شئتم، وقَدِّموا لأنفسكم أعمالا صالحة بمراعاة أوامر الله، وخافوا الله، واعلموا أنكم ملاقوه للحساب يوم القيامة. وبشِّر المؤمنين -أيها النبي- بما يفرحهم ويسرُّهم من حسن الجزاء في الآخرة.', 223, 1, 35, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (231, 2, 1, 2, 231, 'ولا تجعلوا -أيها المسلمون- حلفكم بالله مانعًا لكم من البر وصلة الرحم والتقوى والإصلاح بين الناس: بأن تُدْعَوا إلى فعل شيء منها، فتحتجوا بأنكم أقسمتم بالله ألا تفعلوه، بل على الحالف أن يعدل عن حلفه، ويفعل أعمال البر، ويكفر عن يمينه، ولا يعتاد ذلك. والله سميع لأقوالكم، عليم بجميع أحوالكم.', 224, 1, 35, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (232, 2, 1, 2, 232, 'لا يعاقبكم الله بسبب أيمانكم التي تحلفونها بغير قصد، ولكن يعاقبكم بما قصدَتْه قلوبكم. والله غفور لمن تاب إليه، حليم بمن عصاه حيث لم يعاجله بالعقوبة.', 225, 1, 36, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (233, 2, 1, 2, 233, 'للذين يحلفون بالله أن لا يجامعوا نساءهم، انتظار أربعة أشهر، فإن رجعوا قبل فوات الأشهر الأربعة، فإن الله غفور لما وقع منهم من الحلف بسبب رجوعهم، رحيم بهم.', 226, 1, 36, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (234, 2, 1, 2, 234, 'وإن عقدوا عزمهم على الطلاق، باستمرارهم في اليمين، وترك الجماع، فإن الله سميع لأقوالهم، عليم بمقاصدهم، وسيجازيهم على ذلك.', 227, 1, 36, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (235, 2, 1, 2, 235, 'والمطلقات ذوات الحيض، يجب أن ينتظرن دون نكاح بعد الطلاق مدة ثلاثة أطهار أو ثلاث حيضات على سبيل العدة؛ ليتأكدن من فراغ الرحم من الحمل. ولا يجوز لهن تزوج رجل آخر في أثناء هذه العدة حتى تنتهي. ولا يحل لهن أن يخفين ما خلق الله في أرحامهن من الحمل أو الحيض، إن كانت المطلقات مؤمنات حقًا بالله واليوم الآخر. وأزواج المطلقات أحق بمراجعتهن في العدة. وينبغي أن يكون ذلك بقصد الإصلاح والخير، وليس بقصد الإضرار تعذيبًا لهن بتطويل العدة. وللنساء حقوق على الأزواج، مثل التي عليهن، على الوجه المعروف، وللرجال على النساء منزلة زائدة من حسن الصحبة والعشرة بالمعروف والقِوامة على البيت وملك الطلاق. والله عزيز له العزة القاهرة، حكيم يضع كل شيء في موضعه المناسب.', 228, 1, 36, 29, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (236, 2, 1, 2, 236, 'الطلاق الذي تحصل به الرجعة مرتان، واحدة بعد الأخرى، فحكم الله بعد كل طلقة هو إمساك المرأة بالمعروف، وحسن العشرة بعد مراجعتها، أو تخلية سبيلها مع حسن معاملتها بأداء حقوقها، وألا يذكرها مطلقها بسوء. ولا يحل لكم- أيها الأزواج- أن تأخذوا شيئًا مما أعطيتموهن من المهر ونحوه، إلا أن يخاف الزوجان ألا يقوما بالحقوق الزوجية، فحينئذ يعرضان أمرهما على الأولياء، فإن خاف الأولياء عدم إقامة الزوجين حدود الله، فلا حرج على الزوجين فيما تدفعه المرأة للزوج مقابل طلاقها. تلك الأحكام هي حدود الله الفاصلة بين الحلال والحرام، فلا تتجاوزوها، ومن يتجاوز حدود الله تعالى فأولئك هم الظالمون أنفسهم بتعريضها لعذاب الله.', 229, 1, 36, 30, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (237, 2, 1, 2, 237, 'فإن طلَّق الرجل زوجته الطلقة الثالثة، فلا تحلُّ له إلا إذا تزوجت رجلا غيره زواجًا صحيحًا وجامعها فيه ويكون الزواج عن رغبة، لا بنية تحليل المرأة لزوجها الأول، فإن طلقها الزوج الآخر أو مات عنها وانقضت عدتها، فلا إثم على المرأة وزوجها الأول أن يتزوجا بعقد جديد، ومهر جديد، إن غلب على ظنهما أن يقيما أحكام الله التي شرعها للزوجين. وتلك أحكام الله المحددة يبينها لقوم يعلمون أحكامه وحدوده؛ لأنهم المنتفعون بها.', 230, 1, 36, 30, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (238, 2, 1, 2, 238, 'وإذا طَلَّقتم النساء فقاربن انتهاء عدتهن، فراجعوهن، ونيتكم القيام بحقوقهن على الوجه المستحسن شرعًا وعرفًا، أو اتركوهن حتى تنقضي عدتهن. واحذروا أن تكون مراجعتهن بقصد الإضرار بهن لأجل الاعتداء على حقوقهن. ومن يفعل ذلك فقد ظلم نفسه باستحقاقه العقوبة، ولا تتخذوا آيات الله وأحكامه لعبًا ولهوًا. واذكروا نعمة الله عليكم بالإسلام وتفصيل الأحكام. واذكروا ما أنزل الله عليكم من القرآن والسنة، واشكروا له سبحانه على هذه النعم الجليلة، يُذكِّركم الله بهذا، ويخوفكم من المخالفة، فخافوا الله وراقبوه، واعلموا أن الله عليم بكل شيء، لا يخفى عليه شيء، وسيجازي كلا بما يستحق.', 231, 1, 37, 30, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (239, 2, 1, 2, 239, 'واذا طلَّقتم نساءكم دون الثلاث وانتهت عدتهن من غير مراجعة لهن، فلا تضيقوا -أيها الأولياء- على المطلقات بمنعهن من العودة إلى أزواجهن بعقد جديد إذا أردن ذلك، وحدث التراضي شرعًا وعرفًا. ذلك يوعظ به من كان منكم صادق الإيمان بالله واليوم الآخر. إن تَرْكَ العضل وتمكين الأزواج من نكاح زوجاتهم أكثر نماء وطهارة لأعراضكم، وأعظم منفعة وثوابًا لكم. والله يعلم ما فيه صلاحكم وأنتم لا تعلمون ذلك.', 232, 1, 37, 31, NULL, 14, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (240, 2, 1, 2, 240, 'وعلى الوالدات إرضاع أولادهن مدة سنتين كاملتين لمن أراد إتمام الرضاعة، ويجب على الآباء أن يكفُلوا للمرضعات المطلقات طعامهن وكسوتهن، على الوجه المستحسن شرعًا وعرفًا؛ لأن الله لا يكلف نفسًا إلا قدر طاقتها، ولا يحل للوالدين أن يجعلوا المولود وسيلة للمضارة بينهما، ويجب على الوارث عند موت الوالد مثل ما يجب على الوالد قبل موته من النفقة والكسوة. فإن أراد الوالدان فطام المولود قبل انتهاء السنتين فلا حرج عليهما إذا تراضيا وتشاورا في ذلك؛ ليصلا إلى ما فيه مصلحة المولود. وإن اتفق الوالدان على إرضاع المولود من مرضعة أخرى غير والدته فلا حرج عليهما، إذا سلَّم الوالد للأم حقَّها، وسلَّم للمرضعة أجرها بما يتعارفه الناس. وخافوا الله في جميع أحوالكم، واعلموا أن الله بما تعملون بصير، وسيجازيكم على ذلك.', 233, 1, 37, 31, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (241, 2, 1, 2, 241, 'والذين يموتون منكم، ويتركون زوجات بعدهم، يجب عليهن الانتظار بأنفسهن مدة أربعة أشهر وعشرة أيام، لا يخرجن من منزل الزوجية، ولا يتزيَّنَّ، ولا يتزوجن، فإذا انتهت المدة المذكورة فلا إثم عليكم يا أولياء النساء فيما يفعلن في أنفسهن من الخروج، والتزين، والزواج على الوجه المقرر شرعًا. والله سبحانه وتعالى خبير بأعمالكم ظاهرها وباطنها، وسيجازيكم عليها.', 234, 1, 38, 31, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (242, 2, 1, 2, 242, 'ولا إثم عليكم -أيها الرجال- فيما تُلَمِّحون به مِن طلب الزواج بالنساء المتوفَّى عنهنَّ أزواجهن، أو المطلقات طلاقًا بائنًا في أثناء عدتهن، ولا ذنب عليكم أيضًا فيما أضمرتموه في أنفسكم من نية الزواج بهن بعد انتهاء عدتهن. علم الله أنكم ستذكرون النساء المعتدَّات، ولن تصبروا على السكوت عنهن، لضعفكم؛ لذلك أباح لكم أن تذكروهن تلميحًا أو إضمارًا في النفس، واحذروا أن تواعدوهن على النكاح سرًا بالزنى أو الاتفاق على الزواج في أثناء العدة، إلا أن تقولوا قولا يُفْهَم منه أن مثلها يُرْغَبُ فيها الأزواج، ولا تعزموا على عقد النكاح في زمان العدة حتى تنقضي مدتها. واعلموا أن الله يعلم ما في أنفسكم فخافوه، واعلموا أن الله غفور لمن تاب من ذنوبه، حليم على عباده لا يعجل عليهم بالعقوبة.', 235, 1, 38, 31, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (243, 2, 1, 2, 243, 'لا إثم عليكم -أيها الأزواج- إن طلقتم النساء بعد العقد عليهن، وقبل أن تجامعوهن، أو تحددوا مهرًا لهن، ومتِّعوهن بشيء ينتفعن به جبرًا لهن، ودفعًا لوحشة الطلاق، وإزالة للأحقاد. وهذه المتعة تجب بحسب حال الرجل المطلِّق: على الغني قَدْر سَعَة رزقه، وعلى الفقير قَدْر ما يملكه، متاعًا على الوجه المعروف شرعًا، وهو حق ثابت على الذين يحسنون إلى المطلقات وإلى أنفسهم بطاعة الله.', 236, 1, 38, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (244, 2, 1, 2, 244, 'وإن طلَّقتم النساء بعد العقد عليهن، ولم تجامعوهن، ولكنكم ألزمتم أنفسكم بمهر محدد لهن، فيجب عليكم أن تعطوهن نصف المهر المتفق عليه، إلا أنْ تُسامِح المطلقات، فيتركن نصف المهر المستحق لهن، أو يسمح الزوج بأن يترك للمطلقة المهر كله، وتسامحكم أيها الرجال والنساء أقرب إلى خشية الله وطاعته، ولا تنسوا -أيها الناس- الفضل والإحسان بينكم، وهو إعطاء ما ليس بواجب عليكم، والتسامح في الحقوق. إن الله بما تعملون بصير، يُرغِّبكم في المعروف، ويحثُّكم على الفضل.', 237, 1, 38, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (245, 2, 1, 2, 245, 'حافظوا -أيها المسلمون- على الصلوات الخمس المفروضة بالمداومة على أدائها في أوقاتها بشروطها وأركانها وواجباتها، وحافظوا على الصلاة المتوسطة بينها وهي صلاة العصر، وقوموا في صلاتكم مطيعين لله، خاشعين ذليلين.', 238, 1, 39, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (246, 2, 1, 2, 246, 'فإن خفتم من عدو لكم فصلوا صلاة الخوف ماشين، أو راكبين، على أي هيئة تستطيعونها ولو بالإيماء، أو إلى غير جهة القبلة، فإذا زال خوفكم فصلُّوا صلاة الأمن، واذكروا الله فيها، ولا تنقصوها عن هيئتها الأصلية، واشكروا له على ما علَّمكم من أمور العبادات والأحكام ما لم تكونوا على علم به.', 239, 1, 39, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (247, 2, 1, 2, 247, 'والأزواج الذين يموتون ويتركون زوجات بعدهم، فعليهم وصيةً لهنَّ: أن يُمَتَّعن سنه تامة من يوم الوفاة، بالسكنى في منزل الزوج من غير إخراج الورثة لهن مدة السنة؛ جبرًا لخاطر الزوجة، وبرًا بالمتوفَّى. فإن خرجت الزوجات باختيارهن قبل انقضاء السنة فلا إثم عليكم -أيها الورثة- في ذلك، ولا حرج على الزوجات فيما فعلن في أنفسهن من أمور مباحة. والله عزيز في ملكه، حكيم في أمره ونهيه. وهذه الآية منسوخة بقوله تعالى: (والذين يتوفون منكم ويذرون أزواجًا يتربصن بأنفسهن أربعة أشهر وعشرًا).', 240, 1, 39, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (248, 2, 1, 2, 248, 'وللمطلقات متاع من كسوة ونفقة على الوجه المعروف المستحسن شرعًا، حقًا على الذين يخافون الله ويتقونه في أمره ونهيه.', 241, 1, 39, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (249, 2, 1, 2, 249, 'مثل ذلك البيان الواضح في أحكام الأولاد والنساء، يبيِّن الله لكم آياته وأحكامه في كل ما تحتاجونه في معاشكم ومعادكم؛ لكي تعقلوها وتعملوا بها.', 242, 1, 39, 32, NULL, 15, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (250, 2, 1, 2, 250, 'ألم تعلم -أيها الرسول- قصة الذين فرُّوا من أرضهم ومنازلهم، وهم ألوف كثيرة؛ خشية الموت من الطاعون أو القتال، فقال لهم الله: موتوا، فماتوا دفعة واحدة عقوبة على فرارهم من قدر الله، ثم أحياهم الله تعالى بعد مدة؛ ليستوفوا آجالهم، وليتعظوا ويتوبوا؟ إن الله لذو فضل عظيم على الناس بنعمه الكثيرة، ولكن أكثر الناس لا يشكرون فضل الله عليهم.', 243, 1, 39, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (251, 2, 1, 2, 251, 'وقاتلوا -أيها المسلمون- الكفار لنصرة دين الله، واعلموا أن الله سميع لأقوالكم، عليم بنيَّاتكم وأعمالكم.', 244, 1, 39, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (252, 2, 1, 2, 252, 'من ذا الذي ينفق في سبيل الله إنفاقًا حسنًا احتسابًا للأجر، فيضاعفه له أضعافا كثيرة لا تحصى من الثواب وحسن الجزاء؟ والله يقبض ويبسط، فأنفقوا ولا تبالوا؛ فإنه هو الرزاق، يُضيِّق على مَن يشاء من عباده في الرزق، ويوسعه على آخرين، له الحكمة البالغة في ذلك، وإليه وحده ترجعون بعد الموت، فيجازيكم على أعمالكم.', 245, 1, 39, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (253, 2, 1, 2, 253, 'ألم تعلم -أيها الرسول- قصة الأشراف والوجهاء من بني إسرائيل من بعد زمان موسى؛ حين طلبوا من نبيهم أن يولي عليهم ملكا، يجتمعون تحت قيادته، ويقاتلون أعداءهم في سبيل الله. قال لهم نبيهم: هل الأمر كما أتوقعه إنْ فُرِض عليكم القتال في سبيل الله أنكم لا تقاتلون؛ فإني أتوقع جبنكم وفراركم من القتال، قالوا مستنكرين توقع نبيهم: وأي مانع يمنعنا عن القتال في سبيل الله، وقد أَخْرَجَنَا عدوُّنا من ديارنا، وأبعدنا عن أولادنا بالقتل والأسر؟ فلما فرض الله عليهم القتال مع الملِك الذي عيَّنه لهم جَبُنوا وفرُّوا عن القتال، إلا قليلا منهم ثبتوا بفضل الله. والله عليم بالظالمين الناكثين عهودهم.', 246, 1, 40, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (254, 2, 1, 2, 254, 'وقال لهم نبيهم: إن الله قد أرسل إليكم طالوت مَلِكًا إجابة لطلبكم، يقودكم لقتال عدوكم كما طلبتم. قال كبراء بني إسرائيل: كيف يكون طالوت مَلِكًا علينا، وهو لا يستحق ذلك؟ لأنه ليس من سبط الملوك، ولا من بيت النبوة، ولم يُعْط كثرة في الأموال يستعين بها في ملكه، فنحن أحق بالملك منه؛ لأننا من سبط الملوك ومن بيت النبوة. قال لهم نبيهم: إن الله اختاره عليكم وهو سبحانه أعلم بأمور عباده، وزاده سَعَة في العلم وقوة في الجسم ليجاهد العدو. والله مالك الملك يعطي ملكه مَن يشاء من عباده، والله واسع الفضل والعطاء، عليم بحقائق الأمور، لا يخفى عليه شيء.', 247, 1, 40, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (255, 2, 1, 2, 255, 'وقال لهم نبيهم: إن علامة ملكه أن يأتيكم الصندوق الذي فيه التوراة -وكان أعداؤهم قد انتزعوه منهم- فيه طمأنينة من ربكم تثبت قلوب المخلصين، وفيه بقية من بعض أشياء تركها آل موسى وآل هارون، مثل العصا وفُتات الألواح تحمله الملائكة. إن في ذلك لأعظم برهان لكم على اختيار طالوت ملكًا عليكم بأمر الله، إن كنتم مصدقين بالله ورسله.', 248, 1, 40, 33, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (256, 2, 1, 2, 256, 'فلما خرج طالوت بجنوده لقتال العمالقة قال لهم: إن الله ممتحنكم على الصبر بنهر أمامكم تعبرونه؛ ليتميَّز المؤمن من المنافق، فمن شرب منكم من ماء النهر فليس مني، ولا يصلح للجهاد معي، ومن لم يذق الماء فإنه مني؛ لأنه مطيع لأمري وصالح للجهاد، إلا مَن ترخَّص واغترف غُرْفة واحدة بيده فلا لوم عليه. فلما وصلوا إلى النهر انكبوا على الماء، وأفرطوا في الشرب منه، إلا عددًا قليلا منهم صبروا على العطش والحر، واكتفوا بغُرْفة اليد، وحينئذ تخلف العصاة. ولما عبر طالوت النهر هو والقلة المؤمنة معه -وهم ثلاثمائة وبضعة عشر رجلا لملاقاة العدو، ورأوا كثرة عدوهم وعدَّتهم، قالوا: لا قدرة لنا اليوم بجالوت وجنوده الأشداء، فأجاب الذين يوقنون بلقاء الله، يُذَكِّرون إخوانهم بالله وقدرته قائلين: كم من جماعة قليلة مؤمنة صابرة، غلبت بإذن الله وأمره جماعة كثيرة كافرة باغية. والله مع الصابرين بتوفيقه ونصره، وحسن مثوبته.', 249, 1, 41, 34, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (257, 2, 1, 2, 257, 'ولما ظهروا لجالوت وجنوده، ورأوا الخطر رأي العين، فزعوا إلى الله بالدعاء والضراعة قائلين: ربنا أنزل على قلوبنا صبرًا عظيمًا، وثبت أقدامنا، واجعلها راسخة في قتال العدو، لا تفر مِن هول الحرب، وانصرنا بعونك وتأييدك على القوم الكافرين.', 250, 1, 41, 34, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (258, 2, 1, 2, 258, 'فهزموهم بإذن الله، وقتل داود -عليه السلام- جالوتَ قائدَ الجبابرة، وأعطى الله عز وجل داود بعد ذلك الملك والنبوة في بني إسرائيل، وعَلَّمه مما يشاء من العلوم. ولولا أن يدفع الله ببعض الناس -وهم أهل الطاعة له والإيمان به- بعضًا، وهم أهل المعصية لله والشرك به، لفسدت الأرض بغلبة الكفر، وتمكُّن الطغيان، وأهل المعاصي، ولكن الله ذو فضل على المخلوقين جميعًا.', 251, 1, 41, 34, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (259, 2, 1, 2, 259, 'تلك حجج الله وبراهينه، نقصُّها عليك -أيها النبي- بالصدق، وإنك لمن المرسلين الصادقين.', 252, 1, 41, 34, NULL, 16, 4);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (260, 2, 1, 3, 260, 'هؤلاء الرسل الكرام فضَّل الله بعضهم على بعض، بحسب ما منَّ الله به عليهم: فمنهم مَن كلمه الله كموسى ومحمد عليهما الصلاة والسلام، وفي هذا إثبات صفة الكلام لله عز وجل على الوجه اللائق بجلاله، ومنهم مَن رفعه الله درجاتٍ عاليةً كمحمد صلى الله عليه وسلم، بعموم رسالته، وختم النبوة به، وتفضيل أمته على جميع الأمم، وغير ذلك. وآتى الله تعالى عيسى ابن مريم عليه السلام البينات المعجزات الباهرات، كإبراء مَن ولد أعمى بإذن الله تعالى، ومَن به برص بإذن الله، وكإحيائه الموتى بإذن الله، وأيده بجبريل عليه السلام. ولو شاء الله ألا يقتتل الذين جاؤوا مِن بعد هؤلاء الرسل مِن بعد ما جاءتهم البينات ما اقتتلوا، ولكن وقع الاختلاف بينهم: فمنهم مَن ثبت على إيمانه، ومنهم مَن أصر على كفره. ولو شاء الله بعد ما وقع الاختلاف بينهم، الموجب للاقتتال، ما اقتتلوا، ولكن الله يوفق مَن يشاء لطاعته والإيمان به، ويخذل مَن يشاء، فيعصيه ويكفر به، فهو يفعل ما يشاء ويختار.', 253, 1, 42, 34, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (261, 2, 1, 3, 261, 'يا من آمنتم بالله وصدَّقتم رسوله وعملتم بهديه أخرجوا الزكاة المفروضة، وتصدَّقوا مما أعطاكم الله قبل مجيء يوم القيامة حين لا بيع فيكون ربح، ولا مال تفتدون به أنفسكم مِن عذاب الله، ولا صداقة صديق تُنقذكم، ولا شافع يملك تخفيف العذاب عنكم. والكافرون هم الظالمون المتجاوزون حدود الله.', 254, 1, 42, 35, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (262, 2, 1, 3, 262, 'الله الذي لا يستحق الألوهية والعبودية إلا هو، الحيُّ الذي له جميع معاني الحياة الكاملة كما يليق بجلاله، القائم على كل شيء، لا تأخذه سِنَة أي: نعاس، ولا نوم، كل ما في السماوات وما في الأرض ملك له، ولا يتجاسر أحد أن يشفع عنده إلا بإذنه، محيط علمه بجميع الكائنات ماضيها وحاضرها ومستقبلها، يعلم ما بين أيدي الخلائق من الأمور المستقبلة، وما خلفهم من الأمور الماضية، ولا يَطَّلعُ أحد من الخلق على شيء من علمه إلا بما أعلمه الله وأطلعه عليه. وسع كرسيه السماوات والأرض، والكرسي: هو موضع قدمي الرب -جل جلاله- ولا يعلم كيفيته إلا الله سبحانه، ولا يثقله سبحانه حفظهما، وهو العلي بذاته وصفاته على جميع مخلوقاته، الجامع لجميع صفات العظمة والكبرياء. وهذه الآية أعظم آية في القرآن، وتسمى: (آية الكرسي).', 255, 1, 42, 35, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (263, 2, 1, 3, 263, 'لكمال هذا الدين واتضاح آياته لا يُحتاج إلى الإكراه عليه لمن تُقبل منهم الجزية، فالدلائل بينة يتضح بها الحق من الباطل، والهدى من الضلال. فَمَن يكفر بكل ما عُبِد من دون الله ويؤمن بالله، فقد ثبت واستقام على الطريقة المثلى، واستمسك من الدين بأقوى سبب لا انقطاع له. والله سميع لأقوال عباده، عليم بأفعالهم ونياتهم، وسيجازيهم على ذلك.', 256, 1, 42, 35, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (264, 2, 1, 3, 264, 'الله يتولى المؤمنين بنصره وتوفيقه وحفظه، يخرجهم من ظلمات الكفر، إلى نور الإيمان. والذين كفروا أنصارهم وأولياؤهم الأنداد والأوثان الذين يعبدونهم من دون الله، يُخرجونهم من نور الإيمان إلى ظلمات الكفر، أولئك أصحاب النار الملازمون لها، هم فيها باقون بقاء أبديًا لا يخرجون منها.', 257, 1, 43, 35, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (265, 2, 1, 3, 265, 'هل رأيت -أيها الرسول- أعجب مِن حال هذا الذي جادل إبراهيم عليه السلام في توحيد الله تعالى وربوبيته؛ لأن الله أعطاه المُلْك فتجبَّر وسأل إبراهيمَ: مَن ربُّك؟ فقال عليه السلام: ربي الذي يحيي الخلائق فتحيا، ويسلبها الحياة فتموت، فهو المتفرد بالإحياء والإماتة، قال: أنا أحيي وأميت، أي أقتل مَن أردتُ قَتْلَه، وأستبقي مَن أردت استبقاءه، فقال له إبراهيم: إن الله الذي أعبده يأتي بالشمس من المشرق، فهل تستطيع تغيير هذه السُّنَّة الإلهية بأن تجعلها تأتي من المغرب؛ فتحيَّر هذا الكافر وانقطعت حجته، شأنه شأن الظالمين لا يهديهم الله إلى الحق والصواب.', 258, 1, 43, 36, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (266, 2, 1, 3, 266, 'أو هل رأيت -أيها الرسول- مثل الذي مرَّ على قرية قد تهدَّمت دورها، وخَوَتْ على عروشها، فقال: كيف يحيي الله هذه القرية بعد موتها؟ فأماته الله مائة عام، ثم ردَّ إليه روحه، وقال له: كم قدر الزمان الذي لبثت ميتًا؟ قال: بقيت يومًا أو بعض يوم، فأخبره بأنه بقي ميتًا مائة عام، وأمره أن ينظر إلى طعامه وشرابه، وكيف حفظهما الله من التغيُّر هذه المدة الطويلة، وأمره أن ينظر إلى حماره كيف أحياه الله بعد أن كان عظامًا متفرقة؟ وقال له: ولنجعلك آية للناس، أي: دلالة ظاهرة على قدرة الله على البعث بعد الموت، وأمره أن ينظر إلى العظام كيف يرفع الله بعضها على بعض، ويصل بعضها ببعض، ثم يكسوها بعد الالتئام لحمًا، ثم يعيد فيها الحياة؟ فلما اتضح له ذلك عِيانًا اعترف بعظمة الله، وأنه على كل شيء قدير، وصار آية للناس.', 259, 1, 43, 36, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (267, 2, 1, 3, 267, 'واذكر -أيها الرسول- طلب إبراهيم من ربه أن يريه كيفية البعث، فقال الله له: أَوَلم تؤمن؟ قال: بلى، ولكن أطلب ذلك لأزداد يقينًا على يقيني، قال: فخذ أربعة من الطير فاضممهن إليك واذبحهن وقطعهن، ثم اجعل على كل جبل منهن جزءًا، ثم نادِهن يأتينك مسرعات. فنادى إبراهيم عليه السلام، فإذا كل جزء يعود إلى موضعه، وإذا بها تأتي مسرعة. واعلم أن الله عزيز لا يغلبه شيء، حكيم في أقواله وأفعاله وشرعه وقدره.', 260, 1, 44, 36, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (268, 2, 1, 3, 268, 'ومِن أعظم ما ينتفع به المؤمنون الإنفاقُ في سبيل الله. ومثل المؤمنين الذين ينفقون أموالهم في سبيل الله كمثل حبة زُرِعتْ في أرض طيبة، فإذا بها قد أخرجت ساقًا تشعب منها سبع شعب، لكل واحدة سنبلة، في كل سنبلة مائة حبة. والله يضاعف الأجر لمن يشاء، بحسب ما يقوم بقلب المنفق من الإيمان والإخلاص التام. وفضل الله واسع، وهو سبحانه عليم بمن يستحقه، مطلع على نيات عباده.', 261, 1, 44, 37, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (269, 2, 1, 3, 269, 'الذين يخرجون أموالهم في الجهاد وأنواع الخير، ثم لا يتبعون ما أنفقوا من الخيرات مَنّاً على مَن أعطَوه ولا أذى بقول أو فِعْلٍ يشعره بالتفضل عليه، لهم ثوابهم العظيم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على شيء فاتهم في هذه الدنيا.', 262, 1, 44, 37, NULL, 17, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (270, 2, 1, 3, 270, 'كلام طيب وعفو عما بدر مِن السائل مِن إلحافٍ في السؤال، خير من صدقة يتبعها من المتصدق أذى وإساءة. والله غني عن صدقات العباد، حليم لا يعاجلهم بالعقوبة.', 263, 1, 44, 37, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (271, 2, 1, 3, 271, 'يا من آمنتم بالله واليوم الآخر لا تُذْهِبُوا ثواب ما تتصدقون به بالمنِّ والأذى، فهذا شبيه بالذي يخرج ماله ليراه الناس، فيُثنوا عليه، وهو لا يؤمن بالله ولا يوقن باليوم الآخر، فمثل ذلك مثل حجر أملس عليه تراب هطل عليه مطر غزير فأزاح عنه التراب، فتركه أملس لا شيء عليه، فكذلك هؤلاء المراؤون تضمحلُّ أعمالهم عند الله، ولا يجدون شيئًا من الثواب على ما أنفقوه. والله لا يوفق الكافرين لإصابة الحق في نفقاتهم وغيرها.', 264, 1, 44, 37, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (272, 2, 1, 3, 272, 'ومثل الذين ينفقون أموالهم طلبًا لرضا الله واعتقادًا راسخًا بصدق وعده، كمثل بستان عظيم بأرض عالية طيبة هطلت عليه أمطار غزيرة، فتضاعفت ثمراته، وإن لم تسقط عليه الأمطار الغزيرة فيكفيه رذاذ المطر ليعطي الثمرة المضاعفة، وكذلك نفقات المخلصين تُقبل عند الله وتُضاعف، قلَّت أم كثُرت، فالله المُطَّلِع على السرائر، البصير بالظواهر والبواطن، يثيب كلا بحسب إخلاصه.', 265, 1, 45, 37, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (273, 2, 1, 3, 273, 'أيرغب الواحد منكم أن يكون له بستان فيه النخيل والأعناب، تجري من تحت أشجارِه المياه العذبة، وله فيه من كل ألوان الثمرات، وقد بلغ الكِبَر، ولا يستطيع أن يغرس مثل هذا الغرس، وله أولاد صغار في حاجة إلى هذا البستان وفي هذه الحالة هبَّت عليه ريح شديدة، فيها نار محرقة فأحرقته؛ وهكذا حال غير المخلصين في نفقاتهم، يأتون يوم القيامة ولا حسنة لهم. وبمثل هذا البيان يبيِّن الله لكم ما ينفعكم؛ كي تتأملوا، فتخلصوا نفقاتكم لله.', 266, 1, 45, 37, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (274, 2, 1, 3, 274, 'يا من آمنتم بي واتبعتم رسلي أنفقوا من الحلال الطيب الذي كسبتموه ومما أخرجنا لكم من الأرض، ولا تقصدوا الرديء منه لتعطوه الفقراء، ولو أُعطِيتموه لم تأخذوه إلا إذا تغاضيتم عما فيه من رداءة ونقص. فكيف ترضون لله ما لا ترضونه لأنفسكم؟ واعلموا أن الله الذي رزقكم غني عن صدقاتكم، مستحق للثناء، محمود في كل حال.', 267, 1, 45, 38, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (275, 2, 1, 3, 275, 'هذا البخل واختيار الرديء للصدقة من الشيطان الذي يخوفكم الفقر، ويغريكم بالبخل، ويأمركم بالمعاصي ومخالفة الله تعالى، والله سبحانه وتعالى يعدكم على إنفاقكم غفرانًا لذنوبكم ورزقا واسعا. والله واسع الفضل، عليم بالأعمال والنيَّات.', 268, 1, 45, 38, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (276, 2, 1, 3, 276, 'يؤتي الله الإصابة في القول والفعل مَن يشاء من عباده، ومن أنعم الله عليه بذلك فقد أعطاه خيرًا كثيرًا. وما يتذكر هذا وينتفع به إلا أصحاب العقول المستنيرة بنور الله وهدايته.', 269, 1, 45, 38, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (277, 2, 1, 3, 277, 'وما أعطيتم من مال أو غيره كثير أو قليل تتصدقون به ابتغاء مرضات الله أو أوجبتم على أنفسكم شيئًا من مال أو غيره، فإن الله يعلمه، وهو المُطَّلِع على نياتكم، وسوف يثيبكم على ذلك. ومَن منع حق الله فهو ظالم، والظالمون ليس لهم أنصار يمنعونهم من عذاب الله.', 270, 1, 46, 38, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (278, 2, 1, 3, 278, 'إن تظهروا ما تتصدقون به لله فنِعْمَ ما تصدقتم به، وإن تسرُّوا بها، وتعطوها الفقراء فهذا أفضل لكم؛ لأنه أبعد عن الرياء، وفي الصدقة -مع الإخلاص- محو لذنوبكم. والله الذي يعلم دقائق الأمور، لا يخفى عليه شيء من أحوالكم، وسيجازي كلا بعمله.', 271, 1, 46, 38, NULL, 18, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (279, 2, 1, 3, 279, 'لست -أيها الرسول- مسئولا عن توفيق الكافرين للهداية، ولكن الله يشرح صدور مَن يشاء لدينه، ويوفقه له. وما تبذلوا من مال يَعُدْ عليكم نَفْعُه من الله، والمؤمنون لا ينفقون إلا طلبًا لمرضاة الله. وما تنفقوا من مال -مخلصين لله- توفوا ثوابه، ولا تُنْقَصُوا شيئا من ذلك. وفي الآية إثبات صفة الوجه لله تعالى على ما يليق به سبحانه.', 272, 1, 46, 38, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (280, 2, 1, 3, 280, 'اجعلوا صدقاتكم لفقراء المسلمين الذين لا يستطيعون السفر؛ طلبًا للرزق لاشتغالهم بالجهاد في سبيل الله، يظنهم مَن لا يعرفهم غير محتاجين إلى الصدقة؛ لتعففهم عن السؤال، تعرفهم بعلاماتهم وآثار الحاجة فيهم، لا يسألون الناس بالكُليَّة، وإن سألوا اضطرارًا لم يُلِحُّوا في السؤال. وما تنفقوا مِن مال في سبيل الله فلا يخفى على الله شيء منه، وسيجزي عليه أوفر الجزاء وأتمَّه يوم القيامة.', 273, 1, 46, 38, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (281, 2, 1, 3, 281, 'الذين يُخْرجون أموالهم مرضاة لله ليلا ونهارًا مسرِّين ومعلنين، فلهم أجرهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا. ذلك التشريع الإلهي الحكيم هو منهاج الإسلام في الإنفاق لما فيه مِن سدِّ حاجة الفقراء في كرامة وعزة، وتطهير مال الأغنياء، وتحقيق التعاون على البر والتقوى؛ ابتغاء وجه الله دون قهر أو إكراه.', 274, 1, 46, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (282, 2, 1, 3, 282, 'الذين يتعاملون بالربا -وهو الزيادة على رأس المال- لا يقومون في الآخرة من قبورهم إلا كما يقوم الذي يتخبطه الشيطان من الجنون؛ ذلك لأنهم قالوا: إنما البيع مثل الربا، في أن كلا منهما حلال، ويؤدي إلى زيادة المال، فأكذبهم الله، وبيَّن أنه أحل البيع وحرَّم الربا؛ لما في البيع والشراء من نفع للأفراد والجماعات، ولما في الربا من استغلال وضياع وهلاك. فمن بلغه نهي الله عن الربا فارتدع، فله ما مضى قبل أن يبلغه التحريم لا إثم عليه فيه، وأمره إلى الله فيما يستقبل من زمانه، فإن استمرَّ على توبته فالله لا يضيع أجر المحسنين، ومن عاد إلى الربا ففعله بعد بلوغه نهي الله عنه، فقد استوجب العقوبة، وقامت عليه الحجة، ولهذا قال سبحانه: (فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ)', 275, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (283, 2, 1, 3, 283, 'يذهب الله الربا كله أو يحرم صاحبه بركة ماله، فلا ينتفع به، وينمي الصدقات ويكثرها، ويضاعف الأجر للمتصدقين، ويبارك لهم في أموالهم. والله لا يحب كل مُصِرٍّ على كفره، مُسْتَحِلٍّ أكل الربا، متمادٍ في الإثم والحرام ومعاصي الله.', 276, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (284, 2, 1, 3, 284, 'إن الذين صدقوا الله ورسوله، وعملوا الأعمال الطيبة، وأدَّوا الصلاة كما أمر الله ورسوله، وأخرجوا زكاة أموالهم، لهم ثواب عظيم خاص بهم عند ربهم ورازقهم، ولا يلحقهم خوف في آخرتهم، ولا حزن على ما فاتهم من حظوظ دنياهم.', 277, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (285, 2, 1, 3, 285, 'يا من آمنتم بالله واتبعتم رسوله خافوا الله، واتركوا طلب ما بقي لكم من زيادة على رؤوس أموالكم التي كانت لكم قبل تحريم الربا، إن كنتم محققين إيمانكم قولا وعملا.', 278, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (286, 2, 1, 3, 286, 'فإن لم ترتدعوا عما نهاكم الله عنه فاستيقنوا بحرب من الله ورسوله، وإن رجعتم إلى ربكم وتركتم أَكْلَ الربا فلكم أَخْذُ ما لكم من ديون دون زيادة، لا تَظْلمون أحدًا بأخذ ما زاد على رؤوس أموالكم، ولا يظلمكم أحد بنقص ما أقرضتم.', 279, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (287, 2, 1, 3, 287, 'وإن كان المدين غير قادر على السداد فأمهلوه إلى أن ييسِّر الله له رزقًا فيدفع إليكم مالكم، وإن تتركوا رأس المال كله أو بعضه وتضعوه عن المدين فهو أفضل لكم، إن كنتم تعلمون فَضْلَ ذلك، وأنَّه خير لكم في الدنيا والآخرة.', 280, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (288, 2, 1, 3, 288, 'واحذروا -أيها الناس- يومًا ترجعون فيه إلى الله، وهو يوم القيامة، حيث تعرضون على الله ليحاسبكم، فيجازي كل واحد منكم بما عمل من خير أو شر دون أن يناله ظلم. وفي الآية إشارة إلى أن اجتناب ما حرم الله من المكاسب الربوية، تكميل للإيمان وحقوقه من إقام الصلاة وإيتاء الزكاة وعمل الصالحات.', 281, 1, 47, 39, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (289, 2, 1, 3, 289, 'يا من آمنتم بالله واتبعتم رسوله محمدًا صلى الله عليه وسلم إذا تعاملتم بدَيْن إلى وقت معلوم فاكتبوه؛ حفظًا للمال ودفعًا للنزاع. ولْيقُم بالكتابة رجل أمين ضابط، ولا يمتنع مَن علَّمه الله الكتابة عن ذلك، ولْيقم المدين بإملاء ما عليه من الدَّيْن، وليراقب ربه، ولا ينقص من دينه شيئا. فإن كان المدين محجورًا عليه لتبذيره وإسرافه، أو كان صغيرًا أو مجنونًا، أو لا يستطيع النطق لخرس به أو عدم قدرة كاملة على الكلام، فليتولَّ الإملاء عن المدين القائم بأمره، واطلبوا شهادة رجلين مسلمَيْن بالِغَيْن عاقلَيْن من أهل العدالة. فإن لم يوجد رجلان، فاطلبوا شهادة رجل وامرأتين ترضون شهادتهم، حتى إذا نَسِيَتْ إحداهما ذكَّرتها الأخرى، وعلى الشهداء أن يجيبوا مَن دعاهم إلى الشهادة، وعليهم أداؤها إذا ما دعوا إليها، ولا تَمَلُّوا من كتابة الدَّين قليلا أو كثيرًا إلى وقته المعلوم. ذلكم أعدل في شرع الله وهديه، وأعظم عونًا على إقامة الشهادة وأدائها، وأقرب إلى نفي الشك في جنس الدَّين وقدره وأجله. لكن إن كانت المسألة مسألة بيع وشراء، بأخذ سلعة ودفع ثمنها في الحال، فلا حاجة إلى الكتابة، ويستحب الإشهاد على ذلك منعًا للنزاع والشقاق، ومن الواجب على الشاهد والكاتب أداء الشهادة على وجهها والكتابة كما أمر الله. ولا يجوز لصاحب الحق ومَن عليه الحق الإضرار بالكُتَّاب والشهود، وكذلك لا يجوز للكُتَّاب والشهود أن يضارُّوا بمن احتاج إلى كتابتهم أو شهادتهم، وإن تفعلوا ما نهيتم عنه فإنه خروج عن طاعة الله، وعاقبة ذلك حالَّة بكم. وخافوا الله في جميع ما أمركم به، ونهاكم عنه، ويعلمكم الله جميع ما يصلح دنياكم وأخراكم. والله بكل شيء عليم، فلا يخفى عليه شيء من أموركم، وسيجازيكم على ذلك.', 282, 1, 48, 40, NULL, 19, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (290, 2, 1, 3, 290, 'وإن كنتم مسافرين ولم تجدوا مَن يكتب لكم فادفعوا إلى صاحب الحق شيئًا يكون عنده ضمانًا لحقِّه إلى أن يردَّ المدينُ ما عليه من دين، فإن وثق بعضكم ببعض فلا حرج في ترك الكتابة والإشهاد والرهن، ويبقى الدَّين أمانة في ذمَّة المدين، عليه أداؤه، وعليه أن يراقب الله فلا يخون صاحبه. فإن أنكر المدين ما عليه من دين، وكان هناك مَن حضر وشهد، فعليه أن يظهر شهادته، ومن أخفى هذه الشهادة فهو صاحب قلب غادر فاجر. والله المُطَّلِع على السرائر، المحيط علمه بكل أموركم، سيحاسبكم على ذلك.', 283, 1, 49, 40, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (291, 2, 1, 3, 291, 'لله ملك السماوات والأرض وما فيهما ملكًا وتدبيرًا وإحاطة، لا يخفى عليه شيء. وما تظهروه مما في أنفسكم أو تخفوه فإن الله يعلمه، وسيحاسبكم به، فيعفو عمن يشاء، ويؤاخذ من يشاء. والله قادر على كل شيء، وقد أكرم الله المسلمين بعد ذلك فعفا عن حديث النفس وخطرات القلب ما لم يتبعها كلام أو عمل، كما ثبت ذلك عن رسول الله صلى الله عليه وسلم.', 284, 1, 49, 41, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (292, 2, 1, 3, 292, 'صدَّق وأيقن رسول الله محمد صلى الله عليه وسلم بما أوحي إليه من ربه وحُقَّ له أن يُوقن، والمؤمنون كذلك صدقوا وعملوا بالقرآن العظيم، كل منهم صدَّق بالله رباً وإلهًا متصفًا بصفات الجلال والكمال، وأن لله ملائكة كرامًا، وأنه أنزل كتبًا، وأرسل إلى خلقه رسلا لا نؤمن -نحن المؤمنين- ببعضهم وننكر بعضهم، بل نؤمن بهم جميعًا. وقال الرسول والمؤمنون: سمعنا يا ربنا ما أوحيت به، وأطعنا في كل ذلك، نرجو أن تغفر -بفضلك- ذنوبنا، فأنت الذي ربَّيتنا بما أنعمت به علينا، وإليك -وحدك- مرجعنا ومصيرنا.', 285, 1, 49, 41, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (293, 2, 1, 3, 293, 'دين الله يسر لا مشقة فيه، فلا يطلب الله مِن عباده ما لا يطيقونه، فمن فعل خيرًا نال خيرًا، ومن فعل شرّاً نال شرّاً. ربنا لا تعاقبنا إن نسينا شيئًا مما افترضته علينا، أو أخطأنا في فِعْل شيء نهيتنا عن فعله، ربَّنا ولا تكلفنا من الأعمال الشاقة ما كلفته مَن قبلنا من العصاة عقوبة لهم، ربنا ولا تُحَمِّلْنَا ما لا نستطيعه من التكاليف والمصائب، وامح ذنوبنا، واستر عيوبنا، وأحسن إلينا، أنت مالك أمرنا ومدبره، فانصرنا على مَن جحدوا دينك وأنكروا وحدانيتك، وكذَّبوا نبيك محمدًا صلى الله عليه وسلم، واجعل العاقبة لنا عليهم في الدنيا والآخرة.', 286, 1, 49, 41, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (294, 3, 1, 3, 294, 'سبق الكلام عليها في أول سورة البقرة.', 1, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (295, 3, 1, 3, 295, 'هو الله، لا معبود بحق إلا هو، المتصف بالحياة الكاملة كما يليق بجلاله، القائم على كل شيء.', 2, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (296, 3, 1, 3, 296, 'نَزَّل عليك القرآن بالحق الذي لا ريب فيه، مصدِّقًا لما قبله من كتب ورسل، وأنزل التوراة على موسى علبه السلام، والإنجيل على عيسى عليه السلام من قبل نزول القرآن؛ لإرشاد المتقين إلى الإيمان، وصلاح دينهم ودنياهم، وأنزل ما يفرق بين الحق والباطل. والذين كفروا بآيات الله المنزلة، لهم عذاب عظيم. والله عزيز لا يُغَالَب، ذو انتقام بمن جحد حججه وأدلته، وتفرُّده بالألوهية.', 3, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (297, 3, 1, 3, 297, 'لا يوجد تفسير لهذه الآية', 4, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (298, 3, 1, 3, 298, 'إن الله محيط علمه بالخلائق، لا يخفى عليه شيء في الأرض ولا في السماء، قلَّ أو كثر.', 5, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (299, 3, 1, 3, 299, 'هو وحده الذي يخلقكم في أرحام أمهاتكم كما يشاء، من ذكر وأنثى، وحسن وقبيح، وشقي وسعيد، لا معبود بحق سواه، العزيز الذي لا يُغالَب، الحكيم في أمره وتدبيره.', 6, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (300, 3, 1, 3, 300, 'هو وحده الذي أنزل عليك القرآن: منه آيات واضحات الدلالة، هن أصل الكتاب الذي يُرجع إليه عند الاشتباه، ويُرَدُّ ما خالفه إليه، ومنه آيات أخر متشابهات تحتمل بعض المعاني، لا يتعيَّن المراد منها إلا بضمها إلى المحكم، فأصحاب القلوب المريضة الزائغة، لسوء قصدهم يتبعون هذه الآيات المتشابهات وحدها؛ ليثيروا الشبهات عند الناس، كي يضلوهم، ولتأويلهم لها على مذاهبهم الباطلة. ولا يعلم حقيقة معاني هذه الآيات إلا الله. والمتمكنون في العلم يقولون: آمنا بهذا القرآن، كله قد جاءنا من عند ربنا على لسان رسوله محمد صلى الله عليه وسلم، ويردُّون متشابهه إلى محكمه، وإنما يفهم ويعقل ويتدبر المعاني على وجهها الصحيح أولو العقول السليمة.', 7, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (301, 3, 1, 3, 301, 'ويقولون: يا ربنا لا تَصْرِف قلوبنا عن الإيمان بك بعد أن مننت علينا بالهداية لدينك، وامنحنا من فضلك رحمة واسعة، إنك أنت الوهاب: كثير الفضل والعطاء، تعطي مَن تشاء بغير حساب.', 8, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (302, 3, 1, 3, 302, 'يا ربنا إنا نُقِرُّ ونشهد بأنك ستجمع الناس في يوم لا شَكَّ فيه، وهو يوم القيامة، إنَّك لا تُخلف ما وعَدْتَ به عبادك.', 9, 1, 50, 42, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (303, 3, 1, 3, 303, 'إن الذين جحدوا الدين الحق وأنكروه، لن تنفعهم أموالهم ولا أولادهم من عذاب الله شيئًا إن وقع بهم في الدنيا، ولن تدفعه عنهم في الآخرة، وهؤلاء هم حطب النار يوم القيامة.', 10, 1, 51, 43, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (304, 3, 1, 3, 304, 'شأن الكافرين في تكذيبهم وما ينزل بهم، شأن آل فرعون والذين من قبلهم من الكافرين، أنكروا آيات الله الواضحة، فعاجلهم بالعقوبة بسبب تكذيبهم وعنادهم. والله شديد العقاب لمن كفر به وكذَّب رسله.', 11, 1, 51, 43, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (305, 3, 1, 3, 305, 'قل -أيها الرسول-، للذين كفروا من اليهود وغيرهم والذين استهانوا بنصرك في "بَدْر": إنكم ستُهْزَمون في الدنيا وستموتون على الكفر، وتحشرون إلى نار جهنم؛ لتكون فراشًا دائمًا لكم، وبئس الفراش.', 12, 1, 51, 43, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (306, 3, 1, 3, 306, 'قد كان لكم -أيها اليهود المتكبرون المعاندون- دلالة عظيمة في جماعتين تقابلتا في معركة "بَدْر": جماعة تقاتل من أجل دين الله، وهم محمد صلى الله عليه وسلم وأصحابه، وجماعة أخرى كافرة بالله، تقاتل من أجل الباطل، ترى المؤمنين في العدد مثليهم رأي العين، وقد جعل الله ذلك سببًا لنصر المسلمين عليهم. والله يؤيِّد بنصره من يشاء من عباده. إن في هذا الذي حدث لَعِظة عظيمة لأصحاب البصائر الذين يهتدون إلى حكم الله وأفعاله.', 13, 1, 51, 43, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (307, 3, 1, 3, 307, 'حُسِّن للناس حبُّ الشهوات من النساء والبنين، والأموال الكثيرة من الذهب والفضة، والخيل الحسان، والأنعام من الإبل والبقر والغنم، والأرض المتَّخَذة للغراس والزراعة. ذلك زهرة الحياة الدنيا وزينتها الفانية. والله عنده حسن المرجع والثواب، وهو الجنَّة.', 14, 1, 51, 43, NULL, 20, 5);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (308, 3, 1, 3, 308, 'قل -أيها الرسول-: أأخبركم بخير مما زُيِّن للنَّاس في هذه الحياة الدنيا، لمن راقب الله وخاف عقابه جنات تجري من تحت قصورها وأشجارها الأنهار، خالدين فيها، ولهم فيها أزواج مطهرات من الحيض والنفاس وسوء الخلق، ولهم أعظم من ذلك: رضوان من الله. والله مطَّلِع على سرائر خلقه، عالم بأحوالهم، وسيجازيهم على ذلك.', 15, 1, 51, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (309, 3, 1, 3, 309, 'هؤلاء العباد المتقون يقولون: إننا آمنا بك، واتبعنا رسولك محمدًا صلى الله عليه وسلم، فامْحُ عنا ما اقترفناه من ذنوب، ونجنا من عذاب النار.', 16, 1, 52, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (310, 3, 1, 3, 310, 'هم الذين اتصفوا بالصبر على الطاعات، وعن المعاصي، وعلى ما يصيبهم من أقدار الله المؤلمة، وبالصدق في الأقوال والأفعال وبالطاعة التامة، وبالإنفاق سرا وعلانية، وبالاستغفار في آخر الليل؛ لأنه مَظِنَّة القبول وإجابة الدعاء.', 17, 1, 52, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (311, 3, 1, 3, 311, 'شهد الله أنه المتفرد بالإلهية، وقَرَنَ شهادته بشهادة الملائكة وأهل العلم، على أجلِّ مشهود عليه، وهو توحيده تعالى وقيامه بالعدل، لا إله إلا هو العزيز الذي لا يمتنع عليه شيء أراده، الحكيم في أقواله وأفعاله.', 18, 1, 52, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (312, 3, 1, 3, 312, 'إن الدين الذي ارتضاه الله لخلقه وأرسل به رسله، ولا يَقْبَل غيره هو الإسلام، وهو الانقياد لله وحده بالطاعة والاستسلام له بالعبودية، واتباع الرسل فيما بعثهم الله به في كل حين حتى خُتموا بمحمد صلى الله عليه وسلم، الذي لا يقبل الله مِن أحد بعد بعثته دينًا سوى الإسلام الذي أُرسل به. وما وقع الخلاف بين أهل الكتاب من اليهود والنصارى، فتفرقوا شيعًا وأحزابًا إلا من بعد ما قامت الحجة عليهم بإرسال الرسل وإنزال الكتب؛ بغيًا وحسدًا طلبًا للدنيا. ومن يجحد آيات الله المنزلة وآياته الدالة على ربوبيته وألوهيته، فإن الله سريع الحساب، وسيجزيهم بما كانوا يعملون.', 19, 1, 52, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (313, 3, 1, 3, 313, 'فإن جادلك -أيها الرسول- أهل الكتاب في التوحيد بعد أن أقمت الحجة عليهم فقل لهم: إنني أخلصت لله وحده فلا أشرك به أحدًا، وكذلك من اتبعني من المؤمنين، أخلصوا لله وانقادوا له. وقل لهم ولمشركي العرب وغيرهم: إن أسلمتم فأنتم على الطريق المستقيم والهدى والحق، وإن توليتم فحسابكم على الله، وليس عليَّ إلا البلاغ، وقد أبلغتكم وأقمت عليكم الحجة. والله بصير بالعباد، لا يخفى عليه من أمرهم شيء.', 20, 1, 52, 43, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (314, 3, 1, 3, 314, 'إن الذين يجحدون بالدلائل الواضحة وما جاء به المرسلون، ويقتلون أنبياء الله ظلمًا بغير حق، ويقتلون الذين يأمرون بالعدل واتباع طريق الأنبياء، فبشِّرهم بعذاب موجع.', 21, 1, 52, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (315, 3, 1, 3, 315, 'أولئك الذين بطلت أعمالهم في الدنيا والآخرة، فلا يُقبل لهم عمل، وما لهم من ناصرٍ ينصرهم من عذاب الله.', 22, 1, 52, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (316, 3, 1, 3, 316, 'أرأيت -أيها الرسول- أعجب من حال هؤلاء اليهود الذين أتاهم الله حظا من الكتاب فعلموا أن ما جئت به هو الحق، يُدْعون إلى ما جاء في كتاب الله -وهو القرآن- ليفصل بينهم فيما اختلفوا فيه، فإن لم يوافق أهواءهم يَأْبَ كثير منهم حكم الله؛ لأن من عادتهم الإعراض عن الحق؟', 23, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (317, 3, 1, 3, 317, 'ذلك الانصراف عن الحق سببه اعتقاد فاسد لدى أهل الكتاب؛ بأنهم لن يعذَّبوا إلا أيامًا قليلة، وهذا الاعتقاد أدى إلى جرأتهم على الله واستهانتهم بدينه، واستمرارهم على دينهم الباطل الذي خَدَعوا به أنفسهم.', 24, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (318, 3, 1, 3, 318, 'فكيف يكون حالهم إذا جمعهم الله ليحاسَبوا في يوم لا شك في وقوعه -وهو يوم القيامة-، وأخذ كل واحد جزاءَ ما اكتسب، وهم لا يظلمون شيئا؟', 25, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (319, 3, 1, 3, 319, 'قل -أيها النبي متوجها إلى ربك بالدعاء-: يا مَن لك الملك كلُّه، أنت الذي تمنح الملك والمال والتمكين في الأرض مَن تشاء مِن خلقك، وتسلب الملك ممن تشاء، وتهب العزة في الدنيا والآخرة مَن تشاء، وتجعل الذلَّة على من تشاء، بيدك الخير، إنك -وحدك- على كل شيء قدير. وفي الآية إثبات لصفة اليد لله تعالى على ما يليق به سبحانه.', 26, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (320, 3, 1, 3, 320, 'ومن دلائل قدرتك أنك تُدخل الليل في النهار، وتُدخل النهار في الليل، فيطول هذا ويقصر ذاك، وتُخرج الحي من الميت الذي لا حياة فيه، كإخراج الزرع من الحب، والمؤمن من الكافر، وتُخرج الميت من الحي كإخراج البيض من الدجاج، وترزق من تشاء مَن خلقك بغير حساب.', 27, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (321, 3, 1, 3, 321, 'ينهى الله المؤمنين أن يتخذوا الكافرين أولياء بالمحبة والنصرة من دون المؤمنين، ومَن يتولهم فقد برِئ من الله، والله برِيء منه، إلا أن تكونوا ضعافًا خائفين فقد رخَّص الله لكم في مهادنتهم اتقاء لشرهم، حتى تقوى شوكتكم، ويحذركم الله نفسه، فاتقوه وخافوه. وإلى الله وحده رجوع الخلائق للحساب والجزاء.', 28, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (322, 3, 1, 3, 322, 'قل -أيها النبي- للمؤمنين: إن تكتموا ما استقر في قلوبكم من ممالاة الكافرين ونصرتهم أم تظهروا ذلك لا يَخْفَ على الله منه شيء، فإنَّ علمه محيط بكل ما في السماوات وما في الأرض، وله القدرة التامة على كل شيء.', 29, 1, 53, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (323, 3, 1, 3, 323, 'وفي يوم القيامة يوم الجزاء تجد كل نفس ما عملت من خير ينتظرها موفرًا لتُجزَى به، وما عملت من عمل سيِّئ تجده في انتظارها أيضًا، فتتمنى لو أن بينها وبين هذا العمل زمنًا بعيدًا. فاستعدوا لهذا اليوم، وخافوا بطش الإله الجبار. ومع شدَّة عقابه فإنه سبحانه رءوف بالعباد.', 30, 1, 54, 44, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (324, 3, 1, 3, 324, 'قل -أيها الرسول-: إن كنتم تحبون الله حقا فاتبعوني وآمنوا بي ظاهرًا وباطنًا، يحببكم الله، ويمحُ ذنوبكم، فإنه غفور لذنوب عباده المؤمنين، رحيم بهم. وهذه الآية الكريمة حاكمة على كل من ادعى محبة الله -تعالى- وليس متبعًا لنبيه محمد صلى الله عيه وسلم حق الاتباع، مطيعًا له في أمره ونهيه، فإنه كاذب في دعواه حتى يتابع الرسول صلى الله عليه وسلم حق الاتباع.', 31, 1, 54, 45, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (325, 3, 1, 3, 325, 'قل -أيها الرسول-: أطيعوا الله باتباع كتابه، وأطيعوا الرسول باتباع سنته في حياته وبعد مماته، فإن هم أعرضوا عنك، وأصروا على ما هم عليه مِن كفر وضلال، فليسوا أهلا لمحبة الله؛ فإن الله لا يحب الكافرين.', 32, 1, 54, 45, NULL, 21, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (326, 3, 1, 3, 326, 'إن الله اختار آدم ونوحًا وآل إبراهيم وآل عمران، وجعلهم أفضل أهل زمانهم.', 33, 1, 54, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (327, 3, 1, 3, 327, 'هؤلاء الأنبياء والرسل سلسلة طُهْر متواصلة في الإخلاص لله وتوحيده والعمل بوحيه. والله سميع لأقوال عباده، عليم بأفعالهم، وسيجازيهم على ذلك.', 34, 1, 54, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (328, 3, 1, 3, 328, 'اذكر -أيها الرسول- ما كان من أمر مريم وأمها وابنها عيسى عليه السلام؛ لتردَّ بذلك على من ادعوا أُلوهية عيسى أو بنوَّته لله سبحانه، إذ قالت امرأة عمران حين حملت: يا ربِّ إني جعلت لك ما في بطني خالصا لك، لخدمة "بيت المقدس"، فتقبَّل مني؛ إنك أنت وحدك السميع لدعائي، العليم بنيتي.', 35, 1, 54, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (329, 3, 1, 3, 329, 'فلما تمَّ حملها ووضعت مولودها قالت: ربِّ إني وضعتها أنثى لا تصلح للخدمة في "بيت المقدس" -والله أعلم بما وضَعَتْ، وسوف يجعل الله لها شأنًا- وقالت: وليس الذكر الذي أردت للخدمة كالأنثى في ذلك؛ لأن الذكر أقوى على الخدمة وأقْوَم بها، وإني سمَّيتها مريم، وإني حصَّنتها بك هي وذريَّتها من الشيطان المطرود من رحمتك.', 36, 1, 54, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (330, 3, 1, 3, 330, 'فاستجاب الله دعاءها وقبل منها نَذْرها أحسن قَبول، وتولَّى ابنتها مريم بالرعاية فأنبتها نباتًا حسنًا، ويسَّر الله لها زكريا عليه السلام كافلا فأسكنها في مكان عبادته، وكان كلَّما دخل عليها هذا المكان وجد عندها رزقًا هنيئًا معدّاً قال: يا مريم من أين لكِ هذا الرزق الطيب؟ قالت: هو رزق من عند الله. إن الله -بفضله- يرزق مَن يشاء مِن خلقه بغير حساب.', 37, 1, 54, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (331, 3, 1, 3, 331, 'عندما رأى زكريا ما أكرم الله به مريم مِن رزقه وفضله توجه إلى ربه قائلا يا ربِّ أعطني من عندك ولدًا صالحًا مباركًا، إنك سميع الدعاء لمن دعاك.', 38, 1, 55, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (332, 3, 1, 3, 332, 'فنادته الملائكة وهو واقف بين يدي الله في مكان صلاته يدعوه: أن الله يخبرك بخبر يسرُّك، وهو أنك سترزق بولد اسمه يحيى، يُصَدِّق بكلمة من الله -وهو عيسى ابن مريم عليه السلام-، ويكون يحيى سيدًا في قومه، له المكانة والمنزلة العالية، وحصورًا لا يأتي الذنوب والشهوات الضارة، ويكون نبيّاً من الصالحين الذين بلغوا في الصَّلاح ذروته.', 39, 1, 55, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (333, 3, 1, 3, 333, 'قال زكريا فرحًا متعجبًا: ربِّ أنَّى يكون لي غلام مع أن الشيخوخة قد بلغت مني مبلغها، وامرأتي عقيم لا تلد؟ قال: كذلك يفعل الله ما يشاء من الأفعال العجيبة المخالفة للعادة.', 40, 1, 55, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (334, 3, 1, 3, 334, 'قال زكريَّا: رب اجعل لي علامةً أستدلُّ بها على وجود الولد مني؛ ليحصل لي السرور والاستبشار، قال: علامتك التي طلبتها: ألا تستطيع التحدث إلى الناس ثلاثة أيام إلا بإشارة إليهم، مع أنك سويٌّ صحيح، وفي هذه المدة أكثِرْ من ذكر ربك، وصلِّ له أواخر النهار وأوائله.', 41, 1, 55, 45, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (335, 3, 1, 3, 335, 'واذكر -أيها الرسول- حين قالت الملائكة: يا مريم إن الله اختاركِ لطاعته وطهَّركِ من الأخلاق الرذيلة، واختاركِ على نساء العالمين في زمانك.', 42, 1, 55, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (336, 3, 1, 3, 336, 'يا مريم داومي على الطاعة لربك، وقومي في خشوع وتواضع، واسجدي واركعي مع الراكعين؛ شكرًا لله على ما أولاكِ من نعمه.', 43, 1, 55, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (337, 3, 1, 3, 337, 'ذلك الذي قصصناه عليك -أيها الرسول- من أخبار الغيب التي أوحاها الله إليك، إذ لم تكن معهم حين اختلفوا في كفالة مريم أيُّهم أحق بها وأولى، ووقع بينهم الخصام، فأجْرَوْا القرعة لإلقاء أقلامهم، ففاز زكريا عليه السلام بكفالتها.', 44, 1, 55, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (338, 3, 1, 3, 338, 'وما كنت - يا نبي الله - هناك حين قالت الملائكة: يا مريم إن الله يُبَشِّرْكِ بولد يكون وجوده بكلمة من الله، أي يقول له: "كن"، فيكون، اسمه المسيح عيسى ابن مريم، له الجاه العظيم في الدنيا والآخرة، ومن المقربين عند الله يوم القيامة.', 45, 1, 55, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (339, 3, 1, 3, 339, 'ويكلم الناس في المهد بعد ولادته، وكذلك يكلمهم في حال كهولته بما أوحاه الله إليه. وهذا تكليم النبوَّة والدعوة والإرشاد، وهو معدود من أهل الصلاح والفضل في قوله وعمله.', 46, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (340, 3, 1, 3, 340, 'قالت مريم متعجبة من هذا الأمر: أنَّى يكون لي ولد وأنا لست بذات زوج ولا بَغِيٍّ؟ قال لها المَلَك: هذا الذي يحدث لكِ ليس بمستبعد على الإله القادر، الذي يوجِد ما يشاء من العدم، فإذا أراد إيجاد شيء فإنما يقول له: "كُن" فيكون.', 47, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (341, 3, 1, 3, 341, 'ويعلمه الكتابة، والسداد في القول والفعل، والتوراة التي أوحاها الله إلى موسى عليه السلام، والإنجيل الذي أنزل الله عليه.', 48, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (342, 3, 1, 3, 342, 'ويجعله رسولا إلى بني إسرائيل، ويقول لهم: إني قد جئتكم بعلامة من ربكم تدلُّ على أني مرسل من الله، وهي أني أصنع لكم من الطين مثل شكل الطير، فأنفخ فيه فيكون طيرًا حقيقيا بإذن الله، وأَشفي مَن وُلِد أعمى، ومَن به برص، وأُحيي من كان ميتًا بإذن الله، وأخبركم بما تأكلون وتدَّخرون في بيوتكم من طعامكم. إن في هذه الأمور العظيمة التي ليست في قدرة البشر لدليلا على أني نبي الله ورسوله، إن كنتم مصدِّقين حجج الله وآياته، مقرِّين بتوحيده.', 49, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (343, 3, 1, 3, 343, 'وجئتكم مصدقًا بما في التوراة، ولأحلَّ لكم بوحي من الله بعض ما حرَّمه الله عليكم تخفيفًا من الله ورحمة، وجئتكم بحجة من ربكم على صدق ما أقول لكم، فاتقوا الله ولا تخالفوا أمره، وأطيعوني فيما أبلغكم به عن الله.', 50, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (344, 3, 1, 3, 344, 'إن الله الذي أدعوكم إليه هو وحده ربي وربكم فاعبدوه، فأنا وأنتم سواء في العبودية والخضوع له، وهذا هو الطريق الذي لا اعوجاج فيه.', 51, 1, 56, 46, NULL, 22, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (345, 3, 1, 3, 345, 'فلما استشعر عيسى منهم التصميم على الكفر نادى في أصحابه الخُلَّص: مَن يكون معي في نصرة دين الله؟ قال أصفياء عيسى: نحن أنصار دين الله والداعون إليه، صدَّقنا بالله واتبعناك، واشهد أنت يا عيسى بأنا مستسلمون لله بالتوحيد والطاعة.', 52, 1, 56, 46, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (346, 3, 1, 3, 346, 'ربنا صدَّقنا بما أنزلت من الإنجيل، واتبعنا رسولك عيسى عليه السلام، فاجعلنا ممن شهدوا لك بالوحدانية ولأنبيائك بالرسالة، وهم أمة محمد صلى الله عليه وسلم الذين يشهدون للرسل بأنهم بلَّغوا أممهم.', 53, 1, 57, 46, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (347, 3, 1, 3, 347, 'ومكر الذين كفروا من بني إسرائيل بعيسى عليه السلام، بأن وكَّلوا به من يقتله غِيْلة، فألقى الله شَبَه عيسى على رجل دلَّهم عليه فأمسكوا به، وقتلوه وصلبوه ظناً منهم أنه عيسى عليه السلام، والله خير الماكرين. وفي هذا إثبات صفة المكر لله -تعالى- على ما يليق بجلاله وكماله؛ لأنه مكر بحق، وفي مقابلة مكر الماكرين.', 54, 1, 57, 46, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (348, 3, 1, 3, 348, 'ومكر الله بهم حين قال الله لعيسى: إني قابضك من الأرض من غير أن ينالك سوء، ورافعك إليَّ ببدنك وروحك، ومخلصك من الذين كفروا بك، وجاعل الذين اتبعوك أي على دينك وما جئت به عن الله من الدين والبشارة بمحمد صلى الله عليه وسلم وآمَنوا بمحمد صلى الله عليه وسلم، بعد بعثنه، والتزموا شريعته ظاهرين على الذين جحدوا نبوتك إلى يوم القيامة، ثم إليّ مصيركم جميعًا يوم الحساب، فأفصِل بينكم فيما كنتم فيه تختلفون من أمر عيسى عليه السلام.', 55, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (349, 3, 1, 3, 349, 'فأمَّا الذين كفروا بالمسيح من اليهود أو غَلَوا فيه من النصارى، فأعذبهم عذابًا شديدًا في الدنيا: بالقتل وسلْبِ الأموال وإزالة الملك، وفي الآخرة بالنار، وما لهم مِن ناصر ينصرهم ويدفع عنهم عذاب الله.', 56, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (350, 3, 1, 3, 350, 'وأما الذين آمنوا بالله ورسله وعملوا الأعمال الصالحة، فيعطيهم الله ثواب أعمالهم كاملا غير منقوص. والله لا يحب الظالمين بالشرك والكفر.', 57, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (351, 3, 1, 3, 351, 'ذلك الذي نقصُّه عليك في شأن عيسى، من الدلائل الواضحة على صحة رسالتك، وصحة القرآن الحكيم الذي يفصل بين الحق والباطل، فلا شك فيه ولا امتراء.', 58, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (352, 3, 1, 3, 352, 'إنَّ خَلْقَ الله لعيسى من غير أب مثَلُه كمثل خلق الله لآدم من غير أب ولا أم، إذ خلقه من تراب الأرض، ثم قال له: "كن بشرًا" فكان. فدعوى إلهية عيسى لكونه خلق من غير أب دعوى باطلة؛ فآدم عليه السلام خلق من غير أب ولا أم، واتفق الجميع على أنه عَبْد من عباد الله.', 59, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (353, 3, 1, 3, 353, 'الحق الذي لا شك فيه في أمر عيسى هو الذي جاءك -أيها الرسول- من ربك، فدل على يقينك، وعلى ما أنت عليه من ترك الافتراء، ولا تكن من الشاكِّين، وفي هذا تثبيت وطمأنة لرسول الله صلى الله عليه وسلم.', 60, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (354, 3, 1, 3, 354, 'فمَن جادلك -أيها الرسول- في المسيح عيسى ابن مريم من بعد ما جاءك من العلم في أمر عيسى عليه السلام، فقل لهم: تعالوا نُحْضِر أبناءنا وأبناءكم، ونساءنا ونساءكم، وأنفسنا وأنفسكم، ثم نتجه إلى الله بالدعاء أن يُنزل عقوبته ولعنته على الكاذبين في قولهم، المصرِّين على عنادهم.', 61, 1, 57, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (355, 3, 1, 3, 355, 'إن هذا الذي أنبأتك به من أمر عيسى لهو النبأ الحق الذي لا شك فيه، وما من معبود يستحق العبادة إلا الله وحده، وإن الله لهو العزيز في ملكه، الحكيم في تدبيره وفعله.', 62, 1, 58, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (356, 3, 1, 3, 356, 'فإن أعرضوا عن تصديقك واتباعك فهم المفسدون، والله عليم بهم، وسيجازيهم على ذلك.', 63, 1, 58, 47, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (357, 3, 1, 3, 357, 'قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: تعالَوْا إلى كلمة عدل وحق نلتزم بها جميعًا: وهي أن نَخُص الله وحده بالعبادة، ولا نتخذ أي شريك معه، من وثن أو صنم أو صليب أو طاغوت أو غير ذلك، ولا يدين بعضنا لبعض بالطاعة من دون الله. فإن أعرضوا عن هذه الدعوة الطيبة فقولوا لهم - أيها المؤمنون -: اشهدوا علينا بأنا مسلمون منقادون لربنا بالعبودية والإخلاص. والدعوة إلى كلمة سواء، كما تُوجَّه إلى اليهود والنصارى، توجَّه إلى من جرى مجراهم.', 64, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (358, 3, 1, 3, 358, 'يا أصحاب الكتب المنزلة من اليهود والنصارى، كيف يجادل كل منكم في أن إبراهيم عليه السلام كان على ملَّته، وما أُنزلت التوراة والإنجيل إلا من بعده؟ أفلا تفقهون خطأ قولكم: إن إبراهيم كان يهودياً أو نصرانياً، وقد علمتم أن اليهودية والنصرانية حدثت بعد وفاته بحين؟', 65, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (359, 3, 1, 3, 359, 'ها أنتم يا هؤلاء جادلتم رسول الله محمدًا صلى الله عليه وسلم فيما لكم به علم مِن أمر دينكم، مما تعتقدون صحته في كتبكم، فلِمَ تجادلون فيما ليس لكم به علم من أمر إبراهيم؟ والله يعلم الأمور على خفائها، وأنتم لا تعلمون.', 66, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (360, 3, 1, 3, 360, 'ما كان إبراهيم يهودياً ولا نصرانياً، فلم تكن اليهودية ولا النصرانية إلا من بعده، ولكن كان متبعًا لأمر الله وطاعته، مستسلمًا لربه، وما كان من المشركين.', 67, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (361, 3, 1, 3, 361, 'إنَّ أحق الناس بإبراهيم وأخصهم به، الذين آمنوا به وصدقوا برسالته واتبعوه على دينه، وهذا النبي محمد صلى الله عليه وسلم والذين آمنوا به. والله وليُّ المؤمنين به المتبعين شرعه.', 68, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (362, 3, 1, 3, 362, 'تمنَّت جماعة من اليهود والنصارى لو يضلونكم - أيها المسلمون - عن الإسلام، وما يضلون إلا أنفسهم وأتباعهم، وما يدرون ذلك ولا يعلمونه.', 69, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (363, 3, 1, 3, 363, 'يا أهل التوراة والإنجيل لم تجحدون آيات الله التي أنزلها على رسله في كتبكم، وفيها أن محمدًا صلى الله عليه وسلم هو الرسول المنتظر، وأن ما جاءكم به هو الحق، وأنتم تشهدون بذلك؟ ولكنكم تنكرونه.', 70, 1, 58, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (364, 3, 1, 3, 364, 'يا أهل التوراة والإنجيل لِمَ تخلطون الحق في كتبكم بما حرفتموه وكتبتموه من الباطل بأيديكم، وتُخْفون ما فيهما من صفة محمد صلى الله عليه وسلم، وأن دينه هو الحق، وأنتم تعلمون ذلك؟', 71, 1, 59, 48, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (365, 3, 1, 3, 365, 'وقالت جماعة من أهل الكتاب من اليهود: صدِّقوا بالذي أُنزل على الذين آمنوا أول النهار واكفروا آخره؛ لعلهم يتشككون في دينهم، ويرجعون عنه.', 72, 1, 59, 49, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (366, 3, 1, 3, 366, 'ولا تصدِّقوا تصديقًا صحيحًا إلا لمَن تبع دينكم فكان يهودياً، قل لهم -أيها الرسول-: إن الهدى والتوفيق هدى الله وتوفيقه للإيمان الصحيح. وقالوا: لا تظهروا ما عندكم من العلم للمسلمين فيتعلمون منكم فيساووكم في العلم به، وتكون لهم الأفضلية عليكم، أو أن يتخذوه حجة عند ربكم يغلبونكم بها. قل لهم -أيها الرسول-: إن الفضل والعطاء والأمور كلها بيد الله وتحت تصرفه، يؤتيها من يشاء ممن آمن به وبرسوله. والله واسع عليم، يَسَعُ بعلمه وعطائه جميع مخلوقاته، ممن يستحق فضله ونعمه.', 73, 1, 59, 49, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (367, 3, 1, 3, 367, 'إن الله يختص مِن خلقه مَن يشاء بالنبوة والهداية إلى أكمل الشرائع، والله ذو الفضل العظيم.', 74, 1, 59, 49, NULL, 23, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (368, 3, 1, 3, 368, 'ومن أهل الكتاب من اليهود مَن إنْ تأمنه على كثير من المال يؤدِّه إليك من غير خيانة، ومنهم مَن إنْ تأمنه على دينار واحد لا يؤدِّه اليك، إلا إذا بذلت غاية الجهد في مطالبته. وسبب ذلك عقيدة فاسدة تجعلهم يستحلُّون أموال العرب بالباطل، ويقولون: ليس علينا في أكل أموالهم إثم ولا حرج؛ لأن الله أحلَّها لنا. وهذا كذب على الله، يقولونه بألسنتهم، وهم يعلمون أنهم كاذبون.', 75, 1, 59, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (369, 3, 1, 3, 369, 'ليس الأمر كما زعم هؤلاء الكاذبون، فإن المتقي حقاً هو من أوفى بما عاهد الله عليه من أداء الأمانة والإيمان به وبرسله والتزم هديه وشرعه، وخاف الله عز وجل فامتثل أمره وانتهى عما نهى عنه. والله يحب المتقين الذين يتقون الشرك والمعاصي.', 76, 1, 59, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (370, 3, 1, 3, 370, 'إن الذين يستبدلون بعهد الله ووصيته التي أوصى بها في الكتب التي أنزلها على أنبيائهم، عوضًا وبدلا خسيسًا من عرض الدنيا وحطامها، أولئك لا نصيب لهم من الثواب في الآخرة، ولا يكلمهم الله بما يسرهم، ولا ينظر إليهم يوم القيامة بعين الرحمة، ولا يطهرهم من دنس الذنوب والكفر، ولهم عذاب موجع.', 77, 1, 59, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (371, 3, 1, 3, 371, 'وإن مِن اليهود لَجماعةً يحرفون الكلام عن مواضعه، ويبدلون كلام الله؛ ليوهموا غيرهم أن هذا من الكلام المنزل، وهو التوراة، وما هو منها في شيء، ويقولون: هذا من عند الله أوحاه الله إلى نبيه موسى، وما هو من عند الله، وهم لأجل دنياهم يقولون على الله الكذب وهم يعلمون أنهم كاذبون.', 78, 1, 60, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (372, 3, 1, 3, 372, 'ما ينبغي لأحد من البشر أن يُنزِّل الله عليه كتابه ويجعله حكمًا بين خلقه ويختاره نبياً، ثم يقول للناس: اعبدوني من دون الله، ولكن يقول: كونوا حكماء فقهاء علماء بما كنتم تُعَلِّمونه غيركم من وحي الله تعالى، وبما تدرسونه منه حفظًا وعلمًا وفقهًا.', 79, 1, 60, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (373, 3, 1, 3, 373, 'وما كان لأحد منهم أن يأمركم باتخاذ الملائكة والنبيين أربابًا تعبدونهم من دون الله. أَيُعْقَلُ -أيها الناس- أن يأمركم بالكفر بالله بعد انقيادكم لأمره؟', 80, 1, 60, 49, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (374, 3, 1, 3, 374, 'واذكر -أيها الرسول- إذ أخذ الله سبحانه العهد المؤكد على جميع الأنبياء: لَئِنْ آتيتكم من كتاب وحكمة، ثم جاءكم رسول من عندي، مصدق لما معكم لتؤمنن به ولتنصرنَّه. فهل أقررتم واعترفتم بذلك وأخذتم على ذلك عهدي الموثق؟ قالوا: أقررنا بذلك، قال: فليشهدْ بعضكم على بعض، واشهدوا على أممكم بذلك، وأنا معكم من الشاهدين عليكم وعليهم. وفي هذا أن الله أخذ الميثاق على كل نبي أن يؤمن بمحمد صلى الله عليه وسلم، وأخذ الميثاق على أمم الأنبياء بذلك.', 81, 1, 60, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (375, 3, 1, 3, 375, 'فمن أعرض عن دعوة الإسلام بعد هذا البيان وهذا العهد الذي أخذه الله على أنبيائه، فأولئك هم الخارجون عن دين الله وطاعة ربهم.', 82, 1, 60, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (376, 3, 1, 3, 376, 'أيريد هؤلاء الفاسقون من أهل الكتاب غير دين الله -وهو الإسلام الذي بعث الله به محمدا صلى الله عليه وسلم-، مع أن كل مَن في السموات والأرض استسلم وانقاد وخضع لله طواعية -كالمؤمنين- ورغمًا عنهم عند الشدائد، حين لا ينفعهم ذلك وهم الكفار، كما خضع له سائر الكائنات، وإليه يُرجَعون يوم المعاد، فيجازي كلا بعمله. وهذا تحذير من الله تعالى لخلقه أن يرجع إليه أحد منهم على غير ملة الإسلام.', 83, 1, 60, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (377, 3, 1, 3, 377, 'قل لهم -أيها الرسول-: صدَّقنا بالله وأطعنا، فلا رب لنا غيره، ولا معبود لنا سواه، وآمنَّا بالوحي الذي أنزله الله علينا، والذي أنزله على إبراهيم خليل الله، وابنيه إسماعبل وإسحاق، وابن ابنه يعقوب بن إسحاق، والذي أنزله على الأسباط -وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة مِن ولد يعقوب- وما أوتي موسى وعيسى من التوراة والإنجيل، وما أنزله الله على أنبيائه، نؤمن بذلك كله، ولا نفرق بين أحد منهم، ونحن لله وحده منقادون بالطاعة، مُقِرُّون له بالربوبية والألوهية والعبادة.', 84, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (378, 3, 1, 3, 378, 'ومن يطلب دينًا غير دين الإسلام الذي هو الاستسلام لله بالتوحيد والانقياد له بالطاعة، والعبودية، ولرسوله النبي الخاتم محمد صلى الله عليه وسلم بالإيمان به وبمتابعته ومحبته ظاهرًا وباطنًا، فلن يُقبل منه ذلك، وهو في الآخرة من الخاسرين الذين بخسوا أنفسهم حظوظها.', 85, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (379, 3, 1, 3, 379, 'كيف يوفق الله للإيمان به وبرسوله قومًا جحدوا نبوة محمد صلى الله عليه وسلم بعد إيمانهم به، وشهدوا أن محمدًا صلى الله عليه وسلم حق وما جاء به هو الحق، وجاءهم الحجج من عند الله والدلائل بصحة ذلك؟ والله لا يوفق للحق والصواب الجماعة الظلمة، وهم الذين عدلوا عن الحق إلى الباطل، فاختاروا الكفر على الإيمان.', 86, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (380, 3, 1, 3, 380, 'أولئك الظالمون جزاؤهم أنَّ عليهم لعنة الله والملائكة والناسِ أجمعين، فهم مطرودون من رحمة الله.', 87, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (381, 3, 1, 3, 381, 'ماكثين في النار، لا يُرفع عنهم العذاب قليلا ليستريحوا، ولا يُؤخر عنهم لمعذرة يعتذرون بها.', 88, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (382, 3, 1, 3, 382, 'إلا الذين رجعوا إلى ربهم بالتوبة النصوح من بعد كفرهم وظلمهم، وأصلحوا ما أفسدوه بتوبتهم فإن الله يقبلها، فهو غفور لذنوب عباده، رحيم بهم.', 89, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (383, 3, 1, 3, 383, 'إن الذين كفروا بعد إيمانهم واستمروا على الكفر إلى الممات لن تُقبل لهم توبة عند حضور الموت، وأولئك هم الذين ضلُّوا السبيل، فأخطَؤُوا منهجه.', 90, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (384, 3, 1, 3, 384, 'إن الذين جحدوا نبوة محمد صلى الله عليه وسلم، وماتوا على الكفر بالله ورسوله، فلن يُقبل من أحدهم يوم القيامة ملء الأرض ذهبًا؛ ليفتدي به نفسه من عذاب الله، ولو افتدى به نفسه فِعْلا. أولئك لهم عذاب موجع، وما لهم من أحد ينقذهم من عذاب الله.', 91, 1, 61, 50, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (385, 3, 1, 3, 385, 'لن تدركوا الجنة حتى تتصدقوا مما تحبون، وأي شيء تتصدقوا به مهما كان قليلا أو كثيرًا فإن الله به عليم، وسيجازي كل منفق بحسب عمله.', 92, 1, 62, 51, NULL, 24, 6);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (386, 3, 1, 4, 386, 'كل الأطعمة الطيِّبة كانت حلالا لأبناء يعقوب عليه السلام إلا ما حرَّم يعقوب على نفسه لمرض نزل به، وذلك مِن قبل أن تُنَزَّل التوراة. فلما نُزِّلت التوراة حرَّم الله على بني إسرائيل بعض الأطعمة التي كانت حلالا لهم؛ وذلك لظلمهم وبغيهم. قل لهم -أيها الرسول-: هاتوا التوراة، واقرؤوا ما فيها إن كنتم محقين في دعواكم أن الله أنزل فيها تحريم ما حرَّمه يعقوب على نفسه، حتى تعلموا صدق ما جاء في القرآن من أن الله لم يحرم على بني إسرائيل شيئًا من قبل نزول التوراة، إلا ما حرَّمه يعقوب على نفسه.', 93, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (387, 3, 1, 4, 387, 'فمَن كذب على الله من بعد قراءة التوراة ووضوح الحقيقة، فأولئك هم الظالمون القائلون على الله بالباطل.', 94, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (388, 3, 1, 4, 388, 'قل لهم -أيها الرسول- صَدَق الله فيما أخبر به وفيما شرعه. فإن كنتم صادقين في محبتكم وانتسابكم لخليل الله إبراهيم عليه السلام فاتبعوا ملَّته التي شرعها الله على لسان محمد صلى الله عليه وسلم، فإنها الحق الذي لا شك فيه. وما كان إبراهيم عليه السلام من المشركين بالله في توحيده وعبادته أحدًا.', 95, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (389, 3, 1, 4, 389, 'إن أول بيت بُني لعبادة الله في الأرض لهو بيت الله الحرام الذي في "مكة"، وهذا البيت مبارك تضاعف فيه الحسنات، وتتنزل فيه الرحمات، وفي استقباله في الصلاة، وقصده لأداء الحج والعمرة، صلاح وهداية للناس أجمعين.', 96, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (390, 3, 1, 4, 390, 'في هذا البيت دلالات ظاهرات أنه من بناء إبراهيم، وأن الله عظَّمه وشرَّفه، منها: مقام إبراهيم عليه السلام، وهو الحَجَر الذي كان يقف عليه حين كان يرفع القواعد من البيت هو وابنه إسماعيل، ومن دخل هذا البيت أَمِنَ على نفسه فلا يناله أحد بسوء. وقد أوجب الله على المستطيع من الناس في أي مكان قَصْدَ هذا البيت لأداء مناسك الحج. ومن جحد فريضة الحج فقد كفر، والله غني عنه وعن حجِّه وعمله، وعن سائر خَلْقه.', 97, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (391, 3, 1, 4, 391, 'قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: لِمَ تجحدون حجج الله التي دلَّتْ على أن دين الله هو الإسلام، وتنكرون ما في كتبهم من دلائل وبراهين على ذلك، وأنتم تعلمون؟ والله شهيد على صنيعكم. وفي ذلك تهديد ووعيد لهم.', 98, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (392, 3, 1, 4, 392, 'قل -أيها الرسول- لليهود والنصارى: لِمَ تمنعون من الإسلام من يريد الدخول فيه تطلبون له زيغًا وميلا عن القصد والاستقامة، وأنتم تعلمون أن ما جئتُ به هو الحق؟ وما الله بغافل عما تعملون، وسوف يجازيكم على ذلك.', 99, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (393, 3, 1, 4, 393, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تطيعوا جماعة من اليهود والنصارى ممن آتاهم الله التوراة والإنجيل، يضلوكم، ويلقوا إليكم الشُّبَه في دينكم؛ لترجعوا جاحدين للحق بعد أن كنتم مؤمنين به، فلا تأمنوهم على دينكم، ولا تقبلوا لهم رأيًا أو مشورة.', 100, 1, 62, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (394, 3, 1, 4, 394, 'وكيف تكفرون بالله -أيها المؤمنون -، وآيات القرآن تتلى عليكم، وفيكم رسول الله محمد صلى الله عليه وسلم يبلغها لكم؟ ومَن يتوكل على الله ويستمسك بالقرآن والسنة فقد وُفِّق لطريق واضح، ومنهاج مستقيم.', 101, 1, 63, 51, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (395, 3, 1, 4, 395, 'يا أيها الذين صدَّقوا الله ورسوله، وعملوا بشرعه، خافوا الله حق خوفه: وذلك بأن يطاع فلا يُعصى، ويُشكَر فلا يكفر، ويُذكَر فلا ينسى، وداوموا على تمسككم بإسلامكم إلى آخر حياتكم؛ لتلقوا الله وأنتم عليه.', 102, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (396, 3, 1, 4, 396, 'وتمسَّكوا جميعًا بكتاب ربكم وهدي نبيكم، ولا تفعلوا ما يؤدي إلى فرقتكم. واذكروا نعمة جليلة أنعم الله بها عليكم: إذ كنتم -أيها المؤمنون- قبل الإسلام أعداء، فجمع الله قلوبكم على محبته ومحبة رسوله، وألقى في قلوبكم محبة بعضكم لبعض، فأصبحتم -بفضله- إخوانا متحابين، وكنتم على حافة نار جهنم، فهداكم الله بالإسلام ونجَّاكم من النار. وكما بيَّن الله لكم معالم الإيمان الصحيح فكذلك يبيِّن لكم كل ما فيه صلاحكم؛ لتهتدوا إلى سبيل الرشاد، وتسلكوها، فلا تضلوا عنها.', 103, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (397, 3, 1, 4, 397, 'ولتكن منكم -أيها المؤمنون- جماعة تدعو إلى الخير وتأمر بالمعروف، وهو ما عُرف حسنه شرعًا وعقلا وتنهى عن المنكر، وهو ما عُرف قبحه شرعًا وعقلا وأولئك هم الفائزون بجنات النعيم.', 104, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (398, 3, 1, 4, 398, 'ولا تكونوا -أيها المؤمنون- كأهل الكتاب الذين وقعت بينهم العداوة والبغضاء فتفرَّقوا شيعًا وأحزابًا، واختلفوا في أصول دينهم من بعد أن اتضح لهم الحق، وأولئك مستحقون لعذابٍ عظيم موجع.', 105, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (399, 3, 1, 4, 399, 'يوم القيامة تَبْيَضُّ وجوه أهل السعادة الذين آمنوا بالله ورسوله، وامتثلوا أمره، وتَسْوَدُّ وجوه أهل الشقاوة ممن كذبوا رسوله، وعصوا أمره. فأما الذين اسودَّت وجوههم، فيقال لهم توبيخًا: أكفرتم بعد إيمانكم، فاخترتم الكفر على الإيمان؟ فذوقوا العذاب بسبب كفركم.', 106, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (400, 3, 1, 4, 400, 'وأما الذين ابيضَّتْ وجوهم بنضرة النعيم، وما بُشِّروا به من الخير، فهم في جنة الله ونعيمها، وهم باقون فيها، لا يخرجون منها أبدًا.', 107, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (401, 3, 1, 4, 401, 'هذه آيات الله وبراهينه الساطعة، نتلوها ونقصُّها عليك -أيها الرسول- بالصدق واليقين. وما الله بظالم أحدًا من خلقه، ولا بمنقص شيئًا من أعمالهم؛ لأنه الحاكم العدل الذي لا يجور.', 108, 1, 63, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (402, 3, 1, 4, 402, 'ولله ما في السموات وما في الأرض، ملكٌ له وحده خلقًا وتدبيرًا، ومصير جميع الخلائق إليه وحده، فيجازي كلا على قدر استحقاقه.', 109, 1, 64, 52, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (403, 3, 1, 4, 403, 'أنتم - يا أمة محمد - خير الأمم وأنفع الناس للناس، تأمرون بالمعروف، وهو ما عُرف حسنه شرعًا وعقلا وتنهون عن المنكر، وهو ما عُرف قبحه شرعًا وعقلا وتصدقون بالله تصديقًا جازمًا يؤيده العمل. ولو آمن أهل الكتاب من اليهود والنصارى بمحمد صلى الله عليه وسلم وما جاءهم به من عند الله كما آمنتم، لكان خيرا لهم في الدنيا والآخرة، منهم المؤمنون المصدقون برسالة محمد صلى الله عليه وسلم العاملون بها، وهم قليل، وأكثرهم الخارجون عن دين الله وطاعته.', 110, 1, 64, 53, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (404, 3, 1, 4, 404, 'لن يضركم هؤلاء الفاسقون من أهل الكتاب إلا ما يؤذي أسماعكم من ألفاظ الشرك والكفر وغير ذلك، فإن يقاتلوكم يُهْزَموا، ويهربوا مولِّين الأدبار، ثم لا ينصرون عليكم بأي حال.', 111, 1, 64, 53, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (405, 3, 1, 4, 405, 'جعل الله الهوان والصغار أمرًا لازمًا لا يفارق اليهود، فهم أذلاء محتقرون أينما وُجِدوا، إلا بعهد من الله وعهد من الناس يأمنون به على أنفسهم وأموالهم، وذلك هو عقد الذمة لهم وإلزامهم أحكام الإسلام، ورجعوا بغضب من الله مستحقين له، وضُربت عليهم الذلَّة والمسكنة، فلا ترى اليهوديَّ إلا وعليه الخوف والرعب من أهل الإيمان؛ ذلك الذي جعله الله عليهم بسبب كفرهم بالله، وتجاوزهم حدوده، وقَتْلهم الأنبياء ظلمًا واعتداء، وما جرَّأهم على هذا إلا ارتكابهم للمعاصي، وتجاوزهم حدود الله.', 112, 1, 64, 53, NULL, 25, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (406, 3, 1, 4, 406, 'ليس أهل الكتاب متساوين: فمنهم جماعة مستقيمة على أمر الله مؤمنة برسوله محمد صلى الله عليه وسلم، يقومون الليل مرتلين آيات القرآن الكريم، مقبلين على مناجاة الله في صلواتهم.', 113, 1, 64, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (407, 3, 1, 4, 407, 'يؤمنون بالله واليوم الآخر، ويأمرون بالخير كله، وينهون عن الشر كلِّه، ويبادرون إلى فعل الخيرات، وأولئك مِن عباد الله الصالحين.', 114, 1, 64, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (408, 3, 1, 4, 408, 'وأيُّ عمل قلَّ أو كَثُر من أعمال الخير تعمله هذه الطائفة المؤمنة فلن يضيع عند الله، بل يُشكر لهم، ويجازون عليه. والله عليم بالمتقين الذين فعلوا الخيرات وابتعدوا عن المحرمات؛ ابتغاء رضوان الله، وطلبًا لثوابه.', 115, 1, 64, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (409, 3, 1, 4, 409, 'إن الذين كفروا بآيات الله، وكذبوا رسله، لن تدفع عنهم أموالهم ولا أولادهم شيئًا من عذاب الله في الدنيا ولا في الآخرة، وأولئك أصحاب النار الملازمون لها، لا يخرجون منها.', 116, 1, 65, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (410, 3, 1, 4, 410, 'مَثَلُ ما ينفق الكافرون في وجوه الخير في هذه الحياة الدنيا وما يؤملونه من ثواب، كمثل ريح فيها برد شديد هَبَّتْ على زرع قوم كانوا يرجون خيره، وبسبب ذنوبهم لم تُبْقِ الريح منه شيئًا. وهؤلاء الكافرون لا يجدون في الآخرة ثوابًا، وما ظلمهم الله بذلك، ولكنهم ظلموا أنفسهم بكفرهم وعصيانهم.', 117, 1, 65, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (411, 3, 1, 4, 411, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تتخذوا الكافرين أولياء من دون المؤمنين، تُطْلعونهم على أسراركم، فهؤلاء لا يَفْتُرون عن إفساد حالكم، وهم يفرحون بما يصيبكم من ضرر ومكروه، وقد ظهرت شدة البغض في كلامهم، وما تخفي صدورهم من العداوة لكم أكبر وأعظم. قد بيَّنَّا لكم البراهين والحجج، لتتعظوا وتحذروا، إن كنتم تعقلون عن الله مواعظه وأمره ونهيه.', 118, 1, 65, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (412, 3, 1, 4, 412, 'ها هوذا الدليل على خطئكم في محبتهم، فأنتم تحبونهم وتحسنون إليهم، وهم لا يحبونكم ويحملون لكم العداوة والبغضاء، وأنتم تؤمنون بالكتب المنزلة كلها ومنها كتابهم، وهم لا يؤمنون بكتابكم، فكيف تحبونهم؟ وإذا لقوكم قالوا -نفاقًا-: آمنَّا وصدَّقْنا، وإذا خلا بعضهم إلى بعض بدا عليهم الغم والحزن، فعَضُّوا أطراف أصابعهم من شدة الغضب، لما يرون من ألفة المسلمين واجتماع كلمتهم، وإعزاز الإسلام، وإذلالهم به. قل لهم -أيها الرسول-: موتوا بشدة غضبكم. إن الله مطَّلِع على ما تخفي الصدور، وسيجازي كلا على ما قدَّم مِن خير أو شر.', 119, 1, 65, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (413, 3, 1, 4, 413, 'ومن عداوة هؤلاء أنكم -أيها المؤمنون- إن نزل بكم أمرٌ حسن مِن نصر وغنيمة ظهرت عليهم الكآبة والحزن، وإن وقع بكم مكروه من هزيمة أو نقص في الأموال والأنفس والثمرات فرحوا بذلك، وإن تصبروا على ما أصابكم، وتتقوا الله فيما أمركم به ونهاكم عنه، لا يضركم أذى مكرهم. والله بجميع ما يعمل هؤلاء الكفار من الفساد محيط، وسيجازيهم على ذلك.', 120, 1, 65, 53, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (414, 3, 1, 4, 414, 'واذكر -أيها الرسول- حين خَرَجْتَ من بيتك لابسًا عُدَّة الحرب، تنظم صفوف أصحابك، وتُنْزِل كل واحد في منزله للقاء المشركين في غزوة "أُحُد". والله سميع لأقوالكم، عليم بأفعالكم.', 121, 1, 65, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (415, 3, 1, 4, 415, 'اذكر -أيها الرسول- ما كان من أمر بني سَلِمة وبني حارثة حين حدثتهم أنفسهم بالرجوع مع زعيمهم المنافق عبد الله بن أُبيٍّ؛ خوفًا من لقاء العدو، ولكن الله عصمهم وحفظهم، فساروا معك متوكلين على الله. وعلى الله وحده فليتوكل المؤمنون.', 122, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (416, 3, 1, 4, 416, 'ولقد نصركم الله -أيها المؤمنون- بـ "بدر" على أعدائكم المشركين مع قلة عَدَدكم وعُدَدكم، فخافوا الله بفعل أوامره واجتناب نواهيه؛ لعلكم تشكرون له نعمه.', 123, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (417, 3, 1, 4, 417, 'اذكر -أيها الرسول- ما كان من أمر أصحابك في "بدر" حين شقَّ عليهم أن يأتي مَدَد للمشركين، فأوحينا إليك أن تقول لهم: ألن تكفيكم معونة ربكم بأن يمدكم بثلاثة آلاف من الملائكة مُنْزَلين من السماء إلى أرض المعركة، يثبتونكم، ويقاتلون معكم؟', 124, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (418, 3, 1, 4, 418, 'بلى يكفيكم هذا المَدَد. وبشارة أخرى لكم: إن تصبروا على لقاء العدو وتتقوا الله بفِعْل ما أمركم به واجتناب ما نهاكم عنه، ويأت كفار "مكة" على الفور مسرعين لقتالكم، يظنون أنهم يستأصلونكم، فإن الله يمدكم بخمسة آلاف من الملائكة مسوِّمين أي: قد أعلموا أنفسهم وخيولهم بعلامات واضحات.', 125, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (419, 3, 1, 4, 419, 'وما جعل الله هذا الإمداد بالملائكة إلا بشرى لكم يبشركم بها ولتطمئن قلوبكم، وتطيب بوعد الله لكم. وما النصر إلا من عند الله العزيز الذي لا يغالَب، الحكيم في تدبيره وفعله.', 126, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (420, 3, 1, 4, 420, 'وكان نصر الله لكم بـ "بدْر" ليهلك فريقًا من الكفار بالقتل، ومن نجا منهم من القتل رجع حزينًا قد ضاقت عليه نفسه، يَظْهر عليه الخزي والعار.', 127, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (421, 3, 1, 4, 421, 'ليس لك -أيها الرسول- من أمر العباد شيء، بل الأمر كله لله تعالى وحده لا شريك له، ولعل بعض هؤلاء الذين قاتلوك تنشرح صدورهم للإسلام فيسلموا، فيتوب الله عليهم. ومن بقي على كفره يعذبه الله في الدنيا والآخرة بسبب ظلمه وبغيه.', 128, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (422, 3, 1, 4, 422, 'ولله وحده ما في السموات وما في الأرض، يغفر لمن يشاء من عباده برحمته، ويعذب من يشاء بعدله. والله غفور لذنوب عباده، رحيم بهم.', 129, 1, 66, 54, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (423, 3, 1, 4, 423, 'يا أيها الذين صدّقوا الله ورسوله وعملوا بشرعه احذروا الربا بجميع أنواعه، ولا تأخذوا في القرض زيادة على رؤوس أموالكم وإن قلَّت، فكيف إذا كانت هذه الزيادة تتضاعف كلما حان موعد سداد الدين؟ واتقوا الله بالتزام شرعه؛ لتفوزوا في الدنيا والآخرة.', 130, 1, 66, 55, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (424, 3, 1, 4, 424, 'اجعلوا لأنفسكم وقاية بينكم وبين النار التي هُيِّئت للكافرين.', 131, 1, 66, 55, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (425, 3, 1, 4, 425, 'وأطيعوا الله -أيها المؤمنون- فيما أمركم به من الطاعات وفيما نهاكم عنه من أكل الربا وغيره من الأشياء، وأطيعوا الرسول؛ لترحموا، فلا تعذبوا.', 132, 1, 66, 55, NULL, 26, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (426, 3, 1, 4, 426, 'وبادروا بطاعتكم لله ورسوله لاغتنام مغفرة عظيمة من ربكم وجنة واسعة، عرضها السموات والأرض، أعدها الله للمتقين.', 133, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (427, 3, 1, 4, 427, 'الذين ينفقون أموالهم في اليسر والعسر، والذين يمسكون ما في أنفسهم من الغيظ بالصبر، وإذا قَدَروا عَفَوا عمَّن ظلمهم. وهذا هو الإحسان الذي يحب الله أصحابه.', 134, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (428, 3, 1, 4, 428, 'والذين إذا ارتكبوا ذنبًا كبيرًا أو ظلموا أنفسهم بارتكاب ما دونه، ذكروا وعد الله ووعيده فلجأوا إلى ربهم تائبين، يطلبون منه أن يغفر لهم ذنوبهم، وهم موقنون أنه لا يغفر الذنوب إلا الله، فهم لذلك لا يقيمون على معصية، وهم يعلمون أنهم إن تابوا تاب الله عليهم.', 135, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (429, 3, 1, 4, 429, 'أولئك الموصوفون بتلك الصفات العظيمة جزاؤهم أن يستر الله ذنوبهم، ولهم جنات تجري من تحت أشجارها وقصورها المياه العذبة، خالدين فيها لا يخرجون منها أبدًا. ونِعْمَ أجر العاملين المغفرة والجنة.', 136, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (430, 3, 1, 4, 430, 'يخاطب الله المؤمنين لـمَّا أُصيبوا يوم "أُحد" تعزية لهم بأنه قد مضت من قبلكم أمم، ابتُلي المؤمنون منهم بقتال الكافرين فكانت العاقبة لهم، فسيروا في الأرض معتبرين بما آل إليه أمر أولئك المكذبين بالله ورسله.', 137, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (431, 3, 1, 4, 431, 'هذا القرآن بيان وإرشاد إلى طريق الحق، وتذكير تخشع له قلوب المتقين، وهم الذين يخشون الله، وخُصُّوا بذلك؛ لأنهم هم المنتفعون به دون غيرهم.', 138, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (432, 3, 1, 4, 432, 'ولا تضْعُفوا -أيها المؤمنون- عن قتال عدوكم، ولا تحزنوا لما أصابكم في "أُحد"، وأنتم الغالبون والعاقبة لكم، إن كنتم مصدقين بالله ورسوله متَّبعين شرعه.', 139, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (433, 3, 1, 4, 433, 'إن أصابتكم -أيها المؤمنون- جراح أو قتل في غزوة "أُحد" فحزنتم لذلك، فقد أصاب المشركين جراح وقتل مثل ذلك في غزوة "بدر". وتلك الأيام يُصَرِّفها الله بين الناس، نصر مرة وهزيمة أخرى، لما في ذلك من الحكمة، حتى يظهر ما علمه الله في الأزل ليميز الله المؤمن الصادق مِن غيره، ويُكْرِمَ أقوامًا منكم بالشهادة. والله لا يحب الذين ظلموا أنفسهم، وقعدوا عن القتال في سبيله.', 140, 1, 67, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (434, 3, 1, 4, 434, 'وهذه الهزيمة التي وقعت في "أُحد" كانت اختبارًا وتصفية للمؤمنين، وتخليصًا لهم من المنافقين وهلاكًا للكافرين.', 141, 1, 68, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (435, 3, 1, 4, 435, 'يا أصحاب محمد -صلى الله عليه وسلم- أظننتم أن تدخلوا الجنة، ولم تُبْتَلوا بالقتال والشدائد؟ لا يحصل لكم دخولها حتى تُبْتلوا، ويعلم الله -علما ظاهرا للخلق- المجاهدين منكم في سبيله، والصابرين على مقاومة الأعداء.', 142, 1, 68, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (436, 3, 1, 4, 436, 'ولقد كنتم -أيها المؤمنون- قبل غزوة "أُحد" تتمنون لقاء العدو؛ لتنالوا شرف الجهاد والاستشهاد في سبيل الله الذي حَظِي به إخوانكم في غزوة "بدر"، فها هو ذا قد حصل لكم الذي تمنيتموه وطلبتموه، فدونكم فقاتلوا وصابروا.', 143, 1, 68, 55, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (437, 3, 1, 4, 437, 'وما محمد إلا رسول من جنس الرسل الذين قبله يبلغ رسالة ربه. أفإن مات بانقضاء أجله أو قُتِل كما أشاعه الأعداء رجعتم عن دينكم،، تركتم ما جاءكم به نبيكم؟ ومن يرجِعُ منكم عن دينه فلن يضر الله شيئًا، إنما يضر نفسه ضررًا عظيمًا. أما مَن ثبت على الإيمان وشكر ربه على نعمة الإسلام، فإن الله يجزيه أحسن الجزاء.', 144, 1, 68, 56, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (438, 3, 1, 4, 438, 'لن يموت أحد إلا بإذن الله وقدره وحتى يستوفي المدة التي قدرها الله له كتابًا مؤجَّلا. ومن يطلب بعمله عَرَض الدنيا، نعطه ما قسمناه له من رزق، ولا حظَّ له في الآخرة، ومن يطلب بعمله الجزاء من الله في الآخرة نمنحه ما طلبه، ونؤته جزاءه وافرًا مع ما لَه في الدنيا من رزق مقسوم، فهذا قد شَكَرَنا بطاعته وجهاده، وسنجزي الشاكرين خيرًا.', 145, 1, 68, 56, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (439, 3, 1, 4, 439, 'كثير من الأنبياء السابقين قاتل معهم جموع كثيرة من أصحابهم، فما ضعفوا لِمَا نزل بهم من جروح أو قتل؛ لأن ذلك في سبيل ربهم، وما عَجَزوا، ولا خضعوا لعدوهم، إنما صبروا على ما أصابهم. والله يحب الصابرين.', 146, 1, 68, 56, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (440, 3, 1, 4, 440, 'وما كان قول هؤلاء الصابرين إلا أن قالوا: ربنا اغفر لنا ذنوبنا، وما وقع منا مِن تجاوزٍ في أمر ديننا، وثبِّت أقدامنا حتى لا نفرَّ من قتال عدونا، وانصرنا على مَن جحد وحدانيتك ونبوة أنبيائك.', 147, 1, 68, 56, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (441, 3, 1, 4, 441, 'فأعطى الله أولئك الصابرين جزاءهم في الدنيا بالنصر على أعدائهم، وبالتمكين لهم في الأرض، وبالجزاء الحسن العظيم في الآخرة، وهو جنات النعيم. والله يحب كلَّ مَن أحسن عبادته لربه ومعاملته لخلقه.', 148, 1, 68, 56, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (442, 3, 1, 4, 442, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تطيعوا الذين جحدوا ألوهيتي، ولم يؤمنوا برسلي من اليهود والنصارى والمنافقين والمشركين فيما يأمرونكم به وينهونكم عنه، يضلوكم عن طريق الحق، وترتدُّوا عن دينكم، فتعودوا بالخسران المبين والهلاك المحقق.', 149, 1, 69, 57, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (443, 3, 1, 4, 443, 'إنهم لن ينصروكم، بل الله ناصركم، وهو خير ناصر، فلا يحتاج معه إلى نصرة أحد.', 150, 1, 69, 57, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (444, 3, 1, 4, 444, 'سنقذف في قلوب الذين كفروا أشدَّ الفزع والخوف بسبب إشراكهم بالله آلهة مزعومة، ليس لهم دليل أو برهان على استحقاقها للعبادة مع الله، فحالتهم في الدنيا: رعب وهلع من المؤمنين، أما مكانهم في الآخرة الذي يأوون إليه فهو النار؛ وذلك بسبب ظلمهم وعدوانهم، وساء هذا المقام مقامًا لهم.', 151, 1, 69, 57, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (445, 3, 1, 4, 445, 'ولقد حقق الله لكم ما وعدكم به من نصر، حين كنتم تقتلون الكفار في غزوة "أُحد" بإذنه تعالى، حتى إذا جَبُنتم وضعفتم عن القتال واختلفتم: هل تبقون في مواقعكم أو تتركونها لجمع الغنانم مع مَن يجمعها؟ وعصيتم أمر رسولكم حين أمركم ألا تفارفوا أماكنكم بأي حال، حلَّت بكم الهزيمة من بعد ما أراكم ما تحبون من النصر، وتبيَّن أن منكم مَن يريد الغنائم، وأن منكم مَن يطلب الآخرة وثوابها، ثم صرف الله وجوهكم عن عدوكم؛ ليختبركم، وقد علم الله ندمكم وتوبتكم فعفا عنكم، والله ذو فضل عظيم على المؤمنين.', 152, 1, 69, 57, NULL, 27, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (446, 3, 1, 4, 446, 'اذكروا -يا أصحاب محمد- ما كان مِن أمركم حين أخذتم تصعدون الجبل هاربين من أعدائكم، ولا تلتفتون إلى أحد لِمَا اعتراكم من الدهشة والخوف والرعب، ورسول الله صلى الله عليه وسلم ثابت في الميدان يناديكم من خلفكم قائلا إليَّ عبادَ الله، وأنتم لا تسمعون ولا تنظرون، فكان جزاؤكم أن أنزل الله بكم ألمًا وضيقًا وغمًّا؛ لكي لا تحزنوا على ما فاتكم من نصر وغنيمة، ولا ما حلَّ بكم من خوف وهزيمة. والله خبير بجميع أعمالكم، لا يخفى عليه منها شيء.', 153, 1, 69, 57, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (447, 3, 1, 4, 447, 'ثم كان من رحمة الله بالمؤمنين المخلصين أن ألقى في قلوبهم من بعد ما نزل بها من همٍّ وغمٍّ اطمئنانًا وثقة في وعد الله، وكان من أثره نعاس غَشِي طائفة منهم، وهم أهل الإخلاص واليقين، وطائفة أُخرى أهمَّهم خلاص أنفسهم خاصة، وضَعُفَتْ عزيمتهم وشُغِلوا بأنفسهم، وأساؤوا الظن بربهم وبدينه وبنبيه، وظنوا أن الله لا يُتِمُّ أمر رسوله، وأن الإسلام لن تقوم له قائمة، ولذلك تراهم نادمين على خروجهم، يقول بعضهم لبعض: هل كان لنا من اختيار في الخروج للقتال؟ قل لهم -أيها الرسول-: إن الأمر كلَّه لله، فهو الذي قدَّر خروجكم وما حدث لكم، وهم يُخْفون في أنفسهم ما لا يظهرونه لك من الحسرة على خروجهم للقتال، يقولون: لو كان لنا أدنى اختيار ما قُتِلنا هاهنا. قل لهم: إن الآجال بيد الله، ولو كنتم في بيوتكم، وقدَّر الله أنكم تموتون، لخرج الذين كتب الله عليهم الموت إلى حيث يُقْتلون، وما جعل الله ذلك إلا ليختبر ما في صدوركم من الشك والنفاق، وليميز الخبيث من الطيب، ويظهر أمر المؤمن من المنافق للناس في الأقوال والأفعال. والله عليم بما في صدور خلقه، لا يخفى عليه شيء من أمورهم.', 154, 1, 70, 57, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (448, 3, 1, 4, 448, 'إن الذين فرُّوا منكم -يا أصحاب- محمد عن القتال يوم التقى المؤمنون والمشركون في غزوة "أُحد"، إنما أوقعهم الشيطان في هذا الذنب ببعض ما عملوا من الذنوب، ولقد تجاوز الله عنهم فلم يعاقبهم. إن الله غفور للمذنبين التائبين، حليم لا يعاجل من عصاه بالعقوبة.', 155, 1, 70, 57, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (449, 3, 1, 4, 449, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تُشابهوا الكافرين الذين لا يؤمنون بربهم، فهم يقولون لإخوانهم من أهل الكفر إذا خرجوا يبحثون في أرض الله عن معاشهم أو كانوا مع الغزاة المقاتلين فماتوا أو قُتِلوا: لو لم يخرج هؤلاء ولم يقاتلوا وأقاموا معنا ما ماتوا وما قُتلوا. وهذا القول يزيدهم ألمًا وحزنًا وحسرة تستقر في قلوبهم، أما المؤمنون فإنهم يعلمون أن ذلك بقدر الله فيهدي الله قلوبهم، ويخفف عنهم المصيبة، والله يحيي مَن قدَّر له الحياة -وإن كان مسافرًا أو غازيًا- ويميت مَنِ انتهى أجله -وإن كان مقيمًا- والله بكل ما تعملونه بصير، فيجازيكم به.', 156, 1, 70, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (450, 3, 1, 4, 450, 'ولئن قُتِلتم -أيها المؤمنون- وأنتم تجاهدون في سبيل الله أو متم في أثناء القتال، ليغفرن الله لكم ذنوبكم، وليرحمنكم رحمة من عنده، فتفوزون بجنات النعيم، وذلك خير من الدنيا وما يجمعه أهلها.', 157, 1, 70, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (451, 3, 1, 4, 451, 'ولئن انقضت آجالكم في هذه الحياة الدنيا، فمتم على فُرُشكم، أو قتلتم في ساحة القتال، لإلى الله وحده تُحشرون، فيجازيكم بأعمالكم.', 158, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (452, 3, 1, 4, 452, 'فبرحمة من الله لك ولأصحابك -أيها النبي- منَّ الله عليك فكنت رفيقًا بهم، ولو كنت سيِّئ الخُلق قاسي القلب، لانْصَرَفَ أصحابك من حولك، فلا تؤاخذهم بما كان منهم في غزوة "أُحد"، واسأل الله -أيها النبي- أن يغفر لهم، وشاورهم في الأمور التي تحتاج إلى مشورة، فإذا عزمت على أمر من الأمور -بعد الاستشارة- فأَمْضِه معتمدًا على الله وحده، إن الله يحب المتوكلين عليه.', 159, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (453, 3, 1, 4, 453, 'إن يمددكم الله بنصره ومعونته فلا أحد يستطيع أن يغلبكم، وإن يخذلكم فمن هذا الذي يستطيع أن ينصركم من بعد خذلانه لكم؟ وعلى الله وحده فليتوكل المؤمنون.', 160, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (454, 3, 1, 4, 454, 'وما كان لنبيٍّ أن يَخُونَ أصحابه بأن يأخذ شيئًا من الغنيمة غير ما اختصه الله به، ومن يفعل ذلك منكم يأت بما أخذه حاملا له يوم القيامة؛ ليُفضَح به في الموقف المشهود، ثم تُعطى كل نفس جزاءَ ما كسبت وافيًا غير منقوص دون ظلم.', 161, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (455, 3, 1, 4, 455, 'لا يستوي من كان قصده رضوان الله ومن هو مُكِبٌ على المعاصي، مسخط لربه، فاستحق بذلك سكن جهنم، وبئس المصير.', 162, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (456, 3, 1, 4, 456, 'أصحاب الجنة المتبعون لما يرضي الله متفاوتون في الدرجات، وأصحاب النار المتبعون لما يسخط الله متفاوتون في الدركات، لا يستوون. والله بصير بأعمالهم لا يخفى عليه منها شيء.', 163, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (457, 3, 1, 4, 457, 'لقد أنعم الله على المؤمنين من العرب؛ إذ بعث فيهم رسولا من أنفسهم، يتلو عليهم آيات القرآن، ويطهرهم من الشرك والأخلاق الفاسدة، ويعلمهم القرآن والسنة، وإن كانوا من قبل هذا الرسول لفي غيٍّ وجهل ظاهر.', 164, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (458, 3, 1, 4, 458, 'أولما أصابتكم -أيها المؤمنون- مصيبة، وهي ما أُصيب منكم يوم "أُحد" قد أصبتم مثليها من المشركين في يوم "بدْر"، قلتم متعجبين: كيف يكون هذا ونحن مسلمون ورسول الله صلى الله عليه وسلم فينا وهؤلاء مشركون؟ قل لهم -أيها النبي-: هذا الذي أصابكم هو من عند أنفسكم بسبب مخالفتكم أمْرَ رسولكم وإقبالكم على جمع الغنائم. إن الله يفعل ما يشاء ويحكم ما يريد، لا معقِّب ‌‌‌‌لحكمه.', 165, 1, 71, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (459, 3, 1, 4, 459, 'وما وقع بكم مِن جراح أو قتل في غزوة "أُحد" يوم التقى جَمْعُ المؤمنين وجمع المشركين فكان النصر للمؤمنين أولا ثم للمشركين ثانيًا، فذلك كله بقضاء الله وقدره، وليظهر ما علمه الله في الأزل؛ ليميز المؤمنين الصادقين منكم.', 166, 1, 72, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (460, 3, 1, 4, 460, 'وليعلم المنافقين الذين كشف الله ما في قلوبهم حين قال المؤمنون لهم: تعالوا قاتلوا معنا في سبيل الله، أو كونوا عونًا لنا بتكثيركم سوادنا، فقالوا: لو نعلم أنكم تقاتلون أحدًا لكنا معكم عليهم، هم للكفر في هذا اليوم أقرب منهم للإيمان؛ لأنهم يقولون بأفواههم ما ليس في قلوبهم. والله أعلم بما يُخفون في صدورهم.', 167, 1, 72, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (461, 3, 1, 4, 461, 'هؤلاء المنافقون هم الذين قعدوا وقالوا لإخوانهم الذين أصيبوا مع المسلمين في حربهم المشركين يوم "أُحد": لو أطاعَنا هؤلاء ما قتلوا. قل لهم -أيها الرسول-: فادفعوا عن أنفسكم الموت إن كنتم صادقين في دعواكم أنهم لو أطاعوكم ما قتلوا، وأنكم قد نجوتم منه بقعودكم عن القتال.', 168, 1, 72, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (462, 3, 1, 4, 462, 'ولا تظنَّنَّ -أيها النبي- أن الذين قتلوا في سبيل الله أموات لا يُحِسُّون شيئًا، بل هم أحياء حياة برزخية في جوار ربهم الذي جاهدوا من أجله، وماتوا في سبيله، يجري عليهم رزقهم في الجنة، ويُنعَّمون.', 169, 1, 72, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (463, 3, 1, 4, 463, 'لقد عَمَّتهم السعادة حين مَنَّ الله عليهم، فأعطاهم مِن عظيم جوده وواسع كرمه من النعيم والرضا ما تَقَرُّ به أعينهم، وهم يفرحون بإخوانهم المجاهدين الذين فارقوهم وهم أحياء؛ ليفوزوا كما فازوا، لِعِلْمِهم أنهم سينالون من الخير الذي نالوه، إذا استشهدوا في سبيل الله مخلصين له، وأن لا خوف عليهم فيما يستقبلون من أمور الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.', 170, 1, 72, 58, NULL, 28, 7);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (464, 3, 1, 4, 464, 'وإنهم في فرحة غامرة بما أُعطوا من نعم الله وجزيل عطائه، وأن الله لا يضيع أجر المؤمنين به، بل ينمِّيه ويزيده من فضله.', 171, 1, 72, 58, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (465, 3, 1, 4, 465, 'الذين لبُّوا نداء الله ورسوله وخرجوا في أعقاب المشركين إلى "حمراء الأسد" بعد هزيمتهم في غزوة "أُحد" مع ما كان بهم من آلام وجراح، وبذلوا غاية جهدهم، والتزموا بهدي نبيهم، للمحسنين منهم والمتقين ثواب عظيم.', 172, 1, 72, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (466, 3, 1, 4, 466, 'وهم الذين قال لهم بعض المشركين: إن أبا سفيان ومن معه قد أجمعوا أمرهم على الرجوع إليكم لاستئصالكم، فاحذروهم واتقوا لقاءهم، فإنه لا طاقة لكم بهم، فزادهم ذلك التخويف يقينًا وتصديقًا بوعد الله لهم، ولم يَثْنِهم ذلك عن عزمهم، فساروا إلى حيث شاء الله، وقالوا: حسبنا الله أي: كافينا، ونِعْم الوكيل المفوَّض إليه تدبير عباده.', 173, 1, 72, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (467, 3, 1, 4, 467, 'فرجعوا من "حمراء الأسد" إلى "المدينة" بنعمة من الله بالثواب الجزيل وبفضل منه بالمنزلة العالية، وقد ازدادوا إيمانًا ويقينًا، وأذلوا أعداء الله، وفازوا بالسلامة من القتل والقتال، واتبعوا رضوان الله بطاعتهم له ولرسوله. والله ذو فضل عظيم عليهم وعلى غيرهم.', 174, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (468, 3, 1, 4, 468, 'إنَّما المثبِّط لكم في ذلك هو الشيطان جاءكم يخوِّفكم أنصاره، فلا تخافوا المشركين؛ لأنّهم ضعاف لا ناصر لهم، وخافوني بالإقبال على طاعتي إن كنتم مصدِّقين بي، ومتبعين رسولي.', 175, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (469, 3, 1, 4, 469, 'لا يُدْخِل الحزنَ إلى قلبك -أيها الرسول- هؤلاء الكفارُ بمسارعتهم في الجحود والضلال، إنهم بذلك لن يضروا الله، إنما يضرون أنفسهم بحرمانها حلاوة الإيمان وعظيم الثواب، يريد الله ألا يجعل لهم ثوابًا في الآخرة؛ لأنهم انصرفوا عن دعوة الحق، ولهم عذاب شديد.', 176, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (470, 3, 1, 4, 470, 'إن الذين استبدلوا الكفر بالإيمان لن يضروا الله شيئًا، بل ضرر فِعْلِهم يعود على أنفسهم، ولهم في الآخرة عذاب موجع.', 177, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (471, 3, 1, 4, 471, 'ولا يظننَّ الجاحدون أننا إذا أَطَلْنا أعمارهم، ومتعناهم بمُتع الدنيا، ولم تؤاخذهم بكفرهم وذنوبهم، أنهم قد نالوا بذلك خيرًا لأنفسهم، إنما نؤخر عذابهم وآجالهم؛ ليزدادوا ظلمًا وطغيانًا، ولهم عذاب يهينهم ويذلُّهم.', 178, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (472, 3, 1, 4, 472, 'ما كان الله ليَدَعَكم أيها المصدقون بالله ورسوله العاملون بشرعه على ما أنتم عليه من التباس المؤمن منكم بالمنافق حتى يَمِيزَ الخبيث من الطيب، فيُعرف المنافق من المؤمن الصادق. وما كان مِن حكمة الله أن يطلعكم -أيها المؤمنون- على الغيب الذي يعلمه من عباده، فتعرفوا المؤمن منهم من المنافق، ولكنه يميزهم بالمحن والابتلاء، غير أن الله تعالى يصطفي من رسله مَن يشاء؛ ليطلعه على بعض علم الغيب بوحي منه، فآمنوا بالله ورسوله، وإن تؤمنوا إيمانًا صادقًا وتتقوا ربكم بطاعته، فلكم أجر عظيم عند الله.', 179, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (473, 3, 1, 4, 473, 'ولا يظنن الذين يبخلون بما أنعم الله به عليهم تفضلا منه أن هذا البخل خير لهم، بل هو شرٌّ لهم؛ لأن هذا المال الذي جمعوه سيكون طوقًا من نار يوضع في أعناقهم يوم القيامة. والله سبحانه وتعالى هو مالك الملك، وهو الباقي بعد فناء جميع خلقه، وهو خبير بأعمالكم جميعها، وسيجازي كلا على قدر استحقاقه.', 180, 1, 73, 59, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (474, 3, 1, 4, 474, 'لقد سمع الله قول اليهود الذين قالوا: إن الله فقير إلينا يطلب منا أن نقرضه أموالا ونحن أغنياء. سنكتب هذا القول الذي قالوه، وسنكتب أنهم راضون بما كان مِن قَتْل آبائهم لأنبياء الله ظلمًا وعدوانًا، وسوف نؤاخذهم بذلك في الآخرة، ونقول لهم وهم في النار يعذبون: ذوقوا عذاب النار المحرقة.', 181, 1, 74, 60, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (475, 3, 1, 4, 475, 'ذلك العذاب الشديد بسبب ما قدَّمتموه في حياتكم الدنيا من المعاصي القولية والفعلية والاعتقادية، وأن الله ليس بظلام للعببد.', 182, 1, 74, 60, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (476, 3, 1, 4, 476, 'هؤلاء اليهود حين دُعُوا إلى الإسلام قالوا: إن الله أوصانا في التوراة ألا نصدِّق مَن جاءنا يقول: إنه رسول من الله، حتى يأتينا بصدقة يتقرب بها إلى الله، فتنزل نار من السماء فتحرقها. قل لهم -أيها الرسول-: أنتم كاذبون في قولكم؛ لأنه قد جاء آباءكم رسلٌ من قِبلي بالمعجزات والدلائل على صدقهم، وبالذي قلتم من الإتيان بالقربان الذي تأكله النار، فَلِمَ قَتَل آباؤكم هؤلاء الأنبياء إن كنتم صادقين في دعواكم؟', 183, 1, 74, 60, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (477, 3, 1, 4, 477, 'فإن كذَّبك -أيها الرسول- هؤلاء اليهود وغيرهم من أهل الكفر، فقد كذَّب المبطلون كثيرًا من المرسلين مِن قبلك، جاءوا أقوامهم بالمعجزات الباهرات والحجج الواضحات، والكتب السماوية التي هي نور يكشف الظلمات، والكتابِ البيِّن الواضح.', 184, 1, 74, 60, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (478, 3, 1, 4, 478, 'كل نفس لا بدَّ أن تذوق الموت، وبهذا يرجع جميع الخلق إلى ربهم؛ ليحاسبهم. وإنما تُوفَّون أجوركم على أعمالكم وافية غير منقوصة يوم القيامة، فمن أكرمه ربه ونجَّاه من النار وأدخله الجنة فقد نال غاية ما يطلب. وما الحياة الدنيا إلا متعة زائلة، فلا تغترُّوا بها.', 185, 1, 74, 60, NULL, 29, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (479, 3, 1, 4, 479, 'لَتُخْتَبَرُنَّ -أيها المؤمنون- في أموالكم بإخراج النفقات الواجبة والمستحبَّة، وبالجوائح التي تصيبها، وفي أنفسكم بما يجب عليكم من الطاعات، وما يحلُّ بكم من جراح أو قتل وفَقْد للأحباب، وذلك حتى يتميَّز المؤمن الصادق من غيره. ولتَسمعُنَّ من اليهود والنصارى والمشركين ما يؤذي أسماعكم من ألفاظ الشرك والطعن في دينكم. وإن تصبروا -أيها المؤمنون- على ذلك كله، وتتقوا الله بلزوم طاعته واجتناب معصيته، فإن ذلك من الأمور التي يُعزم عليها، وينافس فيها.', 186, 1, 74, 60, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (480, 3, 1, 4, 480, 'واذكر -أيها الرسول- إذ أخذ الله العهد الموثق على الذين آتاهم الله الكتاب من اليهود والنصارى، فلليهود التوراة وللنصارى الإنجيل؛ ليعملوا بهما، ويبينوا للناس ما فيهما، ولا يكتموا ذلك ولا يخفوه، فتركوا العهد ولم يلتزموا به، وأخذوا ثمنا بخسًا مقابل كتمانهم الحق وتحريفهم الكتاب، فبئس الشراء يشترون، في تضييعهم الميثاق، وتبديلهم الكتاب.', 187, 1, 75, 60, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (481, 3, 1, 4, 481, 'ولا تظنن الذين يفرحون بما أَتَوا من أفعال قبيحة كاليهود والمنافقين وغيرهم، ويحبون أن يثني عليهم الناس بما لم يفعلوا، فلا تظننهم ناجين من عذاب الله في الدنيا، ولهم في الآخرة عذاب موجع. وفي الآية وعيد شديد لكل آت لفعل السوء معجب به، ولكل مفتخر بما لم يعمل، ليُثنيَ عليه الناس ويحمدوه.', 188, 1, 75, 60, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (482, 3, 1, 4, 482, 'ولله وحده ملك السموات والأرض وما فيهما، والله على كل شيء قدير.', 189, 1, 75, 60, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (483, 3, 1, 4, 483, 'إن في خلق السموات والأرض على غير مثال سابق، وفي تعاقُب الليل والنهار، واختلافهما طولا وقِصَرًا لدلائل وبراهين عظيمة على وحدانية الله لأصحاب العقول السليمة.', 190, 1, 75, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (484, 3, 1, 4, 484, 'الذين يذكرون الله في جميع أحوالهم: قيامًا وقعودًا وعلى جنوبهم، وهم يتدبرون في خلق السموات والأرض، قائلين: يا ربنا ما أوجدت هذا الخلق عبثًا، فأنت منزَّه عن ذلك، فاصْرِف عنا عذاب النار.', 191, 1, 75, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (485, 3, 1, 4, 485, 'يا ربنا نجِّنا من النار، فإنك -يا ألله- مَن تُدخِلْه النار بذنوبه فقد فضحته وأهنته، وما للمذنبين الظالمين لأنفسهم من أحد يدفع عنهم عقاب الله يوم القيامة.', 192, 1, 75, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (486, 3, 1, 4, 486, 'يا ربنا إننا سمعنا مناديا -هو نبيك محمد صلى الله عليه وسلم- ينادي الناس للتصديق بك، والإقرار بوحدانيتك، والعمل بشرعك، فأجبنا دعوته وصدَّقنا رسالته، فاغفر لنا ذنوبنا، واستر عيوبنا، وألحقنا بالصالحين.', 193, 1, 75, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (487, 3, 1, 4, 487, 'يا ربنا أعطنا ما وعدتنا على ألسنة رسلك من نصر وتمكين وتوفيق وهداية، ولا تفضحنا بذنوبنا يوم القيامة، فإنك كريم لا تُخْلف وعدًا وَعَدْتَ به عبادك.', 194, 1, 75, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (488, 3, 1, 4, 488, 'فأجاب الله دعاءهم بأنه لا يضيع جهد مَن عمل منهم عملا صالحًا ذكرًا كان أو أنثى، وهم في أُخُوَّة الدين وقَبول الأعمال والجزاء عليها سواء، فالذين هاجروا رغبةً في رضا الله تعالى، وأُخرجوا من ديارهم، وأوذوا في طاعة ربهم وعبادتهم إيّاه، وقاتلوا وقُتِلوا في سبيل الله لإعلاء كلمته، ليسترنَّ الله عليهم ما ارتكبوه من المعاصي، كما سترها عليهم في الدنيا، فلا يحاسبهم عليها، وليدخلنَّهم جنات تجري من تحت قصورها وأشجارها الأنهار جزاء من عند الله، والله عنده حسن الثواب.', 195, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (489, 3, 1, 4, 489, 'لا تغتر -أيها الرسول- بما عليه أهل الكفر بالله من بسطة في العيش، وسَعَة في الرزق، وانتقالهم من مكان إلى مكان للتجارات وطلب الأرباح والأموال، فعمَّا قليل يزول هذا كلُّه عنهم، ويصبحون مرتهنين بأعمالهم السيئة.', 196, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (490, 3, 1, 4, 490, 'متاع قليل زائل، ثم يكون مصيرهم يوم القيامة إلى النار، وبئس الفراش.', 197, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (491, 3, 1, 4, 491, 'لكن الذين خافوا ربهم، وامتثلوا أوامره، واجتنبوا نواهيه، قد أعدَّ الله لهم جنات تجري من تحت أشجارها الأنهار، هي منزلهم الدائم لا يخرجون منه. وما عد الله أعظم وأفضل لأهل الطاعة مما يتقلب فيه الذين كفروا من نعيم الدنيا.', 198, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (492, 3, 1, 4, 492, 'وإن بعضًا من أهل الكتاب لَيصدِّق بالله ربًّا واحدًا وإلهًا معبودًا، وبما أُنزِل إليكم من هذا القرآن، وبما أُنزِل إليهم من التوراة والإنجيل متذللين لله، خاضعين له، لا يشترون بآيات الله ثمنًا قليلا من حطام الدنيا، ولا يكتمون ما أنزل الله، ولا يحرفونه كغيرهم من أهل الكتاب. أولئك لهم ثواب عظيم عنده يوم يلقونه، فيوفيهم إياه غير منقوص. إنَّ الله سريع الحساب، لا يعجزه إحصاء أعمالهم، ومحاسبتهم عليها.', 199, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (493, 3, 1, 4, 493, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اصبروا على طاعة ربكم، وعلى ما ينزل بكم من ضر وبلاء، وصابروا أعداءكم حتى لا يكونوا أشد صبرًا منكم، وأقيموا على جهاد عدوي وعدوكم، وخافوا الله في جميع أحوالكم؛ رجاء أن تفوزوا برضاه في الدنيا والآخرة.', 200, 1, 76, 61, NULL, 30, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (494, 4, 1, 4, 494, 'يا أيها الناس خافوا الله والتزموا أوامره، واجتنبوا نواهيه؛ فهو الذي خلقكم من نفس واحدة هي آدم عليه السلام، وخلق منها زوجها وهي حواء، ونشر منهما في أنحاء الأرض رجالا كثيرًا ونساء كثيرات، وراقبوا الله الذي يَسْأل به بعضكم بعضًا، واحذروا أن تقطعوا أرحامكم. إن الله مراقب لجميع أحوالكم.', 1, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (495, 4, 1, 4, 495, 'وأعطوا مَن مات آباؤهم وهم دون البلوغ، وكنتم عليهم أوصياء، أموالهم إذا وصلوا سن البلوغ، ورأيتم منهم قدرة على حفظ أموالهم، ولا تأخذوا الجيِّد من أموالهم، وتجعلوا مكانه الرديء من أموالكم، ولا تخلطوا أموالهم بأموالكم؛ لتحتالوا بذلك على أكل أموالهم. إن من تجرأ على ذلك فقد ارتكب إثمًا عظيمًا.', 2, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (496, 4, 1, 4, 496, 'وإن خفتم ألا تعدلوا في يتامى النساء اللاتي تحت أيديكم بأن لا تعطوهن مهورهن كغيرهن، فاتركوهن وانكحوا ما طاب لكم من النساء من غيرهن: اثنتين أو ثلاثًا أو أربعًا، فإن خشيتم ألا تعدلوا بينهن فاكتفوا بواحدة، أو بما عندكم من الإماء. ذلك الذي شرعته لكم في اليتيمات والزواج من واحدة إلى أربع، أو الاقتصار على واحدة أو ملك اليمين، أقرب إلى عدم الجَوْرِ والتعدي.', 3, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (497, 4, 1, 4, 497, 'وأعطوا النساء مهورهن، عطية واجبة وفريضة لازمة عن طيب نفس منكم. فإن طابت أنفسهن لكم عن شيء من المهر فوهَبْنه لكم فخذوه، وتصرَّفوا فيه، فهو حلال طيب.', 4, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (498, 4, 1, 4, 498, 'ولا تؤتوا -أيها الأولياء- من يُبَذِّر من الرجال والنساء والصبيان أموالهم التي تحت أيديكم فيضعوها في غير وجهها، فهذه الأموال هي التي عليها قيام حياة الناس، وأنفقوا عليهم منها واكسوهم، وقولوا لهم قولا معروفًا من الكلام الطيب والخلق الحسن.', 5, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (499, 4, 1, 4, 499, 'واختبروا مَن تحت أيديكم من اليتامى لمعرفة قدرتهم على حسن التصرف في أموالهم، حتى إذا وصلوا إلى سن البلوغ، وعَلمتم منهم صلاحًا في دينهم، وقدرة على حفظ أموالهم، فسلِّموها لهم، ولا تعتدوا عليها بإنفاقها في غير موضعها إسرافًا ومبادرة لأكلها قبل أن يأخذوها منكم. ومَن كان صاحب مال منكم فليستعفف بغناه، ولا يأخذ من مال اليتيم شيئًا، ومن كان فقيرًا فليأخذ بقدر حاجته عند الضرورة. فإذا علمتم أنهم قادرون على حفظ أموالهم بعد بلوغهم الحُلُم وسلمتموها إليهم، فأَشْهِدوا عليهم؛ ضمانًا لوصول حقهم كاملا إليهم؛ لئلا ينكروا ذلك. ويكفيكم أن الله شاهد عليكم، ومحاسب لكم على ما فعلتم.', 6, 1, 77, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (500, 4, 1, 4, 500, 'للذكور -صغارًا أو كبارًا- نصيب شرعه الله فيما تركه الوالدان والأقربون من المال، قليلا كان أو كثيرًا، في أنصبة محددة واضحة فرضها الله عز وجل لهؤلاء، وللنساء كذلك.', 7, 1, 78, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (501, 4, 1, 4, 501, 'وإذا حضر قسمةَ الميراث أقاربُ الميت ممن لا حقَّ لهم في التركة، أو حضرها من مات آباؤهم وهم صغار، أو مَن لا مال لهم فأعطوهم شيئًا من المال على وجه الاستحباب قبل تقسيم التركة على أصحابها، وقولوا لهم قولا حسنًا غير فاحش ولا قبيح.', 8, 1, 78, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (502, 4, 1, 4, 502, 'ولْيَخَفِ الذين لو ماتوا وتركوا من خلفهم أبناء صغارًا ضعافًا خافوا عليهم الظلم والضياع، فليراقبوا الله فيمن تحت أيديهم من اليتامى وغيرهم، وذلك بحفظ أموالهم، وحسن تربيتهم، ودَفْع الأذى عنهم، وليقولوا لهم قولا موافقا للعدل والمعروف.', 9, 1, 78, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (503, 4, 1, 4, 503, 'إن الذين يعْتَدون على أموال اليتامى، فيأخذونها بغير حق، إنما يأكلون نارًا تتأجّج في بطونهم يوم القيامة، وسيدخلون نارا يقاسون حرَّها.', 10, 1, 78, 62, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (504, 4, 1, 4, 504, 'يوصيكم الله ويأمركم في شأن أولادكم: إذا مات أحد منكم وترك أولادًا: ذكورًا وإناثًا، فميراثه كله لهم: للذكر مثل نصيب الأنثيين، إذا لم يكن هناك وارث غيرهم. فإن ترك بنات فقط فللبنتين فأكثر ثلثا ما ترك، وإن كانت ابنة واحدة، فلها النصف. ولوالِدَي الميت لكل واحد منهما السدس إن كان له ولد: ذكرًا كان أو أنثى، واحدًا أو أكثر. فإن لم يكن له ولد وورثه والداه فلأمه الثلث ولأبيه الباقي. فإن كان للميت إخوة اثنان فأكثر، ذكورًا كانوا أو إناثًا، فلأمه السدس، وللأب الباقي ولا شيء للإخوة. وهذا التقسيم للتركة إنما يكون بعد إخراج وصية الميت في حدود الثلث أو إخراج ما عليه من دَيْن. آباؤكم وأبْناؤكم الذين فُرِض لهم الإرث لا تعرفون أيهم أقرب لكم نفعًا في دنياكم وأخراكم، فلا تفضلوا واحدًا منهم على الآخر. هذا الذي أوصيتكم به مفروض عليكم من الله. إن الله كان عليمًا بخلقه، حكيمًا فيما شرعه لهم.', 11, 1, 78, 63, NULL, 31, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (505, 4, 1, 4, 505, 'ولكم -أيها الرجال- نصف ما ترك أزواجكم بعد وفاتهن إن لم يكن لهن ولد ذكرًا كان أو أنثى، فإن كان لهن ولد فلكم الربع مما تركن، ترثونه من بعد إنفاذ وصيتهن الجائزة، أو ما يكون عليهن من دَيْن لمستحقيه. ولأزواجكم - أيها الرجال - الربع مما تركتم، إن لم يكن لكم ابن أو ابنة منهن أو من غيرهن، فإن كان لكم ابن أو ابنة فلهن الثمن مما تركتم، يقسم الربع أو الثمن بينهن، فإن كانت زوجة واحدة كان هذا ميراثًا لها، من بعد إنفاذ ما كنتم أوصيتم به من الوصايا الجائزة، أو قضاء ما يكون عليكم من دَيْن. وإن مات رجل أو امراة وليس له أو لها ولد ولا والد، وله أو لها أخ أو أخت من أم فلكل واحد منهما السدس. فإن كان الإخوة أو الأخوات لأم أكثر من ذلك فهم شركاء في الثلث يقسم بينهم بالسوية لا فرق بين الذكر والأنثى، وهذا الذي فرضه الله للإخوة والأخوات لأم يأخذونه ميراثًا لهم من بعد قضاء ديون الميت، وإنفاذ وصيته إن كان قد أوصى بشيء لا ضرر فيه على الورثة. بهذا أوصاكم ربكم وصية نافعة لكم. والله عليم بما يصلح خلقه، حليم لا يعاجلهم بالعقوبة.', 12, 1, 79, 63, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (506, 4, 1, 4, 506, 'تلك الأحكام الإلهية التي شرعها الله في اليتامى والنساء والمواريث، شرائعه الدالة على أنها مِن عند الله العليم الحكيم. ومَن يطع الله ورسوله فيما شرع لعباده من هذه الأحكام وغيرها، يدخله جنات كثيرة الأشجار والقصور، تجري من تحتها الأنهار بمياهها العذبة، وهم باقون في هذا النعيم، لا يخرجون منه، وذلك الثواب هو الفلاح العظيم.', 13, 1, 79, 63, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (507, 4, 1, 4, 507, 'ومَن يَعْصِ الله ورسوله، بإنكاره لأحكام الله، وتجاوزه ما شرعه الله لعباده بتغييرها، أو تعطيل العمل بها، يدخله نارًا ماكثًا فيها، وله عذاب يخزيه ويهينه.', 14, 1, 79, 63, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (508, 4, 1, 4, 508, 'واللاتي يزنين من نسائكم، فاستشهدوا -أيها الولاة والقضاة- عليهن أربعة رجال عدول من المسلمين، فإن شهدوا عليهن بذلك فاحبسوهن في البيوت حتى تنتهي حياتهن بالموت، أو يجعل الله لهن طريقًا للخلاص من ذلك.', 15, 1, 80, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (509, 4, 1, 4, 509, 'واللذان يقعان في فاحشة الزنى، فآذُوهما بالضرب والهجر والتوبيخ، فإن تابا عمَّا وقع منهما وأصلحا بما يقدِّمان من الأعمال الصالحة فاصفحوا عن أذاهما. ويستفاد من هذه الآية والتي قبلها أن الرجال إذا فعلوا الفاحشة يُؤْذَوْن، والنساء يُحْبَسْنَ ويُؤذَيْنَ، فالحبس غايتة الموت، والأذية نهايتها إلى التوبة والصلاح. وكان هذا في صدر الإسلام، ثم نُسخ بما شرع الله ورسوله، وهو الرجم للمحصن والمحصنة، وهما الحران البالغان العاقلان، اللذان جامعا في نكاح صحيح، والجلدُ مائة جلدة، وتغريب عام لغيرهما. إن الله كان توابا على عباده التائبين، رحيمًا بهم.', 16, 1, 80, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (510, 4, 1, 4, 510, 'إنَّما يقبل الله التوبة من الذين يرتكبون المعاصي والذنوب بجهل منهم لعاقبتها، وإيجابها لسخط الله -فكل عاص لله مخطئًا أو متعمِّدًا فهو جاهل بهذا الاعتبار، وإن كان عالمًا بالتحريم -ثم يرجعون إلى ربهم بالإنابة والطاعة قبل معاينة الموت، فأولئك يقبل الله توبتهم. وكان الله عليمًا بخلقه، حكيمًا في تدبيره وتقديره.', 17, 1, 80, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (511, 4, 1, 4, 511, 'وليس قَبول التوبة للذين يُصِرُّون على ارتكاب المعاصي، ولا يرجعون إلى ربهم إلى أن تأتيهم سكرات الموت، فيقول أحدهم: إني تبت الآن، كما لا تُقبل توبة الذين يموتون وهم جاحدون، منكرون لوحدانية الله ورسالة رسوله محمد صلى الله عليه وسلم. أولئك المصرُّون على المعاصي إلى أن ماتوا، والجاحدون الذين يموتون وهم كفار، أعتدنا لهم عذابًا موجعًا.', 18, 1, 80, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (512, 4, 1, 4, 512, 'يا أيها الذين آمنوا لا يجوز لكم أن تجعلوا نساء آبائكم من جملة تَرِكتهم، تتصرفون فيهن بالزواج منهن، أو المنع لهن، أو تزويجهن للآخرين، وهن كارهات لذلك كله، ولا يجوز لكم أن تضارُّوا أزواجكم وأنتم كارهون لهن؛ ليتنازلن عن بعض ما آتيتموهن من مهر ونحوه، إلا أن يرتكبن أمرا فاحشا كالزنى، فلكم حينئذ إمساكهن حتى تأخذوا ما أعطيتموهن. ولتكن مصاحبتكم لنسائكم مبنية على التكريم والمحبة، وأداء ما لهن من حقوق. فإن كرهتموهن لسبب من الأسباب الدنيوية فاصبروا؛ فعسى أن تكرهوا أمرًا من الأمور ويكون فيه خير كثير.', 19, 1, 80, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (513, 4, 1, 4, 513, 'وإن أردتم استبدال زوجة مكان أخرى، وكنتم قد أعطيتم مَن تريدون طلاقها مالا كثيرًا مهرًا لها، فلا يحل لكم أن تأخذوا منه شيئًا، أتأخذونه كذبًا وافتراءً واضحًا؟', 20, 1, 81, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (514, 4, 1, 4, 514, 'وكيف يحلُّ لكم أن تأخذوا ما أعطيتموهن من مهر، وقد استمتع كل منكما بالآخر بالجماع، وأخَذْنَ منكم ميثاقًا غليظًا من إمساكهن بمعروف أو تسريحهن بإحسان؟', 21, 1, 81, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (515, 4, 1, 4, 515, 'ولا تتزوجوا مَن تزوجه آباؤكم من النساء إلا ما قد سلف منكم ومضى في الجاهلية فلا مؤاخذة فيه. إن زواج الأبناء من زوجات آبائهم أمر قبيح يفحش ويعظم قبحه، وبغيض يمقت الله فاعله، وبئس طريقًا ومنهجًا ما كنتم تفعلونه في جاهليتكم.', 22, 1, 81, 64, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (516, 4, 1, 4, 516, 'حرَّم الله عليكم نكاح أمهاتكم، ويدخل في ذلك الجدَّات مِن جهة الأب أو الأم، وبناتكم: ويشمل بنات الأولاد وإن نزلن، وأخواتكم الشقيقات أو لأب أو لأم، وعماتكم: أخوات آبائكم وأجدادكم، وخالاتكم: أخوات أمهاتكم وجداتكم، وبنات الأخ، وبنات الأخت: ويدخل في ذلك أولادهن، وأمهاتكم اللاتي أرضعنكم، وأخواتكم من الرضاعة -وقد حرَّم رسول الله صلى الله عليه وسلم من الرضاع ما يحرم من النسب- وأمهات نسائكم، سواء دخلتم بنسائكم، أم لم تدخلوا بهن، وبنات نسائكم من غيركم اللاتي يتربَّيْنَ غالبًا في بيوتكم وتحت رعايتكم، وهن مُحرَّمَات فإن لم يكنَّ في حجوركم، ولكن بشرط الدخول بأمهاتهن، فإن لم تكونوا دخلتم بأمهاتهن وطلقتموهن أو متْنَ قبل الدخول فلا جناح عليكم أن تنكحوهن، كما حرَّم الله عليكم أن تنكحوا زوجات أبنائكم الذين من أصلابكم، ومن أُلحق بهم مِن أبنائكم من الرضاع، وهذا التحريم يكون بالعقد عليها، دخل الابن بها أم لم يدخل، وحرَّم عليكم كذلك الجمع في وقت واحد بين الأختين بنسب أو رضاع إلا ما قد سلف ومضى منكم في الجاهلية. ولا يجوز كذلك الجمع بين المرأة وعمتها أو خالتها كما جاء في السنة. إن الله كان غفورًا للمذنبين إذا تابوا، رحيمًا بهم، فلا يكلفهم ما لا يطيقون.', 23, 1, 81, 65, NULL, 32, 8);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (517, 4, 1, 5, 517, 'ويحرم عليكم نكاح المتزوجات من النساء، إلا مَنْ سَبَيْتُم منهن في الجهاد، فإنه يحل لكم نكاحهن، بعد استبراء أرحامهن بحيضة، كتب الله عليكم تحريم نكاح هؤلاء، وأجاز لكم نكاح مَن سواهن، ممَّا أحله الله لكم أن تطلبوا بأموالكم العفة عن اقتراف الحرام. فما استمتعتم به منهن بالنكاح الصحيح، فأعطوهن مهورهن، التي فرض الله لهن عليكم، ولا إثم عليكم فيما تمَّ التراضي به بينكم، من الزيادة أو النقصان في المهر، بعد ثبوت الفريضة. إن الله تعالى كان عليمًا بأمور عباده، حكيما في أحكامه وتدبيره.', 24, 1, 82, 65, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (518, 4, 1, 5, 518, 'ومن لا قدرة له على مهور الحرائر المؤمنات، فله أن ينكح غيرهن، من فتياتكم المؤمنات المملوكات. والله تعالى هو العليم بحقيقة إيمانكم، بعضكم من بعض، فتزوجوهن بموافقة أهلهن، وأعطوهن مهورهن على ما تراضيتم به عن طيب نفس منكم، متعففات عن الحرام، غير مجاهرات بالزنى، ولا مسرات به باتخاذ أخلاء، فإذا تزوجن وأتين بفاحشة الزنى فعليهن من الحدِّ نصف ما على الحرائر. ذلك الذي أبيح مِن نكاح الإماء بالصفة المتقدمة إنما أبيح لمن خاف على نفسه الوقوع في الزنى، وشق عليه الصبر عن الجماع، والصبر عن نكاح الإماء مع العفة أولى وأفضل. والله تعالى غفور لكم، رحيم بكم إذ أذن لكم في نكاحهن عند العجز عن نكاح الحرائر.', 25, 1, 82, 65, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (519, 4, 1, 5, 519, 'يريد الله تعالى بهذه التشريعات، أن يوضح لكم معالم دينه القويم، وشرعه الحكيم، ويدلكم على طرق الأنبياء والصالحين من قبلكم في الحلال والحرام، ويتوب عليكم بالرجوع بكم إلى الطاعات، وهو سبحانه عليم بما يصلح شأن عباده، حكيم فيما شرعه لكم.', 26, 1, 82, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (520, 4, 1, 5, 520, 'والله يريد أن يتوب عليكم، ويتجاوز عن خطاياكم، ويريد الذين ينقادون لشهواتهم وملذاتهم أن تنحرفوا عن الدين انحرافًا كبيرًا.', 27, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (521, 4, 1, 5, 521, 'يريد الله تعالى بما شرعه لكم التيسير، وعدم التشديد عليكم؛ لأنكم خلقتم ضعفاء.', 28, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (522, 4, 1, 5, 522, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا يحل لكم أن يأكل بعضكم مال بعض بغير حق، إلا أن يكون وَفْقَ الشرع والكسب الحلال عن تراض منكم، ولا يقتل بعضكم بعضًا فتهلكوا أنفسكم بارتكاب محارم الله ومعاصيه. إن الله كان بكم رحيمًا في كل ما أمركم به، ونهاكم عنه.', 29, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (523, 4, 1, 5, 523, 'ومن يرتكب ما نهى الله عنه من أخذ المال الحرام كالسرقة والغصب والغش معتديًا متجاوزًا حد الشرع، فسوف يدخله الله نارًا يقاسي حرَّها، وكان ذلك على الله يسيرًا.', 30, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (524, 4, 1, 5, 524, 'إن تبتعدوا -أيها المؤمنون- عن كبائر الذنوب كالإشراك بالله وعقوق الوالدين وقَتْلِ النفس بغير الحق وغير ذلك، نكفِّر عنكم ما دونها من الصغائر، وندخلكم مدخلا كريمًا، وهو الجنَّة.', 31, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (525, 4, 1, 5, 525, 'ولا تتمنوا ما فضَّل الله به بعضكم على بعض، في المواهب والأرزاق وغير ذلك، فقد جعل الله للرجال نصيبًا مقدَّرًا من الجزاء بحسب عملهم، وجعل للنساء نصيبًا مما عملن، واسألوا الله الكريم الوهاب يُعْطِكم من فضله بدلا من التمني. إن الله كان بكل شيء عليمًا، وهو أعلم بما يصلح عباده فيما قسمه لهم من خير.', 32, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (526, 4, 1, 5, 526, 'ولكل واحد منكم جعلنا ورثة يرثون مما ترك الوالدان والأقربون، والذين تحالفتم معهم بالأيمان المؤكدة على النصرة وإعطائهم شيئًا من الميراث فأعطوهم ما قُدِّر لهم. والميراث بالتحالف كان في أول الإسلام، ثم رُفع حكمه بنزول آيات المواريث. إن الله كان مُطَّلِعًا على كل شيء من أعمالكم، وسيجازيكم على ذلك.', 33, 1, 83, 66, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (527, 4, 1, 5, 527, 'الرجال قوَّامون على توجيه النساء ورعايتهن، بما خصهم الله به من خصائص القِوامَة والتفضيل، وبما أعطوهن من المهور والنفقات. فالصالحات المستقيمات على شرع الله منهن، مطيعات لله تعالى ولأزواجهن، حافظات لكل ما غاب عن علم أزواجهن بما اؤتمنَّ عليه بحفظ الله وتوفيقه، واللاتي تخشون منهن ترفُّعهن عن طاعتكم، فانصحوهن بالكلمة الطيبة، فإن لم تثمر معهن الكلمة الطيبة، فاهجروهن في الفراش، ولا تقربوهن، فإن لم يؤثر فعل الهِجْران فيهن، فاضربوهن ضربًا لا ضرر فيه، فإن أطعنكم فاحذروا ظلمهن، فإن الله العليَّ الكبير وليُّهن، وهو منتقم ممَّن ظلمهنَّ وبغى عليهن.', 34, 1, 84, 67, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (528, 4, 1, 5, 528, 'وإن علمتم -يا أولياء الزوجين- شقاقًا بينهما يؤدي إلى الفراق، فأرسلوا إليهما حكمًا عدلا من أهل الزوج، وحكمًا عدلا من أهل الزوجة؛ لينظرا ويحكما بما فيه المصلحة لهما، وبسبب رغبة الحكمين في الإصلاح، واستعمالهما الأسلوب الطيب يوفق الله بين الزوجين. إن الله تعالى عليم، لا يخفى عليه شيء من أمر عباده، خبير بما تنطوي عليه نفوسهم.', 35, 1, 84, 67, NULL, 33, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (529, 4, 1, 5, 529, 'واعبدوا الله وانقادوا له وحده، ولا تجعلوا له شريكًا في الربوبية والعبادة، وأحسنوا إلى الوالدين، وأدُّوا حقوقهما، وحقوق الأقربين، واليتامى والمحتاجين، والجار القريب منكم والبعيد، والرفيق في السفر وفي الحضر، والمسافر المحتاج، والمماليك من فتيانكم وفتياتكم. إن الله تعالى لا يحب المتكبرين من عباده، المفتخرين على الناس.', 36, 1, 84, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (530, 4, 1, 5, 530, 'الذين يمتنعون عن الإنفاق والعطاء مما رزقهم الله، ويأمرون غيرهم بالبخل، ويجحدون نِعَمَ الله عليهم، ويخفون فضله وعطاءه. وأعددنا للجاحدين عذابًا مخزيًا.', 37, 1, 84, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (531, 4, 1, 5, 531, 'وأعتدنا هذا العذاب كذلك للذين ينفقون أموالهم رياءً وسمعةً، ولا يصدقون بالله اعتقادًا وعملا ولا بيوم القيامة. وهذه الأعمال السيئة مما يدعو إليها الشيطان. ومن يكن الشيطان له ملازمًا فبئس الملازم والقرين.', 38, 1, 85, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (532, 4, 1, 5, 532, 'وأيُّ ضرر يلحقهم لو صدَّقوا بالله واليوم الآخر اعتقادًا وعملا وأنفقوا مما أعطاهم الله باحتساب وإخلاص، والله تعالى عليم بهم وبما يعملون، وسيحاسبهم على ذلك.', 39, 1, 85, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (533, 4, 1, 5, 533, 'إن الله تعالى لا ينقص أحدًا من جزاء عمله مقدار ذرة، وإن تكن زنة الذرة حسنة فإنه سبحانه يزيدها ويكثرها لصاحبها، ويتفضل عليه بالمزيد، فيعطيه من عنده ثوابًا كبيرًا هو الجنة.', 40, 1, 85, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (534, 4, 1, 5, 534, 'فكيف يكون حال الناس يوم القيامة، إذا جاء الله من كل أمة برسولها ليشهد عليها بما عملت، وجاء بك -أيها الرسول- لتكون شهيدًا على أمتك أنك بلغتهم رسالة ربِّك.', 41, 1, 85, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (535, 4, 1, 5, 535, 'يوم يكون ذلك، يتمنى الذين كفروا بالله تعالى وخالفوا الرسول ولم يطيعوه، لو يجعلهم الله والأرض سواء، فيصيرون ترابًا، حتى لا يبعثوا وهم لا يستطيعون أن يُخفوا عن الله شيئًا مما في أنفسهم، إذ ختم الله على أفواههم، وشَهِدَتْ عليهم جوارحهم بما كانوا يعملون.', 42, 1, 85, 67, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (536, 4, 1, 5, 536, 'يا أيها الذين صدَّقوا بالله ورسوله وعملوا بشرعه، لا تقربوا الصلاة ولا تقوموا إليها حال السكر حتى تميزوا وتعلموا ما تقولون، وقد كان هذا قبل التحريم القاطع للخمر في كل حال، ولا تقربوا الصلاة في حال الجنابة، ولا تقربوا مواضعها وهي المساجد، إلا من كان منكم مجتازًا من باب إلى باب، حتى تتطهروا. وإن كنتم في حال مرض لا تقدرون معه على استعمال الماء، أو حال سفر، أو جاء أحد منكم من الغائط، أو جامعتم النساء، فلم تجدوا ماء للطهارة فاقصدوا ترابًا طاهرًا، فامسحوا بوجوهكم وأيديكم منه. إن الله تعالى كان عفوًّا عنكم، غفورًا لكم.', 43, 1, 85, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (537, 4, 1, 5, 537, 'ألم تعلم -أيها الرسول- أمر اليهود الذين أُعطوا حظًّا من العلم مما جاءهم من التوراة، يستبدلون الضلالة بالهدى، ويتركون ما لديهم من الحجج والبراهين، الدالة على صدق رسالة الرسول محمد صلى الله عليه وسلم، ويتمنون لكم -أيها المؤمنون المهتدون- أن تنحرفوا عن الطريق المستقيم؛ لتكونوا ضالين مثلهم.', 44, 1, 85, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (538, 4, 1, 5, 538, 'والله سبحانه وتعالى أعلم منكم -أيها المؤمنون- بعداوة هؤلاء اليهود لكم، وكفى بالله وليًّا يتولاكم، وكفى به نصيرًا ينصركم على أعدائكم.', 45, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (539, 4, 1, 5, 539, 'من اليهود فريق دأبوا على تبديل كلام الله وتغييره عمَّا هو عليه افتراء على الله، ويقولون للرسول صلى الله عليه وسلم: سمعنا قولك وعصينا أمرك واسمع منَّا لا سمعت، ويقولون: راعنا سمعك أي: افهم عنا وأفهمنا، يلوون ألسنتهم بذلك، وهم يريدون الدعاء عليه بالرعونة حسب لغتهم، والطعن في دين الإسلام. ولو أنهم قالوا: سمعنا وأطعنا، بدل و"عصينا"، واسمع دون "غير مسمع"، وانظرنا بدل "راعنا" لكان ذلك خيرًا لهم عند الله وأعدل قولا ولكن الله طردهم من رحمته؛ بسبب كفرهم وجحودهم نبوة محمد صلى الله عليه وسلم، فلا يصدقون بالحق إلا تصديقًا قليلا لا ينفعهم.', 46, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (540, 4, 1, 5, 540, 'يا أهل الكتاب، صدِّقوا واعملوا بما نزَّلنا من القرآن، مصدقًا لما معكم من الكتب من قبل أن نأخذكم بسوء صنيعكم، فنمحو الوجوه ونحولها قِبَلَ الظهور، أو نلعن هؤلاء المفسدين بمسخهم قردة وخنازير، كما لعنَّا اليهود مِن أصحاب السبت، الذين نُهوا عن الصيد فيه فلم ينتهوا، فغضب الله عليهم، وطردهم من رحمته، وكان أمر الله نافذًا في كل حال.', 47, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (541, 4, 1, 5, 541, 'إن الله تعالى لا يغفر ولا يتجاوز عمَّن أشرك به أحدًا من مخلوقاته، أو كفر بأي نوع من أنواع الكفر الأكبر، ويتجاوز ويعفو عمَّا دون الشرك من الذنوب، لمن يشاء من عباده، ومن يشرك بالله غيره فقد اختلق ذنبًا عظيمًا.', 48, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (542, 4, 1, 5, 542, 'ألم تعلم -أيها الرسول- أمر أولئك الذين يُثنون على أنفسهم وأعمالهم، ويصفونها بالطهر والبعد عن السوء؟ بل الله تعالى وحده هو الذي يثني على مَن يشاء مِن عباده، لعلمه بحقيقة أعمالهم، ولا يُنقَصون من أعمالهم شيئًا مقدار الخيط الذي يكون في شق نَواة التمرة.', 49, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (543, 4, 1, 5, 543, 'انظر إليهم -أيها الرسول- متعجبًا من أمرهم، كيف يختلقون على الله الكذب، وهو المنزَّه عن كل ما لا يليق به؟ وكفى بهذا الاختلاق ذنبًا كبيرًا كاشفًا عن فساد معتقدهم.', 50, 1, 86, 68, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (544, 4, 1, 5, 544, 'ألم تعلم -أيها الرسول- أمر أولئك اليهود الذين أُعطوا حظًّا من العلم يصدقون بكل ما يُعبد من دون الله من الأصنام وشياطين الإنس والجن تصديقا يحملهم على التحاكم إلى غير شرع الله، ويقولون للذين كفروا بالله تعالى وبرسوله محمد صلى الله عليه وسلم: هؤلاء الكافرون أقْومُ، وأعدلُ طريقًا من أولئك الذين آمنوا؟', 51, 1, 86, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (545, 4, 1, 5, 545, 'أولئك الذين كَثُرَ فسادهم وعمَّ ضلالهم، طردهم الله تعالى من رحمته، ومَن يطرده الله من رحمته فلن تجد له من ينصره، ويدفع عنه سوء العذاب.', 52, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (546, 4, 1, 5, 546, 'بل ألهم حظ من الملك، ولو أوتوه لما أعطوا أحدًا منه شيئًا، ولو كان مقدار النقرة التي تكون في ظهر النَّواة؟', 53, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (547, 4, 1, 5, 547, 'بل أيحسدون محمدًا صلى الله عليه وسلم على ما أعطاه الله من نعمة النبوة والرسالة، ويحسدون أصحابه على نعمة التوفيق إلى الإيمان، والتصديق بالرسالة، واتباع الرسول، والتمكين في الأرض، ويتمنون زوال هذا الفضل عنهم؟ فقد أعطينا ذرية إبراهيم عليه السلام -من قَبْلُ- الكتب، التي أنزلها الله عليهم وما أوحي إليهم مما لم يكن كتابا مقروءا، وأعطيناهم مع ذلك ملكا واسعا.', 54, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (548, 4, 1, 5, 548, 'فمن هؤلاء الذين أوتوا حظًّا من العلم، مَن صدَّق برسالة محمد صلى الله عليه وسلم، وعمل بشرعه، ومنهم مَن أعرض ولم يستجب لدعوته، ومنع الناس من اتباعه. وحسبكم -أيها المكذبون- نار جهنم تسعَّر بكم.', 55, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (549, 4, 1, 5, 549, 'إن الذين جحدوا ما أنزل الله من آياته ووحي كتابه ودلائله وحججه، سوف ندخلهم نارًا يقاسون حرَّها، كلما احترقت جلودهم بدَّلْناهم جلودًا أخرى؛ ليستمر عذابهم وألمهم. إن الله تعالى كان عزيزًا لا يمتنع عليه شيء، حكيمًا في تدبيره وقضائه.', 56, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (550, 4, 1, 5, 550, 'والذين اطمأنت قلوبهم بالإيمان بالله تعالى والتصديق برسالة رسوله محمد صلى الله عليه وسلم، واستقاموا على الطاعة، سندخلهم جنات تجري من تحتها الأنهار، ينعمون فيها أبدًا ولا يخرجون منها، ولهم فيها أزواج طهرها الله مِن كل أذى، وندخلهم ظلا كثيفًا ممتدًا في الجنة.', 57, 1, 87, 69, NULL, 34, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (551, 4, 1, 5, 551, 'إن الله تعالى يأمركم بأداء مختلف الأمانات، التي اؤتمنتم عليها إلى أصحابها، فلا تفرطوا فيها، ويأمركم بالقضاء بين الناس بالعدل والقسط، إذا قضيتم بينهم، ونِعْمَ ما يعظكم الله به ويهديكم إليه. إن الله تعالى كان سميعًا لأقوالكم، مُطَّلعًا على سائر أعمالكم، بصيرًا بها.', 58, 1, 87, 69, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (552, 4, 1, 5, 552, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، استجيبوا لأوامر الله تعالى ولا تعصوه، واستجيبوا للرسول صلى الله عليه وسلم فيما جاء به من الحق، وأطيعوا ولاة أمركم في غير معصية الله، فإن اختلفتم في شيء بينكم، فأرجعوا الحكم فيه إلى كتاب الله تعالى وسنة رسوله محمد صلى الله عليه وسلم، إن كنتم تؤمنون حق الإيمان بالله تعالى وبيوم الحساب. ذلك الردُّ إلى الكتاب والسنة خير لكم من التنازع والقول بالرأي، وأحسن عاقبة ومآلا.', 59, 1, 87, 69, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (553, 4, 1, 5, 553, 'ألم تعلم -أيها الرسول- أمر أولئك المنافقين الذين يدَّعون الإيمان بما أُنزل إليك -وهو القرآن- وبما أُنزل إلى الرسل من قبلك، وهم يريدون أن يتحاكموا في فَصْل الخصومات بينهم إلى غير ما شرع الله من الباطل، وقد أُمروا أن يكفروا بالباطل؟ ويريد الشيطان أن يبعدهم عن طريق الحق، بعدًا شديدًا. وفي هذه الآية دليل على أن الإيمان الصادق، يقتضي الانقياد لشرع الله، والحكم به في كل أمر من الأمور، فمن زعم أنه مؤمن واختار حكم الطاغوت على حكم الله، فهو كاذب في زعمه.', 60, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (554, 4, 1, 5, 554, 'وإذا نُصح هؤلاء، وقيل لهم: تعالوا إلى ما أنزل الله، وإلى الرسول محمد صلى الله عليه وسلم، وهديه، أبصَرْتَ الذين يظهرون الإيمان ويبطنون الكفر، يعرضون عنك إعراضًا.', 61, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (555, 4, 1, 5, 555, 'فكيف يكون حال أولئك المناففين، إذا حلَّت بهم مصيبة بسبب ما اقترفوه بأيديهم، ثم جاؤوك -أيها الرسول- يعتذرون، ويؤكدون لك أنهم ما قصدوا بأعمالهم تلك إلا الإحسان والتوفيق بين الخصوم؟', 62, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (556, 4, 1, 5, 556, 'أولئك هم الذين يعلم الله حقيقة ما في قلوبهم من النفاق، فتولَّ عنهم، وحذِّرهم من سوء ما هم عليه، وقل لهم قولا مؤثرًا فيهم زاجرًا لهم.', 63, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (557, 4, 1, 5, 557, 'وما بعَثْنَا من رسول من رسلنا، إلا ليستجاب له، بأمر الله تعالى وقضائه. ولو أن هؤلاء الذين ظلموا أنفسهم باقتراف السيئات، جاؤوك -أيها الرسول- في حياتك تائبين سائلين الله أن يغفر لهم ذنوبهم، واستغفرت لهم، لوجدوا الله توابًا رحيمًا.', 64, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (558, 4, 1, 5, 558, 'أقسم الله تعالى بنفسه الكريمة أن هؤلاء لا يؤمنون حقيقة حتى يجعلوك حكمًا فيما وقع بينهم من نزاع في حياتك، ويتحاكموا إلى سنتك بعد مماتك، ثم لا يجدوا في أنفسهم ضيقًا مما انتهى إليه حكمك، وينقادوا مع ذلك انقيادًا تاماً، فالحكم بما جاء به رسول الله صلى الله عليه وسلم من الكتاب والسنة في كل شأن من شؤون الحياة من صميم الإيمان مع الرضا والتسليم.', 65, 1, 88, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (559, 4, 1, 5, 559, 'ولو أوجبنا على هؤلاء المنافقين المتحاكمين إلى الطاغوت أن يقتل بعضهم بعضًا، أو أن يخرجوا من ديارهم، ما استجاب لذلك إلا عدد قليل منهم، ولو أنهم استجابوا لما يُنصحون به لكان ذلك نافعًا لهم، وأقوى لإيمانهم، ولأعطيناهم من عندنا ثوابًا عظيمًا في الدنيا والآخرة، ولأرشدناهم ووفقناهم إلى طريق الله القويم.', 66, 1, 89, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (560, 4, 1, 5, 560, 'لا يوجد تفسير لهذه الآية', 67, 1, 89, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (561, 4, 1, 5, 561, 'لا يوجد تفسير لهذه الآية', 68, 1, 89, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (562, 4, 1, 5, 562, 'ومن يستجب لأوامر الله تعالى وهدي رسوله محمد صلى الله عليه وسلم فأولئك الذين عَظُمَ شأنهم وقدرهم، فكانوا في صحبة مَن أنعم الله تعالى عليهم بالجنة من الأنبياء والصديقين الذين كمُل تصديقهم بما جاءت به الرسل، اعتقادًا وقولا وعملا والشهداء في سبيل الله وصالح المؤمنين، وحَسُنَ هؤلاء رفقاء في الجنة.', 69, 1, 89, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (563, 4, 1, 5, 563, 'ذلك العطاء الجزيل من الله وحده. وكفى بالله عليما يعلم أحوال عباده، ومَن يَستحقُّ منهم الثواب الجزيل بما قام به من الأعمال الصالحة.', 70, 1, 89, 70, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (564, 4, 1, 5, 564, 'يا أيها الذين آمنوا خذوا حذركم بالاستعداد لعدوكم، فاخرجوا لملاقاته جماعة بعد جماعة أو مجتمعين.', 71, 1, 89, 71, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (565, 4, 1, 5, 565, 'وإنَّ منكم لنفرًا يتأخر عن الخروج لملاقاة الأعداء متثاقلا ويثبط غيره عن عمد وإصرار، فإن قُدِّر عليكم وأُصِبتم بقتل وهزيمة، قال مستبشرًا: قد حفظني الله، حين لم أكن حاضرًا مع أولئك الذين وقع لهم ما أكرهه لنفسي، وسرَّه تخلفه عنكم.', 72, 1, 89, 71, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (566, 4, 1, 5, 566, 'ولئن نالكم فضل من الله وغنيمة، ليقولن -حاسدًا متحسرًا، كأن لم تكن بينكم وبينه مودة في الظاهر-: يا ليتني كنت معهم فأظفر بما ظَفِروا به من النجاة والنصرة والغنيمة.', 73, 1, 89, 71, NULL, 35, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (567, 4, 1, 5, 567, 'فليجاهد في سبيل نصرة دين الله، وإعلاء كلمته، الذين يبيعون الحياة الدنيا بالدار الآخرة وثوابها. ومن يجاهد في سبيل الله مخلصًا، فيُقْتَلْ أو يَغْلِبْ، فسوف نؤتيه أجرًا عظيمًا.', 74, 1, 89, 71, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (568, 4, 1, 5, 568, 'وما الذي يمنعكم -أيها المؤمنون- عن الجهاد في سبيل نصرة دين الله، ونصرة عباده المستضعفين من الرجال والنساء والصغار الذين اعتُدي عليهم، ولا حيلة لهم ولا وسيلة لديهم إلا الاستغاثة بربهم، يدعونه قائلين: ربنا أخرجنا من هذه القرية -يعني "مكة "- التي ظَلَم أهلها أنفسهم بالكفر والمؤمنين بالأذى، واجعل لنا من عندك وليّاً يتولى أمورنا، ونصيرًا ينصرنا على الظالمين؟', 75, 1, 90, 71, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (569, 4, 1, 5, 569, 'الذين صدَقُوا في إيمانهم اعتقادًا وعملا يجاهدون في سبيل نصرة الحق وأهله، والذين كفروا يقاتلون في سبيل البغي والفساد في الأرض، فقاتلوا أيها المؤمنون أهل الكفر والشرك الذين يتولَّون الشيطان، ويطيعون أمره، إن تدبير الشيطان لأوليائه كان ضعيفًا.', 76, 1, 90, 71, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (570, 4, 1, 5, 570, 'ألم تعلم -أيها الرسول- أمر أولئك الذين قيل لهم قبل الإذن بالجهاد: امنعوا أيديكم عن قتال أعدائكم من المشركين، وعليكم أداء ما فرضه الله عليكم من الصلاة، والزكاة، فلما فرض عليهم القتال إذا جماعة منهم قد تغير حالهم، فأصبحوا يخافون الناس ويرهبونهم، كخوفهم من الله أو أشد، ويعلنون عما اعتراهم من شدة الخوف، فيقولون: ربنا لِمَ أَوْجَبْتَ علينا القتال؟ هلا أمهلتنا إلى وقت قريب، رغبة منهم في متاع الحياة الدنيا، قل لهم -أيها الرسول-: متاع الدنيا قليل، والآخرة وما فيها أعظم وأبقى لمن اتقى، فعمل بما أُمر به، واجتنب ما نُهي عنه.، لا يظلم ربك أحدًا شيئًا، ولو كان مقدار الخيط الذي يكون في شق نَواة التمرة.', 77, 1, 90, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (571, 4, 1, 5, 571, 'أينما تكونوا يلحقكم الموت في أي مكان كنتم فيه عند حلول آجالكم، ولو كنتم في حصون منيعة بعيدة عن ساحة المعارك والقتال. وإن يحصل لهم ما يسرُّهم من متاع هذه الحياة، ينسبوا حصوله إلى الله تعالى، وإن وقع عليهم ما يكرهونه ينسبوه إلى الرسول محمد صلى الله عليه وسلم جهالة وتشاؤمًا، وما علموا أن ذلك كله من عند الله وحده، بقضائه وقدره، فما بالهم لا يقاربون فَهْمَ أيِّ حديث تحدثهم به؟', 78, 1, 90, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (572, 4, 1, 5, 572, 'ما أصابك -أيها الإنسان- مِن خير ونعمة فهو من الله تعالى وحده، فضلا وإحسانًا، وما أصابك من جهد وشدة فبسبب عملك السيئ، وما اقترفته يداك من الخطايا والسيئات. وبعثناك -أيها الرسول- لعموم الناس رسولا تبلغهم رسالة ربك، وكفى بالله شهيدًا على صدق رسالتك.', 79, 1, 90, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (573, 4, 1, 5, 573, 'من يستجب للرسول صلى الله عليه وسلم، ويعمل بهديه، فقد استجاب لله تعالى وامتثل أمره، ومن أعرض عن طاعة الله ورسوله فما بعثناك -أيها الرسول- على هؤلاء المعترضين رقيبًا تحفظ أعمالهم وتحاسبهم عليها، فحسابهم علينا.', 80, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (574, 4, 1, 5, 574, 'ويُظْهر هؤلاء المعرضون، وهم في مجلس رسول الله صلى الله عليه وسلم، طاعتهم للرسول وما جاء به، فإذا ابتعدوا عنه وانصرفوا عن مجلسه، دبَّر جماعة منهم ليلا غير ما أعلنوه من الطاعة، وما علموا أن الله يحصي عليهم ما يدبرون، وسيجازيهم عليه أتم الجزاء، فتول عنهم -أيها الرسول- ولا تبال بهم، فإنهم لن يضروك، وتوكل على الله، وحسبك به وليّاً وناصرًا.', 81, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (575, 4, 1, 5, 575, 'أفلا ينظر هؤلاء في القرآن، وما جاء به من الحق، نظر تأمل وتدبر، حيث جاء على نسق محكم يقطع بأنه من عند الله وحده؟ ولو كان مِن عند غيره لوجدوا فيه اختلافًا كثيرًا.', 82, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (576, 4, 1, 5, 576, 'وإذا جاء هؤلاء الذين لم يستقر الإيمان في قلوبهم أمْرٌ يجب كتمانه متعلقًا بالأمن الذي يعود خيره على الإسلام والمسلمين، أو بالخوف الذي يلقي في قلوبهم عدم الاطمئنان، أفشوه وأذاعوا به في الناس، ولو ردَّ هؤلاء ما جاءهم إلى رسول الله صلى الله عليه وسلم وإلى أهل العلم والفقه لَعَلِمَ حقيقة معناه أهل الاستنباط منهم. ولولا أنْ تَفَضَّلَ الله عليكم ورحمكم لاتبعتم الشيطان ووساوسه إلا قليلا منكم.', 83, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (577, 4, 1, 5, 577, 'فجاهد -أيها النبي- في سبيل الله لإعلاء كلمته، لا تلزم فعل غيرك ولا تؤاخذ به، وحُضَّ المؤمنين على القتال والجهاد، ورغِّبهم فيه، لعل الله يمنع بك وبهم بأس الكافرين وشدتهم. والله تعالى أشد قوة وأعظم عقوبة للكافرين.', 84, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (578, 4, 1, 5, 578, 'من يَسْعَ لحصول غيره على الخير يكن له بشفاعته نصيب من الثواب، ومن يَسْعَ لإيصال الشر إلى غيره يكن له نصيب من الوزر والإثم. وكان الله على كل شيء شاهدًا وحفيظًا.', 85, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (579, 4, 1, 5, 579, 'وإذا سلَّم عليكم المسلم فردُّوا عليه بأفضل مما سلَّم لفظًا وبشاشةً، أو ردوا عليه بمثل ما سلَّم، ولكل ثوابه وجزاؤه. إن الله تعالى كان على كل شيء مجازيًا.', 86, 1, 91, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (580, 4, 1, 5, 580, 'الله وحده المتفرد بالألوهية لجميع الخلق، ليجمعنكم يوم القيامة، الذي لا شك فيه، للحساب والجزاء. ولا أحد أصدق من الله حديثًا فيما أخبر به.', 87, 1, 92, 72, NULL, 36, 9);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (581, 4, 1, 5, 581, 'فما لكم -أيها المؤمنون- في شأن المنافقين إذ اختلفتم فرقتين: فرقة تقول بقتالهم وأخرى لا تقول بذلك؟ والله تعالى قد أوقعهم في الكفر والضلال بسبب سوء أعمالهم. أتودون هداية من صرف الله تعالى قلبه عن دينه؟ ومن خذله الله عن دينه، واتباع ما أمره به، فلا طريق له إلى الهدى.', 88, 1, 92, 73, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (582, 4, 1, 5, 582, 'تمنَّى المنافقون لكم أيها المؤمنون، لو تنكرون حقيقة ما آمنت به قلوبكم، مثلما أنكروه بقلوبهم، فتكونون معهم في الإنكار سواء، فلا تتخذوا منهم أصفياء لكم، حتى يهاجروا في سبيل الله، برهانًا على صدق إيمانهم، فإن أعرضوا عما دعوا إليه، فخذوهم أينما كانوا واقتلوهم، ولا تتخذوا منهم وليّاً من دون الله ولا نصيرًا تستنصرونه به.', 89, 1, 92, 73, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (583, 4, 1, 5, 583, 'لكن الذين يتصلون بقوم بينكم وبينهم عهد وميثاق فلا تقاتلوهم، وكذلك الذين أتَوا إليكم وقد ضاقت صدورهم وكرهوا أن يقاتلوكم، كما كرهوا أن يقاتلوا قومهم، فلم يكونوا معكم ولا مع قومهم، فلا تقاتلوهم، ولو شاء الله تعالى لسلَّطهم عليكم، فلقاتلوكم مع أعدائكم من المشركين، ولكن الله تعالى صرفهم عنكم بفضله وقدرته، فإن تركوكم فلم يقاتلوكم، وانقادوا اليكم مستسلمين، فليس لكم عليهم من طريق لقتالهم.', 90, 1, 92, 73, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (584, 4, 1, 5, 584, 'ستجدون قومًا آخرين من المنافقين يودون الاطمئنان على أنفسهم من جانبكم، فيظهرون لكم الإيمان، ويودون الاطمئنان على أنفسهم من جانب قومهم الكافرين، فيظهرون لهم الكفر، كلما أعيدوا إلى موطن الكفر والكافرين، وقعوا في أسوأ حال. فهؤلاء إن لم ينصرفوا عنكم، ويقدموا إليكم الاستسلام التام، ويمنعوا أنفسهم عن قتالكم فخذوهم بقوة واقتلوهم أينما كانوا، وأولئك الذين بلغوا في هذا المسلك السيِّئ حدّاً يميزهم عمَّن عداهم، فهم الذين جعلنا لكم الحجة البينة على قتلهم وأسرهم.', 91, 1, 92, 73, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (585, 4, 1, 5, 585, 'ولا يحق لمؤمن الاعتداء على أخيه المؤمن وقتله بغير حق، إلا أن يقع منه ذلك على وجه الخطأ الذي لا عمد فيه، ومن وقع منه ذلك الخطأ فعليه عتق رقبة مؤمنة، وتسليم دية مقدرة إلى أوليائه، إلا أن يتصدقوا بها عليه ويعفوا عنه. فإن كان المقتول من قوم كفار أعداء للمؤمنين، وهو مؤمن بالله تعالى، وبما أنزل من الحق على رسوله محمد صلى الله عليه وسلم، فعلى قاتله عتق رقبة مؤمنة، وإن كان من قوم بينكم وبينهم عهد وميثاق، فعلى قاتله دية تسلم إلى أوليائه وعتق رقبة مؤمنة، فمن لم يجد القدرة على عتق رقبة مؤمنة، فعليه صيام شهرين متتابعين؛ ليتوب الله تعالى عليه. وكان الله تعالى عليما بحقيقة شأن عباده، حكيمًا فيما شرعه لهم.', 92, 1, 93, 74, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (586, 4, 1, 5, 586, 'ومن يَعْتَدِ على مؤمن فيقتله عن عمد بغير حق فعاقبته جهنم، خالدًا فيها مع سخط الله تعالى عليه وطَرْدِهِ من رحمته، إن جازاه على ذنبه وأعدَّ الله له أشد العذاب بسبب ما ارتكبه من هذه الجناية العظيمة. ولكنه سبحانه يعفو ويتفضل على أهل الإيمان فلا يجازيهم بالخلود في جهنم.', 93, 1, 93, 74, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (587, 4, 1, 5, 587, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إذا خرجتم في الأرض مجاهدين في سبيل الله فكونوا على بينة مما تأتون وتتركون، ولا تنفوا الإيمان عمن بدا منه شيء من علامات الإسلام ولم يقاتلكم؛ لاحتمال أن يكون مؤمنًا يخفي إيمانه، طالبين بذلك متاع الحياة الدنيا، والله تعالى عنده من الفضل والعطاء ما يغنيكم به، كذلك كنتم في بدء الإسلام تخفون إيمانكم عن قومكم من المشركين فمَنَّ الله عليكم، وأعزَّكم بالإيمان والقوة، فكونوا على بيِّنة ومعرفة في أموركم. إن الله تعالى عليم بكل أعمالكم، مطَّلع على دقائق أموركم، وسيجازيكم عليها.', 94, 1, 93, 74, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (588, 4, 1, 5, 588, 'لا يتساوى المتخلفون عن الجهاد في سبيل الله -غير أصحاب الأعذار منهم- والمجاهدون في سبيل الله، بأموالهم وأنفسهم، فضَّل الله تعالى المجاهدين على القاعدين، ورفع منزلتهم درجة عالية في الجنة، وقد وعد الله كلا من المجاهدين بأموالهم وأنفسهم والقاعدين من أهل الأعذار الجنة لِما بذلوا وضحَّوا في سبيل الحق، وفضَّل الله تعالى المجاهدين على القاعدين ثوابًا جزيلا.', 95, 1, 94, 74, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (589, 4, 1, 5, 589, 'هذا الثواب الجزيل منازل عالية في الجنات من الله تعالى لخاصة عباده المجاهدين في سبيله، ومغفرة لذنوبهم ورحمة واسعة ينعمون فيها. وكان الله غفورًا لمن تاب إليه وأناب، رحيمًا بأهل طاعته، المجاهدين في سبيله.', 96, 1, 94, 74, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (590, 4, 1, 5, 590, 'إن الذين توفَّاهم الملائكة وقد ظلموا أنفسهم بقعودهم في دار الكفر وترك الهجرة، تقول لهم الملائكة توبيخًا لهم: في أي شيء كنتم من أمر دينكم؟ فيقولون: كنا ضعفاء في أرضنا، عاجزين عن دفع الظلم والقهر عنا، فيقولون لهم توبيخا: ألم تكن أرض الله واسعة فتخرجوا من أرضكم إلى أرض أخرى بحيث تأمنون على دينكم؟ فأولئك مثواهم النار، وقبح هذا المرجع والمآب.', 97, 1, 94, 75, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (591, 4, 1, 5, 591, 'ويعذر من ذاك المصير العجزة من الرجال والنساء والصغار الذين لا يقدرون على دفع القهر والظلم عنهم، ولا يعرفون طريقًا يخلصهم مما هم فيه من المعاناة.', 98, 1, 94, 75, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (592, 4, 1, 5, 592, 'فهؤلاء الضعفاء هم الذين يُرجى لهم من الله تعالى العفو؛ لعلمه تعالى بحقيقة أمرهم. وكان الله عفوًا غفورًا.', 99, 1, 94, 75, NULL, 37, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (593, 4, 1, 5, 593, 'ومَن يخرج من أرض الشرك إلى أرض الإسلام فرارًا بدينه، راجيًا فضل ربه، قاصدًا نصرة دينه، يجد في الأرض مكانًا ومتحولا ينعم فيه بما يكون سببًا في قوته وذلة أعدائه، مع السعة في رزقه وعيشه، ومن يخرج من بيته قاصدًا نصرة دين الله ورسوله صلى الله عليه وسلم، وإعلاء كلمة الله، ثم يدركه الموت قبل بلوغه مقصده، فقد ثبت له جزاء عمله على الله، فضلا منه وإحسانًا. وكان الله غفورًا رحيمًا بعباده.', 100, 1, 94, 75, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (594, 4, 1, 5, 594, 'وإذا سافرتم -أيها المؤمنون- في أرض الله، فلا حرج ولا إثم عليكم في قصر الصلاة إن خفتم من عدوان الكفار عليكم في حال صلاتكم، وكانت غالب أسفار المسلمين في بدء الإسلام مخوفة، والقصر رخصة في السفر حال الأمن أو الخوف. إن الكافرين مجاهرون لكم بعداوتهم، فاحذروهم.', 101, 1, 94, 76, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (595, 4, 1, 5, 595, 'وإذا كنت -أيها النبي- في ساحة القتال، فأردت أن تصلي بهم، فلتقم جماعة منهم معك للصلاة، وليأخذوا سلاحهم، فإذا سجد هؤلاء فلتكن الجماعة الأخرى من خلفكم في مواجهة عدوكم، وتتم الجماعة الأولى ركعتهم الثانية ويُسلِّمون، ثم تأتي الجماعة الأخرى التي لم تبدأ الصلاة فليأتموا بك في ركعتهم الأولى، ثم يكملوا بأنفسهم ركعتهم الثانية، وليحذروا مِن عدوهم وليأخذوا أسلحتهم. ودَّ الجاحدون لدين الله أن تغفُلوا عن سلاحكم وزادكم؛ ليحملوا عليكم حملة واحلة فيقضوا عليكم، ولا إثم عليكم حيننذ إن كان بكم أذى من مطر، أو كنتم في حال مرض، أن تتركوا أسلحتكم، مع أخذ الحذر. إن الله تعالى أعدَّ للجاحدين لدينه عذابًا يهينهم، ويخزيهم.', 102, 1, 95, 76, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (596, 4, 1, 5, 596, 'فإذا أدَّيتم الصلاة، فأديموا ذكر الله في جميع أحوالكم، فإذا زال الخوف فأدُّوا الصلاة كاملة، ولا تفرِّطوا فيها فإنها واجبة في أوقات معلومة في الشرع.', 103, 1, 95, 76, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (597, 4, 1, 5, 597, 'ولا تضعفوا في طلب عدوكم وقتاله، إن تكونوا تتألمون من القتال وآثاره، فأعداؤكم كذلك يتألمون منه أشد الألم، ومع ذلك لا يكفون عن قتالكم، فأنتم أولى بذلك منهم، لما ترجونه من الثواب والنصر والتأييد، وهم لا يرجون ذلك. وكان الله عليمًا بكل أحوالكم، حكيمًا في أمره وتدبيره.', 104, 1, 95, 76, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (598, 4, 1, 5, 598, 'إنا أنزلنا إليك -أيها الرسول- القرآن مشتملا على الحق؛ لتفصل بين الناس جميعًا بما أوحى الله إليك، وبَصَّرك به، فلا تكن للذين يخونون أنفسهم -بكتمان الحق- مدافعًا عنهم بما أيدوه لك من القول المخالف للحقيقة.', 105, 1, 95, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (599, 4, 1, 5, 599, 'واطلب من الله تعالى المغفرة في جميع أحوالك، إن الله تعالى كان غفورًا لمن يرجو فضله ونوال مغفرته، رحيمًا به.', 106, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (600, 4, 1, 5, 600, 'ولا تدافع عن الذين يخونون أنفسهم بمعصية الله. إن الله -سبحانه- لا يحب مَن عَظُمَتْ خيانته، وكثر ذنبه.', 107, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (601, 4, 1, 5, 601, 'يستترون من الناس خوفًا من اطلاعهم على أعمالهم السيئة، ولا يستترون من الله تعالى ولا يستحيون منه، وهو عزَّ شأنه معهم بعلمه، مطلع عليهم حين يدبِّرون -ليلا- ما لا يرضى من القول، وكان الله -تعالى- محيطًا بجميع أقوالهم وأفعالهم، لا يخفى عليه منها شيء.', 108, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (602, 4, 1, 5, 602, 'ها أنتم -أيها المؤمنون- قد حاججتم عن هؤلاء الخائنين لأنفسهم في هذه الحياة الدنيا، فمن يحاجج الله تعالى عنهم يوم البعث والحساب؟ ومن ذا الذي يكون على هؤلاء الخائنين وكيلا يوم القيامة؟', 109, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (603, 4, 1, 5, 603, 'ومن يُقْدِمْ على عمل سيِّئ قبيح، أو يظلم نفسه بارتكاب ما يخالف حكم الله وشرعه، ثم يرجع إلى الله نادمًا على ما عمل، راجيًا مغفرته وستر ذنبه، يجد الله تعالى غفورًا له، رحيمًا به.', 110, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (604, 4, 1, 5, 604, 'ومن يعمد إلى ارتكاب ذنب فإنما يضر بذلك نفسه وحدها، وكان الله تعالى عليمًا بحقيقة أمر عباده، حكيمًا فيما يقضي به بين خلقه.', 111, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (605, 4, 1, 5, 605, 'ومن يعمل خطيئة بغير عمد، أو يرتكب ذنبًا متعمدًا ثم يقذف بما ارتكبه نفسًا بريئة لا جناية لها، فقد تحمَّل كذبًا وذنبًا بيّنا.', 112, 1, 96, 77, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (606, 4, 1, 5, 606, 'ولولا أن الله تعالى قد مَنَّ عليك -أيها الرسول- ورحمك بنعمة النبوة، فعصمك بتوفيقه بما أوحى إليك، لعزمت جماعة من الذين يخونون أنفسهم أن يُزِلُّوكَ عن طريق الحق، وما يُزِلُّونَ بذلك إلا أنفسهم، وما يقدرون على إيذائك لعصمة الله لك، وأنزل الله عليك القرآن والسنة المبينة له، وهداك إلى علم ما لم تكن تعلمه مِن قبل، وكان ما خصَّك الله به من فضلٍ أمرًا عظيمًا.', 113, 1, 96, 78, NULL, 38, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (607, 4, 1, 5, 607, 'لا نفع في كثير من كلام الناس سرّاً فيما بينهم، إلا إذا كان حديثًا داعيًا إلى بذل المعروف من الصدقة، أو الكلمة الطيبة، أو التوفيق بين الناس، ومن يفعل تلك الأمور طلبًا لرضا الله تعالى راجيًا ثوابه، فسوف نؤتيه ثوابًا جزيلا واسعًا.', 114, 1, 97, 78, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (608, 4, 1, 5, 608, 'ومن يخالف الرسول صلى الله عليه وسلم من بعد ما ظهر له الحق، ويسلك طريقًا غير طريق المؤمنين، وما هم عليه من الحق، نتركه وما توجَّه إليه، فلا نوفقه للخير، وندخله نار جهنم يقاسي حرَّها، وبئس هذا المرجع والمآل.', 115, 1, 97, 78, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (609, 4, 1, 5, 609, 'إن الله تعالى لا يغفر أن يشرك به، ويغفر ما دون الشرك من الذنوب لمن يشاء من عباده. ومن يجعل لله تعالى الواحد الأحد شريكًا من خلقه، فقد بَعُدَ عن الحق بعدًا كبيرًا.', 116, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (610, 4, 1, 5, 610, 'ما يعبد المشركون من دون الله تعالى إلا أوثانًا لا تنفع ولا تضر، وما يعبدون إلا شيطانًا متمردًا على الله، بلغ في الفساد والإفساد حدّاً كبيرًا.', 117, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (611, 4, 1, 5, 611, 'طرده الله تعالى من رحمته. وقال الشيطان: لأتخذن مِن عبادك جزءًا معلومًا في إغوائهم قولا وعملا.', 118, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (612, 4, 1, 5, 612, 'ولأصرفَنَّ مَن تبعني منهم عن الحق، ولأعِدَنَّهم بالأماني الكاذبة، ولأدعونَّهم إلى تقطيع آذان الأنعام وتشقيقها لما أزينه لهم من الباطل، ولأدعونَّهم إلى تغيير خلق الله في الفطرة، وهيئة ما عليه الخلق. ومن يستجب للشيطان ويتخذه ناصرًا له من دون الله القوي العزيز، فقد هلك هلاكًا بيِّنًا.', 119, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (613, 4, 1, 5, 613, 'يعد الشيطان أتباعه بالوعود الكاذبة، ويغريهم بالأماني الباطلة الخادعة، وما يَعِدهم إلا خديعة لا صحة لها، ولا دليل عليها.', 120, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (614, 4, 1, 5, 614, 'أولئك مآلهم جهنم، ولا يجدون عنها معدلا ولا ملجأً.', 121, 1, 97, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (615, 4, 1, 5, 615, 'والذين صَدَقوا في إيمانهم بالله تعالى، وأتبعوا الإيمان بالأعمال الصالحة سيدخلهم الله -بفضله- جنات تجري من تحت أشجارها الأنهار ماكثين فيها أبدًا، وعدا من الله تعالى الذي لا يخلف وعده. ولا أحد أصدق من الله تعالى في قوله ووعده.', 122, 1, 98, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (616, 4, 1, 5, 616, 'لا يُنال هذا الفضل العظيم بالأماني التي تتمنونها أيها المسلمون، ولا بأماني أهل الكتاب من اليهود والنصارى، وإنما يُنال بالإيمان الصادق بالله تعالى، وإحسان العمل الذي يرضيه. ومن يعمل عملا سيئًا يجز به، ولا يجد له سوى الله تعالى وليّاً يتولى أمره وشأنه، ولا نصيرًا ينصره، ويدفع عنه سوء العذاب.', 123, 1, 98, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (617, 4, 1, 5, 617, 'ومن يعمل من الأعمال الصالحة من ذكر أو أنثى، وهو مؤمن بالله تعالى وبما أنزل من الحق، فأولئك يدخلهم الله الجنة دار النعيم المقيم، ولا يُنْقَصون من ثواب أعمالهم شيئًا، ولو كان مقدار النقرة في ظهر النواة.', 124, 1, 98, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (618, 4, 1, 5, 618, 'لا أحد أحسن دينًا ممن انقاد بقلبه وسائر جوارحه لله تعالى وحده، وهو محسن، واتبع دين إبراهيم وشرعه، مائلا عن العقائد الفاسدة والشرائع الباطلة. وقد اصطفى الله إبراهيم -عليه الصلاة والسلام- واتخذه صفيّاً من بين سائر خلقه. وفي هذه الآية، إثبات صفة الخُلّة لله -تعالى- وهي أعلى مقامات المحبة، والاصطفاء.', 125, 1, 98, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (619, 4, 1, 5, 619, 'ولله جميع ما في هذا الكون من المخلوقات، فهي ملك له تعالى وحده. وكان الله تعالى بكل شيء محيطًا، لا يخفى عليه شيء من أمور خلقه.', 126, 1, 98, 79, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (620, 4, 1, 5, 620, 'يطلب الناس منك -أيها النبي- أن تبين لهم ما أشكل عليهم فَهْمُه من قضايا النساء وأحكامهن، قل الله تعالى يبيِّن لكم أمورهن، وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تعطونهن ما فرض الله تعالى لهن من المهر والميراث وغير ذلك من الحقوق، وتحبون نكاحهن أو ترغبون عن نكاحهن، ويبيِّن الله لكم أمر الضعفاء من الصغار، ووجوب القيام لليتامى بالعدل وترك الجور عليهم في حقوقهم. وما تفعلوا من خير فإن الله تعالى كان به عليمًا، لا يخفى عليه شيء منه ولا من غيره.', 127, 1, 98, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (621, 4, 1, 5, 621, 'وإن علمت امرأة من زوجها ترفعًا عنها، وتعاليًا عليها أو انصرافًا عنها فلا إثم عليهما أن يتصالحا على ما تطيب به نفوسهما من القسمة أو النفقة، والصلح أولى وأفضل. وجبلت النفوس على الشح والبخل. وإن تحسنوا معاملة زوجاتكم وتخافوا الله فيهن، فإن الله كان بما تعملون من ذلك وغيره عالمًا لا يخفى عليه شيء، وسيجازيكم على ذلك.', 128, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (622, 4, 1, 5, 622, 'ولن تقدروا -أيها الرجال- على تحقيق العدل التام بين النساء في المحبة وميل القلب، مهما بذلتم في ذلك من الجهد، فلا تعرضوا عن المرغوب عنها كل الإعراض، فتتركوها كالمرأة التي ليست بذات زوج ولا هي مطلقة فتأثموا. وإن تصلحوا أعمالكم فتعدلوا في قَسْمكم بين زوجاتكم، وتراقبوا الله تعالى وتخشوه فيهن، فإن الله تعالى كان غفورًا لعباده، رحيمًا بهم.', 129, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (623, 4, 1, 5, 623, 'وإن وقعت الفرقة بين الرجل وامرأته، فإن الله تعالى يغني كلا منهما من فضله وسعته؛ فإنه سبحانه وتعالى واسع الفضل والمنة، حكيم فيما يقضي به بين عباده.', 130, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (624, 4, 1, 5, 624, 'ولله ملك ما في السموات وما في الأرض وما بينهما. ولقد عهدنا إلى الذين أُعطوا الكتاب من قبلكم من اليهود والنصارى، وعهدنا إليكم كذلك -يا أمة محمد- بتقوى الله تعالى، والقيام بأمره واجتناب نهيه، وبيَّنَّا لكم أنكم إن تجحدوا وحدانية الله تعالى وشرعه فإنه سبحانه غني عنكم؛ لأن له جميع ما في السموات والأرض. وكان الله غنيّاً عن خلقه، حميدًا في صفاته وأفعاله.', 131, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (625, 4, 1, 5, 625, 'ولله ملك ما في هذا الكون من الكائنات، وكفى به سبحانه قائمًا بشؤون خلقه حافظًا لها.', 132, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (626, 4, 1, 5, 626, 'إن يشأ الله يُهلكُّم أيها الناس، ويأت بقوم آخرين غيركم. وكان الله على ذلك قديرًا.', 133, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (627, 4, 1, 5, 627, 'من يرغب منكم -أيها الناس- في ثواب الدنيا ويعرض عن الآخرة، فعند الله وحده ثواب الدنيا والآخرة، فليطلب من الله وحده خيري الدنيا والآخرة، فهو الذي يملكهما. وكان الله سميعًا لأقوال عباده، بصيرًا بأعمالهم ونياتهم، وسيجازيهم على ذلك.', 134, 1, 99, 80, NULL, 39, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (628, 4, 1, 5, 628, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، كونوا قائمين بالعدل، مؤدين للشهادة لوجه الله تعالى، ولو كانت على أنفسكم، أو على آبائكم وأمهاتكم، أو على أقاربكم، مهما كان شأن المشهود عليه غنيًّا أو فقيرًا؛ فإن الله تعالى أولى بهما منكم، وأعلم بما فيه صلاحهما، فلا يحملنَّكم الهوى والتعصب على ترك العدل، وإن تحرفوا الشهادة بألسنتكم فتأتوا بها على غير حقيقتها، أو تعرضوا عنها بترك أدائها أو بكتمانها، فإن الله تعالى كان عليمًا بدقائق أعمالكم، وسيجازيكم بها.', 135, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (629, 4, 1, 5, 629, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه داوموا على ما أنتم عليه من التصديق الجازم بالله تعالى وبرسوله محمد صلى الله عليه وسلم، ومن طاعتهما، وبالقرآن الذي نزله عليه، وبجميع الكتب التي أنزلها الله على الرسل. ومن يكفر بالله تعالى، وملائكته المكرمين، وكتبه التي أنزلها لهداية خلقه، ورسله الذين اصطفاهم لتبليغ رسالته، واليوم الآخر الذي يقوم الناس فيه بعد موتهم للعرض والحساب، فقد خرج من الدين، وبَعُدَ بعدًا كبيرًا عن طريق الحق.', 136, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (630, 4, 1, 5, 630, 'إن الذين دخلوا في الإيمان، ثم رجعوا عنه إلى الكفر، ثم عادوا إلى الإيمان، ثم رجعوا إلى الكفر مرة أخرى، ثم أصرُّوا على كفرهم واستمروا عليه، لم يكن الله ليغفر لهم، ولا ليدلهم على طريق من طرق الهداية، التي ينجون بها من سوء العاقبة.', 137, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (631, 4, 1, 5, 631, 'بشّر -أيها الرسول- المنافقين -وهم الذين يظهرون الإيمان ويبطنون الكفر- بأن لهم عذابًا موجعًا.', 138, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (632, 4, 1, 5, 632, 'الذين يوالون الكافرين، ويتخذونهم أعوانًا لهم، ويتركون ولاية المؤمنين، ولا يرغبون في مودتهم. أيطلبون بذلك النصرة والمنعة عند الكافرين؟ إنهم لا يملكون ذلك، فالنصرة والعزة والقوة جميعها لله تعالى وحده.', 139, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (633, 4, 1, 5, 633, 'وقد نزل عليكم -أيها المؤمنون- في كتاب ربكم أنه إذا سمعتم الكفر بآيات الله والاستهزاء بها فلا تجلسوا مع الكافرين والمستهزئين، إلا إذا أخذوا في حديث غير حديث الكفر والاستهزاء بآيات الله. إنكم إذا جالستموهم، وهم على ما هم عليه، فأنتم مثلهم؛ لأنكم رضيتم بكفرهم واستهزائهم، والراضي بالمعصية كالفاعل لها. إن الله تعالى جامع المنافقين والكافرين في نار جهنم جميعًا، يلْقَون فيها سوء العذاب.', 140, 1, 100, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (634, 4, 1, 5, 634, 'المنافقون هم الذين ينتظرون ما يحلُّ بكم -أيها المؤمنون- من الفتن والحرب، فإن منَّ الله عليكم بفضله، ونصركم على عدوكم وغنمتم، قالوا لكم: ألم نكن معكم نؤازركم؟ وإن كان للجاحدين لهذا الدين قَدْرٌ من النصر والغنيمة، قالوا لهم: ألم نساعدكم بما قدَّمناه لكم ونَحْمِكُم من المؤمنين؟ فالله تعالى يقضي بينكم وبينهم يوم القيامة، ولن يجعل الله للكافرين طريقًا للغلبة على عباده الصالحين، فالعاقبة للمتقين في الدنيا والآخرة.', 141, 1, 101, 81, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (635, 4, 1, 5, 635, 'إنَّ طريقة هؤلاء المنافقين مخادعة الله تعالى، بما يظهرونه من الإيمان وما يبطنونه من الكفر، ظنًّا أنه يخفى على الله، والحال أن الله خادعهم ومجازيهم بمثل عملهم، وإذا قام هؤلاء المنافقون لأداء الصلاة، قاموا إليها في فتور، يقصدون بصلاتهم الرياء والسمعة، ولا يذكرون الله تعالى إلا ذكرًا قليلا.', 142, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (636, 4, 1, 5, 636, 'إنَّ مِن شأن هؤلاء المنافقين التردد والحَيْرة والاضطراب، لا يستقرون على حال، فلا هم مع المؤمنين ولا هم مع الكافرين. ومن يصرف الله قلبه عن الإيمان به والاستمساك بهديه، فلن تجد له طريقًا إلى الهداية واليقين.', 143, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (637, 4, 1, 5, 637, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا توالوا الجاحدين لدين الله، وتتركوا موالاة المؤمنين ومودتهم. أتريدون بمودَّة أعدائكم أن تجعلوا لله تعالى عليكم حجة ظاهرة على عدم صدقكم في إيمانكم؟', 144, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (638, 4, 1, 5, 638, 'إن المنافقين في أسفل منازل النار يوم القيامة، ولن تجد لهم -أيها الرسول- ناصرًا يدفع عنهم سوء هذا المصير.', 145, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (639, 4, 1, 5, 639, 'إلا الذين رجعوا إلى الله تعالى وتابوا إليه، وأصلحوا ما أفسدوا من أحوالهم باطنًا وظاهرًا، ووالوا عباده المؤمنين، واستمسكوا بدين الله، وأخلصوا له سبحانه، فأولئك مع المؤمنين في الدنيا والآخرة، وسوف يعطي الله المؤمنين ثوابًا عظيمًا.', 146, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (640, 4, 1, 5, 640, 'ما يفعل الله بعذابكم إن أصلحتم العمل وآمنتم بالله ورسوله، فإن الله سبحانه غني عمَّن سواه، وإنما يعذب العباد بذنوبهم. وكان الله شاكرًا لعباده على طاعتهم له، عليمًا بكل شيء.', 147, 1, 101, 82, NULL, 40, 10);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (641, 4, 1, 6, 641, 'لا يُحِبُّ الله أن يَجهر أحدٌ بقول السوء، لكن يُباح للمظلوم أن يَذكُر ظالمه بما فيه من السوء؛ ليبيِّن مَظْلمته. وكان الله سميعًا لما تجهرون به، عليمًا بما تخفون من ذلك.', 148, 1, 102, 82, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (642, 4, 1, 6, 642, 'نَدَب الله تعالى إلى العفو، ومهَّد له بأنَّ المؤمن: إمَّا أن يُظهر الخير، وإمَّا أن يُخفيه، وكذلك مع الإساءة: إما أن يظهرها في حال الانتصاف من المسيء، وإما أن يعفو ويصفح، والعفوُ أفضلُ؛ فإن من صفاته تعالى العفو عن عباده مع قدرته عليهم.', 149, 1, 102, 82, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (643, 4, 1, 6, 643, 'إن الذين يكفرون بالله ورسله من اليهود والنصارى، ويريدون أن يفرقوا بين الله ورسله بأن يؤمنوا بالله ويكذبوا رسله الذين أرسلهم إلى خلقه، أو يعترفوا بصدق بعض الرسل دون بعض، ويزعموا أنَّ بعضهم افتروا على ربِّهم، ويريدون أن يتخذوا طريقًا إلى الضلالة التي أحدثوها والبدعة التي ابتدعوها.', 150, 1, 102, 82, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (644, 4, 1, 6, 644, 'أولئك هم أهل الكفر المحقَّق الذي لا شك فيه، وأعتدنا للكافرين عذابًا يخزيهم ويهينهم.', 151, 1, 102, 82, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (645, 4, 1, 6, 645, 'والذين صَدَّقوا بوحدانية الله، وأقرُّوا بنبوَّة رسله أجمعين، ولم يفرقوا بين أحد منهم، وعملوا بشريعة الله، أولئك سوف يعطيهم جزاءهم وثوابهم على إيمانهم به وبرسله. وكان الله غفورًا رحيمًا.', 152, 1, 102, 82, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (646, 4, 1, 6, 646, 'يسألك اليهود -أيها الرسول- معجزة مثل معجزة موسى تشهد لك بالصدق: بأن تنزل عليهم صُحُفًا من الله مكتوبةً، مثل مجيء موسى بالألواح من عند الله، فلا تعجب -أيها الرسول- فقد سأل أسلافهم موسى -عليه السلام- ما هو أعظم: سألوه أن يريهم الله علانيةً، فَصُعِقوا بسبب ظلمهم أنفسهم حين سألوا أمرًا ليس من حقِّهم. وبعد أن أحياهم الله بعد الصعق، وشاهدوا الآيات البينات على يد موسى القاطعة بنفي الشرك، عبدوا العجل من دون الله، فعَفونا عن عبادتهم العجل بسبب توبتهم، وآتينا موسى حجة عظيمة تؤيِّد صِدق نُبُوَّتِه.', 153, 1, 102, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (647, 4, 1, 6, 647, 'ورفعنا فوق رؤوسهم جبل الطور حين امتنعوا عن الالتزام بالعهد المؤكد الذي أعطوه بالعمل بأحكام التوراة، وأمرناهم أن يدخلوا باب "بيت المقدس" سُجَّدًا، فدخلوا يزحفون على أستاههم، وأمرناهم ألا يَعْتَدُوا بالصيد في يوم السبت فاعتدَوا، وصادوا، وأخذنا عليهم عهدًا مؤكدًا، فنقضوه.', 154, 1, 102, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (648, 4, 1, 6, 648, 'فلعنَّاهم بسبب نقضهم للعهود، وكفرهم بآيات الله الدالة على صدق رسله، وقتلهم للأنبياء ظلمًا واعتداءً، وقولهم: قلوبنا عليها أغطية فلا تفقه ما تقول، بل طمس الله عليها بسبب كفرهم، فلا يؤمنون إلا إيمانًا قليلا لا ينفعهم.', 155, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (649, 4, 1, 6, 649, 'وكذلك لعنَّاهم بسبب كفرهم وافترائهم على مريم بما نسبوه إليها من الزنى، وهي بريئة منه.', 156, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (650, 4, 1, 6, 650, 'وبسبب قولهم -على سبيل التهكم والاستهزاء-: هذا الذي يدعي لنفسه هذا المنصب (قتلناه)، وما قتلوا عيسى وما صلبوه، بل صلبوا رجلا شبيهًا به ظنًّا منهم أنه عيسى. ومن ادَّعى قَتْلَهُ من اليهود، ومن أسلمه إليهم من النصارى، كلهم واقعون في شك وحَيْرَة، لا عِلْمَ لديهم إلا اتباع الظن، وما قتلوه متيقنين بل شاكين متوهمين.', 157, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (651, 4, 1, 6, 651, 'بل رفع الله عيسى إليه ببدنه وروحه حيًّا، وطهَّره من الذين كفروا. وكان الله عزيزًا في ملكه، حكيمًا في تدبيره وقضائه.', 158, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (652, 4, 1, 6, 652, 'وإنه لا يبقى أحدٌ من أهل الكتاب بعد نزول عيسى آخر الزمان إلا آمن به قبل موته عليه السلام، ويوم القيامة يكون عيسى -عليه السلام- شهيدًا بتكذيب مَن كذَّبه، وتصديق مَن صدَّقه.', 159, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (653, 4, 1, 6, 653, 'فبسبب ظلم اليهود بما ارتكبوه من الذنوب العظيمة حَرَّم الله عليهم طيبات من المأكل كانت حلالا لهم، وبسبب صدِّهم أنفسهم وغيرهم عن دين الله القويم.', 160, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (654, 4, 1, 6, 654, 'وبسبب تناولهم الربا الذي نهوا عنه، واستحلالهم أموال الناس بغير استحقاق، وأعتدنا للكافرين بالله ورسوله مِن هؤلاء اليهود عذابًا موجعًا في الآخرة.', 161, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (655, 4, 1, 6, 655, 'لكنِ المتمكنون في العلم بأحكام الله من اليهود، والمؤمنون بالله ورسوله، يؤمنون بالذي أنزله الله إليك -أيها الرسول- وهو القرآن، وبالذي أنزل إلى الرسل من قبلك كالتوراة والإنجيل، ويؤدُّون الصلاة في أوقاتها، ويخرجون زكاة أموالهم، ويؤمنون بالله وبالبعث والجزاء، أولئك سيعطيهم الله ثوابًا عظيمًا، وهو الجنة.', 162, 1, 103, 83, NULL, 41, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (656, 4, 1, 6, 656, 'إنا أوحينا اليك -أيها الرسول- بتبليغ الرسالة كما أوحينا إلى نوح والنبيين من بعده، وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط -وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة من ولد يعقوب- وعيسى وأيوب ويونس وهارون وسليمان. وآتينا داود زبورًا، وهو كتاب وصحف مكتوبة.', 163, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (657, 4, 1, 6, 657, 'وأرسلنا رسلا قد قصصناهم عليك في القرآن من قبل هذه الآية، ورسلا لم نقصصهم عليك لحكمة أردناها. وكلم الله موسى تكليمًا؛ تشريفًا له بهذه الصفة. وفي هذه الآية الكريمة، إثبات صفة الكلام لله -تعالى- كما يليق بجلاله، وأنه سبحانه كلم نبيه موسى -عليه السلام- حقيقة بلا وساطة.', 164, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (658, 4, 1, 6, 658, 'أرسَلْتُ رسلا إلى خَلْقي مُبشِّرين بثوابي، ومنذرين بعقابي؛ لئلا يكون للبشر حجة يعتذرون بها بعد إرسال الرسل. وكان الله عزيزًا في ملكه، حكيمًا في تدبيره.', 165, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (659, 4, 1, 6, 659, 'إن يكفر بك اليهود وغيرهم -أيها الرسول- فالله يشهد لك بأنك رسوله الذي أَنْزَلَ عليه القرآن العظيم، أنزله بعلمه، وكذلك الملائكة يشهدون بصدق ما أوحي إليك، وشهادة الله وحدها كافية.', 166, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (660, 4, 1, 6, 660, 'إن الذين جحدوا نُبُوَّتك، وصدوا الناس عن الإسلام، قد بَعُدوا عن طريق الحق بُعْدًا شديدًا.', 167, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (661, 4, 1, 6, 661, 'إن الذين كفروا بالله وبرسوله، وظلموا باستمرارهم على الكفر، لم يكن الله ليغفر ذنوبهم، ولا ليدلهم على طريق ينجيهم.', 168, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (662, 4, 1, 6, 662, 'إلا طريق جهنم ماكثين فيها أبدًا، وكان ذلك على الله يسيرًا، فلا يعجزه شيء.', 169, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (663, 4, 1, 6, 663, 'يا أيها الناس قد جاءكم رسولنا محمد صلى الله عليه وسلم بالإسلام دين الحق من ربكم، فَصَدِّقوه واتبعوه، فإن الإيمان به خيرلكم، وإن تُصرُّوا على كفركم فإن الله غني عنكم وعن إيمانكم؛ لأنه مالك ما في السموات والأرض. وكان الله عليمًا بأقوالكم وأفعالكم، حكيمًا في تشريعه وأمره. فإذا كانت السموات والأرض قد خضعتا لله تعالى كونًا وقدرًا خضوع سائر ملكه، فأولى بكم أن تؤمنوا بالله وبرسوله محمد صلى الله عليه وسلم، وبالقرآن الذي أنزله عليه، وأن تنقادوا لذلك شرعًا حتى يكون الكون كلُّه خاضعًا لله قدرًا وشرعًا. وفي الآية دليل على عموم رسالة نبي الله ورسوله محمد صلى الله عليه وسلم.', 170, 1, 104, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (664, 4, 1, 6, 664, 'يا أهل الإنجيل لا تتجاوزوا الاعتقاد الحق في دينكم، ولا تقولوا على الله إلا الحق، فلا تجعلوا له صاحبةً ولا ولدًا. إنما المسيح عيسى ابن مريم رسول الله أرسله الله بالحق، وخَلَقَه بالكلمة التي أرسل بها جبريل إلى مريم، وهي قوله: "كن"، فكان، وهي نفخة من الله تعالى نفخها جبريل بأمر ربه، فَصدِّقوا بأن الله واحد وأسلموا له، وصدِّقوا رسله فيما جاؤوكم به من عند الله واعملوا به، ولا تجعلوا عيسى وأمه مع الله شريكين. انتهوا عن هذه المقالة خيرًا لكم مما أنتم عليه، إنما الله إله واحد سبحانه. ما في السموات والأرض مُلْكُه، فكيف يكون له منهم صاحبة أو ولد؟ وكفى بالله وكيلا على تدبير خلقه وتصريف معاشهم، فتوكَّلوا عليه وحده فهو كافيكم.', 171, 1, 105, 84, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (665, 4, 1, 6, 665, 'لن يَأْنف ولن يمتنع المسيح أن يكون عبدًا لله، وكذلك لن يأنَفَ الملائكة المُقَرَّبون من الإقرار بالعبودية لله تعالى. ومن يأنف عن الانقياد والخضوع ويستكبر فسيحشرهم كلهم إليه يوم القيامة، ويفصلُ بينهم بحكمه العادل، ويجازي كلا بما يستحق.', 172, 1, 105, 85, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (666, 4, 1, 6, 666, 'فأمَّا الذين صَدَّقوا بالله اعتقادًا وقولا وعملا واستقاموا على شريعته فيوفيهم ثواب أعمالهم، ويزيدُهم من فضله، وأما الذين امتنعوا عن طاعة الله، واستكبروا عن التذلل له فيعذبهم عذابًا موجعًا، ولا يجدون لهم وليًّا ينجيهم من عذابه، ولا ناصرًا ينصرهم من دون الله.', 173, 1, 105, 85, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (667, 4, 1, 6, 667, 'يا أيها الناس قد جاءكم برهان من ربكم، وهو رسولنا محمد، وما جاء به من البينات والحجج القاطعة، وأعظمها القرآن الكريم، مما يشهد بصدق نبوته ورسالته الخاتمة، وأنزلنا إليكم القرآن هدًى ونورًا مبينًا.', 174, 1, 105, 85, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (668, 4, 1, 6, 668, 'فأمَّا الذين صدَّقوا بالله اعتقادًا وقولا وعملا واستمسكوا بالنور الذي أُنزل إليهم، فسيدخلهم الجنة رحمة منه وفضلا ويوفقهم إلى سلوك الطريق المستقيم المفضي إلى روضات الجنات.', 175, 1, 105, 85, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (669, 4, 1, 6, 669, 'يسألونك -أيها الرسول- عن حكم ميراث الكلالة، وهو من مات وليس له ولدٌ ولا والد، قل: الله يُبيِّن لكم الحكم فيها: إن مات امرؤ ليس له ولد ولا والد، وله أخت لأبيه وأمه، أو لأبيه فقط، فلها نصف تركته، ويرث أخوها شقيقًا كان أو لأب جميع مالها إذا ماتت وليس لها ولد ولا والد. فإن كان لمن مات كلالةً أختان فلهما الثلثان مما ترك. وإذا اجتمع الذكور من الإخوة لغير أم مع الإناث فللذكر مثل نصيب الأنثيين من أخواته. يُبيِّن الله لكم قسمة المواريث وحكم الكلالة، لئلا تضلوا عن الحقِّ في أمر المواريث. والله عالم بعواقب الأمور، وما فيها من الخير لعباده.', 176, 1, 106, 85, NULL, 42, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (670, 5, 1, 6, 670, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، أتِمُّوا عهود الله الموثقة، من الإيمان بشرائع الدين، والانقياد لها، وأَدُّوا العهود لبعضكم على بعض من الأمانات، والبيوع وغيرها، مما لم يخالف كتاب الله، وسنة رسوله محمد صلى الله عليه وسلم. وقد أحَلَّ الله لكم البهيمة من الأنعام، وهي الإبلُ والبقر والغنم، إلا ما بيَّنه لكم من تحريم الميتة والدم وغير ذلك، ومن تحريم الصيد وأنتم محرمون. إن الله يحكم ما يشاء وَفْق حكمته وعدله.', 1, 2, 106, 86, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (671, 5, 1, 6, 671, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تتعدَّوا حدود الله ومعالمه، ولا تستحِلُّوا القتال في الأشهر الحرم، وهي: ذو القعدة وذو الحجة والمحرم ورجب، وكان ذلك في صدر الإسلام، ولا تستحِلُّوا حرمة الهَدْي، ولا ما قُلِّدَ منه؛ إذ كانوا يضعون القلائد، وهي ضفائر من صوف أو وَبَر في الرقاب علامةً على أن البهيمة هَدْيٌ وأن الرجل يريد الحج، ولا تَسْتَحِلُّوا قتال قاصدي البيت الحرام الذين يبتغون من فضل الله ما يصلح معايشهم ويرضي ربهم. وإذا حللتم من إحرامكم حلَّ لكم الصيد، ولا يحمِلَنَّكم بُغْض قوم من أجل أن منعوكم من الوصول إلى المسجد الحرام -كما حدث عام "الحديبية"- على ترك العدل فيهم. وتعاونوا -أيها المؤمنون فيما بينكم- على فِعْل الخير، وتقوى الله، ولا تعاونوا على ما فيه إثم ومعصية وتجاوز لحدود الله، واحذروا مخالفة أمر الله فإنه شديد العقاب.', 2, 2, 106, 86, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (672, 5, 1, 6, 672, 'حرَّم الله عليكم الميتة، وهي الحيوان الذي تفارقه الحياة بدون ذكاة، وحرَّم عليكم الدم السائل المُراق، ولحم الخنزير، وما ذُكِر عليه غير اسم الله عند الذبح، والمنخنقة التي حُبِس نَفَسُها حتى ماتت، والموقوذة وهي التي ضُربت بعصا أو حجر حتى ماتت، والمُتَرَدِّية وهي التي سقطت من مكان عال أو هَوَت في بئر فماتت، والنطيحة وهي التي ضَرَبَتْها أخرى بقرنها فماتت، وحرَّم الله عليكم البهيمة التي أكلها السبُع، كالأسد والنمر والذئب، ونحو ذلك. واستثنى -سبحانه- مما حرَّمه من المنخنقة وما بعدها ما أدركتم ذكاته قبل أن يموت فهو حلال لكم، وحرَّم الله عليكم ما ذُبِح لغير الله على ما يُنصب للعبادة من حجر أو غيره، وحرَّم الله عليكم أن تطلبوا عِلْم ما قُسِم لكم أو لم يقسم بالأزلام، وهي القداح التي كانوا يستقسمون بها إذا أرادوا أمرًا قبل أن يقدموا عليه. ذلكم المذكور في الآية من المحرمات -إذا ارتُكبت- خروج عن أمر الله وطاعته إلى معصيته. الآن انقطع طمع الكفار من دينكم أن ترتدوا عنه إلى الشرك بعد أن نصَرْتُكم عليهم، فلا تخافوهم وخافوني. اليوم أكملت لكم دينكم دين الإسلام بتحقيق النصر وإتمام الشريعة، وأتممت عليكم نعمتي بإخراجكم من ظلمات الجاهلية إلى نور الإيمان، ورضيت لكم الإسلام دينًا فالزموه، ولا تفارقوه. فمن اضطرَّ في مجاعة إلى أكل الميتة، وكان غير مائل عمدًا لإثم، فله تناوله، فإن الله غفور له، رحيم به.', 3, 2, 107, 86, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (673, 5, 1, 6, 673, 'يسألك أصحابك -أيها النبي-: ماذا أُحِلَّ لهم أَكْلُه؟ قل لهم: أُحِلَّ لكم الطيبات وصيدُ ما دَرَّبتموه من ذوات المخالب والأنياب من الكلاب والفهود والصقور ونحوها مما يُعَلَّم، تعلمونهن طلب الصيد لكم، مما علمكم الله، فكلوا مما أمسكن لكم، واذكروا اسم الله عند إرسالها للصيد، وخافوا الله فيما أمركم به وفيما نهاكم عنه. إن الله سريع الحساب.', 4, 2, 107, 86, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (674, 5, 1, 6, 674, 'ومن تمام نعمة الله عليكم اليوم -أيها المؤمنون- أن أَحَلَّ لكم الحلال الطيب، وذبائحُ اليهود والنصارى -إن ذكَّوها حَسَبَ شرعهم- حلال لكم وذبائحكم حلال لهم. وأَحَلَّ لكم -أيها المؤمنون- نكاح المحصنات، وهُنَّ الحرائر من النساء المؤمنات، العفيفات عن الزنى، وكذلك نكاحَ الحرائر العفيفات من اليهود والنصارى إذا أعطيتموهُنَّ مهورهن، وكنتم أعِفَّاء غير مرتكبين للزنى، ولا متخذي عشيقات، وأمِنتم من التأثر بدينهن. ومن يجحد شرائع الإيمان فقد بطل عمله، وهو يوم القيامة من الخاسرين.', 5, 2, 107, 86, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (675, 5, 1, 6, 675, 'يا أيها الذين آمنوا إذا أردتم القيام إلى الصلاة، وأنتم على غير طهارة فاغسلوا وجوهكم وأيديكم مع المرافق (والمِرْفَق: المِفْصَل الذي بين الذراع والعَضُد) وامسحوا رؤوسكم، واغسلوا أرجلكم مع الكعبين (وهما: العظمان البارزان عند ملتقى الساق بالقدم). وإن أصابكم الحدث الأكبر فتطهروا بالاغتسال منه قبل الصلاة. فإن كنتم مرضى، أو على سفر في حال الصحة، أو قضى أحدكم حاجته، أو جامع زوجته فلم تجدوا ماء فاضربوا بأيديكم وجه الأرض، وامسحوا وجوهكم وأيديكم منه. ما يريد الله في أمر الطهارة أن يُضَيِّق عليكم، بل أباح التيمم توسعةً عليكم، ورحمة بكم، إذ جعله بديلا للماء في الطهارة، فكانت رخصة التيمُّم من تمام النعم التي تقتضي شكر المنعم؛ بطاعته فيما أمر وفيما نهى.', 6, 2, 108, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (676, 5, 1, 6, 676, 'واذكروا نعمة الله عليكم فيما شَرَعه لكم، واذكروا عهده الذي أخذه تعالى عليكم من الإيمان بالله ورسوله محمد صلى الله عليه وسلم، والسمع والطاعة لهما، واتقوا الله فيما أمركم به ونهاكم عنه. إن الله عليمٌ بما تُسِرُّونه في نفوسكم.', 7, 2, 108, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (677, 5, 1, 6, 677, 'يا أيها الذين آمَنوا بالله ورسوله محمد صلى الله عليه وسلم كونوا قوَّامين بالحق، ابتغاء وجه الله، شُهداء بالعدل، ولا يحملنكم بُغْضُ قوم على ألا تعدلوا، اعدِلوا بين الأعداء والأحباب على درجة سواء، فذلك العدل أقرب لخشية الله، واحذروا أن تجوروا. إن الله خبير بما تعملون، وسيجازيكم به.', 8, 2, 108, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (678, 5, 1, 6, 678, 'وعد الله الذين صدَّقوا الله ورسوله وعملوا الصالحات أن يغفر لهم ذنوبهم، وأن يثيبهم على ذلك الجنة، والله لا يخلف وعده.', 9, 2, 108, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (679, 5, 1, 6, 679, 'والذين جحدوا وحدانية الله الدالة على الحق المبين، وكذَّبوا بأدلته التي جاءت بها الرسل، هم أهل النار الملازمون لها.', 10, 2, 109, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (680, 5, 1, 6, 680, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اذكروا ما أنعم الله به عليكم من نعمة الأمنِ، وإلقاءِ الرعب في قلوب أعدائكم الذين أرادوا أن يبطشوا بكم، فصرفهم الله عنكم، وحال بينهم وبين ما أرادوه بكم، واتقوا الله واحذروه، وتوكلوا على الله وحده في أموركم الدينية والدنيوية، وثِقوا بعونه ونصره.', 11, 2, 109, 87, NULL, 43, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (681, 5, 1, 6, 681, 'ولقد أخذ الله العهد المؤكَّد على بني إسرائيل أن يخلصوا له العبادة وحده، وأمر الله موسى أن يجعل عليهم اثني عشر عريفًا بعدد فروعهم، يأخذون عليهم العهد بالسمع والطاعة لله ولرسوله ولكتابه، وقال الله لبني إسرائيل: إني معكم بحفظي ونصري، لئن أقمتم الصلاة، وأعطيتم الزكاة المفروضة مستحقيها، وصدَّقتم برسلي فيما أخبروكم به ونصرتموهم، وأنفقتم في سبيلي، لأكفِّرنَّ عنكم سيئاتكم، ولأدْخِلَنَّكُم جناتٍ تجري من تحت قصورها الأنهار، فمن جحد هذا الميثاق منكم فقد عدل عن طريق الحق إلى طريق الضلال.', 12, 2, 109, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (682, 5, 1, 6, 682, 'فبسبب نقض هؤلاء اليهود لعهودهم المؤكَّدة طردناهم من رحمتنا، وجعلنا قلوبهم غليظة لا تلين للإيمان، يبدلون كلام الله الذي أنزله على موسى، وهو التوراة، وتركوا نصيبًا مما ذُكِّروا به، فلم يعملوا به. ولا تزال -أيها الرسول- تجد من اليهود خيانةً وغَدرًا، فهم على منهاج أسلافهم إلا قليلا منهم، فاعف عن سوء معاملتهم لك، واصفح عنهم، فإن الله يحب مَن أحسن العفو والصفح إلى من أساء إليه. (وهكذا يجد أهل الزيغ سبيلا إلى مقاصدهم السيئة بتحريف كلام الله وتأويله على غير وجهه، فإن عجَزوا عن التحريف والتأويل تركوا ما لا يتفق مع أهوائهم مِن شرع الله الذي لا يثبت عليه إلا القليل ممن عصمه الله منهم).', 13, 2, 109, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (683, 5, 1, 6, 683, 'وأخذنا على الذين ادَّعوا أنهم أتباع المسيح عيسى -وليسوا كذلك- العهد المؤكد الذي أخذناه على بني إسرائيل: بأن يُتابعوا رسولهم وينصروه ويؤازروه، فبدَّلوا دينهم، وتركوا نصيبًا مما ذكروا به، فلم يعملوا به، كما صنع اليهود، فألقينا بينهم العداوة والبغضاء إلى يوم القيامة، وسوف ينبئهم الله بما كانوا يصنعون يوم الحساب، وسيعاقبهم على صنيعهم.', 14, 2, 110, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (684, 5, 1, 6, 684, 'يا أهل الكتاب من اليهود والنصارى، قد جاءكم رسولنا محمد صلى الله عليه وسلم يبيِّن لكم كثيرًا مما كنتم تُخْفونه عن الناس مما في التوراة والإنجيل، ويترك بيان ما لا تقتضيه الحكمة. قد جاءكم من الله نور وكتاب مبين: وهو القرآن الكريم.', 15, 2, 110, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (685, 5, 1, 6, 685, 'يهدي الله بهذا الكتاب المبين من اتبع رضا الله تعالى، طرق الأمن والسلامة، ويخرجهم بإذنه من ظلمات الكفر إلى نور الإيمان، ويوفقهم إلى دينه القويم.', 16, 2, 110, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (686, 5, 1, 6, 686, 'لقد كفر النصارى القائلون بأن الله هو المسيح ابن مريم، قل -أيها الرسول- لهؤلاء الجهلة من النصارى: لو كان المسيح إلهًا كما يدَّعون لقَدرَ أن يدفع قضاء الله إذا جاءه بإهلاكه وإهلاك أُمِّه ومَن في الأرض جميعًا، وقد ماتت أم عيسى فلم يدفع عنها الموت، كذلك لا يستطيع أن يدفع عن نفسه؛ لأنهما عبدان من عباد الله لا يقدران على دفع الهلاك عنهما، فهذا دليلٌ على أنه بشر كسائر بني آدم. وجميع الموجودات في السماوات والأرض ملك لله، يخلق ما يشاء ويوجده، وهو على كل شيء قدير. فحقيقة التوحيد توجب تفرُّد الله تعالى بصفات الربوبية والألوهية، فلا يشاركه أحد من خلقه في ذلك، وكثيرًا ما يقع الناس في الشرك والضلال بغلوهم في الأنبياء والصالحين، كما غلا النصارى في المسيح، فالكون كله لله، والخلق بيده وحده، وما يظهر من خوارق وآيات مَرَدُّه إلى الله. يخلق سبحانه ما يشاء، ويفعل ما يريد.', 17, 2, 110, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (687, 5, 1, 6, 687, 'وزعم اليهود والنصارى أنهم أبناء الله وأحباؤه، قل لهم -أيها الرسول-: فَلأيِّ شيء يعذِّبكم بذنوبكم؟ فلو كنتم أحبابه ما عذبكم، فالله لا يحب إلا من أطاعه، وقل لهم: بل أنتم خلقٌ مثلُ سائر بني آدم، إن أحسنتُم جوزيتم بإحسانكم خيرا، وإن أسَأْتُم جوزيتم بإساءتكم شرًّا، فالله يغفر لمن يشاء، ويعذب من يشاء، وهو مالك الملك، يُصَرِّفه كما يشاء، وإليه المرجع، فيحكم بين عباده، ويجازي كلا بما يستحق.', 18, 2, 111, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (688, 5, 1, 6, 688, 'يا أيها اليهود والنصارى قد جاءكم رسولنا محمد صلى الله عليه وسلم، يُبيِّن لكم الحق والهدى بعد مُدَّة من الزمن بين إرساله بإرسال عيسى ابن مريم؛ لئلا تقولوا: ما جاءنا من بشير ولا نذير، فلا عُذرَ لكم بعد إرساله إليكم، فقد جاءكم من الله رسولٌ يبشِّر مَن آمن به، ويُنذِز مَن عصاه. والله على كل شيء قدير من عقاب العاصي وثواب المطيع.', 19, 2, 111, 88, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (689, 5, 1, 6, 689, 'واذكر -أيها الرسول- إذ قال موسى عليه السلام لقومه: يا بني إسرائيل اذكروا نعمة الله عليكم، إذ جعل فيكم أنبياء، وجعلكم ملوكًا تملكون أمركم بعد أن كنتم مملوكين لفرعون وقومه، وقد منحكم من نعمه صنوفًا لم يمنحها أحدًا من عالَمي زمانكم.', 20, 2, 111, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (690, 5, 1, 6, 690, 'يا قوم ادخلوا الأرض المقدسة -أي المطهرة، وهي "بيت المقدس" وما حولها- التي وعد الله أن تدخلوها وتقاتلوا مَن فيها من الكفار، ولا ترجعوا عن قتال الجبارين، فتخسروا خير الدنيا وخير الآخرة.', 21, 2, 111, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (691, 5, 1, 6, 691, 'قالوا: يا موسى، إن فيها قومًا أشداء أقوياء، لا طاقة لنا بحربهم، وإنَّا لن نستطيع دخولها وهم فيها، فإن يخرجوا منها فإنَّا داخلون.', 22, 2, 111, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (692, 5, 1, 6, 692, 'قال رجلان من الذين يخشون الله تعالى، أنعم الله عليهما بطاعته وطاعة نبيِّه، لبني إسرائيل: ادخلوا على هؤلاء الجبارين باب مدينتهم، أخْذًا بالأسباب، فإذا دخلتم الباب غلبتموهم، وعلى الله وحده فتوكَّلوا، إن كنتم مُصدِّقين رسوله فيما جاءكم به، عاملين بشرعه.', 23, 2, 111, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (693, 5, 1, 6, 693, 'قال قوم موسى له: إنا لن ندخل المدينة أبدًا ما دام الجبارون فيها، فاذهب أنت وربك فقاتلاهم، أما نحن فقاعدون هاهنا ولن نقاتلهم. وهذا إصرارٌ منهم على مخالفة موسى عليه السلام.', 24, 2, 112, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (694, 5, 1, 6, 694, 'توجَّه موسى إلى ربه داعيًا: إني لا أقدر إلا على نفسي وأخي، فاحكم بيننا وبين القوم الفاسقين.', 25, 2, 112, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (695, 5, 1, 6, 695, 'قال الله لنبيه موسى عليه السلام: إن الأرض المقدَّسة محرَّم على هؤلاء اليهود دخولها أربعين سنة، يتيهون في الأرض حائرين، فلا تأسف -يا موسى- على القوم الخارجين عن طاعتي.', 26, 2, 112, 89, NULL, 44, 11);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (696, 5, 1, 6, 696, 'واقصص -أيها الرسول- على بني إسرائيل خَبَر ابنَيْ آدم قابيل وهابيل، وهو خبرٌ حقٌ: حين قَدَّم كلٌّ منهما قربانًا -وهو ما يُتَقرَّب به إلى الله تعالى - فتقبَّل الله قُربان هابيل؛ لأنه كان تقيًّا، ولم يتقبَّل قُربان قابيل؛ لأنه لم يكن تقيًّا، فحسد قابيلُ أخاه، وقال: لأقتلنَّك، فَردَّ هابيل: إنما يتقبل الله ممن يخشونه.', 27, 2, 112, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (697, 5, 1, 6, 697, 'وقال هابيلُ واعظًا أخاه: لَئنْ مَدَدْتَ إليَّ يدكَ لتقتُلني لا تَجِدُ مني مثل فعْلك، وإني أخشى الله ربَّ الخلائق أجمعين.', 28, 2, 112, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (698, 5, 1, 6, 698, 'إني أريد أن ترجع حاملا إثم قَتْلي، وإثمك الذي عليك قبل ذلك، فتكون من أهل النار وملازميها، وذلك جزاء المعتدين.', 29, 2, 112, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (699, 5, 1, 6, 699, 'فَزَيَّنت لقابيلَ نفسُه أن يقتل أخاه، فقتله، فأصبح من الخاسرين الذين باعوا آخرتهم بدنياهم.', 30, 2, 112, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (700, 5, 1, 6, 700, 'لما قتل قابيلُ أخاه لم يعرف ما يصنع بجسده، فأرسل الله غرابًا يحفر حفرةً في الأرض ليدفن فيها غرابًا مَيِّتًا؛ ليدل قابيل كيف يدفن جُثمان أخيه؟ فتعجَّب قابيل، وقال: أعجزتُ أن أصنع مثل صنيع هذا الغراب فأستُرَ عورة أخي؟ فدَفَنَ قابيل أخاه، فعاقبه الله بالندامة بعد أن رجع بالخسران.', 31, 2, 112, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (701, 5, 1, 6, 701, 'بسبب جناية القتل هذه شَرَعْنا لبني اسرائيل أنه من قتل نفسا بغير سبب من قصاص، أو فساد في الأرض بأي نوع من أنواع الفساد، الموجب للقتل كالشرك والمحاربة فكأنما قتل الناس جميعًا فيما استوجب من عظيم العقوبة من الله، وأنه من امتنع عن قَتْل نفس حرَّمها الله فكأنما أحيا الناس جميعًا؛ فالحفاظ على حرمة إنسان واحد حفاظ على حرمات الناس كلهم. ولقد أتت بني إسرائيل رسلُنا بالحجج والدلائل على صحة ما دعَوهم إليه من الإيمان بربهم، وأداء ما فُرِضَ عليهم، ثم إن كثيرًا منهم بعد مجيء الرسل إليهم لمتجاوزون حدود الله بارتكاب محارم الله وترك أوامره.', 32, 2, 113, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (702, 5, 1, 6, 702, 'إنما جزاء الذين يحاربون الله، ويبارزونه بالعداوة، ويعتدون على أحكامه، وعلى أحكام رسوله، ويفسدون في الأرض بقتل الأنفس، وسلب الأموال، أن يُقَتَّلوا، أو يُصَلَّبوا مع القتل (والصلب: أن يُشَدَّ الجاني على خشبة) أو تُقْطَع يدُ المحارب اليمنى ورجله اليسرى، فإن لم يَتُبْ تُقطعْ يدُه اليسرى ورجلُه اليمنى، أو يُنفَوا إلى بلد غير بلدهم، ويُحبسوا في سجن ذلك البلد حتى تَظهر توبتُهم. وهذا الجزاء الذي أعدَّه الله للمحاربين هو ذلّ في الدنيا، ولهم في الآخرة عذاب شديد إن لم يتوبوا.', 33, 2, 113, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (703, 5, 1, 6, 703, 'لكن مَن أتى من المحاربين من قبل أن تقدروا عليهم وجاء طائعًا نادمًا فإنه يسقط عنه ما كان لله، فاعلموا -أيها المؤمنون- أن الله غفور لعباده، رحيم بهم.', 34, 2, 113, 90, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (704, 5, 1, 6, 704, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، خافوا الله، وتَقَرَّبوا إليه بطاعته والعمل بما يرضيه، وجاهدوا في سبيله؛ كي تفوزوا بجناته.', 35, 2, 113, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (705, 5, 1, 6, 705, 'إن الذين جحدوا وحدانية الله، وشريعته، لو أنهم ملكوا جميع ما في الأرض، وملكوا مثله معه، وأرادوا أن يفتدوا أنفسهم يوم القيامة من عذاب الله بما ملكوا، ما تَقبَّل الله ذلك منهم، ولهم عذاب مُوجع.', 36, 2, 113, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (706, 5, 1, 6, 706, 'يريد هؤلاء الكافرون الخروج من النار لما يلاقونه من أهوالها، ولا سبيل لهم إلى ذلك، ولهم عذاب دائم.', 37, 2, 114, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (707, 5, 1, 6, 707, 'والسارق والسارقة فاقطعوا -يا ولاة الأمر- أيديهما بمقتضى الشرع، مجازاة لهما على أَخْذهما أموال الناس بغير حق، وعقوبةً يمنع الله بها غيرهما أن يصنع مثل صنيعهما. والله عزيز في ملكه، حكيم في أمره ونهيه.', 38, 2, 114, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (708, 5, 1, 6, 708, 'فمن تاب مِن بعد سرقته، وأصلح في كل أعماله، فإن الله يقبل توبته. إن الله غفور لعباده، رحيم بهم.', 39, 2, 114, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (709, 5, 1, 6, 709, 'ألم تعلم -أيها الرسول- أن الله خالق الكون ومُدبِّره ومالكه، وأنه تعالى الفعَّال لما يريد، يعذب من يشاء، ويغفر لمن يشاء، وهو على كل شيء قدير.', 40, 2, 114, 91, NULL, 45, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (710, 5, 1, 6, 710, 'يا أيها الرسول لا يحزنك الذين يسارعون في جحود نبوتك من المنافقين الذين أظهروا الإسلام وقلوبهم خالية منه، فإني ناصرك عليهم. ولا يحزنك تسرُّع اليهود إلى إنكار نبوتك، فإنهم قوم يستمعون للكذب، ويقبلون ما يَفْتَريه أحبارُهم، ويستجيبون لقوم آخرين لا يحضرون مجلسك، وهؤلاء الآخرون يُبَدِّلون كلام الله من بعد ما عَقَلوه، ويقولون: إن جاءكم من محمد ما يوافق الذي بدَّلناه وحرَّفناه من أحكام التوراة فاعملوا به، وإن جاءكم منه ما يخالفه فاحذروا قبوله، والعمل به. ومن يشأ الله ضلالته فلن تستطيع -أيها الرسول- دَفْعَ ذلك عنه، ولا تقدر على هدايته. وإنَّ هؤلاء المنافقين واليهود لم يُرِدِ الله أن يطهِّر قلوبهم من دنس الكفر، لهم الذلُّ والفضيحة في الدنيا، ولهم في الآخرة عذاب عظيم.', 41, 2, 114, 91, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (711, 5, 1, 6, 711, 'هؤلاء اليهود يجمعون بين استماع الكذب وأكل الحرام، فإن جاؤوك يتحاكمون إليك فاقض بينهم، أو اتركهم، فإن لم تحكم بينهم فلن يقدروا على أن يضروك بشيء، وإن حكمت فاحكم بينهم بالعدل. إن الله يحب العادلين.', 42, 2, 115, 91, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (712, 5, 1, 6, 712, 'إنَّ صنيع هؤلاء اليهود عجيب، فهم يحتكمون إليك -أيها الرسول- وهم لا يؤمنون بك، ولا بكتابك، مع أن التوراة التي يؤمنون بها عندهم، فيها حكم الله، ثم يتولَّون مِن بعد حكمك إذا لم يُرضهم، فجمعوا بين الكفر بشرعهم، والإعراض عن حكمك، وليس أولئك المتصفون بتلك الصفات، بالمؤمنين بالله وبك وبما تحكم به.', 43, 2, 115, 91, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (713, 5, 1, 6, 713, 'إنا أنزلنا التوراة فيها إرشاد من الضلالة، وبيان للأحكام، وقد حكم بها النبيُّون -الذين انقادوا لحكم الله، وأقروا به- بين اليهود، ولم يخرجوا عن حكمها ولم يُحَرِّفوها، وحكم بها عُبَّاد اليهود وفقهاؤهم الذين يربُّون الناس بشرع الله؛ ذلك أن أنبياءهم قد استأمنوهم على تبليغ التوراة، وفِقْه كتاب الله والعمل به، وكان الربانيون والأحبار شهداء على أن أنبياءهم قد قضوا في اليهود بكتاب الله. ويقول تعالى لعلماء اليهود وأحبارهم: فلا تخشوا الناس في تنفيذ حكمي؛ فإنهم لا يقدرون على نفعكم ولا ضَرِّكم، ولكن اخشوني فإني أنا النافع الضار، ولا تأخذوا بترك الحكم بما أنزلتُ عوضًا حقيرًا. الحكم بغير ما أنزل الله من أعمال أهل الكفر، فالذين يبدلون حكم الله الذي أنزله في كتابه، فيكتمونه ويجحدونه ويحكمون بغيره معتقدين حله وجوازه فأولئك هم الكافرون.', 44, 2, 115, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (714, 5, 1, 6, 714, 'وفَرَضنا عليهم في التوراة أن النفس تُقْتَل بالنفس، والعين تُفْقَأ بالعين، والأنف يُجْدَع بالأنف، والأذُن تُقْطع بالأذُن، والسنَّ تُقْلَعُ بالسنِّ، وأنَّه يُقْتَصُّ في الجروح، فمن تجاوز عن حقه في الاقتصاص من المُعتدي فذلك تكفير لبعض ذنوب المعتدى عليه وإزالةٌ لها. ومن لم يحكم بما أنزل الله في القصاص وغيره، فأولئك هم المتجاوزون حدود الله.', 45, 2, 115, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (715, 5, 1, 6, 715, 'وأتبعنا أنبياء بني إسرائيل عيسى ابن مريم مؤمنًا بما في التوراة، عاملا بما فيها مما لم ينسخه كتابه، وأنزلنا إليه الإنجيل هاديا إلى الحق، ومبيِّنًا لما جهله الناس مِن حكم الله، وشاهدًا على صدق التوراة بما اشتمل عليه من أحكامها، وقد جعلناه بيانًا للذين يخافون الله وزاجرًا لهم عن ارتكاب المحرَّمات.', 46, 2, 116, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (716, 5, 1, 6, 716, 'وليحكم أهل الإنجيل الذين أُرسِل إليهم عيسى بما أنزل الله فيه. ومن لم يحكم بما أنزل الله فأولئك هم الخارجون عن أمره، العاصون له.', 47, 2, 116, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (717, 5, 1, 6, 717, 'وأنزلنا إليك -أيها الرسول- القرآن، وكل ما فيه حقّ يشهد على صدق الكتب قبله، وأنها من عند الله، مصدقًا لما فيها من صحة، ومبيِّنًا لما فيها من تحريف، ناسخًا لبعض شرائعها، فاحكم بين المحتكمين إليك من اليهود بما أنزل الله إليك في هذا القرآن، ولا تنصرف عن الحق الذي أمرك الله به إلى أهوائهم وما اعتادوه، فقد جعلنا لكل أمة شريعة، وطريقة واضحة يعملون بها. ولو شاء الله لجعل شرائعكم واحدة، ولكنه تعالى خالف بينها ليختبركم، فيظهر المطيع من العاصي، فسارعوا إلى ما هو خير لكم في الدارين بالعمل بما في القرآن، فإن مصيركم إلى الله، فيخبركم بما كنتم فيه تختلفون، ويجزي كلا بعمله.', 48, 2, 116, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (718, 5, 1, 6, 718, 'واحكم -أيها الرسول- بين اليهود بما أنزل الله إليك في القرآن، ولا تتبع أهواء الذين يحتكمون إليك، واحذرهم أن يصدُّوك عن بعض ما أنزل الله إليك فتترك العمل به، فإن أعرض هؤلاء عمَّا تحكم به فاعلم أن الله يريد أن يصرفهم عن الهدى بسبب ذنوبٍ اكتسبوها من قبل. وإن كثيرًا من الناس لَخارجون عن طاعة ربهم.', 49, 2, 116, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (719, 5, 1, 6, 719, 'أيريد هؤلاء اليهود أن تحكم بينهم بما تعارف عليه المشركون عبدةُ الأوثان من الضلالات والجهالات؟! لا يكون ذلك ولا يليق أبدًا ومَن أعدل مِن الله في حكمه لمن عقل عن الله شَرْعه، وآمن به، وأيقن أن حكم الله هو الحق؟', 50, 2, 116, 92, NULL, 46, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (720, 5, 1, 6, 720, 'يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى حلفاءَ وأنصارًا على أهل الإيمان؛ ذلك أنهم لا يُوادُّون المؤمنين، فاليهود يوالي بعضهم بعضًا، وكذلك النصارى، وكلا الفريقين يجتمع على عداوتكم. وأنتم -أيها المؤمنون- أجدرُ بأن ينصر بعضُكم بعضًا. ومن يتولهم منكم فإنه يصير من جملتهم، وحكمه حكمهم. إن الله لا يوفق الظالمين الذين يتولون الكافرين.', 51, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (721, 5, 1, 6, 721, 'يخبر الله تعالى عن جماعة من المنافقين أنهم كانوا يبادرون في موادة اليهود لما في قلوبهم من الشكِّ والنفاق، ويقولون: إنما نوادُّهم خشية أن يظفروا بالمسلمين فيصيبونا معهم، قال الله تعالى ذكره: فعسى الله أن يأتي بالفتح -أي فتح "مكة"- وينصر نَبِيَّه، ويُظْهِر الإسلام والمسلمين على الكفار، أو يُهيِّئ من الأمور ما تذهب به قوةُ اليهود والنَّصارى، فيخضعوا للمسلمين، فحينئذٍ يندم المنافقون على ما أضمروا في أنفسهم من موالاتهم.', 52, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (722, 5, 1, 6, 722, 'وحينئذ يقول بعض المؤمنين لبعض مُتعجِّبين من حال المنافقين -إذا كُشِف أمرهم-: أهؤلاء الذين أقسموا بأغلظ الأيمان إنهم لَمَعَنا؟! بطلت أعمال المنافقين التي عملوها في الدنيا، فلا ثواب لهم عليها؛ لأنهم عملوها على غير إيمان، فخسروا الدنيا والآخرة.', 53, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (723, 5, 1, 6, 723, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه من يرجع منكم عن دينه، ويستبدل به اليهودية أو النصرانية أو غير ذلك، فلن يضرُّوا الله شيئًا، وسوف يأتي الله بقوم خير منهم يُحِبُّهم ويحبونه، رحماء بالمؤمنين أشدَّاء على الكافرين، يجاهدون أعداء الله، ولا يخافون في ذات الله أحدًا. ذلك الإنعام مِن فضل الله يؤتيه من أراد، والله واسع الفضل، عليم بمن يستحقه من عباده.', 54, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (724, 5, 1, 6, 724, 'إنما ناصركم -أيُّها المؤمنون- الله ورسوله، والمؤمنون الذين يحافظون على الصلاة المفروضة، ويؤدون الزكاة عن رضا نفس، وهم خاضعون لله.', 55, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (725, 5, 1, 6, 725, 'ومن وثق بالله وتولَّى الله ورسوله والمؤمنين، فهو من حزب الله، وحزب الله هم الغالبون المنتصرون.', 56, 2, 117, 93, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (726, 5, 1, 6, 726, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تتخذوا الذين يستهزئون ويتلاعبون بدينكم من أهل الكتاب والكفارَ أولياءَ، وخافوا الله إن كنتم مؤمنين به وبشرعه.', 57, 2, 117, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (727, 5, 1, 6, 727, 'وإذا أذَّن مؤذنكم -أيها المؤمنون- بالصلاة سخر اليهود والنصارى والمشركون واستهزؤوا من دعوتكم إليها؛ وذلك بسبب جهلهم بربهم، وأنهم لا يعقلون حقيقة العبادة.', 58, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (728, 5, 1, 6, 728, 'قل -أيها الرسول- لهؤلاء المستهزئين من أهل الكتاب: ما تَجِدُونه مطعنًا أو عيبًا هو محمدة لنا: من إيماننا بالله وكتبه المنزلة علينا، وعلى من كان قبلنا، وإيماننا بأن أكثركم خارجون عن الطريق المستقيم!', 59, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (729, 5, 1, 6, 729, 'قل -أيها النبي- للمؤمنين: هل أخبركم بمن يُجازَى يوم القيامة جزاءً أشدَّ مِن جزاء هؤلاء الفاسقين؟ إنهم أسلافهم الذين طردهم الله من رحمته وغَضِب عليهم، ومَسَخَ خَلْقهم، فجعل منهم القردة والخنازير، بعصيانهم وافترائهم وتكبرهم، كما كان منهم عُبَّاد الطاغوت (وهو كل ما عُبِد من دون الله وهو راضٍ)، لقد ساء مكانهم في الآخرة، وضلَّ سَعْيُهم في الدنيا عن الطريق الصحيح.', 60, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (730, 5, 1, 6, 730, 'وإذا جاءكم -أيها المؤمنون- منافقو اليهود، قالوا: آمنَّا، وهم مقيمون على كفرهم، قد دخلوا عليكم بكفرهم الذي يعتقدونه بقلوبهم، ثم خرجوا وهم مصرُّون عليه، والله أعلم بسرائرهم، وإن أظهروا خلاف ذلك.', 61, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (731, 5, 1, 6, 731, 'وترى -أيها الرسول- كثيرًا من اليهود يبادرون إلى المعاصي من قول الكذب والزور، والاعتداء على أحكام الله، وأكْل أموال الناس بالباطل، لقد ساء عملهم واعتداؤهم.', 62, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (732, 5, 1, 6, 732, 'هلا ينهى هؤلاء الذين يسارعون في الإثم والعدوان أئمتُهم وعلماؤهم، عن قول الكذب والزور، وأكل أموال الناس بالباطل، لقد ساء صنيعهم حين تركوا النهي عن المنكر.', 63, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (733, 5, 1, 6, 733, 'يُطلع الله نَبِيَّه على شيء من مآثم اليهود -وكان مما يُسرُّونه فيما بينهم- أنهم قالوا: يد الله محبوسة عن فعل الخيرات، بَخِلَ علينا بالرزق والتوسعة، وذلك حين لحقهم جَدْب وقحط. غُلَّتْ أيديهم، أي: حبست أيديهم هم عن فِعْلِ الخيرات، وطردهم الله من رحمته بسبب قولهم. وليس الأمر كما يفترونه على ربهم، بل يداه مبسوطتان لا حَجْرَ عليه، ولا مانع يمنعه من الإنفاق، فإنه الجواد الكريم، ينفق على مقتضى الحكمة وما فيه مصلحة العباد. وفي الآية إثبات لصفة اليدين لله سبحانه وتعالى كما يليق به من غير تشبيه ولا تكييف. لكنهم سوف يزدادون طغيانًا وكفرًا بسبب حقدهم وحسدهم؛ لأن الله قد اصطفاك بالرسالة. ويخبر تعالى أن طوائف اليهود سيظلون إلى يوم القيامة يعادي بعضهم بعضًا، وينفر بعضهم من بعض، كلما تآمروا على الكيد للمسلمين بإثارة الفتن وإشعال نار الحرب ردَّ الله كيدهم، وفرَّق شملهم، ولا يزال اليهود يعملون بمعاصي الله مما ينشأ عنها الفساد والاضطراب في الأرض. والله تعالى لا يحب المفسدين.', 64, 2, 118, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (734, 5, 1, 6, 734, 'ولو أن اليهود والنصارى صدَّقوا الله ورسوله، وامتثلوا أوامر الله واجتنبوا نواهيه، لكفَّرنا عنهم ذنوبهم، ولأدخلناهم جنات النعيم في الدار الآخرة.', 65, 2, 119, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (735, 5, 1, 6, 735, 'ولو أنَّهم عملوا بما في التوراة والإنجيل، وبما أُنْزِل عليك أيها الرسول - وهو القرآن الكريم - لرُزِقوا من كلِّ سبيلٍ، فأنزلنا عليهم المطر، وأنبتنا لهم الثمر، وهذا جزاء الدنيا. وإنَّ مِن أهل الكتاب فريقًا معتدلا ثابتًا على الحق، وكثير منهم ساء عملُه، وضل عن سواء السبيل.', 66, 2, 119, 94, NULL, 47, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (736, 5, 1, 6, 736, 'يا أيها الرسول بلِّغ وحي الله الذي أنزِل إليك من ربك، وإن قصَّرت في البلاغ فَكَتَمْتَ منه شيئًا، فإنك لم تُبَلِّغ رسالة ربِّك، وقد بلَّغ صلى الله عليه وسلم رسالة ربه كاملة، فمن زعم أنه كتم شيئًا مما أنزِل عليه، فقد أعظم على الله ورسوله الفرية. والله تعالى حافظك وناصرك على أعدائك، فليس عليك إلا البلاغ. إن الله لا يوفق للرشد مَن حاد عن سبيل الحق، وجحد ما جئت به من عند الله.', 67, 2, 119, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (737, 5, 1, 6, 737, 'قل -أيها الرسول- لليهود والنصارى: إنكم لستم على حظٍّ من الدين ما دمتم لم تعملوا بما في التوراة والإنجيل، وما جاءكم به محمد من القرآن، وإن كثيرًا من أهل الكتاب لا يزيدهم إنزالُ القرآن إليك إلا تجبُّرًا وجحودًا، فهم يحسدونك؛ لأن الله بعثك بهذه الرسالة الخاتمة، التي بَيَّن فيها معايبهم، فلا تحزن -أيها الرسول- على تكذيبهم لك.', 68, 2, 119, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (738, 5, 1, 6, 738, 'إن الذين آمنوا (وهم المسلمون) واليهود، والصابئين (وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه) والنصارى (وهم أتباع المسيح) من آمن منهم بالله الإيمان الكامل، وهو توحيد الله والتصديق بمحمد صلى الله عليه وسلم وبما جاء به، وآمن باليوم الآخر، وعمل العمل الصالح، فلا خوف عليهم من أهوال يوم القيامة، ولا هم يحزنون على ما تركوه وراءهم في الدنيا.', 69, 2, 119, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (739, 5, 1, 6, 739, 'لقد أخذنا العهد المؤكَّد على بني إسرائيل في التوراة بالسمع والطاعة، وأرسلنا إليهم بذلك رسلنا، فَنَقَضوا ما أُخذ عليهم من العهد، واتبعوا أهواءهم، وكانوا كلما جاءهم رسول من أولئك الرسل بما لا تشتهيه أنفسهم عادَوْه: فكذبوا فريقًا من الرسل، وقتلوا فريقًا آخر.', 70, 2, 119, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (740, 5, 1, 6, 740, 'وظنَّ هؤلاء العُصاة أن الله لن يأخذهم بالعذاب جزاء عصيانهم وعُتُوِّهم، فمضوا في شهواتهم، وعمُوا عن الهدى فلم يبصروه، وصَمُّوا عن سماع الحقِّ فلم ينتفعوا به، فأنزل الله بهم بأسه، فتابوا فتاب الله عليهم، ثم عَمِي كثيرٌ منهم، وصمُّوا، بعدما تبين لهم الحقُّ، والله بصير بأعمالهم خيرها وشرها وسيجازيهم عليها.', 71, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (741, 5, 1, 6, 741, 'يقسم الله تعالى بأن الذين قالوا: إن الله هو المسيح ابن مريم، قد كفروا بمقالتهم هذه، وأخبر تعالى أن المسيح قال لبني إسرائيل: اعبدوا الله وحده لا شريك له، فأنا وأنتم في العبودية سواء. إنه من يعبد مع الله غيره فقد حرَّم الله عليه الجنة، وجعل النار مُستَقَرَّه، وليس له ناصرٌ يُنقذُه منها.', 72, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (742, 5, 1, 6, 742, 'لقد كفر من النصارى من قال: إنَّ الله مجموع ثلاثة أشياء: هي الأب، والابن، وروح القدس. أما عَلِمَ هؤلاء النصارى أنه ليس للناس سوى معبود واحد، لم يلد ولم يولد، وإن لم ينته أصحاب هذه المقالة عن افترائهم وكذبهم ليُصِيبَنَّهم عذاب مؤلم موجع بسبب كفرهم بالله.', 73, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (743, 5, 1, 6, 743, 'أفلا يرجع هؤلاء النصارى إلى الله تعالى، ويتولون عمَّا قالوا، ويسألون الله تعالى المغفرة؟ والله تعالى متجاوز عن ذنوب التائبين، رحيمٌ بهم', 74, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (744, 5, 1, 6, 744, 'ما المسيح ابن مريم عليه السلام إلا رسولٌ كمن تقدمه من الرسل، وأُمُّه قد صَدَّقت تصديقًا جازمًا علمًا وعملا وهما كغيرهما من البشر يحتاجان إلى الطعام، ولا يكون إلهًا مَن يحتاج الى الطعام ليعيش. فتأمَّل -أيها الرسول- حال هؤلاء الكفار. لقد وضحنا العلاماتِ الدالةَ على وحدانيتنا، وبُطلان ما يَدَّعونه في أنبياء الله. ثم هم مع ذلك يَضِلُّون عن الحق الذي نَهديهم إليه، ثم انظر كيف يُصرفون عن الحق بعد هذا البيان؟', 75, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (745, 5, 1, 6, 745, 'قل -أيها الرسول- لهؤلاء الكفرة: كيف تشركون مع الله من لا يَقْدِرُ على ضَرِّكم، ولا على جَلْبِ نفع لكم؟ والله هو السميع لأقوال عباده، العليم بأحوالهم.', 76, 2, 120, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (746, 5, 1, 6, 746, 'قل -أيها الرسول- للنصارى: لا تتجاوزوا الحقَّ فيما تعتقدونه من أمر المسيح، ولا تتبعوا أهواءكم، كما اتَّبع اليهود أهواءهم في أمر الدين، فوقعوا في الضلال، وحملوا كثيرًا من الناس على الكفر بالله، وخرجوا عن طريق الاستقامة الى طريق الغَواية والضلال.', 77, 2, 121, 95, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (747, 5, 1, 6, 747, 'يخبر تعالى أنه طرد من رحمته الكافرين من بني إسرائيل في الكتاب الذي أنزله على داود -عليه السلام- وهو الزَّبور، وفي الكتاب الذي أنزله على عيسى - عليه السلام - وهو الإنجيل؛ بسبب عصيانهم واعتدائهم على حرمات الله.', 78, 2, 121, 96, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (748, 5, 1, 6, 748, 'كان هؤلاء اليهود يُجاهرون بالمعاصي ويرضونها، ولا يَنْهى بعضُهم بعضًا عن أيِّ منكر فعلوه، وهذا من أفعالهم السيئة، وبه استحقوا أن يُطْرَدُوا من رحمة الله تعالى.', 79, 2, 121, 96, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (749, 5, 1, 6, 749, 'تَرَى -أيها الرسول- كثيرًا من هؤلاء اليهود يتخذون المشركين أولياء لهم، ساء ما عملوه من الموالاة التي كانت سببًا في غضب الله عليهم، وخلودهم في عذاب الله يوم القيامة.', 80, 2, 121, 96, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (750, 5, 1, 6, 750, 'ولو أن هؤلاء اليهود الذين يناصرون المشركين كانوا قد آمنوا بالله تعالى والنبي محمد صلى الله عليه وسلم، وأقرُّوا بما أنزل إليه -وهو القرآن الكريم- ما اتخذوا الكفار أصحابًا وأنصارًا، ولكن كثيرًا منهم خارجون عن طاعة الله ورسوله.', 81, 2, 121, 96, NULL, 48, 12);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (751, 5, 1, 7, 751, 'لتجدنَّ -أيها الرسول- أشدَّ الناس عداوة للذين صدَّقوك وآمنوا بك واتبعوك، اليهودَ؛ لعنادهم، وجحودهم، وغمطهم الحق، والذين أشركوا مع الله غيره، كعبدة الأوثان وغيرهم، ولتجدنَّ أقربهم مودة للمسلمين الذين قالوا: إنا نصارى، ذلك بأن منهم علماء بدينهم متزهدين وعبَّادًا في الصوامع متنسكين، وأنهم متواضعون لا يستكبرون عن قَبول الحق، وهؤلاء هم الذين قبلوا رسالة محمد صلى الله عليه وسلم، وآمنوا بها.', 82, 2, 121, 96, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (752, 5, 1, 7, 752, 'ومما يدل على قرب مودتهم للمسلمين أن فريقًا منهم (وهم وفد الحبشة لما سمعوا القرآن) فاضت أعينهم من الدمع فأيقنوا أنه حقٌّ منزل من عند الله تعالى، وصدَّقوا بالله واتبعوا رسوله، وتضرعوا إلى الله أن يكرمهم بشرف الشهادة مع أمَّة محمد عليه السلام على الأمم يوم القيامة.', 83, 2, 122, 96, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (753, 5, 1, 7, 753, 'وقالوا: وأيُّ لوم علينا في إيماننا بالله، وتصديقنا بالحق الذي جاءنا به محمد صلى الله عليه وسلم من عند الله، واتباعنا له، ونرجو أن يدخلنا ربنا مع أهل طاعته في جنته يوم القيامة؟', 84, 2, 122, 96, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (754, 5, 1, 7, 754, 'فجزاهم الله بما قالوا من الاعتزاز بإيمانهم بالإسلام، وطلبهم أن يكونوا مع القوم الصالحين، جنات تجري من تحت أشجارها الأنهار، ماكثين فيها لا يخرجون منها، ولا يُحوَّلون عنها، وذلك جزاء إحسانهم في القول والعمل.', 85, 2, 122, 96, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (755, 5, 1, 7, 755, 'والذين جحدوا وحدانية الله وأنكروا نبوة محمد صلى الله عليه وسلم، وكذَّبوا بآياته المنزلة على رسله، أولئك هم أصحاب النار الملازمون لها.', 86, 2, 122, 96, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (756, 5, 1, 7, 756, 'يا أيها الذين آمنوا لا تحرِّموا طيبات أحلَّها الله لكم من المطاعم والمشارب ونكاح النساء، فتضيقوا ما وسَّع الله عليكم، ولا تتجاوزوا حدود ما حرَّم الله. إن الله لا يحب المعتدين.', 87, 2, 122, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (757, 5, 1, 7, 757, 'وتمتعوا -أيها المؤمنون- بالحلال الطيب مما أعطاكم الله ومنحكم إياه، واتقوا الله بامتثال أوامره، واجتناب نواهيه؛ فإن إيمانكم بالله يوجب عليكم تقواه ومراقبته.', 88, 2, 122, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (758, 5, 1, 7, 758, 'لا يعاقبكم الله -أيها المسلمون- فيما لا تقصدون عَقْدَه من الأيمان، مثل قول بعضكم: لا والله، وبلى والله، ولكن يعاقبكم فيما قصدتم عقده بقلوبكم، فإذا لم تَفُوا باليمين فإثم ذلك يمحوه الله بما تقدِّمونه مما شرعه الله لكم كفارة من إطعام عشرة مساكين، لكل مسكين نصف صاع من أوسط طعام أهل البلد، أو كسوتهم، لكل مسكين ما يكفي في الكسوة عُرفًا، أو إعتاق مملوك من الرق، فالحالف الذي لم يف بيمينه مخير بين هنا الأمور الثلاثة، فمن لم يجد شيئًا من ذلك فعليه صيام ثلاثة أيام. تلك مكفرات عدم الوفاء بأيمانكم، واحفظوا -أيها المسلمون- أيمانكم: باجتناب الحلف، أو الوفاء إن حلفتم، أو الكفارة إذا لم تفوا بها. وكما بيَّن الله لكم حكم الأيمان والتحلل منها يُبيِّن لكم أحكام دينه؛ لتشكروا له على هدايته إياكم إلى الطريق المستقيم.', 89, 2, 122, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (759, 5, 1, 7, 759, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إنما الخمر: وهي كل مسكر يغطي العقل، والميسر: وهو القمار، وذلك يشمل المراهنات ونحوها، مما فيه عوض من الجانبين، وصدٌّ عن ذكر الله، والأنصاب: وهي الحجارة التي كان المشركون يذبحون عندها تعظيمًا لها، وما ينصب للعبادة تقربًا إليه، والأزلام: وهي القِداح التي يستقسم بها الكفار قبل الإقدام على الشيء، أو الإحجام عنه، إن ذلك كله إثمٌ مِن تزيين الشيطان، فابتعدوا عن هذه الآثام، لعلكم تفوزون بالجنة.', 90, 2, 123, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (760, 5, 1, 7, 760, 'إنما يريد الشيطان بتزيين الآثام لكم أن يُلقِي بينكم ما يوجد العداوة والبغضاء، بسبب شرب الخمر ولعب الميسر، ويصرفكم عن ذكر الله وعن الصلاة بغياب العقل في شرب الخمر، والاشتغال باللهو في لعب الميسر، فانتهوا عن ذلك.', 91, 2, 123, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (761, 5, 1, 7, 761, 'وامتثلوا -أيها المسلمون- طاعة الله وطاعة رسوله محمد صلى الله عليه وسلم في كل ما تفعلون وتتركون، واتقوا الله وراقبوه في ذلك، فإن أعرضتم عن الامتثال فعملتم ما نهيتم عنه، فاعلموا أنما على رسولنا محمد صلى الله عليه وسلم البلاغ المبين.', 92, 2, 123, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (762, 5, 1, 7, 762, 'ليس على المؤمنين الذين شربوا الخمر قبل تحريمها إثم في ذلك، إذا تركوها واتقوا سخط الله وآمنوا به، وقدَّموا الأعمال الصالحة التي تدل على إيمانهم ورغبتهم في رضوان الله تعالى عنهم، ثم ازدادوا بذلك مراقبة لله عز وجل وإيمانا به، حتى أصبحوا مِن يقينهم يعبدونه، وكأنهم يرونه. وإن الله تعالى يحب الذين بلغوا درجة الإحسان حتى أصبح إيمانهم بالغيب كالمشاهدة.', 93, 2, 123, 97, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (763, 5, 1, 7, 763, 'يا أيها الذين صدقوا الله ورسوله وعملوا بشرعه، ليبلونكم الله بشيء من الصيد يقترب منكم على غير المعتاد حيث تستطيعون أَخْذَ صغاره بغير سلاح وأخذ كباره بالسلاح؛ ليعلم الله علمًا ظاهرًا للخلق الذين يخافون ربهم بالغيب، ليقينهم بكمال علمه بهم، وذلك بإمساكهم عن الصيد، وهم محرمون. فمن تجاوز حَدَّه بعد هذا البيان فأقدم على الصيد -وهو مُحْرِم- فإنه يستحق العذاب الشديد.', 94, 2, 123, 98, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (764, 5, 1, 7, 764, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تقتلوا صيد البر، وأنتم محرمون بحج أو عمرة، أو كنتم داخل الحرم ومَن قتل أيَّ نوعٍ من صيد البرِّ متعمدًا فجزاء ذلك أن يذبح مثل ذلك الصيد من بهيمة الأنعام: الإبل أو البقر أو الغنم، بعد أن يُقَدِّره اثنان عدلان، وأن يهديه لفقراء الحرم، أو أن يشتري بقيمة مثله طعامًا يهديه لفقراء الحرم لكل مسكين نصف صاع، أو يصوم بدلا من ذلك يوما عن كل نصف صاع من ذلك الطعام، فَرَضَ الله عليه هذا الجزاء؛ ليلقى بإيجاب الجزاء المذكور عاقبة فِعْله. والذين وقعوا في شيء من ذلك قبل التحريم فإن الله تعالى قد عفا عنهم، ومَن عاد إلى المخالفة متعمدًا بعد التحريم، فإنه مُعَرَّض لانتقام الله منه. والله تعالى عزيز قويٌّ منيع في سلطانه، ومِن عزته أنه ينتقم ممن عصاه إذا أراد، لا يمنعه من ذلك مانع.', 95, 2, 123, 98, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (765, 5, 1, 7, 765, 'أحل الله لكم -أيها المسلمون- في حال إحرامكم صيد البحر، وهو ما يصاد منه حيًّا، وطعامه: وهو الميت منه؛ من أجل انتفاعكم به مقيمين أو مسافرين، وحرم عليكم صيد البَرِّ ما دمتم محرمين بحج أو عمرة. واخشوا الله ونفذوا جميع أوامِره، واجتنبوا جميع نواهيه؛ حتى تظفَروا بعظيم ثوابه، وتَسْلموا من أليم عقابه عندما تحشرون للحساب والجزاء.', 96, 2, 124, 98, NULL, 49, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (766, 5, 1, 7, 766, 'امتنَّ الله على عباده بأن جعل الكعبة البيت الحرام صلاحًا لدينهم، وأمنًا لحياتهم؛ وذلك حيث آمنوا بالله ورسوله وأقاموا فرائضه، وحرَّم العدوان والقتال في الأشهر الحرم (وهي ذو القعدة وذو الحجة والمحرم ورجب) فلا يعتدي فيها أحد على أحد، وحرَّم تعالى الاعتداء على ما يُهدَى إلى الحرم من بهيمة الأنعام، وحرَّم كذلك الاعتداء على القلائد، وهي ما قُلِّد إشعارًا بأنه بقصد به النسك؛ ذلك لتعلموا أن الله يعلم جميع ما في السموات وما في الأرض، ومن ذلك ما شرعه لحماية خلقه بعضهم من بعض، وأن الله بكل شيء عليم، فلا تخفى عليه خافية.', 97, 2, 124, 98, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (767, 5, 1, 7, 767, 'اعلموا -أيها الناس- أن الله جل وعلا شديد العقاب لمن عصاه، وأن الله غفور رحيم لمن تاب وأناب.', 98, 2, 124, 98, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (768, 5, 1, 7, 768, 'يبيِّن الله تعالى أن مهمة رسوله صلى الله عليه وسلم هداية الدلالة والتبليغ، وبيد الله -وحده- هداية التوفيق، وأن ما تنطوي عليه نفوس الناس مما يُسرون أو يعلنون من الهداية أو الضلال يعلمه الله.', 99, 2, 124, 98, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (769, 5, 1, 7, 769, 'قل -أيها الرسول-: لا يستوي الخبيث والطيب من كل شيء، فالكافر لا يساوي المؤمن، والعاصي لا يساوي المطيع، والجاهل لا يساوي العالم، والمبتدع لا يساوي المتبع، والمال الحرام لا يساوي الحلال، ولو أعجبك -أيها الإنسان- كثرة الخبيث وعدد أهله. فاتقوا الله يا أصحاب العقول الراجحة باجتناب الخبائث، وفعل الطيبات؛ لتفلحوا بنيل المقصود الأعظم، وهو رضا الله تعالى والفوز بالجنة.', 100, 2, 124, 98, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (770, 5, 1, 7, 770, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تسألوا عن أشياء من أمور الدين لم تؤمروا فيها بشيء، كالسؤال عن الأمور غير الواقعة، أو التي يترتب عليها تشديدات في الشرع، ولو كُلِّفتموها لشقَّتْ عليكم، وإن تسألوا عنها في حياة رسول الله صلى الله عليه وسلم وحين نزول القرآن عليه تُبيَّن لكم، وقد تُكلَّفونها فتعجزون عنها، تركها الله معافيًا لعباده منها. والله غفور لعباده إذا تابوا، حليم عليهم فلا يعاقبهم وقد أنابوا إليه.', 101, 2, 124, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (771, 5, 1, 7, 771, 'إن مثل تلك الأسئلة قد سألها قومٌ مِن قبلكم رسلَهم، فلما أُمِروا بها جحدوها، ولم ينفذوها، فاحذروا أن تكونوا مثلهم.', 102, 2, 124, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (772, 5, 1, 7, 772, 'ما شرع الله للمشركين ما ابتدعوه في بهيمة الأنعام مِن تَرْك الانتفاع ببعضها وجعلها للأصنام، وهي: البَحيرة التي تُقطع أذنها إذا ولدت عددًا من البطون، والسائبة وهي التي تُترك للأصنام، والوصيلة وهي التي تتصل ولادتها بأنثى بعد أنثى، والحامي وهو الذكر من الإبل إذا وُلد من صلبه عدد من الإبل، ولكن الكفار نسبوا ذلك إلى الله تعالى افتراء عليه، وأكثر الكافرين لا يميزون الحق من الباطل.', 103, 2, 124, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (773, 5, 1, 7, 773, 'وإذا قيل لهؤلاء الكفار المحرِّمين ما أحل الله: تعالوا إلى تنزيل الله وإلى رسوله ليتبين لكم الحلال والحرام، قالوا: يكفينا ما ورثناه عن آبائنا من قول وعمل، أيقولون ذلك ولو كان آباؤهم لا يعلمون شيئًا أي: لا يفهمون حقًّا ولا يعرفونه، ولا يهتدون إليه؟ فكيف يتبعونهم، والحالة هذه؟ فإنه لا يتبعهم إلا من هو أجهل منهم وأضل سبيلا.', 104, 2, 125, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (774, 5, 1, 7, 774, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه ألزموا أنفسكم بالعمل بطاعة الله واجتناب معصيته، وداوموا على ذلك وإن لم يستجب الناس لكم، فإذا فعلتم ذلك فلا يضركم ضلال مَن ضلَّ إذا لزمتم طريق الاستقامة، وأمرتم بالمعروف ونهيتم عن المنكر، إلى الله مرجعكم جميعًا في الآخرة، فيخبركم بأعمالكم، ويجازيكم عليها.', 105, 2, 125, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (775, 5, 1, 7, 775, 'يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إذا قرب الموت من أحدكم، فلْيُشْهِد على وصيته اثنين أمينين من المسلمين أو آخرين من غير المسلمين عند الحاجة، وعدم وجود غيرهما من المسلمين، تُشهدونهما إن أنتم سافرتم في الأرض فحلَّ بكم الموت، وإن ارتبتم في شهادتهما فقفوهما من بعد الصلاة -أي صلاة المسلمين، وبخاصة صلاة العصر-، فيقسمان بالله قسمًا خالصًا لا يأخذان به عوضًا من الدنيا، ولا يحابيان به ذا قرابة منهما، ولا يكتمان به شهادة لله عندهما، وأنهما إن فَعَلا ذلك فهما من المذنبين.', 106, 2, 125, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (776, 5, 1, 7, 776, 'فإن اطلع أولياء الميت على أن الشاهدين المذكورين قد أثما بالخيانة في الشهادة أو الوصية فليقم مقامهما في الشهادة اثنان من أولياء الميت فيقسمان بالله: لَشهادتنا الصادقة أولى بالقبول من شهادتهما الكاذبة، وما تجاوزنا الحق في شهادتنا، إنا إن اعتدينا وشهدنا بغير الحق لمن الظالمين المتجاوزين حدود الله.', 107, 2, 125, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (777, 5, 1, 7, 777, 'ذلك الحكم عند الارتياب في الشاهدين من الحلف بعد الصلاة وعدم قبول شهادتهما، أقرب إلى أن يأتوا بالشهادة على حقيقتها خوفًا من عذاب الآخرة، أو خشية من أن ترد اليمين الكاذبة من قِبَل أصحاب الحق بعد حلفهم، فيفتضح الكاذب الذي ردت يمينه في الدنيا وقت ظهور خيانته. وخافوا الله -أيها الناس- وراقبوه أن تحلفوا كذبًا، وأن تقتطعوا بأيمانكم مالا حرامًا، واسمعوا ما توعظون به. والله لا يهدي القوم الفاسقين الخارجين عن طاعته.', 108, 2, 125, 99, NULL, 50, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (778, 5, 1, 7, 778, 'واذكروا -أيها الناس- يوم القيامة يوم يجمع الله الرسل عليهم السلام، فيسألهم عن جواب أممهم لهم حينما دعوهم إلى التوحيد فيجيبون: لا علم لنا، فنحن لا نعلم ما في صدور الناس، ولا ما أحدثوا بعدنا. إنك أنت عليم بكل شيء مما ظهر وخفي.', 109, 2, 126, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (779, 5, 1, 7, 779, 'إذ قال الله يوم القيامة: يا عيسى ابن مريم اذكر نعمتي عليك إذ خلقتك من غير أب، وعلى والدتك حيث اصطفيتها على نساء العالمين، وبرأتها مما نُسِب إليها، ومن هذه النعم على عيسى أنه قوَّاه وأعانه بجبريل عليه السلام، يكلم الناس وهو رضيع، ويدعوهم إلى الله وهو كبير بما أوحاه الله إليه من التوحيد، ومنها أن الله تعالى علَّمه الكتابة والخط بدون معلم، ووهبه قوة الفهم والإدراك، وعَلَّمه التوراة التي أنزلها على موسى عليه السلام، والإنجيل الذي أنزل عليه هداية للناس، ومن هذه النعم أنه يصوِّر من الطين كهيئة الطير فينفخ في تلك الهيئة، فتكون طيرًا بإذن الله، ومنها أنه يشفي الذي وُلِد أعمى فيبصر، ويشفي الأبرص، فيعود جلده سليمًا بإذن الله، ومنها أنه يدعو الله أن يحييَ الموتى فيقومون من قبورهم أحياء، وذلك كله بإرادة الله تعالى وإذنه، وهي معجزات باهرة تؤيد نبوة عيسى عليه السلام، ثم يذكِّره الله جل وعلا نعمته عليه إذ منع بني إسرائيل حين همُّوا بقتله، وقد جاءهم بالمعجزات الواضحة الدالة على نبوته، فقال الذين كفروا منهم: إنَّ ما جاء به عيسى من البينات سحر ظاهر.', 110, 2, 126, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (780, 5, 1, 7, 780, 'واذكر نعمتي عليك، إذ ألهمتُ، وألقيتُ في قلوب جماعة من خلصائك أن يصدقوا بوحدانية الله تعالى ونبوتك، فقالوا: صدَّقنا يا ربنا، واشهد بأننا خاضعون لك منقادون لأمرك.', 111, 2, 126, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (781, 5, 1, 7, 781, 'واذكر إذ قال الحواريون: يا عيسى ابن مريم هل يستطيع ربك إن سألته أن ينزل علينا مائدة طعام من السماء؟ فكان جوابه أن أمرهم بأن يتقوا عذاب الله تعالى، إن كانوا مؤمنين حقَّ الإيمان.', 112, 2, 126, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (782, 5, 1, 7, 782, 'قال الحواريون: نريد أن نأكل من المائدة وتسكن قلوبنا لرؤيتها، ونعلم يقينا صدقك في نبوتك، وأن نكون من الشاهدين على هذه الآية أن الله أنزلها حجة له علينا في توحيده وقدرته على ما يشاء، وحجة لك على صدقك في نبوتك.', 113, 2, 126, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (783, 5, 1, 7, 783, 'أجاب عيسى ابن مريم طلب الحواريين فدعا ربه جل وعلا قائلا ربنا أنزل علينا مائدة طعام من السماء، نتخذ يوم نزولها عيدًا لنا، نعظمه نحن ومَن بعدنا، وتكون المائدة علامة وحجة منك يا ألله على وحدانيتك وعلى صدق نبوتي، وامنحنا من عطائك الجزيل، وأنت خير الرازقين.', 114, 2, 127, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (784, 5, 1, 7, 784, 'قال الله تعالى: إني منزل مائدة الطعام عليكم، فمن يجحد منكم وحدانيتي ونبوة عيسى عليه السلام بعد نزول المائدة فإني أعذبه عذابًا شديدًا، لا أعذبه أحدًا من العالمين. وقد نزلت المائدة كما وعد الله.', 115, 2, 127, 100, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (785, 5, 1, 7, 785, 'واذكر إذ قال الله تعالى يوم القيامة: يا عيسى ابن مريم أأنت قلت للناس اجعلوني وأمي معبودين من دون الله؟ فأجاب عيسى -منزِّهًا الله تعالى-: ما ينبغي لي أن أقول للناس غير الحق. إن كنتُ قلتُ هذا فقد علمتَه؛ لأنه لا يخفى عليك شيء، تعلم ما تضمره نفسي، ولا أعلم أنا ما في نفسك. إنك أنت عالمٌ بكل شيء مما ظهر أو خفي.', 116, 2, 127, 101, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (786, 5, 1, 7, 786, 'قال عيسى عليه السلام: يا ربِّ ما قلتُ لهم إلا ما أوحيته إليَّ، وأمرتني بتبليغه من إفرادك بالتوحيد والعبادة، وكنتُ على ما يفعلونه -وأنا بين أظهرهم- شاهدًا عليهم وعلى أفعالهم وأقوالهم، فلما وفيتني أجلي على الأرض، ورفعتني إلى السماء حيًّا، كنت أنت المطَّلِع على سرائرهم، وأنت على كل شيء شهيد، لا تخفى عليك خافية في الأرض ولا في السماء.', 117, 2, 127, 101, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (787, 5, 1, 7, 787, 'إنك يا ألله إن تعذبهم فإنهم عبادك -وأنت أعلم بأحوالهم-، تفعل بهم ما تشاء بعدلك، وإن تغفر برحمتك لمن أتى منهم بأسباب المغفرة، فإنك أنت العزيز الذي لا يغالَبُ، الحكيم في تدبيره وأمره. وهذه الآية ثناء على الله -تعالى- بحكمته وعدله، وكمال علمه.', 118, 2, 127, 101, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (788, 5, 1, 7, 788, 'قال الله تعالى لعيسى عليه السلام يوم القيامة: هذا يوم الجزاء الذي ينفع الموحدين توحيدهم ربهم، وانقيادهم لشرعه، وصدقهم في نياتهم وأقوالهم وأعمالهم، لهم جنات تجري من تحت قصورها الأنهار، ماكثين فيها أبدًا، رضي الله عنهم فقبل حسناتهم، ورضوا عنه بما أعطاهم من جزيل ثوابه. ذلك الجزاء والرضا منه عليهم هو الفوز العظيم.', 119, 2, 127, 101, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (789, 5, 1, 7, 789, 'لله وحده لا شريك له ملك السموات والأرض وما فيهن، وهو -سبحانه- على كل شيء قدير لا يعجزه شيء.', 120, 2, 127, 101, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (790, 6, 1, 7, 790, 'الثناء على الله بصفاته التي كلّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، الذي أنشأ السموات والأرض وما فيهن، وخلق الظلمات والنور، وذلك بتعاقب الليل والنهار. وفي هذا دلالة على عظمة الله تعالى، واستحقاقه وحده العبادة، فلا يجوز لأحد أن يشرك به غيره. ومع هذا الوضوح فإن الكافرين يسوون بالله غيره، ويشركون به.', 1, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (791, 6, 1, 7, 791, 'هو الذي خلق أباكم آدم من طين وأنتم سلالة منه، ثم كتب مدة بقائكم في هذه الحياة الدنيا، وكتب أجلا آخر محدَّدًا لا يعلمه إلا هو جل وعلا وهو يوم القيامة، ثم أنتم بعد هذا تشكُّون في قدرة الله تعالى على البعث بعد الموت.', 2, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (792, 6, 1, 7, 792, 'والله سبحانه هو الإله المعبود في السموات والأرض. ومن دلائل ألوهيته أنه يعلم جميع ما تخفونه -أيها الناس- وما تعلنونه، ويعلم جميع أعمالكم من خير أو شر؛ ولهذا فإنه -جلَّ وعلا- وحده هو الإله المستحق للعبادة.', 3, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (793, 6, 1, 7, 793, 'هؤلاء الكفار الذين يشركون مع الله تعالى غيره قد جاءتهم الحجج الواضحة والدلالات البينة على وحدانية الله -جل وعلا- وصِدْقِ محمد صلى الله عليه وسلم في نبوته، وما جاء به، ولكن ما إن جاءتهم حتى أعرضوا عن قبولها، ولم يؤمنوا بها.', 4, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (794, 6, 1, 7, 794, 'لقد جحد هؤلاء الكفار الحقَّ الذي جاءهم به محمد صلى الله عليه وسلم وسخروا من دعائه؛ جهلا منهم بالله واغترارًا بإمهاله إياهم، فسوف يرون ما استهزءوا به أنه الحق والصدق، ويبين الله للمكذبين كذبهم وافتراءهم، ويجازيهم عليه.', 5, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (795, 6, 1, 7, 795, 'ألم يعلم هؤلاء الذين يجحدون وحدانية الله تعالى واستحقاقه وحده العبادة، ويكذبون رسوله محمدًا صلى الله عليه وسلم ما حلَّ بالأمم المكذبة قبلهم من هلاك وتدمير، وقد مكنَّاهم في الأرض ما لم نمكن لكم أيها الكافرون، وأنعمنا عليهم بإنزال الأمطار وجريان الأنهار من تحت مساكنهم؛ استدراجًا وإملاءً لهم، فكفروا بنعم الله وكذبوا الرسل، فأهلكناهم بسبب ذنونهم، وأنشأنا من بعدهم أممًا أخرى خلفوهم في عمارة الأرض؟', 6, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (796, 6, 1, 7, 796, 'ولو نزَّلنا عليك -أيها الرسول- كتابًا من السماء في أوراق فلمسه هؤلاء المشركون بأيديهم لقالوا: إنَّ ما جئت به -أيها الرسول- سحر واضح بيِّن.', 7, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (797, 6, 1, 7, 797, 'وقال هؤلاء المشركون: هلا أنزل الله تعالى على محمد مَلَكًا من السماء؛ ليصدقه فيما جاء به من النبوة، ولوأنزلنا مَلَكًّا من السماء إجابة لطلبهم لقضي الأمر بإهلاكهم، ثم لا يمهلون لتوبة، فقد سبق في علم الله أنهم لا يؤمنون.', 8, 2, 128, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (798, 6, 1, 7, 798, 'ولو جعلنا الرسول المرسل إليهم مَلَكًا إذ لم يقتنعوا بمحمد صلى الله عليه وسلم، لجعلنا ذلك الملك في صورة البشر، حتى يستطيعوا السماع منه ومخاطبته؛ إذ ليس بإمكانهم رؤية الملك على صورته الملائكية، ولو جاءهم الملك بصورة رجل لاشتبه الأمر عليهم، كما اشتبه عليهم أمر محمد صلى الله عليه وسلم.', 9, 2, 129, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (799, 6, 1, 7, 799, 'ولمَّا كان طلبهم إنزال الملك على سبيل الاستهزاء بمحمد صلى الله عليه وسلم بيَّن الله تعالى له أن الاستهزاء بالرسل عليهم السلام ليس أمرا حادثا، بل قد وقع من الكفار السابقين مع أنبيائهم، فأحاط بهم العذاب الذي كانوا يهزؤون به وينكرون وقوعه.', 10, 2, 129, 102, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (800, 6, 1, 7, 800, 'قل لهم -أيها الرسول-: سيروا في الأرض ثم انظروا كيف أعقب الله المكذبين الهلاك والخزي؟ فاحذروا مثل مصارعهم، وخافوا أن يحلَّ بكم مثل الذي حل بهم.', 11, 2, 129, 103, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (801, 6, 1, 7, 801, 'قل -أيها الرسول- لهؤلاء المشركين: لمن مُلكُ السموات والأرض وما فيهن؟ قل: هو لله كما تقرون بذلك وتعلمونه، فاعبدوه وحده. كتب الله على نفسه الرحمة فلا يعجل على عباده بالعقوبة. ليجمعنكم إلى يوم القيامة الذي لا شك فيه للحساب والجزاء. الذين أشركوا بالله أهلكوا أنفسهم، فهم لا يوحدون الله، ولا يصدقون بوعده ووعيده، ولا يقرون بنبوة محمد صلى الله عليه وسلم.', 12, 2, 129, 103, NULL, 51, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (802, 6, 1, 7, 802, 'ولله ملك كل شيء في السموات والأرض، سكن أو تحرك، خفي أو ظهر، الجميع عبيده وخلقه، وتحت قهره وتصرفه وتدبيره، وهو السميع لأقوال عباده، الحليم بحركاتهم وسرائرهم.', 13, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (803, 6, 1, 7, 803, 'قل -أيها الرسول- لهؤلاء المشركين مع الله تعالى غيره: أغير الله تعالى أتخذ وليًّا ونصيرًا، وهو خالق السموات والأرض وما فيهن، وهو الذي يرزق خلقه ولا يرزقه أحد؟ قل -أيها الرسول-: إني أُمِرْتُ أن أكون أول مَن خضع وانقاد له بالعبودية من هذه الأمة، ونهيت أن أكون من المشركين معه غيره.', 14, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (804, 6, 1, 7, 804, 'قل -أيها الرسول- لهؤلاء المشركين مع الله غيره: إني أخاف إن عصيت ربي، فخالفت أمره، وأشركت معه غيره في عبادته، أن ينزل بي عذاب عظيم يوم القيامة.', 15, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (805, 6, 1, 7, 805, 'من يصرف الله عنه ذلك العذاب الشديد فقد رحمه، وذلك الصرف هو الظفر البين بالنجاة من العذاب العظيم.', 16, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (806, 6, 1, 7, 806, 'وإن يصبك الله تعالى -أيها الإنسان- بشيء يضرك كالفقر والمرض فلا كاشف له إلا هو، وإن يصبك بخير كالغنى والصحة فلا راد لفضله ولا مانع لقضائه، فهو -جل وعلا- القادر على كل شيء.', 17, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (807, 6, 1, 7, 807, 'والله سبحانه هو الغالب القاهر فوق عباده؛ خضعت له الرقاب وذَلَّتْ له الجبابرة، وهو الحكيم الذي يضع الأشياء مواضعها وَفْق حكمت، الخبير الذي لا يخفى عليه شيء. ومن اتصف بهذه الصفات يجب ألا يشرك به. وفي هذه الآية إثبات الفوقية لله -تعالى- على جميع خلقه، فوقية مطلقة تليق بجلاله سبحانه.', 18, 2, 129, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (808, 6, 1, 7, 808, 'قل -أيها الرسول لهؤلاء المشركين-: أيُّ شيء أعظم شهادة في إثبات صدقي فيما أخبرتكم به أني رسول الله؟ قل: الله شهيد بيني وبينكم أي: هو العالم بما جئتكم به وما أنتم قائلونه لي، وأوحى الله إليَّ هذا القرآن مِن أجل أن أنذركم به عذابه أن يحلَّ بكم، وأنذر به مَن وصل إليه من الأمم. إنكم لتقرون أن مع الله معبودات أخرى تشركونها به. قل لهم -أيها الرسول-: إني لا أشهد على ما أقررتم به، إنما الله إله واحد لا شريك له، وإنني بريء من كل شريك تعبدونه معه.', 19, 2, 130, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (809, 6, 1, 7, 809, 'الذين آتيناهم التوراة والإنجيل، يعرفون محمدًا صلى الله عليه وسلم بصفاته المكتوبة عندهم كمعرفتهم أبناءهم، فكما أن أبناءهم لا يشتبهون أمامهم بغيرهم، فكذلك محمد صلى الله عليه وسلم لا يشتبه بغيره لدقة وصفه في كتبهم، ولكنهم اتبعوا أهواءهم، فخسروا أنفسهم حين كفروا بمحمد صلى الله عليه وسلم وبما جاء به.', 20, 2, 130, 103, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (810, 6, 1, 7, 810, 'لا أحد أشد ظلمًا ممَّن تَقَوَّلَ الكذب على الله تعالى، فزعم أن له شركاء في العبادة، أو ادَّعى أن له ولدًا أو صاحبة، أو كذب ببراهينه وأدلته التي أيَّد بها رسله عليهم السلام. إنه لا يفلح الظالمون الذين افتروا الكذب على الله، ولا يظفرون بمطالبهم في الدنيا ولا في الآخرة.', 21, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (811, 6, 1, 7, 811, 'وليحذر هؤلاء المشركون المكذبون بآيات الله تعالى يوم نحشرهم ثم نقول لهم: أين آلهتكم التي كنتم تدَّعون أنهم شركاء مع الله تعالى ليشفعوا لكم؟', 22, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (812, 6, 1, 7, 812, 'ثم لم تكن إجابتهم حين فتنوا واختبروا بالسؤال عن شركائهم إلا أن تبرؤوا منهم، وأقسموا بالله ربهم أنهم لم يكونوا مشركين مع الله غيره.', 23, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (813, 6, 1, 7, 813, 'تأمل -أيها الرسول- كيف كذب هؤلاء المشركون على أنفسهم وهم في الآخرة قد تبرؤوا من الشرك؟ وذهب وغاب عنهم ما كانوا يظنونه من شفاعة آلهتهم.', 24, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (814, 6, 1, 7, 814, 'ومن هؤلاء المشركين من يستمع إليك القرآن -أيها الرسول-، فلا يصل إلى قلوبهم؛ لأنهم بسبب اتباعهم أهواءهم جعلنا على قلوبهم أغطية؛ لئلا يفقهوا القرآن، وجعلنا في آذانهم ثقلا وصممًا فلا تسمع ولا تعي شيئًا، وإن يروا الآيات الكثيرة الدالة على صدق محمد صلى الله عليه وسلم لا يصدقوا بها، حتى إذا جاؤوك -أيها الرسول- بعد معاينة الآيات الدالة على صدقك يخاصمونك: يقول الذين جحدوا آيات الله: ما هذا الذي نسمع إلا ما تناقله الأولون من حكايات لا حقيقة لها.', 25, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (815, 6, 1, 7, 815, 'وهؤلاء المشركون ينهون الناس عن اتباع محمد صلى الله عليه وسلم والاستماع إليه، ويبتعدون بأنفسهم عنه، وما يهلكون -بصدهم عن سبيل الله- إلا أنفسهم، وما يحسون أنهم يعملون لهلاكها.', 26, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (816, 6, 1, 7, 816, 'ولو ترى -أيها الرسول- هؤلاء المشركين يوم القيامة لرأيت أمرًا عظيمًا، وذلك حين يُحْبَسون على النار، ويشاهدون ما فيها من السلاسل والأغلال، ورأوا بأعينهم تلك الأمور العظام والأهوال، فعند ذلك قالوا: ياليتنا نُعاد إلى الحياة الدنيا، فنصدق بآيات الله ونعمل بها، ونكون من المؤمنين.', 27, 2, 130, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (817, 6, 1, 7, 817, 'ليس الأمر كذلك، بل ظهر لهم يوم القيامة ما كانوا يعلمونه من أنفسهم من صدق ما جاءت به الرسل في الدنيا، وإن كانوا يظهرون لأتباعه خلافه. ولو فرض أن أعيدوا إلى الدنيا فأمهلوا لرجعوا إلى العناد بالكفر والتكذيب. وإنهم لكاذبون في قولهم: لو رددنا إلى الدنيا لم نكذب بآيات ربنا، وكنا من المؤمنين.', 28, 2, 131, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (818, 6, 1, 7, 818, 'وقال هؤلاء المشركون المنكرون للبعث: ما الحياة إلا هذه الحياة التي نحن فيها، وما نحن بمبعوثين بعد موتنا.', 29, 2, 131, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (819, 6, 1, 7, 819, 'ولو ترى -أيها الرسول- منكري البعث إذ حُبسوا بين يدي الله تعالى لقضائه فيهم يوم القيامة، لرأيت أسوأ حال، إذ يقول الله جل وعلا أليس هذا بالحق، أي: أليس هذا البعث الذي كنتم تنكرونه في الدنيا حقًّا؟ قالوا: بلى وربنا إنه لحق، قال الله تعالى: فذوقوا العذاب بما كنتم تكفرون أي: العذاب الذي كنتم تكذبون به في الدنيا بسبب جحودكم بالله تعالى ورسوله محمد صلى الله عليه وسلم.', 30, 2, 131, 104, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (820, 6, 1, 7, 820, 'قد خسر الكفار الذين أنكروا البعث بعد الموت، حتى إذا قامت القيامة، وفوجئوا بسوء المصير، نادَوا على أنفسهم بالحسرة على ما ضيَّعوه في حياتهم الدنيا، وهم يحملون آثامهم على ظهورهم، فما أسوأ الأحمال الثقيلة السيئة التي يحملونها!!', 31, 2, 131, 105, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (821, 6, 1, 7, 821, 'وما الحياة الدنيا في غالب أحوالها إلا غرور وباطل، والعمل الصالح للدار الآخرة خير للذين يخشون الله، فيتقون عذابه بطاعته واجتناب معاصيه. أفلا تعقلون -أيها المشركون المغترون بزينة الحياة الدنيا- فتقدِّموا ما يبقى على ما يفنى؟', 32, 2, 131, 105, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (822, 6, 1, 7, 822, 'إنا نعلم إنه ليُدْخل الحزنَ إلى قلبك تكذيبُ قومك لك في الظاهر، فاصبر واطمئن؛ فإنهم لا يكذبونك في قرارة أنفسهم، بل يعتقدون صدقك، ولكنهم لظلمهم وعدوانهم يجحدون البراهين الواضحة على صدقك، فيكذبونك فيما جئت به.', 33, 2, 131, 105, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (823, 6, 1, 7, 823, 'ولقد كذَّب الكفارُ رسلا من قبلك أرسلهم الله تعالى إلى أممهم وأوذوا في سبيله، فصبروا على ذلك ومضوا في دعوتهم وجهادهم حتى أتاهم نصر الله. ولا مبدل لكلمات الله، وهي ما أنزل على نبيه محمد صلى الله عليه وسلم مِن وعده إياه بالنصر على مَن عاداه. ولقد جاءك -أيها الرسول- مِن خبر مَن كان قبلك من الرسل، وما تحقق لهم من نصر الله، وما جرى على مكذبيهم من نقمة الله منهم وغضبه عليهم، فلك فيمن تقدم من الرسل أسوة وقدوة. وفي هذا تسلية للرسول صلى الله عليه وسلم.', 34, 2, 131, 105, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (824, 6, 1, 7, 824, 'وإن كان عَظُمَ عليك -أيها الرسول- صدود هؤلاء المشركين وانصرافهم عن الاستجابة لدعوتك، فإن استطعت أن تتخذ نفقًا في الأرض، أو مصعدًا تصعد فيه إلى السماء، فتأتيهم بعلامة وبرهان على صحة قولك غير الذي جئناهم به فافعل. ولو شاء الله لَجَمعهم على الهدى الذي أنتم عليه ووفَّقهم للإيمان، ولكن لم يشأ ذلك لحكمة يعلمها سبحانه، فلا تكونن -أيها الرسول- من الجاهلين الذين اشتد حزنهم، وتحسَّروا حتى أوصلهم ذلك إلى الجزع الشديد.', 35, 2, 131, 105, NULL, 52, 13);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (825, 6, 1, 7, 825, 'إنما يجيبك -أيها الرسول- إلى ما دعوت إليه من الهدى الذين يسمعون الكلام سماع قبول. أما الكفار فهم في عداد الموتى؛ لأن الحياة الحقيقية إنما تكون بالإسلام. والموتى يخرجهم الله من قبورهم أحياء، ثم يعودون إليه يوم القيامة ليوفوا حسابهم وجزاءهم.', 36, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (826, 6, 1, 7, 826, 'وقال المشركون -تعنتًا واستكبارًا-: هلا أنزل الله علامة تدل على صدق محمد صلى الله عليه وسلم من نوع العلامات الخارقة، قل لهم -أيها الرسول-: إن الله قادر على أن ينزل عليهم آية، ولكن أكثرهم لا يعلمون أن إنزال الآيات إنما يكون وَفْق حكمته تعالى.', 37, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (827, 6, 1, 7, 827, 'ليس في الأرض حيوان يَدِبُّ على الأرض أو طائر يطير في السماء بجناحيه إلا جماعات متجانسة الخلق مثلكم. ما تركنا في اللوح المحفوظ شيئًا إلا أثبتناه، ثم إنهم إلى ربهم يحشرون يوم القيامة، فيحاسب الله كلا بما عمل.', 38, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (828, 6, 1, 7, 828, 'والذين كذبوا بحجج الله تعالى صمٌّ لا يسمعون ما ينفعهم، بُكْمٌ لا يتكلمون بالحق، فهم حائرون في الظلمات، لم يختاروا طريقة الاستقامة. من يشأ الله إضلاله يضلله، ومن يشأ هدايته يجعله على صراط مستقيم.', 39, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (829, 6, 1, 7, 829, 'قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن جاءكم عذاب الله في الدنيا أو جاءتكم الساعة التي تبعثون فيها: أغير الله تدعون هناك لكشف ما نزل بكم من البلاء، إن كتم محقين في زعمكم أن آلهتكم التي تعبدونها من دون الله تنفع أو تضر؟', 40, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (830, 6, 1, 7, 830, 'بل تدعون -هناك- ربكم الذي خلقكم لا غيره، وتستغيثون به، فيفرج عنكم البلاء العظيم النازل بكم إن شاء؛ لأنه القادر على كل شيء، وتتركون حينئذ أصنامكم وأوثانكم وأولياءكم.', 41, 2, 132, 105, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (831, 6, 1, 7, 831, 'ولقد بعثنا -أيها الرسول- إلى جماعات من الناس من قبلك رسلا يدعونهم إلى الله تعالى، فكذَّبوهم، فابتليناهم في أموالهم بشدة الفقر وضيق المعيشة، وابتليناهم في أجسامهم بالأمراض والآلام؛ رجاء أن يتذللوا لربهم، ويخضعوا له وحده بالعبادة.', 42, 2, 132, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (832, 6, 1, 7, 832, 'فهلا إذ جاء هذه الأمم المكذبة بلاؤنا تذللوا لنا، ولكن قست قلوبهم، وزيَّن لهم الشيطان ما كانوا يعملون من المعاصي، ويأتون من الشرك.', 43, 2, 132, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (833, 6, 1, 7, 833, 'فلما تركوا العمل بأوامر الله تعالى معرضين عنها، فتحنا عليهم أبواب كل شيء من الرزق فأبدلناهم بالبأساء رخاءً في العيش، وبالضراء صحة في الأجسام؛ استدراجا منا لهم، حتى إذا بطروا، وأعجبوا بما أعطيناهم من الخير والنعمة أخذناهم بالعذاب فجأة، فإذا هم آيسون منقطعون من كل خير.', 44, 2, 132, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (834, 6, 1, 7, 834, 'فاستؤصل هؤلاء القوم وأُهلكوا إذ كفروا بالله وكذَّبوا رسله، فلم يبق منهم أحد. والشكر والثناء لله تعالى -خالق كل شيء ومالكه- على نصرة أوليائه وهلاك أعدائه.', 45, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (835, 6, 1, 7, 835, 'قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أذهب الله سمعكم فأصمَّكم، وذهب بأبصاركم فأعماكم، وطبع على قلوبكم فأصبحتم لا تفقهون قولا أيُّ إله غير الله جل وعلا يقدر على ردِّ ذلك لكم؟! انظر -أيها الرسول- كيف ننوِّع لهم الحجج، ثم هم بعد ذلك يعرضون عن التذكر والاعتبار؟', 46, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (836, 6, 1, 7, 836, 'قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن نزل بكم عقاب الله فجأة وأنتم لا تشعرون به، أو ظاهرًا عِيانًا وأنتم تنظرون إليه: هل يُهلك إلا القوم الظالمون الذين تجاوزوا الحد، بصرفهم العبادة لغير الله تعالى وبتكذيبهم رسله؟', 47, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (837, 6, 1, 7, 837, 'وما نرسل رسلنا إلا مبشرين أهل طاعتنا بالنعيم المقيم، ومنذرين أهل المعصية بالعذاب الأليم، فمن آمن وصدَّق الرسل وعمل صالحًا فأولئك لا يخافون عند لقاء ربهم، ولا يحزنون على شيء فاتهم من حظوظ الدنيا.', 48, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (838, 6, 1, 7, 838, 'والذين كذَّبوا بآياتنا من القرآن والمعجزات فأولئك يصيبهم العذاب يوم القيامة، بسبب كفرهم وخروجهم عن طاعة الله تعالى.', 49, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (839, 6, 1, 7, 839, 'قل -أيها الرسول- لهؤلاء المشركين: إني لا أدَّعي أني أملك خزائن السموات والأرض، فأتصرف فيها، ولا أدَّعي أني أعلم الغيب، ولا أدَّعي أني ملك، وإنما أنا رسول من عند الله، أتبع ما يوحى إليَّ، وأبلِّغ وحيه إلى الناس، قل -أيها الرسول- لهؤلاء المشركين: هل يستوي الكافر الذي عَمِي عن آيات الله تعالى فلم يؤمن بها والمؤمن الذي أبصر آيات الله فآمن بها؟ أفلا تتفكرون في آيات الله؛ لتبصروا الحق فتؤمنوا به؟', 50, 2, 133, 106, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (840, 6, 1, 7, 840, 'وخوِّف -أيها النبي- بالقرآن الذين يعلمون أنهم يُحشرون إلى ربهم، فهم مصدِّقون بوعد الله ووعيده، ليس لهم غير الله وليّ ينصرهم، ولا شفيع يشفع لهم عنده تعالى، فيخلصهم من عذابه؛ لعلهم يتقون الله تعالى بفعل الأوامر واجتناب النواهي.', 51, 2, 133, 107, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (841, 6, 1, 7, 841, 'ولا تُبْعد -أيها النبي- عن مجالستك ضعفاء المسلمين الذين يعبدون ربهم أول النهار وآخره، يريدون بأعمالهم الصالحة وجه الله، ما عليك من حساب هؤلاء الفقراء من شيء، إنما حسابهم على الله، وليس عليهم شيء من حسابك، فإن أبعدتهم فإنك تكون من المتجاوزين حدود الله، الذين يضعون الشيء في غير موضعه.', 52, 2, 133, 107, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (842, 6, 1, 7, 842, 'وكذالك ابتلى الله تعالى بعض عباده ببعض بتباين حظوظهم من الأرزاق والأخلاق، فجعل بعضهم غنيًّا وبعضهم فقيرًا، وبعضهم قويًّا وبعضهم ضعيفًا، فأحوج بعضهم إلى بعض اختبارًا منه لهم بذلك؛ ليقول الكافرون الأغنياء: أهؤلاء الضعفاء مَنَّ الله عليهم بالهداية إلى الإسلام مِن بيننا؟ أليس الله تعالى بأعلم بمن يشكرون نعمته، فيوفقهم إلى الهداية لدينه؟', 53, 2, 134, 107, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (843, 6, 1, 7, 843, 'وإذا جاءك -أيها النبي- الذين صَدَّقوا بآيات الله الشاهدة على صدقك من القرآن وغيره مستفتين عن التوبة من ذنوبهم السابقة، فأكرِمْهم بردِّ السلام عليهم، وبَشِّرهم برحمة الله الواسعة؛ فإنه جلَّ وعلا قد كتب على نفسه الرحمة بعباده تفضلا أنه من اقترف ذنبًا بجهالة منه لعاقبتها وإيجابها لسخط الله -فكل عاص لله مخطئًا أو متعمدًا فهو جاهل بهذا الاعتبار وإن كان عالمًا بالتحريم- ثم تاب من بعده وداوم على العمل الصالح، فإنه تعالى يغفر ذنبه، فهو غفور لعباده التائبين، رحيم بهم.', 54, 2, 134, 107, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (844, 6, 1, 7, 844, 'ومثل هذا البيان الذي بيَّنَّاه لك -أيها الرسول- نبيِّن الحجج الواضحة على كل حق ينكره أهل الباطل؛ ليتبين الحق، وليظهر طريق أهل الباطل المخالفين للرسل.', 55, 2, 134, 107, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (845, 6, 1, 7, 845, 'قل -أيها الرسول- لهؤلاء المشركين: إن الله عز وجل نهاني أن أعبد الأوثان التي تعبدونها من دونه، وقل لهم: لا أتبع أهواءكم قد ضللت عن الصراط المستقيم إن اتبعت أهواءَكم، وما أنا من المهتدين.', 56, 2, 134, 108, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (846, 6, 1, 7, 846, 'قل -أيها الرسول لهؤلاء المشركين-: إني على بصيرة واضحة من شريعة الله التي أوحاها إليَّ، وذلك بإفراده وحده بالعبادة، وقد كذَّبتم بهذا، وليس في قدرتي إنزال العذاب الذي تستعجلون به، وما الحكم في تأخر ذلك إلا إلى الله تعالى، يقصُّ الحقَّ، وهو خير مَن يفصل بين الحق والباطل بقضائه وحكمه.', 57, 2, 134, 108, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (847, 6, 1, 7, 847, 'قل -أيها الرسول-: لو أنني أملك إنزال العذاب الذي تستحجلونه لأنزلته بكم، وقضي الأمر بيني وبينكم، ولكن ذلك إلى الله تعالى، وهو أعلم بالظالمين الذين تجاوزوا حدَّهم فأشركوا معه غيره.', 58, 2, 134, 108, NULL, 53, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (848, 6, 1, 7, 848, 'وعند الله -جل وعلا- مفاتح الغيب أي: خزائن الغيب، لا يعلمها إلا هو، ومنها: علم الساعة، ونزول الغيث، وما في الأرحام، والكسب في المستقبل، ومكان موت الإنسان، ويعلم كل ما في البر والبحر، وما تسقط من ورقة من نبتة إلا يعلمها، فكل حبة في خفايا الأرض، وكل رطب ويابس، مثبت في كتاب واضح لا لَبْس فيه، وهو اللوح المحفوظ.', 59, 2, 134, 108, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (849, 6, 1, 7, 849, 'وهو سبحانه الذي يقبض أرواحكم بالليل بما يشبه قبضها عند الموت، ويعلم ما اكتسبتم في النهار من الأعمال، ثم يعيد أرواحكم إلى أجسامكم باليقظة من النوم نهارًا بما يشبه الأحياء بعد الموت؛ لتُقضى آجالكم المحددة في الدنيا، ثم إلى الله تعالى معادكم بعد بعثكم من قبوركم أحياءً، ثم يخبركم بما كنتم تعملون في حياتكم الدنيا، ثم يجازيكم بذلك.', 60, 2, 135, 108, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (850, 6, 1, 7, 850, 'والله تعالى هو القاهر فوق عباده، فوقية مطلقة من كل وجه، تليق بجلاله سبحانه وتعالى. كل شيء خاضع لجلاله وعظمته، ويرسل على عباده ملائكة، يحفظون أعمالهم ويُحْصونها، حتى إذا نزل الموت بأحدهم قبض روحَه مَلكُ الموت وأعوانه، وهم لا يضيعون ما أُمروا به.', 61, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (851, 6, 1, 7, 851, 'ثم أعيد هؤلاء المتوفون إلى الله تعالى مولاهم الحق. ألا له القضاء والفصل يوم القيامة بين عباده وهو أسرع الحاسبين.', 62, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (852, 6, 1, 7, 852, 'قل -أيها الرسول- لهؤلاء المشركين: من ينقذكم من مخاوف ظلمات البر والبحر؟ أليس هو الله تعالى الذي تدعونه في الشدائد متذللين جهرًا وسرًّا؟ تقولون: لئن أنجانا ربنا من هذه المخاوف لنكونن من الشاكرين بعبادته عز وجل وحده لا شريك له.', 63, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (853, 6, 1, 7, 853, 'قل لهم -أيها الرسول-: الله وحده هو الذي ينقذكم من هذه المخاوف ومن كل شدة، ثم أنتم بعد ذلك تشركون معه في العبادة غيره.', 64, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (854, 6, 1, 7, 854, 'قل -أيها الرسول-: الله عز وجل هو القادر وحده على أن يرسل عليكم عذابًا مِن فوقكم كالرَّجْم أو الطوفان، وما أشبه ذلك، أو من تحت أرجلكم كالزلازل والخسف، أو يخلط أمركم عليكم فتكونوا فرقًا متناحرة يقتل بعضكم بعضًا. انظر -أيها الرسول- كيف نُنوِّع حججنا الواضحات لهؤلاء المشركين لعلهم يفهمون فيعتبروا؟', 65, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (855, 6, 1, 7, 855, 'وكذَّب بهذا القرآن الكفارُ مِن قومك أيها الرسول، وهو الكتاب الصادق في كل ما جاء به. قل لهم: لست عليكم بحفيظ ولا رقيب، وإنما أنا رسول الله أبلغكم ما أرسلت به.', 66, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (856, 6, 1, 7, 856, 'لكل خبر قرار يستقر عنده، ونهاية ينتهي إليها، فيتبيَّن الحق من الباطل، وسوف تعلمون -أيها الكفار- عاقبة أمركم عند حلول عذاب الله بكم.', 67, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (857, 6, 1, 7, 857, 'وإذا رأيت -أيها الرسول- المشركين الذين يتكلمون في آيات القرآن بالباطل والاستهزاء، فابتعد عنهم حتى يأخذوا في حديث آخر، وإن أنساك الشيطان هذا الأمر فلا تقعد بعد تذكرك مع القوم المعتدين، الذين تكلموا في آيات الله بالباطل.', 68, 2, 135, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (858, 6, 1, 7, 858, 'وما على المؤمنين الذين يخافون الله تعالى، فيطيعون أوامره، ويجتنبون نواهيه من حساب الله للخائضين المستهزئين بآيات الله من شيء، ولكن عليهم أن يعظوهم ليمسكوا عن ذلك الكلام الباطل، لعلهم يتقون الله تعالى.', 69, 2, 136, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (859, 6, 1, 7, 859, 'واترك -أيها الرسول- هؤلاء المشركين الذين جعلوا دين الإسلام لعبًا ولهوًا؛ مستهزئين بآيات الله تعالى، وغرَّتهم الحياة الدنيا بزينتها، وذكّر بالقرآن هؤلاء المشركين وغيرهم؛ كي لا ترتهن نفس بذنوبها وكفرها بربها، ليس لها غير الله ناصر ينصرها، فينقذها من عذابه، ولا شافع يشفع لها عنده، وإن تَفْتَدِ بأي فداء لا يُقْبَل منها. أولئك الذين ارتُهِنوا بذنوبهم، لهم في النار شراب شديد الحرارة وعذاب موجع؛ بسبب كفرهم بالله تعالى ورسوله محمَّد صلى الله عليه وسلم وبدين الإسلام.', 70, 2, 136, 109, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (860, 6, 1, 7, 860, 'قل -أيها الرسول- لهؤلاء المشركين: أنعبد من دون الله تعالى أوثانًا لا تنفع ولا تضر؟ ونرجع إلى الكفر بعد هداية الله تعالى لنا إلى الإسلام، فنشبه -في رجوعنا إلى الكفر- مَن فسد عقله باستهواء الشياطين له، فَضَلَّ في الأرض، وله رفقة عقلاء مؤمنون يدعونه إلى الطريق الصحيح الذي هم عليه فيأبى. قل -أيها الرسول- لهؤلاء المشركين: إنَّ هدى الله الذي بعثني به هو الهدى الحق، وأُمِرنا جميعًا لنسلم لله تعالى رب العالمين بعبادته وحده لا شريك له، فهو رب كل شيء ومالكه.', 71, 2, 136, 110, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (861, 6, 1, 7, 861, 'وكذلك أُمرنا بأن نقيم الصلاة كاملة، وأن نخشاه بفعل أوامره واجتناب نواهيه. وهو -جل وعلا- الذي إليه تُحْشَرُ جميع الخلائق يوم القيامة.', 72, 2, 136, 110, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (862, 6, 1, 7, 862, 'والله سبحانه هو الذي خلق السموات والأرض بالحق، واذكر -أيها الرسول- يوم القيامة إذ يقول الله: "كن"، فيكون عن أمره كلمح البصر أو هو أقرب، قوله هو الحق الكامل، وله الملك سبحانه وحده، يوم ينفخ المَلَك في "القرن" النفخة الثانية التي تكون بها عودة الأرواح إلى الأجسام. وهو سبحانه الذي يعلم ما غاب عن حواسكم -أيها الناس - وما تشاهدونه، وهو الحكيم الذي يضع الأمور في مواضعها، الخبير بأمور خلقه. والله تعالى هو الذي يختص بهذه الأمور وغيرها بدءًا ونهاية، نشأة ومصيرًا، وهو وحده الذي يجب على العباد الانقياد لشرعه، والتسليم لحكمه، والتطلع لرضوانه ومغفرته.', 73, 2, 136, 110, NULL, 54, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (863, 6, 1, 7, 863, 'واذكر -أيها الرسول- مُحاجَّة إبراهيم عليه السلام لأبيه آزر، إذ قال له: أتجعل من الأصنام آلهة تعبدها من دون الله تعالى؟ إني أراك وقومك في ضلال بيِّن عن طريق الحق.', 74, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (864, 6, 1, 7, 864, 'وكما هدينا إبراهيم عليه السلام إلى الحق في أمر العبادة نُريه ما تحتوي عليه السموات والأرض من ملك عظيم، وقدرة باهرة، ليكون من الراسخين في الإيمان.', 75, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (865, 6, 1, 7, 865, 'فلما أظلم على إبراهيم عليه السلام الليل وغطَّاه ناظر قومه؛ ليثبت لهم أن دينهم باطل، وكانوا يعبدون النجوم. رأى إبراهيم عليه السلام كوكبًا، فقال -مستدرجا قومه لإلزامهم بالتوحيد-: هذا ربي، فلما غاب الكوكب، قال: لا أحب الآلهة التي تغيب.', 76, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (866, 6, 1, 7, 866, 'فلما رأى إبراهيم القمر طالعًا قال لقومه -على سبيل استدراج الخصم-: هذا ربي، فلما غاب، قال -مفتقرا إلى هداية ربه-: لئن لم يوفقني ربي إلى الصواب في توحيده، لأكونن من القوم الضالين عن سواء السبيل بعبادة غير الله تعالى.', 77, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (867, 6, 1, 7, 867, 'فلما رأى الشمس طالعة قال لقومه: هذا ربي، هذا أكبر من الكوكب والقمر، فلما غابت، قال لقومه: إني بريء مما تشركون من عبادة الأوثان والنجوم والأصنام التي تعبدونها من دون الله تعالى.', 78, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (868, 6, 1, 7, 868, 'إني توجَّهت بوجهي في العبادة لله عز وجل وحده، فهو الذي خلق السموات والأرض، مائلا عن الشرك إلى التوحيد، وما أنا من المشركين مع الله غيره.', 79, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (869, 6, 1, 7, 869, 'وجادله قومه في توحيد الله تعالى قال: أتجادلونني في توحيدي لله بالعبادة، وقد وفقني إلى معرفة وحدانيته، فإن كنتم تخوفونني بآلهتكم أن توقع بي ضررًا فإنني لا أرهبها فلن تضرني، إلا أن يشاء ربي شيئًا. وسع ربي كل شيء علمًا. أفلا تتذكرون فتعلموا أنه وحده المعبود المستحق للعبودية؟', 80, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (870, 6, 1, 7, 870, 'وكيف أخاف أوثانكم وأنتم لا تخافون ربي الذي خلقكم، وخلق أوثانكم التي أشركتموها معه في العبادة، من غير حجة لكم على ذلك؟ فأي الفريقين: فريق المشركين وفريق الموحدين أحق بالطمأنينة والسلامة والأمن من عذاب الله؟ إن كنتم تعلمون صدق ما أقول فأخبروني.', 81, 2, 137, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (871, 6, 1, 7, 871, 'الذين صدَّقوا الله ورسوله وعملوا بشرعه ولم يخلطوا إيمانهم بشرك، أولئك لهم الطمأنينة والسلامة، وهم الموفقون إلى طريق الحق.', 82, 2, 138, 110, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (872, 6, 1, 7, 872, 'وتلك الحجة التي حاجَّ بها إبراهيم عليه السلام قومه هي حجتنا التي وفقناه إليها حتى انقطعت حجتهم. نرفع مَن نشاء من عبادنا مراتب في الدنيا والآخرة. إن ربك حكيم في تدبير خلقه، عليم بهم.', 83, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (873, 6, 1, 7, 873, 'ومننَّا على إبراهيم عليه السلام بأن رزقناه إسحاق ابنًا ويعقوب حفيدًا، ووفَّقنا كلا منهما لسبيل الرشاد، وكذلك وفَّقنا للحق نوحًا -من قبل إبراهيم وإسحاق ويعقوب- وكذلك وفَّقنا للحق من ذرية نوح داود وسليمان وأيوب ويوسف وموسى وهارون عليهم السلام، وكما جزينا هؤلاء الأنبياء لإحسانهم نجزي كل محسن.', 84, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (874, 6, 1, 7, 874, 'وكذلك هدينا زكريا ويحيى وعيسى وإلياس، وكل هؤلاء الأنبياء عليهم السلام من الصالحين.', 85, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (875, 6, 1, 7, 875, 'وهدينا كذلك إسماعيل واليسع ويونس ولوطا، وكل هؤلاء الرسل فضَّلناهم على أهل زمانهم.', 86, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (876, 6, 1, 7, 876, 'وكذلك وفَّقنا للحق من شئنا هدايته من آباء هؤلاء وذرياتهم وإخوانهم، واخترناهم لديننا وإبلاغ رسالتنا إلى مَن أرسلناهم إليهم، وأرشدناهم إلى طريق صحيح، لا عوج فيه، وهو توحيد الله تعالى وتنزيهه عن الشرك.', 87, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (877, 6, 1, 7, 877, 'ذلك الهدى هو توفيق الله، الذي يوفق به من يشاء من عباده. ولو أن هؤلاء الأنبياء أشركوا بالله -على سبيل الفرض والتقدير- لبطل عملهم؛ لأن الله تعالى لا يقبل مع الشرك عملا.', 88, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (878, 6, 1, 7, 878, 'أولئك الأنبياء الذين أنعمنا عليهم بالهداية والنبوة هم الذين آتيناهم الكتاب كصحف إبراهيم وتوراة موسى وزبور داود وإنجيل عيسى، وآتيناهم فَهْمَ هذه الكتب، واخترناهم لإبلاغ وحينا، فإن يجحد -أيها الرسول- بآيات هذا القرآن الكفارُ من قومك، فقد وكلنا بها قومًا آخرين -أي: المهاجرين والأنصار وأتباعهم إلى يوم القيامة- ليسوا بها بكافرين، بل مؤمنون بها، عاملون بما تدل عليه.', 89, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (879, 6, 1, 7, 879, 'أولئك الأنبياء المذكورون هم الذين وفقهم الله تعالى لدينه الحق، فاتبع هداهم -أيها الرسول- واسلك سبيلهم. قل للمشركين: لا أطلب منكم على تبليغ الإسلام عوضًا من الدنيا، إنْ أجري إلا على الله، وما الإسلام إلا دعوة جميع الناس إلى الطريق المستقيم وتذكير لكم ولكل مَن كان مثلكم، ممن هو مقيم على باطل، لعلكم تتذكرون به ما ينفعكم.', 90, 2, 138, 111, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (880, 6, 1, 7, 880, 'وما عَظَّم هؤلاء المشركون الله حق تعظيمه؛ إذ أنكروا أن يكون الله تعالى قد أنزل على أحد من البشر شيئًا من وحيه. قل لهم -أيها الرسول-: إذا كان الأمر كما تزعمون، فمن الذي أنزل الكتاب الذي جاء به موسى إلى قومه نورًا للناس وهداية لهم؟ ثم توجه الخطاب إلى اليهود زَجْرًا لهم بقوله: تجعلون هذا الكتاب في قراطيس متفرقة، تظهرون بعضها، وتكتمون كثيرًا منها، ومما كتموه الإخبار عن صفة محمد صلى الله عليه وسلم ونبوته، وعلَّمكم الله معشر العرب بالقرآنِ -الذي أنزله عليكم، فيه خبر مَن قبلكم ومَن بعدكم، وما يكون بعد موتكم- ما لم تعلموه أنتم ولا آباؤكم، قل: الله هو الذي أنزله، ثم دع هؤلاء في حديثهم الباطل يخوضون ويلعبون.', 91, 2, 139, 112, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (881, 6, 1, 7, 881, 'وهذا القرآن كتاب أنزلناه إليك -أيها الرسول- عظيم النفع، مصدق لما تقدمه من الكتب السماوية، أنزلناه لنخوِّف به من عذاب الله وبأسه أهل "مكة" ومن حولها من أهل أقطار الأرض كلها. والذين يصدقون بالحياة الآخرة، يصدقون بأن القرآن كلام الله، ويحافظون على إقام الصلاة في أوقاتها.', 92, 2, 139, 112, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (882, 6, 1, 7, 882, 'ومَن أشدُّ ظلمَّا ممَّن اختلق على الله تعالى قولا كذبًا، فادعى أنه لم يبعث رسولا من البشر، أو ادعى كذبًا أن الله أوحى إليه ولم يُوحِ إليه شيئًا، أو ادَّعى أنه قادر على أن يُنْزل مثل ما أنزل الله من القرآن؟ ولو أنك أبصرت -أيها الرسول- هؤلاء المتجاوزين الحدَّ وهم في أهوال الموت لرأيت أمرًا هائلا والملائكة الذين يقبضون أرواحهم باسطو أيديهم بالعذاب قائلين لهم: أخرجوا أنفسكم، اليوم تهانون غاية الإهانة، كما كنتم تكذبون على الله، وتستكبرون عن اتباع آياته والانقياد لرسله.', 93, 2, 139, 112, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (883, 6, 1, 7, 883, 'ولقد جئتمونا للحساب والجزاء فرادى كما أوجدناكم في الدنيا أول مرة حفاة عراة، وتركتم وراء ظهوركم ما مكنَّاكم فيه مما تتباهون به من أموال في الدنيا، وما نرى معكم في الآخرة أوثانكم التي كنتم تعتقدون أنها تشفع لكم، وتَدَّعون أنها شركاء مع الله في العبادة، لقد زال تَواصُلُكم الذي كان بينكم في الدنيا، وذهب عنكم ما كنتم تَدَّعون من أن آلهتكم شركاء لله في العبادة، وظهر أنكم الخاسرون لأنفسكم وأهليكم وأموالكم.', 94, 2, 139, 112, NULL, 55, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (884, 6, 1, 7, 884, 'إن الله تعالى يشق الحب، فيخرج منه الزرع، ويشق النوى، فيخرج منه الشجر، يخرج الحي من الميت كالإنسان والحيوان مثلا من النطفة، ويخرج الميت من الحي كالنطفة من الإنسان والحيوان، ذلكم الله أي: فاعل هذا هو الله وحده لا شريك له المستحق للعبادة، فكيف تُصْرَفون عن الحق إلى الباطل فتعبدون معه غيره؟', 95, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (885, 6, 1, 7, 885, 'والله سبحانه وتعالى هو الذي شق ضياء الصباح من ظلام الليل، وجعل الليل مستقرًا، يسكن فيه كل متحرك ويهدأ، وجعل الشمس والقمر يجريان في فلكيهما بحساب متقن مقدَّر، لا يتغير ولا يضطرب، ذلك تقدير العزيز الذي عزَّ سلطانه، العليم بمصالح خلقه وتدبير شئونهم. والعزيز والعليم من أسماء الله الحسنى يدلان على كمال العز والعلم.', 96, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (886, 6, 1, 7, 886, 'والله سبحانه هو الذي جعل لكم أيها الناس النجوم علامات، تعرفون بها الطرق ليلا إذا ضللتم بسبب الظلمة الشديدة في البر والبحر، قد بيَّنَّا البراهين الواضحة؛ ليتدبرها منكم أولو العلم بالله وشرعه.', 97, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (887, 6, 1, 7, 887, 'والله سبحانه هو الذي ابتدأ خلقكم أيها الناس من آدم عليه السلام؛ إذ خلقه من طين، ثم كنتم سلالة ونسلا منه، فجعل لكم مستقَرًا تستقرون فيه، وهو أرحام النساء، ومُستودعًا تُحفَظُون فيه، وهو أصلاب الرجال، قد بينا الحجج وميزنا الأدلة، وأحكمناها لقوم يفهمون مواقع الحجج ومواضع العبر.', 98, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (888, 6, 1, 7, 888, 'والله سبحانه هو الذي أنزل من السحاب مطرًا فأخرج به نبات كل شيء، فأخرج من النبات زرعًا وشجرًا أخضر، ثم أخرج من الزرع حَبًّا يركب بعضه بعضًا، كسنابل القمح والشعير والأرز، وأخرج من طلع النخل -وهو ما تنشأ فيه عذوق الرطب- عذوقًا قريبة التناول، وأخرج سبحانه بساتين من أعناب، وأخرج شجر الزيتون والرمان الذي يتشابه في ورقه ويختلف في ثمره شكلا وطعمًا وطبعًا. انظروا أيها الناس إلى ثمر هذا النبات إذا أثمر، وإلى نضجه وبلوغه حين يبلغ. إن في ذلكم - أيها الناس - لدلالات على كمال قدرة خالق هذه الأشياء وحكمته ورحمته لقوم يصدقون به تعالى ويعملون بشرعه.', 99, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (889, 6, 1, 7, 889, 'وجعل هؤلاء المشركون الجن شركاء لله تعالى في العبادة؛ اعتقادًا منهم أنهم ينفعون أو يضرون، وقد خلقهم الله تعالى وما يعبدون من العدم، فهو المستقل بالخلق وحده، فيجب أن يستقل بالعبادة وحده لا شريك له. ولقد كذب هؤلاء المشركون على الله تعالى حين نسبوا إليه البنين والبنات؛ جهلا منهم بما يجب له من صفات الكمال، تنزَّه وعلا عما نسبه إليه المشركون من ذلك الكذب والافتراء.', 100, 2, 140, 113, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (890, 6, 1, 7, 890, 'والله تعالى هو الذي أوجد السموات والأرض وما فيهن على غير مثال سابق. كيف يكون له ولد ولم تكن له صاحبة؟ تعالى الله عما يقول المشركون علوًّا كبيرًا، وهو الذي خلق كل شيء من العدم، ولا يخفى عليه شيء من أمور الخلق.', 101, 2, 140, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (891, 6, 1, 7, 891, 'ذلكم -أيها المشركون- هو ربكم جل وعلا لا معبود بحق سواه، خالق كل شيء فانقادوا واخضعوا له بالطاعة والعبادة. وهو سبحانه على كل شيء وكيل وحفيظ، يدبر أمور خلقه.', 102, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (892, 6, 1, 7, 892, 'لا ترى اللهَ الأبصارُ في الدنيا، أما في الدار الآخرة فإن المؤمنين يرون ربهم بغير إحاطة، وهو سبحانه يدرك الأبصار ويحيط بها، ويعلمها على ما هي عليه، وهو اللطيف بأوليائه الذي يعلم دقائق الأشياء، الخبير الذي يعلم بواطنها.', 103, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (893, 6, 1, 7, 893, 'قل -أيها الرسول- لهؤلاء المشركين: قد جاءتكم براهين ظاهرة تبصرون بها الهدى من الضلال، مما اشتمل عليها القرآن، وجاء بها الرسول عليه الصلاة والسلام، فمَن تبيَّن هذه البراهين وآمن بمدلولها فنَفْعُ ذلك لنفسه، ومَن لم يبصر الهدى بعد ظهور الحجة عليه فعلى نفسه جنى، وما أنا عليكم بحافظ أحصي أعمالكم، وإنما أنا مبلغ، والله يهدي مَن يشاء ويضل مَن يشاء وَفْق علمه وحكمته.', 104, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (894, 6, 1, 7, 894, 'وكما بيَّنَّا في هذا القرآن للمشركين البراهين الظاهرة في أمر التوحيد والنبوة والمعاد نبيِّن لهم البراهين في كل ما جهلوه فيقولون عند ذلك كذبًا: تعلمت من أهل الكتاب، ولنبين -بتصريفنا الآيات- الحقَّ لقوم يعلمونه، فيقبلونه ويتبعونه، وهم المؤمنون برسول الله محمد صلى الله عليه وسلم وما أنزل عليه.', 105, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (895, 6, 1, 7, 895, 'اتبع -أيها الرسول- ما أوحيناه إليك من الأوامر والنواهي التي أعظمُها توحيد الله سبحانه والدعوة إليه، ولا تُبال بعناد المشركين، وادعائهم الباطل.', 106, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (896, 6, 1, 7, 896, 'ولو شاء الله تعالى أن لا يشرك هؤلاء المشركون لما أشركوا، لكنه تعالى عليم بما سيكون من سوء اختيارهم واتباعهم أهواءهم المنحرفة. وما جعلناك -أيها الرسول- عليهم رقيبًا تحفظ عليهم أعمالهم، وما أنت بقَيِّمٍ عليهم تدبر مصالحهم.', 107, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (897, 6, 1, 7, 897, 'ولا تسبوا -أيها المسلمون- الأوثان التي يعبدها المشركون -سدًّا للذريعة- حتى لا يتسبب ذلك في سبهم الله جهلا واعتداءً: بغير علم. وكما حسَّنَّا لهؤلاء عملهم السيئ عقوبة لهم على سوء اختيارهم، حسَّنَّا لكل أمة أعمالها، ثم إلى ربهم معادهم جميعًا فيخبرهم بأعمالهم التي كانوا يعملونها في الدنيا، ثم يجازيهم بها.', 108, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (898, 6, 1, 7, 898, 'وأقسم هؤلاء المشركون بأيمان مؤكَّدة: لئن جاءنا محمد بعلامة خارقة لنصدقنَّ بما جاء به، قل -أيها الرسول-: إنما مجيء المعجزات الخارقة من عند الله تعالى، هو القادر على المجيء بها إذا شاء، وما يدريكم أيها المؤمنون: لعل هذه المعجزات إذا جاءت لا يصدِّق بها هؤلاء المشركون.', 109, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (899, 6, 1, 7, 899, 'ونقلب أفئدتهم وأبصارهم، فنحول بينها وبين الانتفاع بآيات الله، فلا يؤمنون بها كما لم يؤمنوا بآيات القرآن عند نزولها أول مرة، ونتركهم في تمرُّدهم على الله متحيِّرين، لا يهتدون إلى الحق والصواب.', 110, 2, 141, 114, NULL, 56, 14);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (900, 6, 1, 8, 900, 'ولو أننا أجبنا طلب هؤلاء، فنزَّلنا إليهم الملائكة من السماء، وأحيينا لهم الموتى، فكلموهم، وجمعنا لهم كل شيء طلبوه فعاينوه مواجهة، لم يصدِّقوا بما دعوتهم إليه -أيها الرسول- ولم يعملوا به، إلا من شاء الله له الهداية، ولكن أكثر هؤلاء الكفار يجهلون الحق الذي جئت به من عند الله تعالى.', 111, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (901, 6, 1, 8, 901, 'وكما ابتليناك -أيها الرسول- بأعدائك من المشركين ابتلينا جميع الأنبياء -عليهم السلام- بأعداء مِن مردة قومهم وأعداء من مردة الجن، يُلقي بعضهم إلى بعض القول الذي زيَّنوه بالباطل؛ ليغتر به سامعه، فيضل عن سبيل الله. ولو أراد ربك -جلَّ وعلا- لحال بينهم وبين تلك العداوة، ولكنه الابتلاء من الله، فدعهم وما يختلقون مِن كذب وزور.', 112, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (902, 6, 1, 8, 902, 'ولِتميل إليه قلوب الكفار الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، ولتحبَّه أنفسهم، وليكتسبوا من الأعمال السيئة ما هم مكتسبون. وفي هذا تهديد عظيم لهم.', 113, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (903, 6, 1, 8, 903, 'قل -أيها الرسول- لهؤلاء المشركين: أغير الله إلهي وإلهكم أطلب حَكَمًا بيني وبينكم، وهو سبحانه الذي أنزل إليكم القرآن مبينًا فيه الحكم فيما تختصمون فيه من أمري وأمركم؟ وبنو إسرائيل الذين آتاهم الله التوراة والإنجيل يعلمون علمًا يقينًا أن هذا القرآن منزل عليك -أيها الرسول- من ربك بالحق، فلا تكونن من الشاكِّين في شيء مما أوحينا إليك.', 114, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (904, 6, 1, 8, 904, 'وتمت كلمة ربك -وهي القرآن- صدقًا في الأخبار والأقوال، وعدلا في الأحكام، فلا يستطيع أحد أن يبدِّل كلماته الكاملة. والله تعالى هو السميع لما يقول عباده، الحليم بظواهر أمورهم وبواطنها.', 115, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (905, 6, 1, 8, 905, 'ولو فُرض -أيها الرسول- أنك أطعت أكثر أهل الأرض لأضلُّوك عن دين الله، ما يسيرون إلا على ما ظنوه حقًّا بتقليدهم أسلافهم، وما هم إلا يظنون ويكذبون.', 116, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (906, 6, 1, 8, 906, 'إن ربك هو أعلم بالضالين عن سبيل الرشاد، وهو أعلم منكم ومنهم بمن كان على استقامة وسداد، لا يخفى عليه منهم أحد.', 117, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (907, 6, 1, 8, 907, 'فكلوا من الذبائح التي ذُكِرَ اسم الله عليها، إن كنتم ببراهين الله تعالى الواضحة مصدقين.', 118, 2, 142, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (908, 6, 1, 8, 908, 'وأيُّ شيء يمنعكم أيها المسلمون من أن تأكلوا مما ذكر اسم الله عليه، وقد بيَّن الله سبحانه لكم جميع ما حرَّم عليكم؟ لكن ما دعت إليه الضرورة بسبب المجاعة، مما هو محرم عليكم كالميتة، فإنه مباح لكم. وإنَّ كثيرًا من الضالين ليضلون عن سبيل الله أشياعهم في تحليل الحرام وتحريم الحلال بأهوائهم؛ جهلا منهم. إن ربك -أيها الرسول- هو أعلم بمن تجاوز حده في ذلك، وهو الذي يتولى حسابه وجزاءه.', 119, 2, 143, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (909, 6, 1, 8, 909, 'واتركوا -أيها الناس- جميع المعاصي، ما كان منها علانية وما كان سرًّا. إن الذين يفعلون المعاصي سيعاقبهم ربهم؛ بسبب ما كانوا يعملونه من السيئات.', 120, 2, 143, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (910, 6, 1, 8, 910, 'ولا تأكلوا -أيها المسلمون- من الذبائح التي لم يذكر اسم الله عليها عند الذبح، كالميتة وما ذبح للأوثان والجن، وغير ذلك، وإن الأكل من تلك الذبائح لخروج عن طاعة الله تعالى. وإن مردة الجن لَيُلْقون إلى أوليائهم من شياطين الإنس بالشبهات حول تحريم أكل الميتة، فيأمرونهم أن يقولوا للمسلمين في جدالهم معهم: إنكم بعدم أكلكم الميتة لا تأكلون ما قتله الله، بينما تأكلون مما تذبحونه، وإن أطعتموهم -أيها المسلمون في تحليل الميتة- فأنتم وهم في الشرك سواء.', 121, 2, 143, 115, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (911, 6, 1, 8, 911, 'أوَمن كان ميتًا في الضلالة هالكا حائرا، فأحيينا قلبه بالإيمان، وهديناه له، ووفقناه لاتباع رسله، فأصبح يعيش في أنوار الهداية، كمن مثله في الجهالات والأهواء والضلالات المتفرقة، لا يهتدي إلى منفذ ولا مخلص له مما هو فيه؟ لا يستويان، وكما خذلتُ هذا الكافر الذي يجادلكم -أيها المؤمنون- فزيَّنْتُ له سوء عمله، فرآه حسنًا، زيَّنْتُ للجاحدين أعمالهم السيئة؛ ليستوجبوا بذلك العذاب.', 122, 2, 143, 116, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (912, 6, 1, 8, 912, 'ومثل هذا الذي حصل مِن زعماء الكفار في "مكة" من الصدِّ عن دين الله تعالى، جعلنا في كل قرية مجرمين يتزعمهم أكابرهم؛ ليمكروا فيها بالصد عن دين الله، وما يكيدون إلا أنفسهم، وما يُحِسُّون بذلك.', 123, 2, 143, 116, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (913, 6, 1, 8, 913, 'وإذا جاءت هؤلاء المشركين من أهل "مكة" حجة ظاهرة على نبوة محمد صلى الله عليه وسلم، قال بعض كبرائهم: لن نصدِّق بنبوته حتى يعطينا الله من النبوة والمعجزات مثل ما أعطى رسله السابقين. فردَّ الله تعالى عليهم بقوله: الله أعلم حيث يجعل رسالته أي: بالذين هم أهل لحمل رسالته وتبليغها إلى الناس. سينال هؤلاء الطغاة الذل، ولهم عذاب موجع في نار جهنم؛ بسبب كيدهم للإسلام وأهله.', 124, 2, 143, 116, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (914, 6, 1, 8, 914, 'فمن يشأ الله أن يوفقه لقَبول الحق يشرح صدره للتوحيد والإيمان، ومن يشأ أن يضله يجعل صدره في حال شديدة من الانقباض عن قَبول الهدى، كحال مَن يصعد في طبقات الجو العليا، فيصاب بضيق شديد في التنفس. وكما يجعل الله صدور الكافرين شديدة الضيق والانقباض، كذلك يجعل العذاب على الذين لا يؤمنون به.', 125, 2, 144, 116, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (915, 6, 1, 8, 915, 'وهذا الذي بيَّنَّاه لك -أيها الرسول- هو الطريق الموصل إلى رضا ربك وجنته. قد بينَّا البراهين لمن يتذكر من أهل العقول الراجحة.', 126, 2, 144, 116, NULL, 57, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (916, 6, 1, 8, 916, 'للمتذكرين عند ربهم جل وعلا يوم القيامة دار السلامة والأمان من كل مكروه وهي الجنة، وهو سبحانه ناصرهم وحافظهم جزاءً لهم؛ بسبب أعمالهم الصالحة.', 127, 2, 144, 116, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (917, 6, 1, 8, 917, 'واذكر -أيها الرسول- يوم يحشر الله تعالى الكفار وأولياءهم من شياطين الجن فيقول: يا معشر الجن قد أضللتم كثيرًا من الإنس، وقال أولياؤهم من كفار الإنس: ربنا قد انتفع بعضنا من بعض، وبلغنا الأجل الذي أجَّلْتَه لنا بانقضاء حياتنا الدنيا، قال الله تعالى لهم: النار مثواكم، أي: مكان إقامتكم خالدين فيها، إلا مَن شاء الله عدم خلوده فيها من عصاة الموحدين. إن ربك حكيم في تدبيره وصنعه، عليم بجميع أمور عباده.', 128, 2, 144, 116, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (918, 6, 1, 8, 918, 'وكما سلَّطْنا شياطين الجن على كفار الإنس، فكانوا أولياء لهم، نسلِّط الظالمين من الإنس بعضهم على بعض في الدنيا؛ بسبب ما يعملونه من المعاصي.', 129, 2, 144, 116, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (919, 6, 1, 8, 919, 'أيها المشركون من الجن والإنس، ألم يأتكم رسل من جملتكم -وظاهر النصوص يدلُّ على أنَّ الرسل من الإنس فقط-، يخبرونكم بآياتي الواضحة المشتملة على الأمر والنهي وبيان الخير والشر، ويحذرونكم لقاء عذابي في يوم القيامة؟ قال هؤلاء المشركون من الإنس والجن: شَهِدْنا على أنفسنا بأن رسلك قد بلغونا آياتك، وأنذرونا لقاء يومنا هذا، فكذبناهم، وخدعت هؤلاء المشركين زينةُ الحياة الدنيا، وشهدوا على أنفسهم أنهم كانوا جاحدين وحدانية الله تعالى ومكذبين لرسله عليهم السلام.', 130, 2, 144, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (920, 6, 1, 8, 920, 'إنما أعذرنا إلى الثقلين بإرسال الرسل وإنزال الكتب، لئلا يؤاخَذَ أحد بظلمه، وهو لم تبلغه دعوة، ولكن أعذرنا إلى الأمم، وما عذَّبنا أحدًا إلا بعد إرسال الرسل إليهم.', 131, 2, 144, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (921, 6, 1, 8, 921, 'ولكل عامل في طاعة الله تعالى أو معصيته مراتب من عمله، يبلِّغه الله إياها، ويجازيه عليها. وما ربك -أيها الرسول- بغافل عما يعمل عباده.', 132, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (922, 6, 1, 8, 922, 'وربك -أيها الرسول- الذي أمر الناس بعبادته، هو الغني وحده، وكل خلقه محتاجون إليه، وهو سبحانه ذو الرحمة الواسعة، لو أراد لأهلككم، وأوجد قومًا غيركم يخلفونكم من بعد فنائكم، ويعملون بطاعته تعالى، كما أوجدكم من نسل قوم آخرين كانوا قبلكم.', 133, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (923, 6, 1, 8, 923, 'إن الذي يوعدكم به ربكم - أيها المشركون - من العقاب على كفركم واقع بكم، ولن تُعجِزوا ربكم هربًا، فهو قادر على إعادتكم، وإن صرتم ترابًا وعظامًا.', 134, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (924, 6, 1, 8, 924, 'قل -أيها الرسول-: يا قوم اعملوا على طريقتكم فإني عامل على طريقتي التي شرعها لي ربي جل وعلا فسوف تعلمون -عند حلول النقمة بكم- مَنِ الذي تكون له العاقبة الحسنة؟ إنه لا يفوز برضوان الله تعالى والجنة مَن تجاوز حده وظلم، فأشرك مع الله غيره.', 135, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (925, 6, 1, 8, 925, 'وجعل المشركون لله -جلَّ وعلا- جزءًا مما خلق من الزروع والثمار والأنعام يقدمونه للضيوف والمساكين، وجعلوا قسمًا آخر من هذه الأشياء لشركائهم من الأوثان والأنصاب، فما كان مخصصًا لشركائهم فإنه يصل إليها وحدها، ولا يصل إلى الله، وما كان مخصصا لله تعالى فإنه يصل إلى شركائهم. بئس حكم القوم وقسمتهم.', 136, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (926, 6, 1, 8, 926, 'وكما زيَّن الشيطان للمشركين أن يجعلوا لله تعالى من الحرث والأنعام نصيبًا، ولشركائهم نصيبًا، زيَّنت الشياطين لكثير من المشركين قَتْلَ أولادهم خشية الفقر؛ ليوقعوا هؤلاء الآباء في الهلاك بقتل النفس التي حرم الله قتلها إلا بالحق، وليخلطوا عليهم دينهم فيلتبس، فيضلوا ويهلكوا، ولو شاء الله ألا يفعلوا ذلك ما فعلوه، ولكنه قدَّر ذلك لعلمه بسوء حالهم ومآلهم، فاتركهم -أيها الرسول- وشأنهم فيما يفترون من كذب، فسيحكم الله بينك وبينهم.', 137, 2, 145, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (927, 6, 1, 8, 927, 'وقال المشركون: هذه إبل وزرع حرام، لا يأكلها إلا مَن يأذنون له -حسب ادعائهم- مِن سدنة الأوثان وغيرهم. وهذه إبل حُرِّمت ظهورها، فلا يحل ركوبها والحملُ عليها بحال من الأحوال. وهذه إبل لا يَذكرون اسم الله تعالى عليها في أي شأن من شئونها. فعلوا ذلك كذبًا منهم على الله، سيجزيهم الله بسبب ما كانوا يفترون من كذبٍ عليه سبحانه.', 138, 2, 146, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (928, 6, 1, 8, 928, 'وقال المشركون: ما في بطون الأنعام من أجنَّة مباح لرجالنا، ومحرم على نسائنا، إذا ولد حيًّا، ويشتركون فيه إذا ولد ميتًا. سيعاقبهم الله إذ شرَّعوا لأنفسهم من التحليل والتحريم ما لم يأذن به الله. إنه تعالى حكيم في تدبير أمور خلقه، عليم بهم.', 139, 2, 146, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (929, 6, 1, 8, 929, 'قد خسر وهلك الذين قتلوا أولادهم لضعف عقولهم وجهلهم، وحرموا ما رزقهم الله كذبًا على الله. قد بَعُدوا عن الحق، وما كانوا من أهل الهدى والرشاد. فالتحليل والتحريم من خصائص الألوهية في التشريع، والحلال ما أحله الله، والحرام ما حرَّمه الله، وليس لأحد من خَلْقه فردًا كان أو جماعة أن يشرع لعباده ما لم يأذن به الله.', 140, 2, 146, 117, NULL, 58, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (930, 6, 1, 8, 930, 'والله سبحانه وتعالى هو الذي أوجد لكم بساتين: منها ما هو مرفوع عن الأرض كالأعناب، ومنها ما هو غير مرفوع، ولكنه قائم على سوقه كالنخل والزرع، متنوعًا طعمه، والزيتون والرمان متشابهًا منظره، ومختلفًا ثمره وطعمه. كلوا -أيها الناس- مِن ثمره إذا أثمر، وأعطوا زكاته المفروضة عليكم يوم حصاده وقطافه، ولا تتجاوزوا حدود الاعتدال في إخراج المال وأكل الطعام وغير ذلك. إنه تعالى لا يحب المتجاوزين حدوده بإنفاق المال في غير وجهه.', 141, 2, 146, 118, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (931, 6, 1, 8, 931, 'وأوجد من الأنعام ما هو مهيَّأ للحمل عليه لكبره وارتفاعه كالإبل، ومنها ما هو مهيَّأ لغير الحمل لصغره وقربه من الأرض كالبقر والغنم، كلوا مما أباحه الله لكم وأعطاكموه من هذه الأنعام، ولا تحرموا ما أحلَّ الله منها اتباعًا لطرق الشيطان، كما فعل المشركون. إن الشيطان لكم عدو ظاهر العداوة.', 142, 2, 146, 118, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (932, 6, 1, 8, 932, 'هذه الأنعام التي رزقها الله عباده من الإبل والبقر والغنم ثمانية أصناف: أربعة منها من الغنم، وهي الضأن ذكورًا وإناثًا، والمعز ذكورًا وإناثًا. قل -أيها الرسول- لأولئك المشركين: هل حَرَّم الله الذكرين من الغنم؟ فإن قالوا: نعم، فقد كذبوا في ذلك؛ لأنهم لا يحرمون كل ذكر من الضأن والمعز، وقل لهم: هل حَرَّم الله الأنثيين من الغنم؟ فإن قالوا: نعم، فقد كذبوا أيضًا؛ لأنهم لا يحرمون كل أنثى من ولد الضأن والمعز، وقل لهم: هل حَرَّم الله ما اشتملت عليه أرحام الأنثيين من الضأن والمعز من الحمل؟ فإن قالوا: نعم، فقد كذبوا أيضًا؛ لأنهم لا يحرمون كل حَمْل مِن ذلك، خبِّروني بعلم يدل على صحة ما ذهبتم إليه، إن كنتم صادقين فيما تنسبونه إلى ربكم.', 143, 2, 147, 118, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (933, 6, 1, 8, 933, 'والأصناف الأربعة الأخرى: هي اثنان من الإبل ذكورًا وإناثًا، واثنان من البقر ذكورًا وإناثًا. قل -أيها الرسول- لأولئك المشركين: أحَرَّم الله الذكرين أم الأنثيين؟ أم حرَّم ما اشتملت عليه أرحام الأنثيين ذكورًا وإناثًا؟ أم كنتم أيها المشركون حاضرين، إذ وصاكم الله بهذا التحريم للأنعام، فلا أحد أشد ظلمًا ممن اختلق على الله الكذب؛ ليصرف الناس بجهله عن طريق الهدى. إن الله تعالى لا يوفق للرشد مَن تجاوز حدَّه، فكذب على ربه، وأضلَّ الناس.', 144, 2, 147, 118, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (934, 6, 1, 8, 934, 'قل -أيها الرسول-: إني لا أجد فيما أوحى الله إليَّ شيئًا محرمًا على من يأكله مما تذكرون أنه حُرِّم من الأنعام، إلا أن يكون قد مات بغير تذكية، أو يكون دمًا مراقًا، أو يكون لحم خنزير فإنه نجس، أو الذي كانت ذكاته خروجًا عن طاعة الله تعالى؛ كما إذا كان المذبوح قد ذكر عليه اسم غير الله عند الذبح. فمن اضطر إلى الأكل من هذه المحرمات بسبب الجوع الشديد غير طالب بأكله منها تلذذًا، ولا متجاوز حد الضرورة، فإن الله تعالى غفور له، رحيم به. وقد ثبت - فيما بعد - بالسنة تحريم كل ذي ناب من السباع، ومخلب من الطير، والحمر الأهلية، والكلاب.', 145, 2, 147, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (935, 6, 1, 8, 935, 'واذكر -أيها الرسول- لهؤلاء المشركين ما حرمَّنا على اليهود من البهائم والطير: وهو كل ما لم يكن مشقوق الأصابع كالإبل والنَّعام، وشحوم البقر والغنم، إلا ما عَلِق من الشحم بظهورها أو أمعائها، أو اختلط بعظم الألْية والجنب ونحو ذلك. ذلك التحرم المذكور على اليهود عقوبة مِنَّا لهم بسبب أعمالهم السيئة، وإنَّا لصادقون فيما أخبرنا به عنهم.', 146, 2, 147, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (936, 6, 1, 8, 936, 'فإن كذبك -أيها الرسول- مخالفوك من المشركين واليهود، وغيرهم، فقل لهم: ربكم جل وعلا ذو رحمة واسعة، ولا يُدْفع عقابه عن القوم الذين أجرموا، فاكتسبوا الذنوب، واجترحوا السيئات. وفي هذا تهديد لهم لمخالفتهم الرسول صلى الله عليه وسلم.', 147, 2, 148, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (937, 6, 1, 8, 937, 'سيقول الذين أشركوا: لو أراد الله أن لا نشرك -نحن وآباؤنا- وأن لا نحرم شيئًا مِن دونه ما فعلنا ذلك، وردَّ الله عليهم ببيان أن هذه الشبهة قد أثارها الكفار مِن قبلهم، وكذَّبوا بها دعوة رسلهم، واستمَرُّوا على ذلك، حتى نزل بهم عذاب الله. قل لهم -أيها الرسول-: هل عندكم -فيما حرَّمتم من الأنعام والحرث، وفيما زعمتم من أن الله قد شاء لكم الكفر، ورضيه منكم وأحبه لكم- من علم صحيح فتظهروه لنا؟ إن تتبعون في أمور هذا الدين إلا مجرد الظن، وإن أنتم إلا تكذبون.', 148, 2, 148, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (938, 6, 1, 8, 938, 'قل -أيها الرسول- لهم: فلله جل وعلا الحجة القاطعة التي يقطع بها ظنونكم، فلو شاء لوفَّقكم جميعًا إلى طريق الاستقامة.', 149, 2, 148, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (939, 6, 1, 8, 939, 'قل -أيها الرسول- لهؤلاء المشركين: هاتوا شهداءكم الذين يشهدون أن الله تعالى هو الذي حرَّم ما حرَّمتم من الحرث والأنعام، فإن شهدوا -كذبًا وزورًا- فلا تصدقهم، ولا توافق الذين حكَّموا أهواءهم، فكذبوا بآيات الله فيما ذهبوا إليه من تحريم ما أحل الله، وتحليل ما حرم الله، ولا تتبع الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، والذين هم بربهم يشركون فيعبدون معه غيره.', 150, 2, 148, 119, NULL, 59, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (940, 6, 1, 8, 940, 'قل -أيها الرسول- لهم: تعالوا أتل ما حرم ربكم عليكم: أن لا تشركوا معه شيئًا من مخلوقاته في عبادته، بل اصرفوا جميع أنواع العبادة له وحده، كالخوف والرجاء والدعاء، وغير ذلك، وأن تحسنوا إلى الوالدين بالبر والدعاء ونحو ذلك من الإحسان، ولا تقتلوا أولادكم مِن أجل فقر نزل بكم؛ فإن الله يرزقكم وإياهم، ولا تقربوا ما كان ظاهرًا من كبير الآثام، وما كان خفيًّا، ولا تقتلوا النفس التي حرم الله قتلها إلا بالحق، وذلك في حال القصاص من القاتل أو الزنى بعد الإحصان أو الردة عن الإسلام، ذلكم المذكور مما نهاكم الله عنه، وعهد إليكم باجتنابه، ومما أمركم به، وصَّاكم به ربكم؛ لعلكم تعقلون أوامره ونواهيه.', 151, 2, 148, 120, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (941, 6, 1, 8, 941, 'ولا تقربوا أيها الأوصياء مال اليتيم إلا بالحال التي تصلح بها أمواله ويَنْتَفِع بها، حتى يصل إلى سن البلوغ ويكون راشدًا، فإذا بلغ ذلك فسلموا إليه ماله، وأوفوا الكيل والوزن بالعدل الذي يكون به تمام الوفاء. وإذا بذلتم جهدكم فلا حرج عليكم فيما قد يكون من نقص، لا نكلف نفسًا إلا وسعها. وإذا قلتم فتحرَّوا في قولكم العدل دون ميل عن الحق في خبر أو شهادة أو حكم أو شفاعة، ولو كان الذي تعلق به القول ذا قرابة منكم، فلا تميلوا معه بغير حق، وأوفوا بما عهد الله به إليكم من الالتزام بشريعته. ذلكم المتلوُّ عليكم من الأحكام، وصَّاكم به ربكم؛ رجاء أن تتذكروا عاقبة أمركم.', 152, 2, 149, 120, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (942, 6, 1, 8, 942, 'ومما وصاكم الله به أن هذا الإسلام هو طريق الله تعالى المستقيم فاسلكوه، ولا تسلكوا سبل الضلال، فتفرقكم، وتبعدكم عن سبيل الله المستقيم. ذلكم التوجه نحو الطريق المستقيم هو الذي وصَّاكم الله به؛ لتتقوا عذابه بفعل أوامره، واجتناب نواهيه.', 153, 2, 149, 120, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (943, 6, 1, 8, 943, 'ثم قل -أيها الرسول- لهؤلاء المشركين: إن الله تعالى هو الذي أتى موسى التوراة تمامًا لنعمته على المحسنين من أهل ملته، وتفصيلا لكل شيء من أمور دينهم، وهدى ودلالة على الطريق المستقيم ورحمة لهم؛ رجاء أن يصدِّقوا بالبعث بعد الموت والحساب والجزاء، ويعملوا لذلك.', 154, 2, 149, 120, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (944, 6, 1, 8, 944, 'وهذا القرآن كتاب أنزلناه على نبينا محمد صلى الله عليه وسلم، خيره كثير فاتبعوه فيما يأمر به وينهى عنه، واتقوا الله أن تخالفوا له أمرًا؛ رجاء أن ترحموا فتنجوا من عذابه، وتظفروا بثوابه.', 155, 2, 149, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (945, 6, 1, 8, 945, 'وأنزلنا هذا القرآن؛ لئلا تقولوا -يا كفار العرب-: إنما أُنزل الكتاب من السماء على اليهود والنصارى، وقد كنا عن قراءة كتبهم في شغل، ونحن ليس لنا بها علم ولا معرفة.', 156, 2, 149, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (946, 6, 1, 8, 946, 'ولئلا تقولوا -أيها المشركون-: لو أنَّا أُنزل علينا كتاب من السماء، كما أُنزل على اليهود والنصارى، لكنَّا أشدَّ استقامة على طريق الحق منهم، فقد جاءكم كتاب بلسانكم عربي مبين، وذلك حجة واضحة مِن ربكم وإرشاد إلى طريق الحق، ورحمةٌ لهذه الأمة. فلا أحد أشد ظلمًا وعدوانًا ممن كذَّب بحجج الله تعالى وأعرض عنها!! فهؤلاء المعرضون سنعاقبهم عقابًا شديدًا في نار جهنم؛ بسبب إعراضهم عن آياتنا، وصدِّهم عن سبيلنا.', 157, 2, 149, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (947, 6, 1, 8, 947, 'هل ينتظر الذين أعرضوا وصدوا عن سبيل الله إلا أن يأتيهم ملك الموت وأعوانه لقبض أرواحهم، أو يأتي ربك -أيها الرسول- للفصل بين عباده يوم القيامة، أو يأتي بعض أشراط الساعة وعلاماتها الدالة على مجيئها، وهي طلوع الشمس من مغربها؟ فحين يكون ذلك لا ينفع نفسا إيمانها، إن لم تكن آمنت من قبل، ولا يُقبل منها إن كانت مؤمنة كسب عمل صالح إن لم تكن عاملة به قبل ذلك. قل لهم -أيها الرسول-: انتظروا مجيء ذلك؛ لتعلموا المحق من المبطل، والمسيء من المحسن، إنا منتظرون ذلك.', 158, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (948, 6, 1, 8, 948, 'إن الذين فرقوا دينهم بعد ما كانوا مجتمعين على توحيد الله والعمل بشرعه، فأصبحوا فرقا وأحزابا، إنك -أيها الرسول- بريء منهم، إنما حكمهم إلى الله تعالى، ثم يخبرهم بأعمالهم، فيجازي من تاب منهم وأحسن بإحسانه، ويعاقب المسيء بإساءته.', 159, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (949, 6, 1, 8, 949, 'من لقي ربه يوم القيامة بحسنة من الأعمال الصالحة فله عشر حسنات أمثالها، ومن لقي ربه بسيئة فلا يعاقب إلا بمثلها، وهم لا يظلمون مثقال ذرة.', 160, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (950, 6, 1, 8, 950, 'قل -أيها الرسول- لهؤلاء المشركين: إنني أرشدني ربي إلى الطريق القويم الموصل إلى جنته، وهو دين الإسلام القائم بأمر الدنيا والآخرة، وهو دين التوحيد دين إبراهيم عليه السلام، وما كان إبراهيم عليه السلام من المشركين مع الله غيره.', 161, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (951, 6, 1, 8, 951, 'قل -أيها الرسول- لهؤلاء المشركين: إن صلاتي، ونسكي، أي: ذبحي لله وحده، لا للأصنام، ولا للأموات، ولا للجن، ولا لغير ذلك مما تذبحونه لغير الله، وعلى غير اسمه كما تفعلون، وحياتي وموتي لله تعالى رب العالمين.', 162, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (952, 6, 1, 8, 952, 'لا شريك له في ألوهيته ولا في ربوبيته ولا في صفاته وأسمائه، وبذلك التوحيد الخالص أمرني ربي جل وعلا وأنا أول من أقر وانقاد لله من هذه الأمة.', 163, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (953, 6, 1, 8, 953, 'قل -أيها الرسول-: أغير الله أطلب إلها، وهو خالق كل شيء ومالكه ومدبره؟ ولا يعمل أي إنسان عملا سيئا إلا كان إثمه عليه، ولا تحمل نفس آثمة إثم نفس أخرى، ثم إلى ربكم معادكم يوم القيامة، فيخبركم بما كنتم تختلفون فيه من أمر الدين.', 164, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (954, 6, 1, 8, 954, 'والله سبحانه هو الذي جعلكم تخلفون من سبقكم في الأرض بعد أن أهلكهم الله، واستخلفكم فيها؛ لتعمروها بعدهم بطاعة ربكم، ورفع بعضكم في الرزق والقوة فوق بعض درجات، ليبلوكم فيما أعطاكم من نعمه، فيظهر للناس الشاكر من غيره. إن ربك سريع العقاب لمن كفر به وعصاه، وإنه لغفور لمن آمن به وعمل صالحا وتاب من الموبقات، رحيم به، والغفور والرحيم اسمان كريمان من أسماء الله الحسنى.', 165, 2, 150, 121, NULL, 60, 15);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (955, 7, 1, 8, 955, 'سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.', 1, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (956, 7, 1, 8, 956, 'هذا القرآن كتاب عظيم أنزله الله عليك -أيها الرسول- فلا يكن في صدرك شك منه في أنه أنزل من عند الله، ولا تتحرج في إبلاغه والإنذار به، أنزلناه إليك؛ لتخوف به الكافرين وتذكر المؤمنين.', 2, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (957, 7, 1, 8, 957, 'اتبعوا -أيها الناس- ما أُنزل إليكم من ربكم من الكتاب والسنة بامتثال الأوامر واجتناب النواهي، ولا تتبعوا من دون الله أولياء كالشياطين والأحبار والرهبان. إنكم قليلا ما تتعظون، وتعتبرون، فترجعون إلى الحق.', 3, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (958, 7, 1, 8, 958, 'وكثير من القرى أهلكنا أهلها بسبب مخالفة رسلنا وتكذيبهم، فأعقبهم ذلك خزي الدنيا موصولا بذلِّ الآخرة، فجاءهم عذابنا مرة وهم نائمون ليلا ومرة وهم نائمون نهارًا. وخَصَّ الله هذين الوقتين؛ لأنهما وقتان للسكون والاستراحة، فمجيء العذاب فيهما أفظع وأشد.', 4, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (959, 7, 1, 8, 959, 'فما كان قولهم عند مجيء العذاب إلا الإقرار بالذنوب والإساءة، وأنهم حقيقون بالعذاب الذي نزل بهم.', 5, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (960, 7, 1, 8, 960, 'فلنسألن الأمم الذي أرسل إليهم المرسلون: ماذا أجبتم رسلنا إليكم؟ ولنسْألَنَّ المرسلين عن تبليغهم لرسالات ربهم، وعمَّا أجابتهم به أممهم.', 6, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (961, 7, 1, 8, 961, 'فلَنقُصَّنَّ على الخلق كلهم ما عملوا بعلم منا لأعمالهم في الدنيا فيما أمرناهم به، وما نهيناهم عنه، وما كنا غائبين عنهم في حال من الأحوال.', 7, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (962, 7, 1, 8, 962, 'ووزن أعمال الناس يوم القيامة يكون بميزان حقيقي بالعدل والقسط الذي لا ظلم فيه، فمن ثقلت موازين أعماله -لكثرة حسناته- فأولئك هم الفائزون.', 8, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (963, 7, 1, 8, 963, 'ومن خَفَّتْ موازين أعماله -لكثرة سيئاته- فأولئك هم الذين أضاعوا حظَّهم من رضوان الله تعالى، بسبب تجاوزهم الحد بجحد آيات الله تعالى وعدم الانقياد لها.', 9, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (964, 7, 1, 8, 964, 'ولقد مكَّنَّا لكم -أيها الناس- في الأرض، وجعلناها قرارًا لكم، وجعلنا لكم فيها ما تعيشون به من مطاعم ومشارب، ومع ذلك فشكركم لنعم الله قليل.', 10, 2, 151, 122, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (965, 7, 1, 8, 965, 'ولقد أنعمنا عليكم بخلق أصلكم -وهو أبوكم آدم من العدم- ثم صوَّرناه على هيئته المفضلة على كثير من الخلق، ثم أمرنا ملائكتنا عليهم السلام بالسجود له -إكرامًا واحترامًا وإظهارًا لفضل آدم- فسجدوا جميعًا، لكنَّ إبليس الذي كان معهم لم يكن من الساجدين لآدم؛ حسدًا له على هذا التكريم العظيم.', 11, 2, 151, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (966, 7, 1, 8, 966, 'قال تعالى منكرًا على إبليس تَرْكَ السجود: ما منعك ألا تسجد إذ أمرتك؟ فقال إبليس: أنا أفضل منه خلقًا؛ لأني مخلوق من نار، وهو مخلوق من طين. فرأى أن النار أشرف من الطين.', 12, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (967, 7, 1, 8, 967, 'قال الله لإبليس: فاهبط من الجنة، فما يصح لك أن تتكبر فيها، فاخرج من الجنة، إنك من الذليلين الحقيرين.', 13, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (968, 7, 1, 8, 968, 'قال إبليس لله -جل وعلا- حينما يئس من رحمته: أمهلني إلى يوم البعث؛ وذلك لأتمكن من إغواء مَن أقدر عليه من بني آدم.', 14, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (969, 7, 1, 8, 969, 'قال الله تعالى: إنك ممن كتبتُ عليهم تأخير الأجل إلى النفخة الأولى في القرن، إذ يموت الخلق كلهم.', 15, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (970, 7, 1, 8, 970, 'قال إبليس لعنه الله: فبسبب ما أضللتني لأجتهدنَّ في إغواء بني آدم عن طريقك القويم، ولأصدَّنَّهم عن الإسلام الذي فطرتهم عليه.', 16, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (971, 7, 1, 8, 971, 'ثم لآتينَّهم من جميع الجهات والجوانب، فأصدهم عن الحق، وأُحسِّن لهم الباطل، وأرغبهم في الدنيا، وأشككهم في الآخرة، ولا تجد أكثر بني آدم شاكرين لك نعمتك.', 17, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (972, 7, 1, 8, 972, 'قال الله تعالى لإبليس: اخرج من الجنة ممقوتًا مطرودًا، لأملأنَّ جهنم منك وممن تبعك من بني آدم أجمعين.', 18, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (973, 7, 1, 8, 973, 'ويا آدم اسكن أنت وزوجك حواء الجنة، فكُلا من ثمارها حيث شئتما، ولا تأكلا من ثمرة شجرة (عَيَّنها لهما)، فإن فعلتما ذلك كنتما من الظالمين المتجاوزين حدود الله.', 19, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (974, 7, 1, 8, 974, 'فألقى الشيطان لآدم وحواء وسوسة لإيقاعهما في معصية الله تعالى بالأكل من تلك الشجرة التي نهاهما الله عنها؛ لتكون عاقبتهما انكشاف ما سُتر من عوراتهما، وقال لهما في محاولة المكر بهما: إنما نهاكما ربكما عن الأكل مِن ثمر هذه الشجرة مِن أجل أن لا تكونا ملَكين، ومِن أجل أن لا تكونا من الخالدين في الحياة.', 20, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (975, 7, 1, 8, 975, 'وأقسم الشيطان لآدم وحواء بالله إنه ممن ينصح لهما في مشورته عليهما بالأكل من الشجرة، وهو كاذب في ذلك.', 21, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (976, 7, 1, 8, 976, 'فجرَّأهما وغرَّهما، فأكلا من الشجرة التي نهاهما الله عن الاقتراب منها، فلما أكلا منها انكشفت لهما عوراتهما، وزال ما سترهما الله به قبل المخالفة، فأخذا يلزقان بعض ورق الجنة على عوراتهما، وناداهما ربهما جل وعلا ألم أنهكما عن الأكل من تلك الشجرة، وأقل لكما: إن الشيطان لكما عدو ظاهر العداوة؟ وفي هذه الآية دليل على أن كشف العورة من عظائم الأمور، وأنه كان ولم يزل مستهجَنًا في الطباع، مستقبَحًا في العقول.', 22, 2, 152, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (977, 7, 1, 8, 977, 'قال آدم وحواء: ربنا ظلمنا أنفسنا بالأكل من الشجرة، وإن لم تغفر لنا وترحمنا لنكونن ممن أضاعوا حظَّهم في دنياهم وأخراهم. (وهذه الكلمات هي التي تلقاها آدم من ربه، فدعا بها فتاب الله عليه).', 23, 2, 153, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (978, 7, 1, 8, 978, 'قال تعالى مخاطبًا آدم وحواء لإبليس: اهبطوا من السماء إلى الأرض، وسيكون بعضكم لبعض عدوًا، ولكم في الأرض مكان تستقرون فيه، وتتمتعون إلى انقضاء آجالكم.', 24, 2, 153, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (979, 7, 1, 8, 979, 'قال الله تعالى لآدم وحوَّاء وذريتهما: فيها تحيون، أي: في الأرض تقضون أيام حياتكم الدنيا، وفيها تكون وفاتكم، ومنها يخرجكم ربكم، ويحشركم أحياء يوم البعث.', 25, 2, 153, 123, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (980, 7, 1, 8, 980, 'يا بني آدم قد جعلنا لكم لباسًا يستر عوراتكم، وهو لباس الضرورة، ولباسًا للزينة والتجمل، وهو من الكمال والتنعم. ولباسُ تقوى الله تعالى بفعل الأوامر واجتناب النواهي هو خير لباس للمؤمن. ذلك الذي مَنَّ الله به عليكم من الدلائل على ربوبية الله تعالى ووحدانيته وفضله ورحمته بعباده؛ لكي تتذكروا هذه النعم، فتشكروا لله عليها. وفي ذلك امتنان من الله تعالى على خَلْقه بهذه النعم.', 26, 2, 153, 124, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (981, 7, 1, 8, 981, 'يا بني آدم لا يخدعنَّكم الشيطان، فيزين لكم المعصية، كما زيَّنها لأبويكم آدم وحواء، فأخرجهما بسببها من الجنة، ينزع عنهما لباسهما الذي سترهما الله به؛ لتنكشف لهما عوراتهما. إن الشيطان يراكم هو وذريته وجنسه وأنتم لا ترونهم فاحذروهم. إنَّا جعلنا الشياطين أولياء للكفار الذين لا يوحدون الله، ولا يصدقون رسله، ولا يعملون بهديه.', 27, 2, 153, 124, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (982, 7, 1, 8, 982, 'وإذا أتى الكفار قبيحًا من الفعل اعتذروا عن فعله بأنه مما ورثوه عن آبائهم، وأنه مما أمر الله به. قل لهم -أيها الرسول-: إن الله تعالى لا يأمر عباده بقبائح الأفعال ومساوئها، أتقولون على الله -أيها المشركون- ما لا تعلمون كذبًا وافتراءً؟', 28, 2, 153, 124, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (983, 7, 1, 8, 983, 'قل -أيها الرسول- لهؤلاء المشركين: أمر ربي بالعدل، وأمركم بأن تخلصوا له العبادة في كل موضع من مواضعها، وبخاصة في المساجد، وأن تدعوه مخلصين له الطاعة والعبادة، وأن تؤمنوا بالبعث بعد الموت. وكما أن الله أوجدكم من العدم فإنه قادر على إعادة الحياة إليكم مرة أخرى.', 29, 2, 153, 124, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (984, 7, 1, 8, 984, 'جعل الله عباده فريقين: فريقًا وفَّقهم للهداية إلى الصراط المستقيم، وفريقًا وجبت عليهم الضلالة عن الطريق المستقيم، إنهم اتخذوا الشياطين أولياء من دون الله، فأطاعوهم جهلا منهم وظنًا بأنهم قد سلكوا سبيل الهداية.', 30, 2, 153, 124, NULL, 61, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (985, 7, 1, 8, 985, 'يا بني آدم كونوا عند أداء كل صلاة على حالة من الزينة المشروعة من ثياب ساترة لعوراتكم ونظافة وطهارة ونحو ذلك، وكلوا واشربوا من طيبات ما رزقكم الله، ولا تتجاوزوا حدود الاعتدال في ذلك. إن الله لا يحب المتجاوزين المسرفين في الطعام والشراب وغير ذلك.', 31, 2, 154, 124, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (986, 7, 1, 8, 986, 'قل -أيها الرسول- لهؤلاء الجهلة من المشركين: مَن الذي حرم عليكم اللباس الحسن الذي جعله الله تعالى زينة لكم؟ ومَن الذي حرَّم عليكم التمتع بالحلال الطيب من رزق الله تعالى؟ قل -أيها الرسول- لهؤلاء المشركين: إنَّ ما أحله الله من الملابس والطيبات من المطاعم والمشارب حق للذين آمنوا في الحياة الدنيا يشاركهم فيها غيرهم، خالصة لهم يوم القيامة. مثل ذلك التفصيل يفصِّل الله الآيات لقوم يعلمون ما يبيِّن لهم، ويفقهون ما يميز لهم.', 32, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (987, 7, 1, 8, 987, 'قل -أيها الرسول- لهؤلاء المشركين: إنما حَرَّم الله القبائح من الأعمال، ما كان منها ظاهرًا، وما كان خفيًّا، وحَرَّم المعاصي كلها، ومِن أعظمها الاعتداء على الناس، فإن ذلك مجانب للحق، وحرَّم أن تعبدوا مع الله تعالى غيره مما لم يُنَزِّل به دليلا وبرهانًا، فإنه لا حجة لفاعل ذلك، وحرَّم أن تنسبوا إلى الله تعالى ما لم يشرعه افتراءً وكذبًا، كدعوى أن لله ولدًا، وتحريم بعض الحلال من الملابس والمآكل.', 33, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (988, 7, 1, 8, 988, 'ولكل جماعة اجتمعت على الكفر بالله تعالى وتكذيب رسله -عليهم الصلاة والسلام- وقت لحلول العقوبة بهم، فإذا جاء الوقت الذي وقَّته الله لإهلاكهم لا يتأخرون عنه لحظة، ولا يتقدمون عليه.', 34, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (989, 7, 1, 8, 989, 'يا بني آدم إذا جاءكم رسلي من أقوامكم، يتلون عليكم آيات كتابي، ويبينون لكم البراهين على صدق ما جاؤوكم به فأطيعوهم، فإنه من اتقى سخطي وأصلح عمله فلا خوف عليهم يوم القيامة من عقاب الله تعالى، ولا ههم يحزنون على ما فاتهم من حظوظ الدنيا.', 35, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (990, 7, 1, 8, 990, 'والكفار الذين كذَّبوا بالدلائل على توحيد الله، واستعلَوا عن اتباعها، أولئك أصحاب النار ماكثين فيها، لا يخرجون منها أبدًا.', 36, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (991, 7, 1, 8, 991, 'لا أحد أشد ظلمًا ممن اختلق على الله تعالى الكذب، أو كذَّب بآياته المنزلة، أولئك يصل إليهم حظُّهم من العذاب مما كتب لهم في اللوح المحفوظ، حتى إذا جاءهم ملك الموت وأعوانه يقبضون أرواحهم قالوا لهم: أين الذين كنتم تعبدونهم من دون الله من الشركاء والأولياء والأوثان ليخلِّصوكم مما أنتم فيه؟ قالوا: ذهبوا عنا، واعترفوا على أنفسهم حينئذ أنهم كانوا في الدنيا جاحدين مكذبين وحدانية الله تعالى.', 37, 2, 154, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (992, 7, 1, 8, 992, 'قال الله تعالى -لهؤلاء المشركين المفترين-: ادخلوا النار في جملة جماعات من أمثالكم في الكفر، قد سلفت من قبلكم من الجن والإنس، كلما دخلت النارَ جماعةٌ من أهل ملة لعنت نظيرتها التي ضلَّتْ بالاقتداء بها، حتى إذا تلاحق في النار الأولون من أهل الملل الكافرة والآخرون منهم جميعًا، قال الآخرون المتبعون في الدنيا لقادتهم: ربنا هؤلاء هم الذين أضلونا عن الحق، فآتهم عذابًا مضاعفا من النار، قال الله تعالى: لكل ضعف، أي: لكل منكم ومنهم عذاب مضاعف من النار، ولكن لا تدركون أيها الأتباع ما لكل فريق منكم من العذاب والآلام.', 38, 2, 155, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (993, 7, 1, 8, 993, 'وقال المتبوعون من الرؤساء وغيرهم لأتباعهم: نحن وأنتم متساوون في الغيِّ والضلال، وفي فِعْلِ أسباب العذاب فلا فَضْلَ لكم علينا، قال الله تعالى لهم جميعًا: فذوقوا العذاب أي عذاب جهنم؛ بسبب ما كسبتم من المعاصي.', 39, 2, 155, 125, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (994, 7, 1, 8, 994, 'إن الكفار الذين لم يصدِّقوا بحججنا وآياتنا الدالة على وحدانيتنا، ولم يعملوا بشرعنا تكبرًا واستعلاءً، لا تُفتَّح لأعمالهم في الحياة ولا لأرواحهم عند الممات أبواب السماء، ولا يمكن أن يدخل هؤلاء الكفار الجنة إلا إذا دخل الجمل في ثقب الإبرة، وهذا مستحيل. ومثل ذلك الجزاء نجزي الذين كثر إجرامهم، واشتدَّ طغيانهم.', 40, 2, 155, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (995, 7, 1, 8, 995, 'هؤلاء الكفار مخلدون في النار، لهم مِن جهنم فراش مِن تحتهم، ومن فوقهم أغطية تغشاهم. وبمثل هذا العقاب الشديد يعاقب الله تعالى الظالمين الذين تجاوزوا حدوده فكفروا به وعصَوْه.', 41, 2, 155, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (996, 7, 1, 8, 996, 'والذين آمنوا بالله وعملوا الأعمال الصالحة في حدود طاقاتهم -لا يكلف الله نفسًا من الأعمال إلا ما تطيق- أولئك أهل الجنة، هم فيها ماكثون أبدًا لا يخرجون منها.', 42, 2, 155, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (997, 7, 1, 8, 997, 'وأذهب الله تعالى ما في صدور أهل الجنة من حقد وضغائن، ومن كمال نعيمهم أن الأنهار تجري في الجنة من تحتهم. وقال أهل الجنة حينما دخلوها: الحمد لله الذي وفَّقنا للعمل الصالح الذي أكسبنا ما نحن فيه من النعيم، وما كنا لنوفَّق إلى سلوك الطريق المستقيم لولا أَنْ هدانا الله سبحانه لسلوك هذا الطريق، ووفَّقنا للثبات عليه، لقد جاءت رسل ربنا بالحق من الإخبار بوعد أهل طاعته ووعيد أهل معصيته، ونُودوا تهنئة لهم وإكرامًا: أن تلكم الجنة أورثكم الله إياها برحمته، وبما قدَّمتموه من الإيمان والعمل الصالح.', 43, 2, 155, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (998, 7, 1, 8, 998, 'ونادى أصحاب الجنة -بعد دخولهم فيها- أهلَ النار قائلين لهم: إنا قد وجدنا ما وعدنا ربنا على ألسنة رسله حقًا من إثابة أهل طاعته، فهل وجدتم ما وعدكم ربكم على ألسنة رسله حقًا من عقاب أهل معصيته؟ فأجابهم أهل النار قائلين: نعم قد وجدنا ما وعدنا ربنا حقًا. فأذَّن مؤذن بين أهل الجنة وأهل النار: أنْ لعنة الله على الظالمين الذين تجاوزوا حدود الله، وكفروا بالله ورسله.', 44, 2, 156, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (999, 7, 1, 8, 999, 'هؤلاء الكافرون هم الذين كانوا يُعْرِضون عن طريق الله المستقيم، ويمنعون الناس من سلوكه، ويطلبون أن تكون السبيل معوجة حتى لا يتبينها أحد، وهم بالآخرة -وما فيها- جاحدون.', 45, 2, 156, 126, NULL, 62, 16);
INSERT INTO ""quranhub_schema"".""ayat"" ("id", "surat_id", "edition_id", "juz_id", "number", "text", "numberinsurat", "manzil_id", "page_id", "ruku_id", "sajda_id", "hizbquarter_id", "hizb_id") VALUES (1000, 7, 1, 8, 1000, 'وبين أصحاب الجنة وأصحاب النار حاجز عظيم يقال له الأعراف، وعلى هذا الحاجز رجال يعرفون أهل الجنة وأهل النار بعلاماتهم، كبياض وجوه أهل الجنة، وسواد وجوه أهل النار، وهؤلاء الرجال قوم استوت حسناتهم وسيئاتهم يرجون رحمة الله تعالى. ونادى رجال الأعراف أهل الجنة بالتحية قائلين لهم: سلام عليكم، وأهل الأعراف لم يدخلوا الجنة بعد، وهم يرجون دخولها.', 46, 2, 156, 126, NULL, 62, 16);
