INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (454, 'Fate of Fir''on and his chiefs who were warned but they gave no heed', ARRAY['Fate','Fir''on'], 14, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (455, 'Differences arose about Torah given to Musa for his followers'' lack of belief', ARRAY['Torah','Musa'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (456, 'Virtues remove evils, Allah does not let the reward of the righteous be wasted', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (457, 'Freedom of choice given to mankind is the Will of Allah', ARRAY['Allah','Freedom','Will'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (458, 'Al-Quran is revealed in the Arabic language', ARRAY['Arabic'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (459, 'Story of Prophet Yusuf (Joseph)', ARRAY['Joseph','Stori','Prophet','yusuf'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (460, 'There are lessons in this story for the inquirers', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (461, 'They told their father that Yusuf was eaten by a wolf', ARRAY['yusuf'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (462, 'One caravan kidnapped him, brought him to Egypt, and sold him', ARRAY['Egypt'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (463, 'The Egyptian who bought him was a nice man', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (464, 'Women of the town started pointing fingers at her, she invited them to a banquet and asked Yusuf to appear before them and Yusuf was sent to prison', ARRAY['Women','yusuf'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (465, 'Two prison inmates had dreams and asked Yusuf for interpretation and Yusuf''s address to his fellow inmates', ARRAY['yusuf'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (466, 'King of Egypt had a dream and asked for its interpretation and Yusuf''s interpretation of the King''s dream', ARRAY['King','Egypt','yusuf'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (467, 'King of Egypt heard the case of Yusuf and declared him innocent', ARRAY['King','Egypt','yusuf'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (468, 'Yusuf''s appointment as King''s cabinet member', ARRAY['yusuf','King'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (469, 'They asked their father to send Benjamin with them in order to get more grain and Ya''qoob''s advice to his sons', ARRAY['Benjamin','ya''qoob'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (470, 'Yusuf introduced himself to his brother and plotted to retain him and Benjamin was accused of stealing so that he could be retained', ARRAY['Benjamin','yusuf'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (471, 'Al-Quran is a mercy, blessing, and cure for the problems of mankind', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (472, 'Story of Prophet Nuh and his people', ARRAY['Nuh','Stori','Prophet'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (473, 'Teachings of Al-Quran', ARRAY['Teach'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (474, 'Nuh''s address to his people and Nuh''s people challenged him and asked for the scourge of Allah', ARRAY['Nuh','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (475, 'His master''s wife tried to seduce him but Allah saved him', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (476, 'Ya''qoob got the good news of his son Yusuf', ARRAY['yusuf','ya''qoob'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (477, 'Thus his family relocated from Ken''and to Egypt and Yusuf''s prayer to live and die as a Muslim', ARRAY['Ken''and','Muslim','yusuf','Egypt'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (478, 'Most of the ignorant people who believe in Allah also commit shirk', ARRAY['Most','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (479, 'All Rasools were human beings and Story of Yusuf is confirmation of previous scriptures', ARRAY['Rasool','Stori','yusuf'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (480, 'Al-Quran is revealed by Allah, the Creator of the heavens and the earth', ARRAY['Creator','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (481, 'Allah never changes the condition of a people unless they want to change themselves and Pray to Allah alone', ARRAY['Prai','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (482, 'Deities besides Allah have no control over any harm or benefit and Those who do not respond to the call of their Rabb will have escape', ARRAY['Allah','Rabb','Deiti'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (483, 'Those who fulfil their pledge with Allah will have and excellent home in the hereafter and Those who break their pledge will have the curse and a terrible home', ARRAY['Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (484, 'It is the remembrance of Allah that provides tranquility to hearts', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (485, 'There is no God but Him, all things are subject to His command', ARRAY['God'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (486, 'Allah watches minutely each and every soul', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (487, 'Al-Quran is revealed in Arabic for easy understanding', ARRAY['Arabic'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (488, 'Rasool has no power to show any miracle without the sanction of Allah and When Allah commands, there is none to reverse it and That Allah is the Master of all planning', ARRAY['Master','Rasool','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (489, 'This Book is revealed to bring the mankind out from darkness into light', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (490, 'They came to Yusuf and begged for food and some charity and Yusuf disclosed his identity and He forgave his brothers and sent for his family', ARRAY['yusuf'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (491, 'All Rasools speak the language of their own people', ARRAY['Rasool'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (492, 'Deities other than Allah can neither harm nor benefit you and Mankind was one nation until they invented different creeds', ARRAY['Allah','Deiti'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (493, 'Whatever you do, Allah is a witness to it', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (494, 'Mushrikin follow nothing but conjecture, preach nothing but falsehood', ARRAY['Mushrikin'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (495, 'Mankind is ever ungrateful to Allah except the believers and Al-Quran is not forged by the Prophet Muhammad (pbuh)', ARRAY['Muhammad','Prophet','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (496, 'Yusuf''s brothers came to Egypt to get food and grain and Yusuf asked them to bring Benjamin (Yusuf''s younger brother)', ARRAY['Benjamin','yusuf','Egypt'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (497, 'Yusuf''s brothers went back and told their father about the incident of Benjamin''s stealing and retention and Their father sent them back', ARRAY['Benjamin','yusuf'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (498, 'Trees, fruit, vegetables and their tastes are the signs of Allah and For every nation Allah sent a guide (Rasool)', ARRAY['Rasool','Tree','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (499, 'Hypocrites did not join the war against the unbelievers and Prohibition of offering Funeral prayer for the Hypocrites', ARRAY['Prohibit'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (500, 'Stepbrothers of Yusuf asked their father to send him with them on a hunting trip and threw him in a dark well', ARRAY['Stepbroth','yusuf'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (501, 'Prophet Musa was sent to lead his people out from darkness into light', ARRAY['Prophet','Musa'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (502, 'If all the dwellers of earth become nonbelievers, it makes no difference to Allah and In Allah let the believers put their trust', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (503, 'Allah punishes the wrongdoers and blesses those who dread His eminence', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (504, 'Allah has based the creation of the heavens and the earth on Truth', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (505, 'Shaitan has no power over human beings - he only invites and people follow', ARRAY['Shaitan'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (506, 'Greetings in Paradise will be ''Peace''', ARRAY['Greet','Paradis'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (507, 'Example of a "good word" and a "bad word"', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (508, 'The prayer of Prophet Ibrahim for the city of Mecca and its residents and The prayer of Prophet Ibrahim which is made a part of five daily prayers', ARRAY['Ibrahim','Mecca','Prophet'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (509, 'Never think that Allah is unaware of the unjust, or that He will ever break His promise made to His Rasools', ARRAY['Rasool','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (510, 'Allah is the One and Only God', ARRAY['God','Allah'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (511, 'Al-Quran is the Divine Book', ARRAY['Book','Divin'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (512, 'Allah created and decorated the heavens and also created everything suitable for human life on earth', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (513, 'Story of Adam''s creation; prostration of the angels before him and the refusal of Shaitan to prostrate and Shaitan and his followers are destined for hell', ARRAY['Shaitan','Adam','Stori'], 19, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (514, 'The righteous will be awarded paradise', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (515, 'Prophet Ibrahim is given the good news of a son by two angels', ARRAY['Ibrahim','Prophet'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (516, 'The same angels came to Prophet Lut and executed Allah''s decree of stoning to death the nation of homosexuals', ARRAY['Lut','Prophet','Allah'], 19, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (517, 'Punishment to the people of Hijr for their disbelief', ARRAY['Hijr'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (518, 'Allah has sent down His revelations to warn that there is no god but Him and He has created cattle for the benefit of human beings', ARRAY['Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (519, 'It is He Who sends down water from the sky for drinking and agriculture and He set mountains to stabilize earth and Allah has bestowed so many favors that you cannot even count them', ARRAY['Allah'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (520, 'Those who show ingratitude towards Allah''s favors shall be cast into Hell and Allah has given you countless favors', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (521, 'Allah has promised a good abode for those who migrate for His sake', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (522, 'Do the unbelievers feel secure against the wrath of Allah', ARRAY['Do','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (523, 'Whenever unbelievers are in distress they call upon Allah alone; no sooner does He relieve them that they start committing shirk', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (524, 'If Allah were to punish for wrong doings, He would not leave even and animal around the wrongdoers and As water gives life to dead land so does Al-Quran to the human soul', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (525, 'There is a lesson for mankind in the lives of animals ie, milk-producing animals and the honeybee', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (526, 'There are also signs of Allah in the lives of the birds and the animals', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (527, 'On the Day of Judgement a witness will be called from each nation and the unbelievers will face the reality of their invented false gods', ARRAY['Dai','Judgement'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (528, 'Allah commands to do justice, do good to others, and give to near relatives; and He forbids indecency, wickedness, and rebellion', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (529, 'What is with you is transitory; and what is with Allah is everlasting and When you recite Al-Quran, seek Allah''s protection against Shaitan', ARRAY['Shaitan','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (530, 'Unbelievers accused Muhammad (pbuh) of being taught Al-Quran by a certain man, but the man they allude to is non-Arab while Al-Quran is in eloquent Arabic', ARRAY['Arabic','Muhammad','Unbeliev'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (531, 'Do not declare with your tongue what is Halal (lawful) and what is Haram (unlawful) - Halal and Haram are from Allah', ARRAY['Halal','Haram','Do','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (532, 'Ibrahim was a nation in himself', ARRAY['Ibrahim'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (533, 'Call towards the Way of Allah with wisdom; advise and reason in a courteous manner', ARRAY['Call','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (534, 'Allah took Muhammad (pbuh) on a tour of the universe', ARRAY['Muhammad','Allah'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (535, 'Allah fulfilled the prophecy made in the Holy Book of the Israelites that they will create mischief in the land twice and each time they will be punished and Al-Quran guides to the perfectly Straight Way', ARRAY['Book','Israelit','Holi','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (536, 'The book of his own deeds shall be given to each individual on the Day of Judgement', ARRAY['Dai','Judgement'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (537, 'He that seeks guidance does so to his own good and he who goes astray does so to his own loss', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (538, 'The commandments continue', '{}', 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (539, 'Belief in the hereafter is necessary to understand Al-Quran and Hereafter is Life after death', ARRAY['Life'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (540, 'Believers should speak only good words', ARRAY['Believ'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (541, 'Invented gods have no power to relieve you from any distress', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (542, 'Shaitan, his enmity with human beings, and his vow to seduce them', ARRAY['Shaitan'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (543, 'Allah has provided conveyance for you on land and sea', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (544, 'Accountability of every community and its leaders', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (545, 'Five times daily Salah (prayers) and and extra prayer called Tahajjud for the Holy Prophet and Al-Quran is a healing and mercy for the believers', ARRAY['Tahajjud','Salah','Holi','Prophet'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (546, 'Ar-Ruh (Spirit) is at the command of Allah and No one can produce a Quran like this', ARRAY['Quran','Spirit','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (547, 'In Al-Quran Allah has used different methods to make people understand His Message', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (548, 'Musa was given NINE signs; people still did not believe him', ARRAY['NINE','Musa'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (549, 'AL-Quran is but a reminder and the life of this world shall appears to be no longer than one day in the Hereafter', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (550, 'On the Day of Judgement Allah will humiliate the arrogant and cast them into hell, while the righteous will be awarded paradise', ARRAY['Dai','Judgement','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (551, 'There is a lesson in the process of your own creation; Why then, believe in deities who have no power to create anything and disbelieve in Allah, the Creator', ARRAY['Creator','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (552, 'He that desires the transitory things of this life is given here, but in the hereafter he shall be condemned to hell', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (553, 'Some commandments of Allah for the believers including proper behavior with parents, relatives, and the community at large', ARRAY['Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (554, 'If there were other gods besides Allah, they would have tried to dethrone Him', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (555, 'Why the signs are not sent to Muhammad (pbuh) like prior prophets', ARRAY['Muhammad'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (556, 'No compromise is allowed in matters of Islamic law and principles', ARRAY['Islamic'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (557, 'Story of the Companions of the Cave', ARRAY['Stori','Cave'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (558, 'They are in a state of sleep and They were waken up by Allah after hundreds of year', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (559, 'Their identity was disclosed to resolve the disputed issue of life after death, What a shame that instead of getting the point people are disputing about their numbers', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (560, 'Whenever you promise to do something in future, always say, "Insha Allah (If Allah wills)"', ARRAY['Insha','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (561, 'No one is authorized to change the Word of Allah and Proclaim, "Truth from Allah has come, choice is yours, believe or disbelieve"', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (562, 'Parable of a believer and a disbeliever', ARRAY['Parabl'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (563, 'Similitude of worldly life and its relationship with the life of hereafter', ARRAY['Similitud'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (564, 'Fate of those who follow the Shaitan and commit shirk', ARRAY['Fate','Shaitan'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (565, 'Allah has given all kinds of examples in the Quran, so that the people may understand His Message', ARRAY['Quran','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (566, 'Prophet Musa travelled to find Khizer to learn some of the knowledge given to him by Allah Almighty and Khizer warned Musa that he would not be able to bear with him', ARRAY['Almighti','Musa','Allah','Khizer','Prophet'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (567, 'Prophet Musa could not resist questioning Khizer when he made a hole in boat, and when he killed a boy with no apparent reason', ARRAY['Khizer','Prophet','Musa'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (568, 'Story of Prophet Musa and Khizer', ARRAY['Khizer','Stori','Prophet','Musa'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (569, 'Story of king Zul-Qarnain', ARRAY['Stori'], 19, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (570, 'Fate of the Mushrikin and the Believers on the Day of Judgement', ARRAY['Dai','Believ','Judgement','Mushrikin','Fate'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (571, 'Words of Allah are countless and can not be recorded', ARRAY['Allah'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (572, 'Muhammad is but a human being like you', ARRAY['Muhammad'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (573, 'The story of Zakariya and the birth and youth of Yahya (John)', ARRAY['John','Zakariya','yahya'], 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (574, 'The story of Maryem and the miraculous birth of Isa (Jesus)', ARRAY['Jesu','Maryem','Isa'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (575, 'Isa (Jesus) is not the son of God, it is not befitting to the Majesty of God that He needs to beget a son for name, fame, help or continuity of race', ARRAY['Jesu','God','Majesti','Isa'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (576, 'Story of Ibrahim and his idol worshipping father', ARRAY['Ibrahim','Stori'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (577, 'Prophethood of Musa, Isma`il and Idris', ARRAY['Idri','Prophethood','Isma`','Musa'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (578, 'All prophets of Allah were Divine Guided and chosen', ARRAY['Divin','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (579, 'Believers and unbelievers'' life in this world and their life in the Hereafter', ARRAY['Believ'], 17, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (580, 'Al-Quran is a reminder for those who fear Allah, the Creator of the heavens and earth', ARRAY['Creator','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (581, 'Prophet Musa went to the sacred valley of ''Tuwa'' at mount Tur', ARRAY['Tur','Tuwa','Prophet','Musa'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (582, 'Allah chose him as His Rasool and assigned him towards Fir''on (Pharaoh)', ARRAY['Rasool','Fir''on','Pharaoh','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (583, 'Prophet Musa prayed to Allah to open his heart, easy his task and remove the impediment from his speech so that people may understand, what he says Allah granted his request and reminded him about His favors', ARRAY['Allah','Prophet','Musa'], 24, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (584, 'Dialogue between Musa and Fir''on', ARRAY['Fir''on','Musa'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (585, 'Human life cycle', ARRAY['Human'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (586, 'Fir''on disbelieved Musa by calling his miracles a magician trick and challenged him to confront his magicians in public - Musa accepted the challenge', ARRAY['Fir''on','Musa'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (587, 'Confrontation of Musa and Fir''on''s magicians, after witnessing Musa''s miracle Magicians accepted Islam and Dialogue between Magicians and Fir''on', ARRAY['Islam','Fir''on','Musa'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (588, 'Deliverance of the Children of Israel from the bondage of Fir''on', ARRAY['Children','Israel','Fir''on','Deliver'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (589, 'When Prophet Musa went to Mount Tur for communion with Allah - Israelites started worshipping calf in his absence', ARRAY['Mount','Musa','Allah','Israelit','Prophet','Tur'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (590, 'Musa''s inquiry about the idol worshipping, his decision about Samiri, Golden Calf and his address to his people', ARRAY['Samiri','Calf','Musa','Golden'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (591, 'Those who say Allah has begotten a son are uttering a monstrous lie', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (592, 'Al-Fatiha is also called, "Seven verses worthy of oft-recitation" And Proclaim the commandments of Allah publicly and turn away from the Mushrikin', ARRAY['Seven','Mushrikin','Allah'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (593, 'Unbelievers are arrogant and they will be held responsible for that attitude', ARRAY['Unbeliev'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (594, 'Allah has sent the Rasools to warn against the unbelievers excuse, "If Allah wanted, we would have not worshipped anyone else"', ARRAY['Rasool','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (595, 'Al-Quran is revealed in truth and with the truth it has come dow in sections to suit each occasion, for easy deliberation Offer Salah neither too loud nor too low a voice, adopt the middle course', ARRAY['Salah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (596, 'Maryem brought her baby (Jesus) to her people, and the baby spoke to his people in the cradle to defend his mother and proclaim his assignment to be their Prophet', ARRAY['Jesu','Maryem','Prophet'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (597, 'On the Day of Judgement, the unbelievers will wish that they were Muslims and Allah Himself has taken the responsibility of preserving Al-Quran', ARRAY['Dai','Judgement','Allah'], 14, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (598, 'Allah has sent a human Rasool to human beings; if the dwellers of earth had been Angels, Allah would have sent and angel as a Rasool and Only disbelievers can doubt life after death', ARRAY['Angel','Rasool','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (599, 'They were young men who declared the truth about the Oneness of Allah and They had to run away and take refuge in a cave', ARRAY['Oneness','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (600, 'No god other than Allah will be able to save you on the Day of Judgement and Those who say Allah has begotten as son preach such a monstrous lie that even the heavens may crack, earth split and mountains crumble to pieces and Allah has made the Quran easy for Mankind', ARRAY['Quran','Dai','Judgement','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (601, 'Do not envy others in worldly benefits, rather seek Allah''s pleasure if you want to attain the blessed end', ARRAY['Do','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (602, 'AL-Quran is a sign from Allah so there can be no excuse for the unbelievers on the Day of Judgement', ARRAY['Dai','Judgement','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (603, 'The day of accountability is getting closer but the disbelievers are still heedless to the admonition and disputing as to how Rasool can be a human beings', ARRAY['Rasool'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (604, 'Prior nations were destroyed due to similar iniquities', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (605, 'All Rasools were sent with the same Message, "There is no god but Allah, so worship Him alone', ARRAY['Rasool','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (606, 'The skies and earth once were once one mass, Allah split them asunder, and He created all living things from water', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (607, 'Allah has not granted immortality to any human being If Rasools are destined to die, how disbelievers are going to live for ever!', ARRAY['Rasool','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (608, 'Invented gods can not even defend themselves, how they will defend them against Allah and Scale of justice shall be set up on the Day of Judgement', ARRAY['Judgement','Dai','Scale','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (609, 'Musa was given AL-Furqan (the criterion of right and wrong), so is this AL-Quran', ARRAY['Musa'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (610, 'Allah blessed Ibrahim with son (Ishaq) and then a grandson (Ya''qoob) and made each of them Prophets', ARRAY['Ibrahim','ya''qoob','Allah','Ishaq','Prophet'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (611, 'Allah accepted the prayer of Nuh against the unbelievers', ARRAY['Nuh','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (612, 'Allah blessed Prophets Dawood and Sulaiman with wisdom, knowledge and kingdoms', ARRAY['Sulaiman','Dawood','Prophet','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (613, 'Allah accepted Prophet Ayub''s prayer and removed his affliction', ARRAY['Ayub','Prophet','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (614, 'Allah accepted the prayers and blessed Prophets Isma`il, Zulkifl, Yunus, Zakariya and also blessed Maryem', ARRAY['Allah','Maryem','Zulkifl','yunu','Zakariya','Isma`','Prophet'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (615, 'Mankind is but one brotherhood', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (616, 'Whoever does good deeds, provided he is a believer, his endeavor will not be rejected', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (617, 'Allah has sent Muhammad (pbuh) as a blessing for all the worlds (Humans, Jinns and others)', ARRAY['Muhammad','Jinn','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (618, 'A scene from the Hour of Doom', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (619, 'People invoke other deities besides Allah, without knowledge and guidance', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (620, 'Behavior of those who are standing at the verge of faith', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (621, 'Disbelievers will have garment of fire, boiling water and maces of iron to lash them with', ARRAY['Disbeliev'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (622, 'Allah has given equal rights to all believers for Masjid-al-Haram whether they are natives or foreigners', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (623, 'Allah identified the sight of Sacred House to Ibrahim, commanded him to built Ka''bah then call mankind to come for Hajj (Pilgrimage)', ARRAY['Ibrahim','Hajj','Allah','Hous','Ka''bah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (624, 'Committing shirk is as though he had fallen from the sky and his body is snatched away by the birds', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (625, 'Permission is granted to the believers to fight in self defence, and for the cause of Allah', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (626, 'O Muhammad, "you are not the only one being denied, all Prophets were denied before you"', ARRAY['Muhammad','O','Prophet'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (627, 'A day of your Rabb is equal to one thousand year of your calculation', ARRAY['Rabb'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (628, 'Acceptors of Truth shall be forgiven, while others punished', ARRAY['Acceptor'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (629, 'AL-Quran is sent in Arabic to teach and to remind, so read and say, "O Rabb increase my Knowledge"', ARRAY['Arabic','Rabb','O'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (630, 'The creation of heavens and earth is not a game', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (631, 'If there were more than One God, the heavens and earth would have been in a state of disorder', ARRAY['God'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (632, 'The Day of Judgement and the fate of the disbelievers and the believers', ARRAY['Dai','Judgement'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (633, 'Life cycle, life in this world and the life in the Hereafter', ARRAY['Life'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (634, 'Allah always help His Rasools and All the dwellers of the heavens and the earth prostrate before Allah', ARRAY['Rasool','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (635, 'It is not the meat or the blood of the sacrificed animals that reaches Allah, it is your piety that reaches Him', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (636, 'Allah will Judge between you concerning those matter in which you differ', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (637, 'Gods besides Allah has no power to create even a creature like fly', ARRAY['Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (638, 'Allah named the believers as Muslims in the prior Scriptures and also in this (AL-Quran)', ARRAY['Scriptur','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (639, 'Characteristics of true believers', '{}', 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (640, 'After prophet Nuh, Allah sent Hud to guide his people', ARRAY['Hud','Nuh','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (641, 'They called Hud and imposter; as a result Allah destroyed them all in a mighty blast and After Hud Allah sent Rasools to other people, those people also denied and faced a similar punishment', ARRAY['Allah','Rasool','Hud'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (642, 'Musa was sent to Fir''on and his chiefs; they also disbelieved and faced destruction', ARRAY['Fir''on','Musa'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (643, 'Allah has said, "In fact, your religion is one religion; I am your Rabb, so fear Me alone"', ARRAY['Rabb','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (644, 'Allah has not charged any soul with more than it can bear and Those who do not believe in the hereafter will stray from the Right Path', ARRAY['Right','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (645, 'Allah has given you ears, eyes, and hearts, but you seldom show gratitude', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (646, 'Even the disbelievers recognize the existence of Allah', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (647, 'Allah has never begotten a son, nor there is any other god besides Him', ARRAY['Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (648, 'Repel evil with good Seek refuge with Allah against the temptations of Shaitan', ARRAY['Shaitan','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (649, 'Wrongdoers will wish that they be sent back to this world to adopt the Right Way, but it will be too late', ARRAY['Right','Wai','Wrongdoer'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (650, 'On the day of Judgement it will appear as if the life of this world was less than a day', ARRAY['Judgement'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (651, 'Unbelievers will never attain salvation', ARRAY['Unbeliev'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
