INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (657, 'Allah''s order for single people to get married and Allah''s order to grant liberty to those slaves who seek to buy their freedom', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
