INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (665, 'Allah is the One Who has given you life, cause you to die and will bring you back to life for passing on His Judgement', ARRAY['Judgement','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (666, 'Stages of human creation', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (667, 'Allah has made the heavens, vegetation, trees and Animals for the benefit of human beings', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (668, 'Punishment for false witness', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (669, 'Layan (accusing wife when there is no other witness in a case of adultery)', ARRAY['Layan'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (670, 'Every thing in the heaven and earth glorify and praise Allah and Allah has created every living creature from water', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (671, 'True believers are those who, when called towards Allah and His Rasool, say, "We hear and we obey"', ARRAY['True','Rasool','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (672, 'Those who deny the Hour and life after death will be cast in the blazing fire', '{}', 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
