INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (676, 'Characteristics of the True Servants (believers) of Allah', ARRAY['Allah','believ'], 17, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (677, 'Dedication of Prophet Muhammad (pbuh) for the guidance of mankind', ARRAY['Muhammad','Prophet'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (678, 'Assignment of Musa as a Rasool and his dialogue with Fir''on and Miracles of Prophet Musa', ARRAY['Musa','Rasool','Miracl','Fir''on','Prophet'], 23, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (679, 'Fir''on took Prophet Musa''s miracles as magic and summoned the magicians to compete and After witnessing a miracle, all the magicians embraced Islam', ARRAY['Islam','Fir''on','Prophet','Musa'], 18, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (680, 'Deliverance of the Children of Israel and the destruction of Fir''on and his chiefs', ARRAY['Children','Israel','Fir''on','Deliver'], 17, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (681, 'Story of Prophet Nuh, his dialogue with his people, they disbelieved and as a result faced destruction', ARRAY['Nuh','Stori','Prophet'], 18, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
