INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (685, 'Story of Prophet Shu''aib, his address to his people, they disbelieved and as a result faced destruction', ARRAY['Shu''aib','Stori','Prophet'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (686, 'Al-Quran is not brought down by shaitans, it is neither in their interest nor in their power', '{}', 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (687, 'Shaitans descend on slandering sinners, who listen to hearsay and are liars', ARRAY['Shaitan'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (688, 'Disbelievers shall regret on the Day of Judgement not adopting the Right Path', ARRAY['Dai','Right','Disbeliev','Judgement'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (689, 'A scene from the Day of judgement', ARRAY['Dai'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (690, 'Story of Adam''s creation and Shaitan''s temptation and Allah forgave Adam''s sin, chose him and guided him to the right Way and Those who do not read AL-Quran and follow its guidance shall be raise as blind on the Day of Resurrection', ARRAY['Dai','Adam','Shaitan','Allah','Stori'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (691, 'Shaitan tempered with the wishes of all Rasools but Allah abrogated such interjection and On the Day of Judgement Allah Himself shall be the Judge for all', ARRAY['Dai','Judgement','Shaitan','Allah','Rasool','Judg'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (692, 'Those who migrated for the sake of Allah shall be generously rewarded and Allah is the only One who is real, all other deities are false', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (693, 'Prophet Nuh was sent to guide his people, they disbelieved him, as a result Allah drowned all disbelievers in great flood', ARRAY['Nuh','Prophet','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (694, 'Unbelievers who ask for angels today will ask for a stone barrier between them and the angels of punishment', ARRAY['Unbeliev'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (695, 'All nations which rejected Allah''s revelations and His Rasools were utterly destroyed and Those who have taken their desires as their gods are nothing but animals', ARRAY['Rasool','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (696, 'Al-Quran is revealed in plain Arabic by Allah through angel Gabriel, those people who do not want to believe will not believe', ARRAY['Arabic','Gabriel','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (697, 'Ibrahim questioned the idol worshiping of his father and his people and Ibrahim broke all their idols to show, that the gods who can not even defend themselves, how they can be of any benefit to them and They decided to burn him alive but Allah commanded the fire to be cool and comfortable for Ibrahim', ARRAY['Ibrahim','Allah'], 21, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (698, 'Blessed is Allah Who revealed this Al-Quran, the criterion to distinguish right from wrong and Wrongdoers are those who reject the truth and disbelieve a Rasool be cause he is a human being', ARRAY['Wrongdoer','Rasool','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (699, 'On the day of Judgement, those deities whom the Mushrikin invoke will deny any claim of divinity and hold the Mushrikin responsible for their shirk', ARRAY['Mushrikin','Judgement'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (700, 'Story of Prophet Ibrahim and his arguments against idol worshipping and Prayer of Prophet Ibrahim for this life and the life hereafter and Mushrikin and their gods both will be toppled into hell', ARRAY['Ibrahim','Mushrikin','Stori','Prophet'], 36, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (701, 'Fear Allah and do not obey the unbelievers and hypocrites', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (702, 'Al-Quran is a Guide and Good News to the Believers', ARRAY['Guid','Believ','New'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (703, 'Story of Prophet Musa''s selection as a Rasool and Nine signs were shown to Fir''on but he still disbelieved and incurred Allah''s punishment', ARRAY['Musa','Allah','Rasool','Stori','Fir''on','Prophet'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (704, 'Story of Prophet Sulaiman, to whom Allah gave rule over jinns, men, birds and winds', ARRAY['Sulaiman','Stori','Prophet','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (705, 'The hoopoe brought him the news about the Queen of Sheba and Letter from King Sulaiman to the Queen of Sheba', ARRAY['Sheba','Letter','Sulaiman','Queen','King'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (706, 'Communications between Queen of Sheba and Sulaiman', ARRAY['Queen','Sheba','Sulaiman','Commun'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (707, 'A man who had the ''Knowledge of the Book'' brought Throne of the Queen to king Sulaiman in twinkling of and eye and Queen of Sheba and her people embraced Islam', ARRAY['Islam','Sheba','Sulaiman','Queen'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (708, 'Prophet Lut admonished his people but they paid no heed so they faced the scourge of Allah', ARRAY['Lut','Prophet','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (709, 'Praise to Allah and peace be on His Rasools', ARRAY['Rasool','Allah'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (710, 'Just think, is there any god besides Allah Who has created anything in the universe, answer the oppressed or guides to the Right Way?', ARRAY['Right','Wai','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (711, 'Disbelievers doubt Allah''s power of creation and Al-Quran clarifies those matters in which the Israelites differ and A sign from the signs of doomsday', ARRAY['Israelit','Disbeliev','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (712, 'Do not deny Allah''s revelations without gaining their comprehensive knowledge', ARRAY['Do','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (713, 'A scene from the scenes of Doomsday and Those who accept guidance do so to their own good and those who go astray do so to their own peril', '{}', 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (714, 'Fir''on plotted to kill the sons of the Israelites to save his kingship, while Allah planned to bring up one of them in Fir''on''s own household', ARRAY['Israelit','Fir''on','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (715, 'Musa''s youth, his folly of killing a man, and his escape from Fir''on''s retribution', ARRAY['Fir''on','Musa'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (716, 'His arrival at Madyan, acceptance of ten years term employment, and marriage', ARRAY['Madyan'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (717, 'His arrival at Mount Tur, seeing a fire, conversation with Allah, and his appointment as a Rasool to Fir''on and his chiefs', ARRAY['Mount','Allah','Rasool','Fir''on','Tur'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (718, 'Story of Prophet Musa', ARRAY['Stori','Prophet','Musa'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (719, 'Righteous Jews and Christians can recognize the truth of Al-Quran and feel that they were Muslims even before hearing it', ARRAY['Righteou'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (720, 'Prophets cannot give guidance, it is Allah who gives guidance', ARRAY['Prophet','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (721, 'On the Day of Judgement disbelievers will wish that they had accepted Guidance', ARRAY['Dai','Judgement'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (722, 'Allah''s powers are not in the hands of Mushrikin, that they can assign them to whomever they want', ARRAY['Mushrikin','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (723, 'Story of Qarun, the rich man, who was from the people of Musa but he rebelled against the guidance of Allah', ARRAY['Qarun','Stori','Musa','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (724, 'Revelation of Al-Quran is the mercy of Allah, let no one turn you away from it', ARRAY['Revel','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (725, 'Allah tests the believers to see who is truthful and who is a liar', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (726, 'Be kind to your parents but do not obey them in the matter of shirk and Those who say, "Follow us we will bear your burden," are liars', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (727, 'Lut was appointed as a Rasool towards the nation of homosexuals', ARRAY['Lut','Rasool'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (728, 'They rejected Allah''s guidance; as a result Allah destroyed them all', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (729, 'Likewise the Nations of ''Ad, Thamud, Madyan and Fir''on rejected the Rasools of Allah, which resulted in their destruction', ARRAY['Nation','Allah','Madyan','Thamud','Rasool','Fir''on'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (730, 'Parable of those who take protectors other than Allah', ARRAY['Parabl','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (731, 'Salah keeps one away from the shameful deeds and Do not argue with the People of the Book except in good taste', ARRAY['Salah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (732, 'Those who believe in falsehood and disbelieve Allah shall be the losers and How many creatures are there who do not carry their provisions with them ? Allah provides them as He provides you', ARRAY['Allah'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (733, 'The life of this world is nothing but a pastime, the real life is the life Hereafter and Those who strive in Our cause, We do guide them to Our Way', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (734, 'Creation of Man, his consort, heavens, earth, language, colors, sleep, quest for work, lightening, rain and growth of vegetation are all from the signs of Allah', ARRAY['Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (735, 'Wrongdoers are led by their own appetites without real knowledge and  True faith and the nature of sects', ARRAY['Wrongdoer'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (736, 'When and affliction befalls people they call upon Allah, but when He relieves them, lo! They start committing shirk', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (737, 'Commandment to give the relatives their due and likewise to the poor and the travellers in need', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (738, 'It is Allah Who has created you and shall bring you to justice on the Day of Judgement', ARRAY['Dai','Judgement','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (739, 'AL-Quran is the Book of Wisdom, a Guide and a Blessing for the Righteous', ARRAY['Guid','Righteou'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (740, 'Luqman advised his son not to commit Shirk', ARRAY['Luqman'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (741, 'Rights of mother and the parents and  Obey your parents but not in the matters of Shirk', ARRAY['Right','Obei'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (742, 'Advise of Luqman about moral behavior and interaction', ARRAY['Luqman'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (743, 'Main reason of misguidance is the blind following of ones forefathers', ARRAY['Main'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (744, 'If all the trees were pens and the oceans and ink, Allah''s words could not be put to writing and  Allah is the only reality, all others to whom people invoke besides Him are false', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (745, 'O Mankind, fear that Day when no father shall avail his son nor a son his father Let not the Shaitan deceive you concerning this fact', ARRAY['Shaitan','Dai','O'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (746, 'AL-Quran is beyond all doubts, revealed to Muhammad, so that he may warn those people to whom no Warner has come before', ARRAY['Muhammad','Warner'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (747, 'On the Day of Judgement the unbelievers shall believe but that belief will be of no benefit to them', ARRAY['Dai','Judgement'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (748, 'Information about the destruction of prior generations is given to teach a lesson', ARRAY['Informat'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (749, 'The people of Ibrahim even tried to burn him alive but Allah saved him and Lut (his nephew) is the only one who affirmed his belief with him', ARRAY['Ibrahim','Lut','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (750, 'It is Allah Who originates the creation and then repeats it and to Him everyone will be brought for the final Judgement', ARRAY['Judgement','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (751, 'Mischief in the land is the result of Man''s own misdeeds, that''s how Allah let them taste the fruit of their deeds', ARRAY['Allah','''s'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (752, 'By words of mouth neither your wives become your mothers nor adopted sons become your real sons', '{}', 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (753, 'Favors of Allah during the battle of Trench', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (754, 'Attitude of the Hypocrites during the battle of Trench', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (755, 'Allah helped the Muslims to gain victory over the unbelievers and the Jewish tribes in Madinah and Khayber', ARRAY['Khayber','Madinah','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (756, 'Admonition to the wives of Prophet Muhammad (pbuh)', ARRAY['Muhammad','Prophet'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (757, 'Allah''s commandment to the wives of Prophet Muhammad', ARRAY['Muhammad','Prophet','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (758, 'Allah commanded Prophet Muhammad to marry the divorced wife of his adopted son Zaid and Muhammad is not the father of any of your men but a Rasool and Seal of the Prophethood', ARRAY['Allah','Zaid','Muhammad','Rasool','Prophethood','Seal','Prophet'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (759, 'Prophet is sent as a bearer of good news, a Warner and a lamp spreading light', ARRAY['Warner','Prophet'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (760, 'Do not enter the houses of the Prophet without permission, and if invited do not seek long conversation and Do not marry Rasool''s wives after his death', ARRAY['Rasool','Do','Prophet'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (761, 'Allah Himself and His angels send blessings on the Prophet, O Believers invoke Allah''s blessings for him', ARRAY['Believ','O','Prophet','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (762, 'Commandment of Hijab (dress code) for women', ARRAY['Hijab'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (763, 'Punishment for the Hypocrites and scandal mongers', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (764, 'The Hour is surely going to come and the Day of Judgement shall be established to reward the believers and punish those who discredit Allah''s revelations', ARRAY['Dai','Judgement','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (765, 'Those who do not believe in the Hereafter are doomed', '{}', 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (766, 'The people of Saba rejected Allah''s blessings and disbelieved in the Hereafter so Allah made them merely a tale of the past', ARRAY['Allah','Saba'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (767, 'No intercession before Allah can avail any one except for   whom He permits it and Prophet Muhammad is sent for the entire mankind', ARRAY['Muhammad','Prophet','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (768, 'Those who disbelieve in AL-Quran and prior scriptures will be subjected to yokes around their necks before tossing them into Hell and Wealth and children are not the indications of Allah''s pleasure', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (769, 'It is belief that brings you close to Allah not the wealth or children and Whatever you spend in charity, Allah will pay you back and Unbeliever''s statements about the Prophet and AL-Quran', ARRAY['Unbeliev','Prophet','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (770, 'Unbelievers are asked to ponder upon their wrong statements and Truth has come, falsehood neither originates nor restores anything', ARRAY['Unbeliev'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (771, 'On the Day of Judgement unbelievers would like to believe but it will be of no avail to them', ARRAY['Dai','Judgement'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (772, 'None can withhold or award blessings besides Allah and Shaitan is your enemy, so take him as your enemy', ARRAY['Shaitan','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (773, 'That person who consider his evil deeds to be good cannot be guided to the Right Path', ARRAY['Right'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (774, 'Let all those who are seeking honor know that real honor is in the obedience of Allah', ARRAY['Let','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (775, 'Allah has created water, day, night, sun and moon for man''s benefit and Deities besides Allah can neither hear, nor response nor yet own even a thread of a date-stone', ARRAY['Deiti','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (776, 'Mankind is in need of Allah, while He is not in need of any one', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (777, 'Living and dead are not alike You cannot make those who are buried in the grave hear you', '{}', 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (778, 'AL-Quran is the similar Book as the Book which was given to Prophet Musa', ARRAY['Prophet','Musa'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (779, 'Prophet''s wives are believers'' mothers and Blood relations have greater claims than others in the Book of Allah', ARRAY['Blood','Prophet','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (780, 'Those who discourage others from participating in fight against the unbelievers and don''t participate in such a war themselves have no faith and all their deeds will be void', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (781, 'The Life of Rasool Allah (Muhammad) is the best Model for you', ARRAY['Allah','Model','Life','Muhammad','Rasool'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (782, 'In Hell the unbelievers shall ask double punishment for their leaders', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (783, 'O Believers! Fear Allah and always say the right thing and Heavens, Earth and Mountains refuse to take Allah''s Trust but the Man took it', ARRAY['Believ','Allah','O','Earth','Trust'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (784, 'Plotting evil recoil none but the author of it and If Allah was to punish people for their wrong doings, He would have not left even and animal around', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (785, 'AL-Quran is revealed by the Allah to warn people and Prophet is told that he could warn only those people who have the fear of Allah', ARRAY['Prophet','Allah'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (786, 'And example of three Prophets who were sent to one town, all denied them except one man who came from cross the town', ARRAY['Prophet'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (787, 'Allah blessed the man who believed with Paradise and destroyed the disbelievers', ARRAY['Paradis','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (788, 'Allah has created all things in pair', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (789, 'Day, night, sun and moon; all are being regulated by Allah', ARRAY['Dai','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (790, 'Allah has not sent any Book which has a provision of Shirk (worshipping any one else besides Allah)', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (791, 'Story of Prophet Saleh and his address to his people and Saleh''s people plotted to kill him but Allah saved him and destroyed the disbelievers', ARRAY['Saleh','Stori','Prophet','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (792, 'Fir''on and his chiefs disbelieved; as result Allah destroyed them but saved the Children of Israel', ARRAY['Children','Israel','Fir''on','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (793, 'Nuh admonished his people not to commit shirk for 950 years Likewise, Ibrahim admonished his people not to commit shirk', ARRAY['Ibrahim','Nuh'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (794, 'There is a special reward for those who forsake their beds and invoke their Rabb with fear and hope and spend in charity', ARRAY['Rabb'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (795, 'It is not fitting for believers to have option in what has been decided by Allah and His Rasool', ARRAY['Rasool','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (796, 'Divorce when no Iddat (waiting period for remarriage) is required and Special permission for Prophet Muhammad to marry more than four wives and Restriction on Prophet to marry or exchange the present wives after this commandment', ARRAY['Muhammad','Prophet','Iddat'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (797, 'Those who recite AL-Quran, establish Salah and give charity may hope for Allah''s blessings and rewards and Those who disbelieve shall have a painful punishment in the Hell-Fire forever', ARRAY['Salah','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (798, 'Romans (Christians) defeat at the hands of Persian (Pagans) was taken as a sign of the Muslims defeat at the hands of Arab''s unbelievers, so Allah gave good tidings for Roman''s victory as well as Muslims victory in a few year', ARRAY['Roman','Allah','Arab','Persian','Pagan'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (799, 'Allah sent His Rasools for the guidance of people, some believed while other rejected, Allah subjected the guilty to His retribution and helped the Believers and O Prophet you cannot make the dead to hear you', ARRAY['Believ','Allah','O','Rasool','Prophet'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (800, 'Mountains and birds use to sing Allah''s Rhymes with Prophet Dawood and Allah subjected the winds and Jinns to Prophet Sulaiman and Claim of people that Jinns know the unseen is wrong', ARRAY['Sulaiman','Dawood','Allah','Jinn','Prophet'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (801, 'Some Mushrikin regard the angels to be the female divinities being the daughters of Allah', ARRAY['Mushrikin','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (802, 'Disbeliever''s attitude towards spending in the way of Allah', ARRAY['Disbeliev','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (803, 'A scene from the Day of Judgement', ARRAY['Dai','Judgement'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (804, 'Allah''s greeting to the residents of Paradise', ARRAY['Paradis','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (805, 'Allah''s address to the criminal sinners and On the Day of judgement hands and feet shall testify', ARRAY['Dai','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (806, 'AL-Quran is to warn those who are alive and to establish charge against the disbelievers', '{}', 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (807, 'Life in the Hereafter and the Day of Judgement are real', ARRAY['Life','Dai','Judgement'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (808, 'A scene from the Day of Judgement and a treatment for the wrongdoers and A dialogue between the followers and the leaders who mislead them', ARRAY['Dai','Judgement'], 18, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (809, 'A scene from the scenes of Paradise and And example of conversation from a resident of Paradise', ARRAY['Paradis'], 22, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (810, 'A scene from the scenes of Hell', '{}', 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (811, 'Prophet Nuh prayed and Allah respond to his prayers', ARRAY['Nuh','Prophet','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
