INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (813, 'Prophet Ibrahim was asked to offer his only son in sacrifice as a test and he fulfilled it', ARRAY['Ibrahim','Prophet'], 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (814, 'Allah bestowed His favors on Prophets Musa and Haroon', ARRAY['Haroon','Musa','Prophet','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (815, 'Lut was also a Rasool of Allah', ARRAY['Lut','Rasool','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (816, 'Story of Prophet Yunus (Jonah)', ARRAY['Jonah','yunu','Stori','Prophet'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (817, 'Mushrik''s claim of Angels being daughters of Allah and Jinns having blood relations with Allah are utterly false', ARRAY['Mushrik','Jinn','Angel','Allah'], 18, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (818, 'Allah has promised to help His Rasools and His devotees', ARRAY['Rasool','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (819, 'AL-Quran is full of admonition Unbelievers are in sheer arrogance for calling the Prophet as liars', ARRAY['Unbeliev','Prophet'], 14, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (820, 'Allah has not created the heavens and the earth in vain', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (821, 'Story of Sulaiman''s inspection of steeds to be used in Jihad and  Prophet Sulaiman''s prayer of granting him a kingdom, similar of which may not be granted to any one else', ARRAY['Prophet','Sulaiman','Stori','Jihad'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (822, 'Story of Ayub (Job), his sickness and relief', ARRAY['Job','Stori','Ayub'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (823, 'AL-Quran is but a reminder about the reward of Paradise and punishment of the hellfire', ARRAY['Paradis'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (824, 'The mission of the Rasools'' is to warn people and declare that there is no divinity except Allah', ARRAY['Rasool','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (825, 'Story of the creation of Adam and disobedience of Iblees (Shaitan)', ARRAY['Iblee','Shaitan','Adam','Stori'], 18, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (826, 'Believers who cannot practice their faith (Islam) should migrate to other places where they can and The real losers are those who shall lose their souls and their families on the Day of Judgement', ARRAY['Islam','Dai','Believ','Judgement'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (827, 'No one can rescue the one against whom the sentence of punishment has been decreed', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (828, 'AL-Quran is consistent in its verses yet repeats its teachings in different ways and Allah has cited every kind of parable in AL-Quran so that people may learn a lesson', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (829, 'Allah, Who has created the man, shall give him life again, for accountability on the Day of Judgement', ARRAY['Dai','Judgement','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (830, 'Those who have transgressed against their souls should not despair of Allah''s mercy, they should repent while they can', ARRAY['Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (831, 'Worship Allah and be among His thankful servants and On the Day of Judgement the Book of Deeds will be lai open and justice will be done with all fairness', ARRAY['Dai','Judgement','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (832, 'After Judgement unbelievers will driven to Hell and the righteous will be led to Paradise', ARRAY['Judgement','Paradis'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (833, 'No one disputes the revelations of Allah except the kafirs (unbelievers) and The angels who bear the Throne of Allah pray for those who repent and follow the Right Way', ARRAY['Right','Wai','unbeliev','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (834, 'A scene from the Day of Judgement and Furtive looks and the secret thoughts', ARRAY['Dai','Furtiv','Judgement'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (835, 'Those who denied the Prophets and Allah''s revelations were all destroyed', ARRAY['Prophet','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (836, 'Prophet Musa was sent to Fir''on, Haman and Qarun and Fir''on intended to kill Prophet Musa', ARRAY['Qarun','Haman','Musa','Fir''on','Prophet'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (837, 'And excellent speech of one of the relatives of Fir''on in the favor of Prophet Musa', ARRAY['Fir''on','Prophet','Musa'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (838, 'Allah does help His Rasools and the believers in this world''s life and will help them in the life Hereafter and Your Rabb says, "Call on Me, I will answer your prayers"', ARRAY['Rasool','Rabb','Call','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (839, 'No one has the right to be worshipped except Allah, the Creator and the Rabb of the worlds', ARRAY['Rabb','Creator','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (840, 'Those who argue about the revelations of Allah, will soon fin out the Truth and  Allah has sent many Rasools before Muhammad; some are mentioned in AL-Quran and some are not', ARRAY['Muhammad','Rasool','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (841, 'Cattle are the signs of Allah for the people of understanding and Belief after seeing the scourge of Allah is of no avail to the disbelievers', ARRAY['Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (842, 'AL-Quran is a giver of good news and and admonition and Woe to those who deny the Hereafter and do not pay Zakah', ARRAY['Zakah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (843, 'Story of the creation of earth, mountains, seasons, skies and heavens', ARRAY['Stori'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (844, 'Warning to the disbelievers and the example of Allah''s scourge upon the nations of A''d and Thamud', ARRAY['Thamud','''d','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (845, 'On the Day of Judgement people''s own ears, eyes and skins will bear witness against them relating to their misdeeds', ARRAY['Dai','Judgement'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (846, 'Those who do not listen to Al-Quran shall be sternly punished   and those who listen to those who say our God is Allah and then stay firm on it, angels are assigned for their protection', ARRAY['God','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (847, 'The Book given to Prophet Musa was similar to AL-Quran', ARRAY['Prophet','Musa'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (848, 'On the Day of Judgement all other gods to whom people worship besides Allah shall vanish', ARRAY['Dai','Judgement','Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (849, 'Have you ever considered that if Al-Quran is really from Allah and you deny it, what will happen to you', ARRAY['Have','Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (850, 'The heavens might have broken apart from above those who elevate Allah''s creatures to His rank if the angels were not begging forgiveness for the residents of earth', ARRAY['Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (851, 'Islam is the same Deen (way of life) which was enjoined on Nuh, Ibrahim, Musa (Moses) and Isa (Jesus) They were all ordered to establish Deen-al-Islam and do not create division (sects) in it', ARRAY['Ibrahim','Musa','sect','Jesu','Islam','Mose','Deen','Nuh','Isa'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (852, 'He who desires the harvest in the hereafter shall be given many folds, but he who desires in this life shall be given a portion here but shall have no share in the hereafter', '{}', 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (853, 'Whatever afflictions befall upon people are the result of their own misdeeds and True believers are those who establish Salah, give charit and defend themselves when oppressed', ARRAY['Salah'], 14, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (854, 'The real losers are those who will lose on the Day of Resurrection', ARRAY['Dai'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (855, 'It is Allah Who gives daughters and sons as He pleases', ARRAY['Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (856, 'It is not vouchsafed for any human being that Allah should speak to him face to face', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (857, 'Al-Quran is a transcript from the Mother Book which is in Allah''s keeping', ARRAY['Mother','Book','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (858, 'Even the Mushrikin believe that heavens, earth and all therein is created by Allah and Supplication before riding a conveyance', ARRAY['Mushrikin','Supplic','Allah'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (859, 'It is Allah Who recall the souls of people upon their death and of the living people during their sleep', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (860, 'Prophet Musa was sent to Fir''on and his chiefs with signs but they ridicule him and the signs as a result Allah drowned them all', ARRAY['Allah','Fir''on','Prophet','Musa'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (861, 'Prophet Isa (Jesus) was no more than a mortal whom Allah favored and made him and example for the Children of Israel', ARRAY['Allah','Jesu','Israel','Isa','Children','Prophet'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (862, 'Allah revealed this Quran in the Blessed Night (Layla-tul-Qadr) in which all matters are decided wisely by His command', ARRAY['Night','Quran','Allah'], 16, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (863, 'Lessons to be learned from the story of Prophet Musa and the people of Fir''on', ARRAY['Fir''on','Prophet','Musa'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (864, 'Allah delivered the Children of Israel and chose them over the nations of the world inspite of their weaknesses and Day of Sorting Out is the time appointed for resurrection', ARRAY['Dai','Children','Israel','Allah'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (865, 'Food and drink for the sinners in hell', ARRAY['Food'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (866, 'Food and entertainment for the righteous in paradise', ARRAY['Food'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (867, 'Food for thought to those who are seeking the signs of Allah and If they do not believe in Allah and His revelations then in what report will they believe?', ARRAY['Food','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (868, 'Allah has subjected the seas and all that is between the heavens and the earth for human beings and  Israelites made sects in their religion after the knowledge has come to them through Torah', ARRAY['Torah','Israelit','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (869, 'Wrongdoers are protectors of one another while the protector of righteous is Allah Himself', ARRAY['Allah','Wrongdoer'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (870, 'He who has made his own desires as his god, Allah let him go astray and set a seal upon his ears and heart', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (871, 'Allah''s address to the disbelievers on the day of judgement', ARRAY['Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (872, 'Allah created the heavens, earth and all that lies between them to manifest the truth and Those deities to whom Mushrikin invoke are not even aware that they are being invoked', ARRAY['Mushrikin','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (873, 'Al-Quran is the word of Allah, not the Prophet and Prophet is but a plain Warner', ARRAY['Warner','Prophet','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (874, 'Al-Quran conforms the revelation of Torah given to Prophet Musa', ARRAY['Torah','Prophet','Musa'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (875, 'Those who treat their parents with kindness shall be rewarded and those who rebuke their parents shall be punished', '{}', 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (876, 'Nation of A''d rejected Allah''s message, as a result she faced destruction', ARRAY['''d','Nation','Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (877, 'No deity can save people from the wrath of Allah', ARRAY['Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (878, 'A group of jinns embraced Islam after hearing Al-Quran and became the preachers to their folk', ARRAY['Islam'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (879, 'Keep on passing the message of Allah and bear the disbelievers with patience', ARRAY['Allah'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (880, 'Allah void the deeds of the disbelievers', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (881, 'In case of war thoroughly subdue the unbelievers before taking prisoners of war', '{}', 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (882, 'Believers do not follow their own desires', ARRAY['Believ'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (883, 'Parable of paradise and hell', ARRAY['Parabl'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (884, 'Hypocrites are those on whose heart Allah has set a seal', ARRAY['Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (885, 'Promise of obedience (Islam) and good talk which is not followed by action is cursed by Allah', ARRAY['Islam','Promis','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (886, 'Allah put the believers to test in order to know the valiant and the resolute', ARRAY['Allah'], 6, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (887, 'In the case of war Allah is on the side of the believers', ARRAY['Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (888, 'Do not be niggardly if you are asked to give in the cause of Allah', ARRAY['Do','Allah'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (889, 'He who turns away from the remembrance of Allah, Allah appoints a Shaitan to be his intimate friend and Hold fast to Al-Quran if you want to be rightly guided', ARRAY['Shaitan','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (890, 'If you help the cause of Allah, Allah will help and protect you', ARRAY['Allah'], 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (891, 'Ilyas (Elias) was one of the Rasools of Allah', ARRAY['Ilya','Rasool','Elia','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (892, 'Story of Prophet Dawood -mountains and birds used to sing the rhymes of Allah and Story of the two litigants who came to Dawood for a decision', ARRAY['Dawood','Allah','-mountain','Stori','Prophet'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (893, 'Who can be more wicked than the one who invent a lie against Allah? And If Allah intends to harm you, no one can save you and if He intends to bestow His blessings, no one can withhold', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (894, 'Allah saved that believer from the plots of Fir''on and destroyed the people of Fir''on, now they are presented before the fire of Hell morning and evening (punishment of the graves)', ARRAY['Fir''on','Allah'], 13, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (895, 'Prophet Ibrahim recognized the Oneness of Allah and rejected Shirk (Polytheism) and If it were not that all mankind will become one race of unbelievers, Allah would have given the unbeliever houses made with sterling silver', ARRAY['Ibrahim','Polyth','Allah','Oneness','Prophet'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (896, 'Allah testifies that your God is one God and that shaitans do not have and excess to the exalted assembly of angels', ARRAY['God','Allah'], 11, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
