INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (967, 'Fifteen exclusive attributes of Allah', ARRAY['Allah'], 3, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (968, 'Women that become believers, test their Iman, and if you find them truthful do not return them to their unbelieving husbands', ARRAY['Women','Iman'], 2, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (969, 'Allah is not going to treat the Muslims as He will treat the guilty Why disbelievers do not understand this?', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (970, 'Fortunate people and their reward and Unfortunate people and their punishment', '{}', 19, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (971, 'Al-Quran is the word of Allah and not of the Prophet, and is a reminder for those who fear Allah (God)', ARRAY['God','Prophet','Allah'], 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (972, 'A beautiful speech of the jinns who embraced Islam after hearing Al-Quran and Jinns also have different religions and sects, among jinns there are some Muslims and some deviators from the Truth', ARRAY['Islam','Jinn'], 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (973, 'Mosques are built for the worship of Allah, so invoke no one else besides Him', ARRAY['Mosqu','Allah'], 4, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (974, 'Rasools do not have the power to harm or benefit anyone, his mission is just to convey Allah''s message and Only Allah knows the unseen, He reveals it to whom He chooses from', ARRAY['Rasool','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (975, 'Read from the Quran as much as you easily can and  Whatever you spend in the way of Allah, you will find it in the hereafter', ARRAY['Allah','Quran','Read'], 1, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (976, 'Instructions to the Prophet for cleanliness and patience', ARRAY['Prophet'], 7, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (977, 'The day of judgement will be very difficult especially for those who deny Allah''s revelations and oppose His cause', ARRAY['Allah'], 24, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (978, 'Actions which lead to hellfire are, Not to offer Salah, not to feed the poor, waste time in vain talk and to deny the day of judgement', ARRAY['Salah'], 25, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (979, 'Be aware of the day of resurrection and judgement, there is no escape from it', '{}', 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (980, 'Disbelievers do not believe because they never took Al-Islam seriously', ARRAY['Disbeliev'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (981, 'Universe was there before mankind, then Allah created man, provided him guidance and let him use his free will, either to believe or to disbelieve', ARRAY['Allah'], 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (982, 'Exemplary life in paradise for those who choose to believe', '{}', 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (983, 'Allah swears in the name of life giving winds, rain and angels that the day of judgement will be established and Woe on that day to the disbelievers!', ARRAY['Allah'], 28, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (984, 'On that day, The disbelievers will be asked to walk towards hell which they used to deny', '{}', 12, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (985, 'Prophet Nuh''s prayer not to leave any unbeliever on the surface of the earth and Allah granted his wish', ARRAY['Nuh','Prophet','Allah'], 8, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (986, 'Allah Himself took the responsibility of Al-Quran and Last moments of disbeliever''s death', ARRAY['Allah'], 15, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (987, 'Allah sent this Quran gradually according to the issues faced by mankind and This is and admonition for those who want to adopt the way to their Rabb (God)', ARRAY['God','Quran','Rabb','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (988, 'The righteous will be given all that they desire', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (989, 'A warning to the disbelievers', '{}', 5, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (990, 'Creation of heavens , earth, mountains and vegetation clearly points out towards the day of judgement and Resurrection and man''s accountability in the court of Allah', ARRAY['Allah'], 30, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (991, 'Allah granted the Muslims a manifest victory through the treaty of Hudeybiyah and Swearing allegiance to the Prophet is considered swearing allegiance to Allah', ARRAY['Hudeybiyah','Prophet','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (992, 'Allah''s commandment to lower the voice in the presence of Holy Prophet and Make peace between the believers if they fell into fighting among themselves', ARRAY['Make','Holi','Prophet','Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (993, 'Deniers of truth will be put in the fire of hell and Reward for the righteous will be paradise in which they will show gratitude for Allah''s graciousness', ARRAY['Allah','Denier'], 28, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (994, 'Those who befriend those who are under the wrath of Allah will be severely punished and True believers do not befriend those who oppose Allah and His Rasool', ARRAY['Rasool','Allah'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (995, 'O believers, do not say something that you don''t do and Prophet Isa (Jesus) gave a good news of a Rasool coming after him whose name is Ahmed (Muhammad)', ARRAY['Jesu','O','Muhammad','Rasool','Isa','Ahmed','Prophet'], 9, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (996, 'The day of judgement will be equal to fifty thousand years and Disbelievers will wish to save themselves from the punishment at the expense of their children, wives, brothers and relatives, but it will not happen', ARRAY['Disbeliev'], 35, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (997, 'Prophet Nuh''s preaching and submission to Allah after exhausting all his efforts', ARRAY['Nuh','Prophet','Allah'], 20, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (998, 'Allah ordered the Prophet not to stand in prayer the whole night and Those who oppose the Prophet will be treated with heavy fetters and blazing fire and Al-Quran is a reminder for those who want to find the Right Way', ARRAY['Right','Wai','Prophet','Allah'], 19, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (999, 'Allah has assigned two angels to each person for noting down each single word that he utters and  Every stubborn disbeliever will be thrown into hell', ARRAY['Allah'], 14, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""quran_theme"" ("theme_id", "name", "keywords", "total_ayahs", "created_at") VALUES (1000, 'All that is in the heavens and earth glorifies Allah, Who created the heavens and earth in six periods and has the knowledge of everything and Those who spend in charity will be richly rewarded', ARRAY['Allah'], 10, '2025-09-15T11:26:01.808335+00:00'::timestamptz);
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (1, 'Ahmed ibn Ali al-Ajamy', '{"ar": "أحمد بن علي العجمي (مواليد 1968): قارئ سعودي من الخبر بالمنطقة الشرقية. تخرج من جامعة الإمام محمد بن سعود الإسلامية بدرجة في الشريعة. معروف بصوته الواضح ويؤم المصلين منذ 1984.", "en": "Ahmed ibn Ali al-Ajamy (b. 1968): Saudi reciter from Khobar, Eastern Province. Graduated from Imam Muhammad ibn Saud Islamic University with a degree in Sharia. Known for his clear voice and has been leading prayers since 1984."}', 'https://quranhub.b-cdn.net/quran/images/reciters/ahmed-ibn-ali-al-ajamy.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (2, 'Abu Bakr Ash-Shaatree', '{"ar": "أبو بكر الشاطري (مواليد 1970): قارئ سعودي من جدة، تخرج في علوم القرآن. معروف بصوته الهادئ وأسلوبه الخاشع. يؤم حاليًا في مسجد الفرقان بجدة واكتسب شهرة لأدائه المطمئن.", "en": "Abu Bakr Ash-Shaatree (b. 1970): Saudi reciter from Jeddah, graduated in Quranic studies. Known for his calm and serene recitation style. Currently leads prayers at Al-Furqan Mosque in Jeddah and has gained recognition for his peaceful delivery."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abu-bakr-ash-shaatree.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (3, 'Fooladvand - Hedayatfar', '{"ar": "فولادوند - هداية فر: قارئان إيرانيان بارزان معروفان بتلاوتهما المؤثرة للقرآن الكريم في التقليد الفارسي، مساهمان في الحفاظ على أساليب التلاوة الإسلامية الإيرانية.", "en": "Fooladvand - Hedayatfar: Prominent Iranian reciters known for their impactful Quranic recitations in the Persian tradition, contributing to the preservation of Iranian Islamic recitation styles."}', '');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (4, 'Sa''ad Al-Gamidi', '{"ar": "سعد الغامدي: قارئ سعودي مشهور يُحتفى به لصوته العذب وتجويده الدقيق. تلاواته مسموعة على نطاق واسع في العالم الإسلامي لوضوحها وجمالها.", "en": "Saad Al-Ghamdi: Renowned Saudi reciter celebrated for his melodious voice and precise Tajweed. His recitations are widely listened to across the Muslim world for their clarity and beauty."}', 'https://quranhub.b-cdn.net/quran/images/reciters/saad-al-gamidi.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (5, 'Muhammad Abu Sneineh', '{"ar": "محمد أبو سنينة: قارئ ليبي بارز معروف بتلاواته العاطفية والمؤثرة للقرآن الكريم التي تلامس قلوب المستمعين عبر العالم العربي.", "en": "Muhammad Abu Sneineh: Prominent Libyan reciter known for his emotional and heartfelt Quranic recitations that resonate with listeners across the Arab world."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-abu-sneineh.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (6, 'Youssouf Leclerc', '{"ar": "يوسف لوكلير: قارئ فرنسي معروف بتلاواته للقرآن الكريم باللغة الفرنسية المبنية على ترجمة محمد حميد الله، متوفرة على موقع lenoblecoran.fr ومنصات إسلامية مختلفة.", "en": "Youssouf Leclerc: French reciter known for his French translation recitations of the Quran based on Muhammad Hamidullah''s translation, widely available on lenoblecoran.fr and various Islamic platforms."}', '');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (7, 'Hudhaify', '{"ar": "علي الحذيفي (مواليد 1366 هـ): إمام سعودي من منطقة الباحة. تولى مناصب قيادية في مسجد قباء والمسجد النبوي. أستاذ في التوحيد والفقه، معروف بتلاوته الواضحة وإسهاماته العلمية.", "en": "Ali Al-Hudhaify (b. 1366 AH): Saudi Imam from Al-Baha region. Held leadership positions at Quba Mosque and the Prophet''s Mosque. Also a professor of Tawheed and Fiqh, known for his clear recitation and scholarly contributions."}', 'https://quranhub.b-cdn.net/quran/images/reciters/hudhaify.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (8, 'Maher Al Muaiqly', '{"ar": "ماهر المعيقلي (مواليد 1969): إمام المسجد الحرام بمكة المكرمة، وُلد في المدينة المنورة. حاصل على دكتوراه في التفسير والفقه من جامعة أم القرى. معروف بتلاوته المؤثرة، أمّ المصلين في الحرمين منذ 1984.", "en": "Maher Al Muaiqly (b. 1969): Imam of the Grand Mosque in Makkah, born in Madinah. Holds PhDs in Tafsir and Fiqh from Umm al-Qura University. Known for his emotional recitation style, he has led prayers at both Haramain since 1984."}', 'https://quranhub.b-cdn.net/quran/images/reciters/maher-al-muaiqly.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (9, 'Yassin Al Jazairi', '{"ar": "ياسين الجزائري: قارئ جزائري متميز معروف بصوته الجميل وإتقانه لتقاليد التلاوة في شمال إفريقيا، ملهم للمستمعين بأدائه الصادق من القلب.", "en": "Yassin Al-Jazairi: Distinguished Algerian reciter known for his beautiful voice and mastery of North African recitation traditions, inspiring listeners with his heartfelt performances."}', 'https://quranhub.b-cdn.net/quran/images/reciters/yassin-al-jazairi.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (10, 'Abdul Basit Abdul Samad', '{"ar": "عبد الباسط عبد الصمد (1927-1988): قارئ مصري يُلقب بـ\"صاحب الصوت الذهبي\". أول من سجل تلاوات تجارية للقرآن وأول رئيس لنقابة القراء بمصر. وُلد في قنا، حفظ القرآن في سن 10 وأتقن 10 قراءات في سن 14.", "en": "Abdul Basit Abdul Samad (1927-1988): Egyptian reciter known as \"The Golden Voice\". First to record commercial Quran recitations and first president of Egypt''s Reciters Union. Born in Qena, memorized Quran by age 10, mastered 10 styles by 14."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdul-basit-abdul-samad.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (11, 'Abdul Rashid Sufi', '{"ar": "عبد الرشيد صوفي: قارئ صومالي بارز حاصل على إجازة في القراءات العشر. شغل منصب مفتي في الصومال سابقًا ومعروف بإتقانه لأساليب التلاوة المختلفة.", "en": "Abdul Rashid Sufi: Prominent Somali reciter holding certification (Ijazah) in the ten Qira''at. Previously served as a mufti in Somalia and is recognized for his mastery of various recitation styles."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdul-rashid-sufi.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (12, 'Muhammad Abdul Hakim', '{"ar": "محمد عبد الحكيم: قارئ متميز معروف بتلاواته المؤثرة للقرآن الكريم وتفانيه في الحفاظ على طرق التلاوة التقليدية.", "en": "Muhammad Abdul Hakim: Distinguished reciter known for his impactful Quranic recitations and dedication to preserving traditional recitation methods."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-abdul-hakim.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (13, 'Al-Ayoune Al-Kouchi', '{"ar": "العيون الكوشي: قارئ مغربي بارز متخصص في رواية ورش عن نافع. يؤم حاليًا مسجد الأندلس في الدار البيضاء، محافظًا على أسلوب التلاوة المغربي التقليدي.", "en": "Al-Ayoune Al-Kouchi: Prominent Moroccan reciter specializing in the Warsh narration from Nafi''. Currently serves as Imam of Al-Andalus Mosque in Casablanca, preserving the traditional Moroccan recitation style."}', 'https://quranhub.b-cdn.net/quran/images/reciters/al-ayoune-al-kouchi.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (14, 'Shamshad Ali Khan', '{"ar": "شمشاد علي خان: قارئ باكستاني متميز معروف بإتقانه لأساليب التلاوة التقليدية في جنوب آسيا وأدائه المؤثر للآيات القرآنية.", "en": "Shamshad Ali Khan: Distinguished Pakistani reciter known for his mastery of traditional South Asian recitation styles and impactful delivery of Quranic verses."}', 'https://quranhub.b-cdn.net/quran/images/reciters/shamshad-ali-khan.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (15, 'Abdurrahmaan As-Sudais', '{"ar": "عبد الرحمن السديس (مواليد 1960): الإمام الأكبر للمسجد الحرام بمكة منذ 1984 ورئيس شؤون الحرمين. وُلد في الرياض، حاصل على دكتوراه في الشريعة من جامعة أم القرى. معروف بصوته الخاشع وخطبه المؤثرة.", "en": "Abdul Rahman As-Sudais (b. 1960): Chief Imam of the Grand Mosque in Makkah since 1984 and President of the Two Holy Mosques Affairs. Born in Riyadh, holds PhD in Sharia from Umm al-Qura University. Known for his emotional voice and influential sermons."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdurrahmaan-as-sudais.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (16, 'Ibrahim Walk', '{"ar": "إبراهيم ووك: قارئ باللغة الإنجليزية معروف بتلاوته الواضحة لترجمة صحيح إنترناشيونال وترجمات أخرى للقرآن الكريم، جاعلاً النص المقدس في متناول الجماهير الناطقة بالإنجليزية.", "en": "Ibrahim Walk: English narrator known for his clear recitation of Saheeh International and other English translations of the Quran, making the holy text accessible to English-speaking audiences."}', '');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (17, 'Alafasy', '{"ar": "مشاري راشد العفاسي (مواليد 1976): قارئ كويتي مشهور وإمام المسجد الكبير بالكويت. متخصص في القراءات العشر والتفسير من الجامعة الإسلامية بالمدينة المنورة. معروف عالميًا بصوته الجميل والمميز.", "en": "Mishary Rashid Alafasy (b. 1976): Renowned Kuwaiti reciter and Imam of the Grand Mosque in Kuwait. Specialized in the ten Qira''at and Tafsir from the Islamic University of Madinah. Known worldwide for his beautiful and distinctive voice."}', 'https://quranhub.b-cdn.net/quran/images/reciters/alafasy.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (18, 'Saood bin Ibraaheem Ash-Shuraym', '{"ar": "سعود الشريم: إمام وخطيب بالمسجد الحرام بمكة، معروف بصوته القوي وخطبه المتميزة. شريك السديس في إمامة صلاة التراويح منذ التسعينات.", "en": "Saud Ash-Shuraim: Imam and preacher at the Grand Mosque in Makkah, known for his powerful voice and distinguished sermons. Has been a partner with As-Sudais in leading Taraweeh prayers since the 1990s."}', 'https://quranhub.b-cdn.net/quran/images/reciters/saood-bin-ibraaheem-ash-shuraym.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (19, 'Parhizgar', '{"ar": "برهيزكار: قارئ إيراني متميز معروف بإتقانه للتلاوة القرآنية بالأسلوب الفارسي ومساهمته في تقاليد التلاوة الإسلامية في إيران.", "en": "Parhizgar: Distinguished Iranian reciter known for his mastery of Persian-style Quranic recitation and contribution to Islamic recitation traditions in Iran."}', 'https://quranhub.b-cdn.net/quran/images/reciters/parhizgar.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (20, 'Chinese', '{"ar": "قارئ صيني: ممثل للقراء المسلمين الصينيين الذين يعملون على حفظ ونشر التلاوة القرآنية بين المجتمعات المسلمة الناطقة بالصينية، رابطين بين التقاليد الإسلامية والثقافة الصينية.", "en": "Chinese Reciter: Representative of Chinese Muslim reciters who work to preserve and spread Quranic recitation among Chinese-speaking Muslim communities, bridging Islamic tradition with Chinese culture."}', '');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (21, 'Hani Rifai', '{"ar": "هاني الرفاعي: قارئ سعودي متميز مشهور بصوته العذب وتلاواته المؤثرة عاطفيًا. أسلوبه الفريد أكسبه التقدير في جميع أنحاء العالم الإسلامي.", "en": "Hani Ar-Rifai: Distinguished Saudi reciter celebrated for his melodious voice and emotionally moving recitations. His unique style has earned him recognition throughout the Muslim world."}', 'https://quranhub.b-cdn.net/quran/images/reciters/hani-rifai.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (22, 'Abdul Hakim Abdul Latif', '{"ar": "عبد الحكيم عبد اللطيف (1936-2016): عالم مصري وشيخ عموم المقارئ المصرية السابق، كرّس أكثر من 70 عامًا لخدمة القرآن الكريم. وُلد في القاهرة وحفظ القرآن في سن 12، وتُعد أعماله مرجعًا أساسيًا في علوم القراءات.", "en": "Abdul Hakim Abdul Latif (1936-2016): Egyptian scholar and former Sheikh al-Qurra of Egypt who dedicated over 70 years to Quranic service. Born in Cairo, he memorized the Quran by age 12 and his works remain key references in Quranic sciences."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdul-hakim-abdul-latif.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (23, 'Mahmoud Khalil Al-Husary', '{"ar": "محمود خليل الحصري (1917-1980): قارئ مصري كبير حفظ القرآن في سن 8. أول من سجّل المصحف المرتل كاملاً، حمل لقب شيخ المقارئ وفاز بمسابقة الإذاعة المصرية 1944. وُلد في طنطا.", "en": "Mahmoud Khalil Al-Husary (1917-1980): Egyptian master reciter who memorized the Quran by age 8. First to record the complete Murattal Quran, he held the title Shaykh al-Maqari and won Egypt Radio''s 1944 competition. Born in Tanta."}', 'https://quranhub.b-cdn.net/quran/images/reciters/mahmoud-khalil-al-husary.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (24, 'Waleed Alnaehy', '{"ar": "وليد النائحي: قارئ متميز معروف بوضوح نطقه والعمق العاطفي في تلاوته القرآنية، يلامس القلوب بأدائه الصادق.", "en": "Waleed Al-Naehi: Distinguished reciter known for his clear articulation and emotional depth in Quranic recitation, touching hearts with his sincere delivery."}', 'https://quranhub.b-cdn.net/quran/images/reciters/waleed-alnaehy.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (25, 'Muhammad Siddiq Al Minshawi', '{"ar": "محمد صديق المنشاوي (1920-1969): قارئ مصري من سوهاج يُلقب بـ\"الصوت الباكي\". أحد أعلام القراء الأربعة في القرن العشرين، حفظ القرآن في سن 8 وأثر في أجيال بأسلوبه المؤثر.", "en": "Muhammad Siddiq Al-Minshawi (1920-1969): Egyptian reciter from Sohag known as \"The Weeping Voice\". Part of the quadrumvirate of great 20th century reciters, he memorized the Quran by age 8 and influenced generations with his emotional style."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-siddiq-al-minshawi.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (26, 'Ayman Sowaid', '{"ar": "أيمن سويد (مواليد 1955): عالم تجويد وقارئ سوري حاصل على شهادات عليا من الأزهر وأم القرى. يحمل إجازات متعددة ويُعد من أبرز خبراء التجويد المعاصرين، يدرّس القراءات دوليًا.", "en": "Ayman Suwayd (b. 1955): Syrian Tajweed scholar and reciter with advanced degrees from Al-Azhar and Umm Al-Qura. Holds multiple Ijazahs and is considered a leading contemporary expert in Tajweed science, teaching Qira''at internationally."}', 'https://quranhub.b-cdn.net/quran/images/reciters/ayman-sowaid.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (27, 'Ibrahim Akhdar', '{"ar": "إبراهيم الأخضر: قارئ سعودي بارز ومعلم قرآني معروف بتقنية تلاوته الدقيقة وتفانيه في تدريس علوم القرآن للطلاب حول العالم.", "en": "Ibrahim Al-Akhdar: Prominent Saudi reciter and Quranic educator known for his precise recitation technique and dedication to teaching Quranic sciences to students worldwide."}', 'https://quranhub.b-cdn.net/quran/images/reciters/ibrahim-akhdar.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (28, 'Muhammad Abdul Kareem', '{"ar": "محمد عبد الكريم: قارئ متميز معروف بصوته الجميل وإتقانه لأحكام التجويد في تلاواته القرآنية.", "en": "Muhammad Abdul Kareem: Distinguished reciter recognized for his beautiful voice and mastery of Tajweed rules in his Quranic recitations."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-abdul-kareem.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (29, 'Muhammad Jibreel', '{"ar": "محمد جبريل (مواليد 1964): إمام مسجد عمرو بن العاص المصري وقارئ مشهور. حفظ القرآن في صغره، فاز بمسابقات دولية في التلاوة، ويقدم برامج دينية تلفزيونية. معروف بإتقانه لأحكام التلاوة.", "en": "Muhammad Jibreel (b. 1964): Egyptian Imam of Amr Ibn Al-As Mosque and renowned reciter. Memorized the Quran at a young age, won international recitation competitions, and hosts religious TV programs. Known for his mastery of recitation rules."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-jibreel.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (30, 'Abdullah Basfar', '{"ar": "عبد الله بصفر: قارئ سعودي بارز وأستاذ مشارك في جامعة الملك عبد العزيز بجدة. الأمين العام السابق للهيئة العالمية للكتاب والسنة، معروف بصوته العذب وإسهاماته العلمية.", "en": "Abdullah Basfar: Prominent Saudi reciter and associate professor at King Abdulaziz University in Jeddah. Former Secretary-General of the World Book and Sunnah Organization, known for his melodious voice and scholarly contributions."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdullah-basfar.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (31, 'Muhammad Ayyoub', '{"ar": "محمد أيوب (1952-2016): إمام سعودي وُلد في مكة، عُرف بتلاوته الخاشعة المؤثرة. كان إمامًا للمسجد النبوي وأستاذًا للتفسير في الجامعة الإسلامية بالمدينة المنورة. أسلوبه المؤثر لامس قلوب الملايين.", "en": "Muhammad Ayyoub (1952-2016): Saudi Imam born in Makkah, known for his emotional and humble recitation. Served as Imam of the Prophet''s Mosque and was a Tafsir professor at the Islamic University of Madinah. His heartfelt style touched millions."}', 'https://quranhub.b-cdn.net/quran/images/reciters/muhammad-ayyoub.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (32, 'Al Ameen Muhammad Qanyouh', '{"ar": "الأمين محمد قنيوه: قارئ ليبي متميز معروف بأسلوبه المؤثر في التلاوة وتسجيلاته عالية الجودة للقرآن الكريم. تلاواته تُبرز جمال التلاوة القرآنية الليبية التقليدية.", "en": "Al Ameen Muhammad Qanyouh: Distinguished Libyan reciter recognized for his emotive recitation style and quality Quran recordings. His recitations showcase the beauty of traditional Libyan Quranic recitation."}', 'https://quranhub.b-cdn.net/quran/images/reciters/al-ameen-muhammad-qanyouh.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (33, 'Abdul Karim Al-Daghoush', '{"ar": "عبد الكريم الدغوش: قارئ مغربي متميز متخصص في رواية ورش عن نافع، معروف بالتزامه الدقيق بأسلوب التلاوة المغربي التقليدي وتسجيلاته عالية الجودة للقرآن الكريم.", "en": "Abdul Karim Al-Daghoush: Distinguished Moroccan reciter specializing in the Warsh narration from Nafi'', known for his precise adherence to traditional Moroccan recitation style and high-quality Quran recordings."}', 'https://quranhub.b-cdn.net/quran/images/reciters/abdul-karim-al-daghoush.jpeg');
INSERT INTO ""quranhub_schema"".""reciter"" ("id", "englishname", "short_description", "image_url") VALUES (34, 'Rachid Belalya', '{"ar": "رشيد بلالية: قارئ جزائري متميز معروف بصوته القوي وأدائه العاطفي للآيات القرآنية، ممثلاً تقليد التلاوة في شمال إفريقيا.", "en": "Rachid Belalia: Distinguished Algerian reciter known for his powerful voice and emotional delivery of Quranic verses, representing the North African recitation tradition."}', 'https://quranhub.b-cdn.net/quran/images/reciters/rachid-belalya.jpeg');
